// src/components/widgets/UserWidget.jsx
import React, { useState, useEffect } from 'react';
import { Users, Globe } from 'lucide-react';
import { rtdb } from '../../firebase';
import { ref, onValue, get, runTransaction, set } from 'firebase/database';
import { useAuth } from '../../contexts/AuthContext';

const UserWidget = () => {
  const { currentUser } = useAuth();
  const [chatUserCount, setChatUserCount] = useState(0);
  const [webUserCount, setWebUserCount] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  
  useEffect(() => {
    // Use existing userCount structure that already has permissions
    const chatCountRef = ref(rtdb, 'userCount/chat');
    const webCountRef = ref(rtdb, 'userCount/web');
    
    // Set up real-time listener for chat user count
    const chatCountListener = onValue(chatCountRef, (snapshot) => {
      const count = snapshot.val() || 0;
      setChatUserCount(count);
      setLoading(false);
    }, (error) => {
      console.error('Error fetching chat users count:', error);
      setError('Failed to load user data');
      setLoading(false);
    });
    
    // Set up real-time listener for web user count
    const webCountListener = onValue(webCountRef, (snapshot) => {
      const count = snapshot.val() || 0;
      setWebUserCount(count);
    }, (error) => {
      console.error('Error fetching web users count:', error);
    });
    
    // Track unique web users with localStorage
    const trackUniqueWebUser = async () => {
      try {
        // Create a unique ID for this browser
        const generateBrowserId = () => {
          const { userAgent, language, platform } = navigator;
          const screenInfo = `${window.screen.width}x${window.screen.height}`;
          const baseString = `${userAgent}|${language}|${platform}|${screenInfo}`;
          
          // Simple hash function
          let hash = 0;
          for (let i = 0; i < baseString.length; i++) {
            hash = ((hash << 5) - hash) + baseString.charCodeAt(i);
            hash |= 0;
          }
          return Math.abs(hash).toString(16);
        };
        
        // Generate a unique ID for this browser if not already stored
        let browserId = localStorage.getItem('browser_id');
        if (!browserId) {
          browserId = generateBrowserId();
          localStorage.setItem('browser_id', browserId);
        }
        
        // Check if this browser was already counted in this session
        const sessionCounted = sessionStorage.getItem('web_user_counted') === 'true';
        
        // If not counted yet in this session
        if (!sessionCounted) {
          // Mark as counted for this session
          sessionStorage.setItem('web_user_counted', 'true');
          
          // Update activity timestamp
          const currentTime = Date.now();
          localStorage.setItem('last_active_timestamp', currentTime.toString());
          
          // Increment web user count - only if not already counted
          const lastCountTime = localStorage.getItem('last_count_time');
          const oneDayAgo = currentTime - (24 * 60 * 60 * 1000);
          
          // Only count this user if they haven't been counted in the last day
          // This prevents the count from growing indefinitely but still keeps it 
          // from dropping to zero when users are active
          if (!lastCountTime || parseInt(lastCountTime) < oneDayAgo) {
            // Store the time we counted this user
            localStorage.setItem('last_count_time', currentTime.toString());
            
            // Increment web user count
            await runTransaction(webCountRef, (currentCount) => {
              return (currentCount || 0) + 1;
            });
          }
        } else {
          // User already counted in this session, just update the activity timestamp
          localStorage.setItem('last_active_timestamp', Date.now().toString());
        }
      } catch (err) {
        console.error('Error tracking web user:', err);
      }
    };
    
    // Track web user
    trackUniqueWebUser();
    
    // Set up heartbeat to maintain active status
    const heartbeat = setInterval(() => {
      localStorage.setItem('last_active_timestamp', Date.now().toString());
    }, 60000); // Every minute
    
    // Clean up on component unmount
    return () => {
      chatCountListener();
      webCountListener();
      clearInterval(heartbeat);
    };
  }, [currentUser]);
  
  // Function to manually reset counts (admin function)
  const resetCounts = async () => {
    if (!window.confirm('Are you sure you want to reset the user counters? This will set both counters to 0 and rebuild them as users return.')) {
      return;
    }
    
    setLoading(true);
    
    try {
      // Reset counts to 0
      const chatCountRef = ref(rtdb, 'userCount/chat');
      const webCountRef = ref(rtdb, 'userCount/web');
      
      await set(chatCountRef, 0);
      await set(webCountRef, 0);
      
      setChatUserCount(0);
      setWebUserCount(0);
      
      // Clear session storage so this user will be counted again
      sessionStorage.removeItem('web_user_counted');
      localStorage.removeItem('last_count_time');
      
      // Re-run the tracking function to count this user
      const currentTime = Date.now();
      localStorage.setItem('last_active_timestamp', currentTime.toString());
      localStorage.setItem('last_count_time', currentTime.toString());
      
      const webCountRef2 = ref(rtdb, 'userCount/web');
      await runTransaction(webCountRef2, (currentCount) => {
        return (currentCount || 0) + 1;
      });
      
    } catch (err) {
      console.error('Error resetting counts:', err);
      setError('Failed to reset user data');
    }
    
    setLoading(false);
  };
  
  // Total user count
  const totalUsers = chatUserCount + webUserCount;
  
  return (
    <div className="widget-content">
      {error ? (
        <div className="error-message">{error}</div>
      ) : (
        <div className="user-count-container">
          <div className="user-count-total">
            <h3 className="count-label">Total Users</h3>
            <div className="count-value">{loading ? '-' : totalUsers}</div>
          </div>
          
          <div className="user-count-grid">
            {/* Chat Users Count */}
            <div className="user-count-card chat-users">
              <div className="icon-container">
                <Users className="count-icon" />
              </div>
              <div className="count-value">{loading ? '-' : chatUserCount}</div>
              <div className="count-label">Chat Users</div>
            </div>
            
            {/* Web Users Count */}
            <div className="user-count-card web-users">
              <div className="icon-container">
                <Globe className="count-icon" />
              </div>
              <div className="count-value">{loading ? '-' : webUserCount}</div>
              <div className="count-label">Web Users</div>
            </div>
          </div>
          
          <div className="count-footer">
            <button 
              className="refresh-button" 
              onClick={resetCounts}
              disabled={loading}
            >
              {loading ? 'Resetting...' : 'Reset Counters'}
            </button>
            <div className="timestamp">
              Updated: {new Date().toLocaleTimeString()}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default UserWidget;