// src/services/sketchEngine.js
//
// The sound half of Jam Studio. Composition lives in melodyComposer.js; this
// module owns every Tone.js node and turns note events into audio.
//
//   const ctrl = await createSketchEngine();
//   const song = ctrl.generate({ style: 'lofi', keyName: 'F' });
//   await ctrl.play();
//   ctrl.setGroupVolume('melody', -3);
//   ctrl.stop(); ctrl.dispose();
//
// Signal flow (this is what makes it sound like a record rather than a demo):
//
//   voice ─► Channel(vol/pan) ─┬─► group gain ─► duck ─► master bus ─► glue comp
//                              ├─► reverb send ─────────► reverb return ─┘
//                              └─► delay send  ─────────► delay return  ─┘
//   master bus ─► glue comp ─► tone EQ ─► widener ─► limiter ─► out
//
// Reverb and delay are SENDS, not inserts, so the dry signal stays present and
// the drums don't get washed out by the pad's reverb. The kick ducks the
// low/mid groups, which is where the pumping "glue" of modern production
// comes from. Transport BPM is synced to the composition so tempo-relative
// delay times actually land on the beat — the old engine left it at 120.

import * as Tone from 'tone';

import composeSong, {
  SCALES,
  KEYS,
  STYLES,
  STYLE_KEYS,
  SCALE_LABELS,
  degreeToMidi,
  midiToNoteName,
  noteNameToMidi,
  trackGroup,
  TRACK_GROUPS,
  randomSeed,
} from './melodyComposer';

export { SCALES, KEYS, STYLES, STYLE_KEYS, SCALE_LABELS, TRACK_GROUPS, randomSeed };

/** Number of scale degrees the JamPad spans (two octaves of a 7-note scale). */
export const PAD_DEGREES = 14;

const dbToGain = (db) => Math.pow(10, db / 20);

/* ============================ Node graph ============================ */

async function buildEngine() {
  // ---- master chain ----
  const masterOut = new Tone.Gain(1).toDestination();
  const limiter = new Tone.Limiter(-1).connect(masterOut);
  const widener = new Tone.StereoWidener(0.35).connect(limiter);
  const toneEq = new Tone.EQ3({ low: 0, mid: 0, high: 0, lowFrequency: 250, highFrequency: 2800 }).connect(widener);
  const airFilter = new Tone.Filter({ type: 'lowpass', frequency: 14000, Q: 0.4 }).connect(toneEq);
  const glue = new Tone.Compressor({ threshold: -16, ratio: 2.5, attack: 0.012, release: 0.18 }).connect(airFilter);
  // Subsonic energy you can't hear still eats headroom and pumps the glue
  // compressor. Roll it off before the compressor ever sees it.
  const rumbleFilter = new Tone.Filter({ type: 'highpass', frequency: 32, Q: 0.7 }).connect(glue);
  const masterBus = new Tone.Gain(0.85).connect(rumbleFilter);

  // ---- FX returns (sends, not inserts) ----
  const reverb = new Tone.Reverb({ decay: 4.5, preDelay: 0.02, wet: 1 });
  const reverbTone = new Tone.Filter({ type: 'highpass', frequency: 320 }).connect(masterBus);
  reverb.connect(reverbTone);
  await reverb.ready;

  const delay = new Tone.FeedbackDelay({ delayTime: '8n.', feedback: 0.34, wet: 1 });
  const delayTone = new Tone.Filter({ type: 'lowpass', frequency: 3200 }).connect(masterBus);
  delay.connect(delayTone);

  // ---- group busses ----
  // Bass/chords/pad sit behind a duck node the kick pulls down.
  const duck = new Tone.Gain(1).connect(masterBus);
  const groups = {};
  const makeGroup = (name, ducked) => {
    const g = new Tone.Gain(1);
    g.connect(ducked ? duck : masterBus);
    groups[name] = g;
    return g;
  };
  makeGroup('melody', false);
  makeGroup('chords', true);
  makeGroup('arp', false);
  makeGroup('bass', true);
  makeGroup('pad', true);
  makeGroup('drums', false);
  makeGroup('fx', false);
  makeGroup('perf', false);

  const sendNodes = [];
  const groupChannels = {};
  /**
   * Wire a synth into a group with its own level, pan and FX sends.
   *
   * The sends hang off the channel's OUTPUT, not off the group bus, so muting
   * a channel silences its reverb and delay along with it. Muting the group
   * gain instead would leave the wet signal feeding the returns — a muted
   * track you can still hear.
   */
  const voice = (synth, { group, volume = 0, pan = 0, verb = -70, echo = -70 }) => {
    const channel = new Tone.Channel({ volume, pan }).connect(groups[group]);
    synth.connect(channel);
    if (verb > -60) {
      const s = new Tone.Gain(dbToGain(verb));
      channel.connect(s); s.connect(reverb); sendNodes.push(s);
    }
    if (echo > -60) {
      const s = new Tone.Gain(dbToGain(echo));
      channel.connect(s); s.connect(delay); sendNodes.push(s);
    }
    sendNodes.push(channel);
    (groupChannels[group] = groupChannels[group] || []).push({ channel, baseVolume: volume });
    return synth;
  };

  /* ---------------------------- Melody patches ----------------------------
   * Five characters for the lead. They're built lazily — a browser tab does
   * not need five polysynths alive to play one line.
   */
  const leadCache = {};
  const leadBuilders = {
    rhodes: () => voice(new Tone.PolySynth(Tone.FMSynth, {
      harmonicity: 3.01, modulationIndex: 7.5,
      oscillator: { type: 'sine' },
      envelope: { attack: 0.004, decay: 1.4, sustain: 0.12, release: 1.6 },
      modulation: { type: 'sine' },
      modulationEnvelope: { attack: 0.004, decay: 0.35, sustain: 0, release: 0.4 },
    }), { group: 'melody', volume: -9, verb: -15, echo: -19 }),

    saw: () => {
      const s = new Tone.PolySynth(Tone.Synth, {
        oscillator: { type: 'fatsawtooth', count: 3, spread: 22 },
        envelope: { attack: 0.015, decay: 0.28, sustain: 0.55, release: 0.5 },
      });
      const filt = new Tone.Filter({ type: 'lowpass', frequency: 3600, Q: 1.2 });
      const vib = new Tone.Vibrato({ frequency: 5.2, depth: 0.06 });
      s.chain(filt, vib);
      voice(vib, { group: 'melody', volume: -12, verb: -20, echo: -13 });
      return s;
    },

    pluck: () => {
      const s = new Tone.PolySynth(Tone.Synth, {
        oscillator: { type: 'triangle' },
        envelope: { attack: 0.002, decay: 0.22, sustain: 0.02, release: 0.35 },
      });
      const filt = new Tone.Filter({ type: 'lowpass', frequency: 4200, Q: 0.8 });
      s.connect(filt);
      voice(filt, { group: 'melody', volume: -8, verb: -16, echo: -11 });
      return s;
    },

    bell: () => voice(new Tone.PolySynth(Tone.FMSynth, {
      harmonicity: 5.02, modulationIndex: 11,
      oscillator: { type: 'sine' },
      envelope: { attack: 0.003, decay: 1.8, sustain: 0.05, release: 2.2 },
      modulation: { type: 'sine' },
      modulationEnvelope: { attack: 0.002, decay: 0.6, sustain: 0, release: 0.6 },
    }), { group: 'melody', volume: -13, verb: -9, echo: -12 }),

    voxlead: () => {
      const s = new Tone.PolySynth(Tone.AMSynth, {
        harmonicity: 2.5,
        oscillator: { type: 'sine' },
        envelope: { attack: 0.18, decay: 0.5, sustain: 0.75, release: 1.4 },
        modulation: { type: 'triangle' },
        modulationEnvelope: { attack: 0.4, decay: 0.4, sustain: 0.6, release: 1 },
      });
      const form = new Tone.Filter({ type: 'bandpass', frequency: 1100, Q: 1.1 });
      const vib = new Tone.Vibrato({ frequency: 4.6, depth: 0.12 });
      s.chain(form, vib);
      voice(vib, { group: 'melody', volume: -8, verb: -7, echo: -16 });
      return s;
    },
  };
  const getLead = (name) => {
    const key = leadBuilders[name] ? name : 'rhodes';
    if (!leadCache[key]) leadCache[key] = leadBuilders[key]();
    return leadCache[key];
  };

  /* ---------------------------- Accompaniment ---------------------------- */

  const chords = new Tone.PolySynth(Tone.FMSynth, {
    harmonicity: 2, modulationIndex: 3.2,
    oscillator: { type: 'sine' },
    envelope: { attack: 0.012, decay: 1.6, sustain: 0.22, release: 1.5 },
    modulation: { type: 'sine' },
    modulationEnvelope: { attack: 0.01, decay: 0.5, sustain: 0, release: 0.5 },
  });
  const chordFilter = new Tone.Filter({ type: 'lowpass', frequency: 2800, Q: 0.5 });
  const chordChorus = new Tone.Chorus({ frequency: 0.6, delayTime: 3.5, depth: 0.5, wet: 0.4 }).start();
  chords.chain(chordFilter, chordChorus);
  voice(chordChorus, { group: 'chords', volume: -13, verb: -13, echo: -21 });

  const pad = new Tone.PolySynth(Tone.Synth, {
    oscillator: { type: 'fatsawtooth', count: 3, spread: 40 },
    envelope: { attack: 1.8, decay: 1.5, sustain: 0.85, release: 4 },
  });
  // Base frequency of 0 so the LFO alone drives the cutoff — a slow, breathing
  // filter is most of what makes a pad feel alive rather than static.
  const padFilter = new Tone.Filter({ type: 'lowpass', frequency: 0, Q: 0.6 });
  const padLfo = new Tone.LFO({ frequency: 0.06, min: 700, max: 2400 }).start();
  padLfo.connect(padFilter.frequency);
  pad.connect(padFilter);
  voice(padFilter, { group: 'pad', volume: -21, verb: -4, echo: -24 });

  const arp = new Tone.PolySynth(Tone.Synth, {
    oscillator: { type: 'triangle' },
    envelope: { attack: 0.004, decay: 0.2, sustain: 0.08, release: 0.3 },
  });
  const arpFilter = new Tone.Filter({ type: 'lowpass', frequency: 5000, Q: 0.6 });
  arp.connect(arpFilter);
  voice(arpFilter, { group: 'arp', volume: -18, pan: 0.22, verb: -16, echo: -9 });

  // Bass = sine sub for weight + a filtered saw for definition on small speakers.
  const bassSub = new Tone.MonoSynth({
    oscillator: { type: 'sine' },
    envelope: { attack: 0.012, decay: 0.3, sustain: 0.85, release: 0.25 },
    filterEnvelope: { attack: 0.01, decay: 0.2, sustain: 1, release: 0.2, baseFrequency: 200, octaves: 0 },
    portamento: 0.02,
  });
  // The sub carries weight, not level. Sitting it well under the melody keeps
  // the low end felt rather than heard — it was 8dB hotter than this and
  // swallowed everything above it.
  voice(bassSub, { group: 'bass', volume: -14 });

  const bassBody = new Tone.MonoSynth({
    oscillator: { type: 'sawtooth' },
    envelope: { attack: 0.008, decay: 0.22, sustain: 0.5, release: 0.2 },
    filterEnvelope: { attack: 0.01, decay: 0.18, sustain: 0.35, release: 0.2, baseFrequency: 110, octaves: 2.4 },
    filter: { type: 'lowpass', Q: 1.4 },
    portamento: 0.02,
  });
  voice(bassBody, { group: 'bass', volume: -23 });

  const vox = new Tone.PolySynth(Tone.AMSynth, {
    harmonicity: 1.5,
    oscillator: { type: 'sine' },
    envelope: { attack: 1.6, decay: 1, sustain: 0.7, release: 3 },
    modulation: { type: 'sine' },
    modulationEnvelope: { attack: 1, decay: 0.5, sustain: 0.5, release: 2 },
  });
  const voxFilter = new Tone.Filter({ type: 'bandpass', frequency: 1200, Q: 1 });
  vox.connect(voxFilter);
  voice(voxFilter, { group: 'pad', volume: -22, verb: -3 });

  /* ------------------------------- Drums ------------------------------- */

  const kick = new Tone.MembraneSynth({
    pitchDecay: 0.042, octaves: 5.5,
    oscillator: { type: 'sine' },
    envelope: { attack: 0.001, decay: 0.42, sustain: 0.01, release: 0.35 },
  });
  voice(kick, { group: 'drums', volume: -5, verb: -34 });

  const snareNoise = new Tone.NoiseSynth({
    noise: { type: 'white' },
    envelope: { attack: 0.001, decay: 0.16, sustain: 0, release: 0.06 },
  });
  const snareFilter = new Tone.Filter({ type: 'bandpass', frequency: 2100, Q: 0.9 });
  snareNoise.connect(snareFilter);
  voice(snareFilter, { group: 'drums', volume: -14, verb: -13, echo: -30 });

  const snareBody = new Tone.MembraneSynth({
    pitchDecay: 0.02, octaves: 2,
    envelope: { attack: 0.001, decay: 0.12, sustain: 0, release: 0.1 },
  });
  voice(snareBody, { group: 'drums', volume: -20 });

  const hat = new Tone.NoiseSynth({
    noise: { type: 'white' },
    envelope: { attack: 0.001, decay: 0.038, sustain: 0, release: 0.02 },
  });
  const hatFilter = new Tone.Filter({ type: 'highpass', frequency: 9000 });
  hat.connect(hatFilter);
  voice(hatFilter, { group: 'drums', volume: -22, pan: -0.18, verb: -28 });

  /* ------------------------- Transition FX -------------------------
   * Risers, impacts and downlifters. These aren't decoration — a section
   * boundary without one reads as an edit rather than an arrival.
   */

  // Noise sweep: the filter is automated per event, so one voice covers both
  // the riser (sweeping up into a drop) and the downlifter (falling away).
  const sweepFilter = new Tone.Filter({ type: 'bandpass', frequency: 400, Q: 1.6 });
  const sweep = new Tone.NoiseSynth({
    noise: { type: 'white' },
    envelope: { attack: 1, decay: 0.1, sustain: 1, release: 0.35 },
    volume: -26,
  }).connect(sweepFilter);
  voice(sweepFilter, { group: 'fx', volume: -6, verb: -10, echo: -22 });

  const impact = new Tone.NoiseSynth({
    noise: { type: 'white' },
    envelope: { attack: 0.001, decay: 1.8, sustain: 0, release: 0.6 },
    volume: -20,
  });
  const impactFilter = new Tone.Filter({ type: 'highpass', frequency: 500 });
  impact.connect(impactFilter);
  voice(impactFilter, { group: 'fx', volume: -8, verb: -4, echo: -24 });

  /* -------------------- Live performance (JamPad) -------------------- */

  // All three live instruments share one filter so the pad's Y axis has a
  // single, consistent brightness control to move.
  const perfFilter = new Tone.Filter({ type: 'lowpass', frequency: 4000, Q: 0.8 });
  voice(perfFilter, { group: 'perf', volume: -4, verb: -14, echo: -13 });

  const perfGlide = new Tone.FMSynth({
    harmonicity: 2, modulationIndex: 6, portamento: 0.055,
    oscillator: { type: 'sine' },
    envelope: { attack: 0.03, decay: 0.3, sustain: 0.72, release: 0.7 },
    modulation: { type: 'triangle' },
    modulationEnvelope: { attack: 0.25, decay: 0.4, sustain: 0.4, release: 0.7 },
    volume: -8,
  });
  const perfVib = new Tone.Vibrato({ frequency: 4.8, depth: 0.08 });
  perfGlide.chain(perfVib, perfFilter);

  const perfKeys = new Tone.PolySynth(Tone.Synth, {
    oscillator: { type: 'triangle' },
    envelope: { attack: 0.006, decay: 0.28, sustain: 0.22, release: 0.5 },
    volume: -9,
  }).connect(perfFilter);

  const perfBass = new Tone.MonoSynth({
    oscillator: { type: 'square' },
    envelope: { attack: 0.015, decay: 0.2, sustain: 0.6, release: 0.3 },
    filterEnvelope: { attack: 0.02, decay: 0.3, sustain: 0.4, release: 0.3, baseFrequency: 120, octaves: 3 },
    portamento: 0.04,
    volume: -8,
  }).connect(perfFilter);

  return {
    nodes: {
      masterOut, masterBus, limiter, widener, toneEq, airFilter, glue, duck, rumbleFilter,
      reverb, reverbTone, delay, delayTone,
      chords, chordFilter, chordChorus, pad, padFilter, padLfo, arp, arpFilter,
      bassSub, bassBody, vox, voxFilter,
      kick, snareNoise, snareFilter, snareBody, hat, hatFilter,
      sweep, sweepFilter, impact, impactFilter,
      perfGlide, perfVib, perfKeys, perfBass, perfFilter,
    },
    extras: sendNodes,
    groups,
    groupChannels,
    leadCache,
    getLead,
  };
}

/* ============================ Controller ============================ */

/** Legacy palette / mute keys from earlier versions of the studio. */
const LEGACY_PALETTE = { sub: 'bass', poly: 'arp', lead: 'melody', voice: 'pad' };

export async function createSketchEngine() {
  await Tone.start();
  const transport = Tone.getTransport();
  const eng = await buildEngine();

  let currentSketch = null;
  let scheduledIds = [];
  let onTick = null;
  let tickRAF = null;
  let isPlaying = false;
  let loopEnabled = true;
  let leadPatch = 'rhodes';
  let version = 0;

  const groupMuted = {};
  const groupVolume = {};
  TRACK_GROUPS.concat(['perf']).forEach(g => { groupMuted[g] = false; groupVolume[g] = 0; });

  // Mute is expressed as volume, not Channel.mute: Tone implements `mute` by
  // writing the channel's own volume param, so a mute followed by a volume
  // ramp silently cancels itself. Ramping to SILENT_DB does both jobs, and the
  // short ramp avoids a click.
  const SILENT_DB = -90;

  function applyGroupGain(group) {
    (eng.groupChannels[group] || []).forEach(({ channel, baseVolume }) => {
      const db = groupMuted[group] ? SILENT_DB : baseVolume + groupVolume[group];
      channel.volume.rampTo(db, 0.03);
    });
  }

  /* ---------------- Theory (shared with the JamPad) ---------------- */

  const theory = {
    keyName: 'A', scaleName: 'minor', tempo: 90, lead: 'rhodes',
    rootMidi: noteNameToMidi('A3'),
  };

  function setTheory({ keyName, scaleName, tempo, lead } = {}) {
    if (keyName) theory.keyName = keyName;
    if (scaleName && SCALES[scaleName]) theory.scaleName = scaleName;
    if (tempo) {
      theory.tempo = tempo;
      transport.bpm.value = tempo;   // keeps '8n.' delays on the grid
    }
    // The lead patch travels with the jam — otherwise a published sketch plays
    // back on a different instrument than the one it was written on.
    if (lead) { theory.lead = lead; leadPatch = lead; eng.getLead(lead); }
    theory.rootMidi = noteNameToMidi(theory.keyName + '3');
  }

  function getTheory() {
    const scale = SCALES[theory.scaleName] || SCALES.minor;
    const degrees = [];
    for (let d = 0; d < PAD_DEGREES; d++) {
      const midi = degreeToMidi(theory.rootMidi, scale, d);
      degrees.push({ degree: d, midi, note: midiToNoteName(midi) });
    }
    return { ...theory, degrees };
  }

  /* ---------------- Generation ---------------- */

  function generate(opts = {}) {
    version += 1;
    const palette = (opts.palette || ['melody', 'chords', 'bass', 'drums', 'arp'])
      .map(k => LEGACY_PALETTE[k] || k);

    const song = composeSong({ ...opts, palette });
    song.version = version;
    currentSketch = song;

    setTheory({
      keyName: song.keyName, scaleName: song.scaleName,
      tempo: song.tempo, lead: song.lead,
    });
    applyGroupGain('melody');         // a lazily-built patch inherits the mixer

    applyTone(song.params);
    return song;
  }

  /** Brightness/tension shape the master tone rather than a blunt lowpass. */
  function applyTone(params = {}) {
    const brightness = params.brightness ?? 50;
    eng.nodes.airFilter.frequency.rampTo(2200 + (brightness / 100) * 14000, 0.6);
    eng.nodes.toneEq.high.rampTo(-6 + (brightness / 100) * 9, 0.6);
    eng.nodes.toneEq.low.rampTo(2 - (brightness / 100) * 2.5, 0.6);
    // Move the pad's LFO window rather than its base cutoff — the LFO owns it.
    eng.nodes.padLfo.min = 450 + (brightness / 100) * 700;
    eng.nodes.padLfo.max = 1400 + (brightness / 100) * 3400;
  }

  /* ---------------- Playback ---------------- */

  function stop() {
    transport.stop();
    transport.loop = false;
    scheduledIds.forEach(id => transport.clear(id));
    scheduledIds = [];
    isPlaying = false;
    if (tickRAF) cancelAnimationFrame(tickRAF);
    tickRAF = null;
    // Kill anything still ringing so a restart is clean.
    try {
      Object.values(eng.leadCache).forEach(s => s.releaseAll && s.releaseAll());
      eng.nodes.chords.releaseAll();
      eng.nodes.pad.releaseAll();
      eng.nodes.arp.releaseAll();
      eng.nodes.vox.releaseAll();
      eng.nodes.bassSub.triggerRelease();
      eng.nodes.bassBody.triggerRelease();
    } catch (_) { /* noop */ }
  }

  /** Pull the low/mid groups down on each kick — the "glue" pump. */
  function duckOn(time) {
    const g = eng.nodes.duck.gain;
    try {
      g.cancelScheduledValues(time);
      g.setValueAtTime(0.62, time);
      g.linearRampToValueAtTime(1, time + 0.16);
    } catch (_) { /* noop */ }
  }

  function triggerEvent(ev, time) {
    const n = eng.nodes;
    const notes = ev.notes && ev.notes.length ? ev.notes : null;
    const vel = ev.vel ?? 0.7;
    try {
      switch (ev.instr) {
        // --- melodic ---
        case 'melody':
        case 'lead':
          eng.getLead(leadPatch).triggerAttackRelease(notes, ev.dur, time, vel);
          break;
        case 'chords':
        case 'poly':
          n.chords.triggerAttackRelease(notes, ev.dur, time, vel);
          break;
        case 'arp':
          n.arp.triggerAttackRelease(notes, ev.dur, time, vel);
          break;
        case 'pad':
          n.pad.triggerAttackRelease(notes, ev.dur, time, vel);
          break;
        case 'voice':
          n.vox.triggerAttackRelease(notes, ev.dur, time, vel);
          break;
        case 'bass':
        case 'sub':
          n.bassSub.triggerAttackRelease(notes[0], ev.dur, time, vel);
          n.bassBody.triggerAttackRelease(notes[0], ev.dur, time, vel * 0.9);
          break;

        // --- drums ---
        case 'kick':
          n.kick.triggerAttackRelease(notes ? notes[0] : 'C1', ev.dur || 0.25, time, vel);
          duckOn(time);
          break;
        case 'snare':
        case 'clap':
          n.snareNoise.triggerAttackRelease(ev.dur || 0.12, time, vel);
          n.snareBody.triggerAttackRelease('D2', 0.08, time, vel * 0.6);
          break;
        case 'ghost':
          n.snareNoise.triggerAttackRelease(0.05, time, vel * 0.55);
          break;
        case 'hat':
        case 'ride':
          n.hat.triggerAttackRelease(ev.dur || 0.04, time, vel);
          break;

        // --- transition FX ---
        case 'riser':
        case 'downlifter': {
          const dur = Math.max(0.3, ev.dur || 1);
          const [from, to] = ev.instr === 'riser' ? [280, 7000] : [6000, 240];
          const f = n.sweepFilter.frequency;
          f.cancelScheduledValues(time);
          f.setValueAtTime(from, time);
          f.exponentialRampToValueAtTime(to, time + dur);
          // Swell in over the sweep for a riser, fall away for a downlifter.
          n.sweep.envelope.attack = ev.instr === 'riser' ? dur * 0.9 : 0.02;
          n.sweep.envelope.release = ev.instr === 'riser' ? 0.15 : dur * 0.8;
          n.sweep.triggerAttackRelease(dur, time, vel);
          break;
        }
        case 'impact':
          n.impact.triggerAttackRelease(ev.dur || 1.8, time, vel);
          break;

        // --- captured live takes ---
        case 'perf-glide': n.perfGlide.triggerAttackRelease(notes[0], ev.dur, time, vel); break;
        case 'perf-keys':  n.perfKeys.triggerAttackRelease(notes, ev.dur, time, vel); break;
        case 'perf-bass':  n.perfBass.triggerAttackRelease(notes[0], ev.dur, time, vel); break;
        default: break;
      }
    } catch (_) { /* one bad event must not stop the song */ }
  }

  function scheduleAndPlay(eventList, duration) {
    stop();
    transport.position = 0;

    eventList.forEach(({ ev, layerId }) => {
      const id = transport.schedule((time) => {
        if (layerId && layerMuted.has(layerId)) return;
        triggerEvent(ev, time);
      }, ev.t);
      scheduledIds.push(id);
    });

    if (loopEnabled) {
      transport.loop = true;
      transport.loopStart = 0;
      transport.loopEnd = duration;
    } else {
      transport.loop = false;
      scheduledIds.push(transport.schedule(() => {
        stop();
        onTick && onTick({ elapsed: duration, pct: 1, ended: true });
      }, duration + 0.4));
    }

    transport.start();
    isPlaying = true;

    const tick = () => {
      if (!isPlaying) return;
      const elapsed = transport.seconds;
      onTick && onTick({ elapsed, pct: Math.min(1, elapsed / duration), ended: false });
      tickRAF = requestAnimationFrame(tick);
    };
    tick();
  }

  async function play() {
    if (!currentSketch) return;
    scheduleAndPlay(
      currentSketch.events.map(ev => ({ ev, layerId: null })),
      currentSketch.duration || 30,
    );
  }

  /* ---------------- Layered jam playback ---------------- */

  let currentLayers = [];
  let layerDuration = null;
  const layerMuted = new Set();

  /**
   * @param explicitDuration exact loop length in seconds. Pass it when the
   *   layers came from a composed song — the last note usually stops short of
   *   the final bar line, so a duration inferred from the events would loop
   *   early and cut the bar off.
   */
  function loadLayers(layers, jamTheory, explicitDuration) {
    currentLayers = layers || [];
    layerDuration = explicitDuration || null;
    layerMuted.clear();
    if (jamTheory) setTheory(jamTheory);
  }

  function jamDuration() {
    if (layerDuration) return layerDuration;
    let end = 0;
    currentLayers.forEach(l => l.events.forEach(e => { end = Math.max(end, e.t + (e.dur || 0)); }));
    return Math.max(5, Math.min(180, Math.ceil(end)));
  }

  async function playLayers() {
    if (!currentLayers.length) return;
    const flat = [];
    currentLayers.forEach(l => l.events.forEach(ev => flat.push({ ev, layerId: l.id })));
    flat.sort((a, b) => a.ev.t - b.ev.t);
    scheduleAndPlay(flat, jamDuration());
  }

  function setLayerMuted(layerId, muted) {
    if (muted) layerMuted.add(layerId); else layerMuted.delete(layerId);
  }

  /* ---------------- Live performance (JamPad) ---------------- */

  const PERF_SYNTH = { glide: 'perfGlide', keys: 'perfKeys', bass: 'perfBass' };
  let activePerf = null;
  let capturing = false;
  let captureStart = 0;
  let capturedEvents = [];
  let openCapture = null;

  function padToNote(x) {
    const scale = SCALES[theory.scaleName] || SCALES.minor;
    const degree = Math.max(0, Math.min(PAD_DEGREES - 1, Math.floor(x * PAD_DEGREES)));
    const midi = degreeToMidi(theory.rootMidi, scale, degree);
    return { degree, note: midiToNoteName(midi) };
  }

  function expressionFromY(y) {
    const clamped = Math.max(0, Math.min(1, y));
    return { vel: 0.25 + clamped * 0.65, filterFreq: 500 + clamped * 6500 };
  }

  function nowCaptureTime() {
    if (transport.state === 'started') return transport.seconds;
    return (Date.now() - captureStart) / 1000;
  }

  function closeOpenCapture() {
    if (!openCapture) return;
    const dur = Math.max(0.08, nowCaptureTime() - openCapture.t);
    capturedEvents.push({
      t: Math.round(openCapture.t * 1000) / 1000,
      instr: openCapture.instr,
      notes: [openCapture.note],
      dur: Math.round(Math.min(dur, 8) * 1000) / 1000,
      vel: Math.round(openCapture.vel * 100) / 100,
    });
    openCapture = null;
  }

  function perfStart(instr, x, y) {
    const synthKey = PERF_SYNTH[instr] || 'perfGlide';
    const { degree, note } = padToNote(x);
    const { vel, filterFreq } = expressionFromY(y);
    eng.nodes.perfFilter.frequency.rampTo(filterFreq, 0.05);
    try { eng.nodes[synthKey].triggerAttack(note, undefined, vel); } catch (_) { /* noop */ }
    activePerf = { instr, synthKey, degree, note, vel };
    if (capturing) {
      closeOpenCapture();
      openCapture = { t: nowCaptureTime(), instr: `perf-${instr}`, note, vel };
    }
    return { degree, note };
  }

  function perfMove(x, y) {
    if (!activePerf) return null;
    const { degree, note } = padToNote(x);
    const { vel, filterFreq } = expressionFromY(y);
    eng.nodes.perfFilter.frequency.rampTo(filterFreq, 0.05);
    if (degree !== activePerf.degree) {
      const synth = eng.nodes[activePerf.synthKey];
      try {
        if (activePerf.instr === 'keys') synth.triggerAttackRelease(note, 0.25, undefined, vel);
        else synth.setNote(note);       // portamento glide
      } catch (_) { /* noop */ }
      activePerf.degree = degree;
      activePerf.note = note;
      activePerf.vel = vel;
      if (capturing) {
        closeOpenCapture();
        openCapture = { t: nowCaptureTime(), instr: `perf-${activePerf.instr}`, note, vel };
      }
    }
    return { degree, note };
  }

  function perfEnd() {
    if (!activePerf) return;
    const synth = eng.nodes[activePerf.synthKey];
    try {
      if (activePerf.instr === 'keys') synth.releaseAll();
      else synth.triggerRelease();
    } catch (_) { /* noop */ }
    if (capturing) closeOpenCapture();
    activePerf = null;
  }

  function startCapture() {
    capturedEvents = [];
    openCapture = null;
    capturing = true;
    captureStart = Date.now();
  }

  function stopCapture() {
    closeOpenCapture();
    capturing = false;
    return capturedEvents.slice();
  }

  /* ---------------- Mixer ---------------- */

  function setGroupVolume(group, db) {
    if (!(group in groupVolume)) return;
    groupVolume[group] = db;
    applyGroupGain(group);
  }

  function setGroupMuted(group, muted) {
    if (!(group in groupMuted)) return;
    groupMuted[group] = muted;
    applyGroupGain(group);
  }

  /** Legacy: toggleMute('sub'|'pad'|'poly'|'lead'|'voice'|'drums'). */
  function toggleMute(key) {
    const group = LEGACY_PALETTE[key] || key;
    if (!(group in groupMuted)) return false;
    groupMuted[group] = !groupMuted[group];
    applyGroupGain(group);
    return groupMuted[group];
  }

  function setLoop(on) {
    loopEnabled = !!on;
    if (isPlaying) {
      transport.loop = loopEnabled;
      if (loopEnabled && currentSketch) {
        transport.loopStart = 0;
        transport.loopEnd = currentSketch.duration;
      }
    }
  }

  function setLead(name) {
    setTheory({ lead: name });
    applyGroupGain('melody');
  }

  /* ---------------- Streaming tap ---------------- */

  let mediaStreamDest = null;
  function getMediaStream() {
    if (!mediaStreamDest) {
      const raw = Tone.getContext().rawContext;
      mediaStreamDest = raw.createMediaStreamDestination();
      // Tap the post-limiter master so the stream matches what's in the room.
      Tone.connect(eng.nodes.masterOut, mediaStreamDest);
    }
    return mediaStreamDest.stream;
  }

  function setOnTick(fn) { onTick = fn; }

  function dispose() {
    stop();
    const all = [
      ...Object.values(eng.nodes),
      ...Object.values(eng.groups),
      ...Object.values(eng.leadCache),
      ...eng.extras,
    ];
    all.forEach(n => { try { n && n.dispose && n.dispose(); } catch (_) { /* noop */ } });
  }

  return {
    generate,
    play,
    stop,
    setOnTick,
    dispose,
    isPlaying: () => isPlaying,
    getSketch: () => currentSketch,
    // Mixer
    toggleMute,
    getMutes: () => ({ ...groupMuted }),
    setGroupVolume,
    setGroupMuted,
    getGroupVolumes: () => ({ ...groupVolume }),
    setLoop,
    isLooping: () => loopEnabled,
    setLead,
    getLead: () => leadPatch,
    // Theory
    getTheory,
    setTheory,
    // Layered jam playback
    loadLayers,
    playLayers,
    setLayerMuted,
    jamDuration,
    // Live performance
    perfStart,
    perfMove,
    perfEnd,
    startCapture,
    stopCapture,
    isCapturing: () => capturing,
    // Streaming
    getMediaStream,
  };
}

/**
 * Split a composed song into per-instrument layers so it can be mixed with
 * live takes and persisted as a jam.
 */
export function sketchToLayers(sketch) {
  const byGroup = {};
  sketch.events.forEach(e => {
    const g = trackGroup(e.instr);
    if (!g) return;
    (byGroup[g] = byGroup[g] || []).push({
      t: e.t, instr: e.instr, notes: e.notes || [], dur: e.dur, vel: e.vel,
    });
  });
  const stamp = Date.now().toString(36);
  return Object.keys(byGroup).map(g => ({
    id: `gen-${g}-${stamp}-${Math.random().toString(36).slice(2, 7)}`,
    kind: 'generated',
    label: g,
    instr: g,
    events: byGroup[g],
  }));
}

export default createSketchEngine;
