/**
 * TipManager Service
 * Handles tip processing, environment detection, and Stripe integration
 * Path: C:\Users\Tom\Documents\GitHub\presence-react3\presence-react\src\services\TipManager.js
 */

import { 
  getFirestore, 
  doc, 
  getDoc, 
  setDoc, 
  updateDoc, 
  collection, 
  addDoc, 
  serverTimestamp, 
  query, 
  where, 
  getDocs 
} from 'firebase/firestore';
import { getCurrentTipConfig, TIPPING_RULES, EVENT_TYPES } from '../config/tipConfig.js';

class TipManager {
  constructor() {
    this.db = getFirestore();
    this.tipConfig = getCurrentTipConfig();
    console.log('🎁 TipManager initialized with config:', this.tipConfig);
  }

  /**
   * Check if tipping is enabled for a specific event
   * @param {Object} event - Event object
   * @returns {Object} { enabled, reason, eventType }
   */
  checkTippingEligibility(event) {
    if (!event) {
      return { enabled: false, reason: 'Event not found', eventType: null };
    }

    // Determine event type based on event properties
    let eventType = EVENT_TYPES.FREE;
    
    if (event.ticketPrice && event.ticketPrice > 0) {
      eventType = EVENT_TYPES.REGISTERED;
    }
    
    if (event.isVIPEvent || event.eventType === 'vip') {
      eventType = EVENT_TYPES.VIP;
    }
    
    // Check if event is explicitly marked as free
    if (event.isFree === true || event.eventType === 'free') {
      eventType = EVENT_TYPES.FREE;
    }

    const rules = TIPPING_RULES[eventType];
    
    console.log('🎫 Tipping eligibility check:', {
      eventId: event.id,
      eventType,
      ticketPrice: event.ticketPrice,
      isVIP: event.isVIPEvent,
      isFree: event.isFree,
      rules
    });

    return {
      enabled: rules.enabled && this.tipConfig.enabled,
      reason: rules.reason,
      eventType,
      environment: this.tipConfig.name
    };
  }

  /**
   * Get Stripe URL for a specific tip amount
   * @param {number} amount - Tip amount (20, 50, or 100)
   * @returns {string} Stripe URL
   */
  getStripeUrl(amount) {
    const urls = this.tipConfig.stripeUrls;
    
    switch (amount) {
      case 20:
        return urls.tip20;
      case 50:
        return urls.tip50;
      case 100:
        return urls.tip100;
      default:
        console.warn(`⚠️ Invalid tip amount: ${amount}, using default`);
        return urls.tip20;
    }
  }

  /**
   * Create a tip record in Firestore
   * @param {Object} tipData - Tip information
   * @returns {Promise<Object>} Tip record
   */
  async createTipRecord(tipData) {
    try {
      const tipRecord = {
        ...tipData,
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
        status: 'pending',
        environment: this.tipConfig.name,
        useSandbox: this.tipConfig.useSandbox
      };

      const docRef = await addDoc(collection(this.db, 'tips'), tipRecord);
      
      console.log('💰 Tip record created:', {
        id: docRef.id,
        ...tipRecord
      });

      return {
        id: docRef.id,
        ...tipRecord
      };
    } catch (error) {
      console.error('❌ Failed to create tip record:', error);
      throw error;
    }
  }

  /**
   * Update tip record status
   * @param {string} tipId - Tip record ID
   * @param {string} status - New status
   * @param {Object} additionalData - Additional data to update
   */
  async updateTipStatus(tipId, status, additionalData = {}) {
    try {
      const tipRef = doc(this.db, 'tips', tipId);
      await updateDoc(tipRef, {
        status,
        updatedAt: serverTimestamp(),
        ...additionalData
      });

      console.log('📝 Tip status updated:', { tipId, status, ...additionalData });
    } catch (error) {
      console.error('❌ Failed to update tip status:', error);
      throw error;
    }
  }

  /**
   * Get tip statistics for an event
   * @param {string} eventId - Event ID
   * @returns {Promise<Object>} Tip statistics
   */
  async getEventTipStats(eventId) {
    try {
      const tipsQuery = query(
        collection(this.db, 'tips'),
        where('eventId', '==', eventId),
        where('status', '==', 'completed')
      );

      const tipsSnapshot = await getDocs(tipsQuery);
      const tips = tipsSnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));

      const stats = {
        totalTips: tips.length,
        totalAmount: tips.reduce((sum, tip) => sum + tip.amount, 0),
        averageAmount: tips.length > 0 ? tips.reduce((sum, tip) => sum + tip.amount, 0) / tips.length : 0,
        uniqueTippers: new Set(tips.map(tip => tip.userId)).size,
        tips: tips
      };

      console.log('📊 Event tip stats:', { eventId, stats });
      return stats;
    } catch (error) {
      console.error('❌ Failed to get tip stats:', error);
      return {
        totalTips: 0,
        totalAmount: 0,
        averageAmount: 0,
        uniqueTippers: 0,
        tips: []
      };
    }
  }

  /**
   * Get artist tip statistics
   * @param {string} artistId - Artist user ID
   * @returns {Promise<Object>} Artist tip statistics
   */
  async getArtistTipStats(artistId) {
    try {
      const tipsQuery = query(
        collection(this.db, 'tips'),
        where('artistId', '==', artistId),
        where('status', '==', 'completed')
      );

      const tipsSnapshot = await getDocs(tipsQuery);
      const tips = tipsSnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));

      const stats = {
        totalTips: tips.length,
        totalAmount: tips.reduce((sum, tip) => sum + tip.amount, 0),
        totalEvents: new Set(tips.map(tip => tip.eventId)).size,
        averagePerTip: tips.length > 0 ? tips.reduce((sum, tip) => sum + tip.amount, 0) / tips.length : 0,
        uniqueTippers: new Set(tips.map(tip => tip.userId)).size,
        tips: tips
      };

      console.log('👩‍🎨 Artist tip stats:', { artistId, stats });
      return stats;
    } catch (error) {
      console.error('❌ Failed to get artist tip stats:', error);
      return {
        totalTips: 0,
        totalAmount: 0,
        totalEvents: 0,
        averagePerTip: 0,
        uniqueTippers: 0,
        tips: []
      };
    }
  }

  /**
   * Get venue tip statistics
   * @param {string} venueId - Venue ID
   * @returns {Promise<Object>} Venue tip statistics
   */
  async getVenueTipStats(venueId) {
    try {
      const tipsQuery = query(
        collection(this.db, 'tips'),
        where('venueId', '==', venueId),
        where('status', '==', 'completed')
      );

      const tipsSnapshot = await getDocs(tipsQuery);
      const tips = tipsSnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));

      const stats = {
        totalTips: tips.length,
        totalAmount: tips.reduce((sum, tip) => sum + tip.amount, 0),
        totalEvents: new Set(tips.map(tip => tip.eventId)).size,
        averagePerTip: tips.length > 0 ? tips.reduce((sum, tip) => sum + tip.amount, 0) / tips.length : 0,
        uniqueTippers: new Set(tips.map(tip => tip.userId)).size,
        tips: tips
      };

      console.log('🏛️ Venue tip stats:', { venueId, stats });
      return stats;
    } catch (error) {
      console.error('❌ Failed to get venue tip stats:', error);
      return {
        totalTips: 0,
        totalAmount: 0,
        totalEvents: 0,
        averagePerTip: 0,
        uniqueTippers: 0,
        tips: []
      };
    }
  }

  /**
   * Update global tip statistics
   * @param {Object} tipData - Tip data to add to global stats
   */
  async updateGlobalStats(tipData) {
    try {
      const statsRef = doc(this.db, 'admin', 'tipStats');
      const statsDoc = await getDoc(statsRef);
      
      let currentStats = {
        totalTips: 0,
        totalVolume: 0,
        platformRevenue: 0,
        artistRevenue: 0,
        venueRevenue: 0,
        todayTips: 0,
        todayVolume: 0,
        lastUpdated: Date.now()
      };

      if (statsDoc.exists()) {
        currentStats = { ...currentStats, ...statsDoc.data() };
      }

      // Calculate revenue splits (these should come from admin settings)
      const platformSplit = tipData.amount * 0.30; // 30%
      const artistSplit = tipData.amount * 0.50;   // 50%
      const venueSplit = tipData.amount * 0.20;    // 20%

      const updatedStats = {
        ...currentStats,
        totalTips: currentStats.totalTips + 1,
        totalVolume: currentStats.totalVolume + tipData.amount,
        platformRevenue: currentStats.platformRevenue + platformSplit,
        artistRevenue: currentStats.artistRevenue + artistSplit,
        venueRevenue: currentStats.venueRevenue + venueSplit,
        lastUpdated: Date.now()
      };

      // Update today's stats if same day
      const today = new Date().toDateString();
      const lastUpdateDate = new Date(currentStats.lastUpdated || 0).toDateString();
      
      if (today === lastUpdateDate) {
        updatedStats.todayTips = currentStats.todayTips + 1;
        updatedStats.todayVolume = currentStats.todayVolume + tipData.amount;
      } else {
        updatedStats.todayTips = 1;
        updatedStats.todayVolume = tipData.amount;
      }

      await setDoc(statsRef, updatedStats);
      console.log('📈 Global tip stats updated:', updatedStats);
    } catch (error) {
      console.error('❌ Failed to update global stats:', error);
    }
  }

  /**
   * Process tip completion (called when Stripe payment succeeds)
   * @param {string} tipId - Tip record ID
   * @param {Object} paymentData - Payment data from Stripe
   */
  async completeTip(tipId, paymentData) {
    try {
      // Update tip status
      await this.updateTipStatus(tipId, 'completed', {
        stripePaymentId: paymentData.paymentId,
        stripeCustomerId: paymentData.customerId,
        completedAt: Date.now()
      });

      // Get the tip record
      const tipRef = doc(this.db, 'tips', tipId);
      const tipDoc = await getDoc(tipRef);
      
      if (tipDoc.exists()) {
        const tipData = tipDoc.data();
        
        // Update global statistics
        await this.updateGlobalStats(tipData);
        
        console.log('✅ Tip completed successfully:', { tipId, tipData });
        return { success: true, tipData };
      }

      throw new Error('Tip record not found');
    } catch (error) {
      console.error('❌ Failed to complete tip:', error);
      throw error;
    }
  }

  /**
   * Get formatted tip amounts for display
   * @returns {Array} Formatted tip amounts
   */
  getFormattedAmounts() {
    return this.tipConfig.amounts.map(amount => ({
      amount,
      formatted: `$${amount}`,
      url: this.getStripeUrl(amount)
    }));
  }

  /**
   * Check if user can tip (not anonymous)
   * @param {Object} user - Current user object
   * @returns {boolean} Can user tip
   */
  canUserTip(user) {
    return user && user.uid;
  }
}

// Export singleton instance
export default new TipManager();
