// src/components/monetization/WalletTopUp.jsx
import React, { useState, useEffect } from 'react';
import { CardElement, useStripe, useElements } from '@stripe/react-stripe-js';
import { useWallet } from '../../contexts/WalletContext';
import { useAuth } from '../../contexts/AuthContext';
import { 
  CreditCard, 
  DollarSign, 
  AlertTriangle, 
  CheckCircle, 
  X, 
  Wallet 
} from 'lucide-react';
import './WalletTopUp.css';

const WalletTopUp = ({ isOpen, onClose, onSuccess }) => {
  const stripe = useStripe();
  const elements = useElements();
  const { currentUser } = useAuth();
  const { loadWallet, error: walletError, clearError } = useWallet();
  
  const [processing, setProcessing] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(false);
  const [selectedAmount, setSelectedAmount] = useState(10);
  const [customAmount, setCustomAmount] = useState('');
  
  // Preset amounts
  const presetAmounts = [5, 10, 25, 50, 100];
  
  // Reset form when modal opens/closes
  useEffect(() => {
    if (isOpen) {
      setSelectedAmount(10);
      setCustomAmount('');
      setError(null);
      setSuccess(false);
      clearError();
    }
  }, [isOpen, clearError]);

  // Handle custom amount input
  const handleCustomAmountChange = (e) => {
    const value = e.target.value;
    if (value === '' || /^\d*\.?\d{0,2}$/.test(value)) {
      setCustomAmount(value);
      setSelectedAmount(0); // Deselect preset amounts
    }
  };

  // Calculate final amount
  const finalAmount = customAmount ? parseFloat(customAmount) : selectedAmount;

  // Handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!stripe || !elements) {
      setError('Payment system not loaded. Please try again.');
      return;
    }

    if (!currentUser || currentUser.isAnonymous) {
      setError('You must be logged in to add money to your wallet.');
      return;
    }

    if (isNaN(finalAmount) || finalAmount < 1) {
      setError('Please enter an amount of at least $1.00');
      return;
    }

    if (finalAmount > 500) {
      setError('Maximum top-up amount is $500.00');
      return;
    }

    setProcessing(true);
    setError(null);
    
    try {
      const cardElement = elements.getElement(CardElement);
      
      // Create payment method
      const { error: paymentError, paymentMethod } = await stripe.createPaymentMethod({
        type: 'card',
        card: cardElement,
        billing_details: {
          name: currentUser.displayName || currentUser.email,
          email: currentUser.email
        }
      });

      if (paymentError) {
        throw new Error(paymentError.message);
      }

      // In a production app, you would:
      // 1. Send the payment method to your backend
      // 2. Create a payment intent with Stripe
      // 3. Confirm the payment
      // 4. Update the wallet on success

      // For demo purposes, we'll simulate a successful payment
      console.log('Simulating payment processing...');
      
      // Simulate API delay
      await new Promise(resolve => setTimeout(resolve, 2000));
      
      // Load the wallet (this would happen after successful payment)
      const result = await loadWallet(
        finalAmount,
        paymentMethod.id,
        `demo_pi_${Date.now()}` // Demo payment intent ID
      );

      console.log('Wallet loaded successfully:', result);
      
      setSuccess(true);
      
      // Call success callback
      if (onSuccess) {
        onSuccess(result);
      }

      // Close modal after delay
      setTimeout(() => {
        onClose();
      }, 2000);
      
    } catch (err) {
      console.error('Error processing payment:', err);
      setError(err.message || 'Failed to process payment. Please try again.');
    } finally {
      setProcessing(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="wallet-topup-overlay">
      <div className="wallet-topup-modal">
        <div className="topup-header">
          <div className="header-content">
            <Wallet size={24} />
            <h2>Add Money to Wallet</h2>
          </div>
          <button 
            className="close-btn"
            onClick={onClose}
            disabled={processing}
          >
            <X size={20} />
          </button>
        </div>

        {success ? (
          <div className="success-screen">
            <CheckCircle size={64} className="success-icon" />
            <h3>Payment Successful!</h3>
            <p>${finalAmount.toFixed(2)} has been added to your wallet.</p>
            <div className="success-actions">
              <button className="primary-btn" onClick={onClose}>
                Continue
              </button>
            </div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="topup-form">
            <div className="amount-selection">
              <label className="form-label">Select Amount</label>
              <div className="amount-presets">
                {presetAmounts.map(amount => (
                  <button
                    key={amount}
                    type="button"
                    className={`amount-btn ${selectedAmount === amount && !customAmount ? 'selected' : ''}`}
                    onClick={() => {
                      setSelectedAmount(amount);
                      setCustomAmount('');
                    }}
                  >
                    ${amount}
                  </button>
                ))}
              </div>
              
              <div className="custom-amount-input">
                <label className="custom-label">Custom Amount</label>
                <div className="amount-input-wrapper">
                  <span className="currency-symbol">$</span>
                  <input
                    type="text"
                    placeholder="0.00"
                    value={customAmount}
                    onChange={handleCustomAmountChange}
                    className={`amount-input ${customAmount ? 'active' : ''}`}
                  />
                </div>
              </div>
            </div>

            <div className="payment-info">
              <label className="form-label">Payment Information</label>
              <div className="card-element-container">
                <CardElement 
                  options={{
                    style: {
                      base: {
                        fontSize: '16px',
                        color: '#ffffff',
                        fontFamily: 'system-ui, -apple-system, sans-serif',
                        '::placeholder': {
                          color: '#9CA3AF',
                        },
                      },
                      invalid: {
                        color: '#EF4444',
                      },
                    },
                  }}
                />
              </div>
            </div>

            <div className="payment-summary">
              <div className="summary-row">
                <span>Amount to add:</span>
                <span className="amount">${finalAmount ? finalAmount.toFixed(2) : '0.00'}</span>
              </div>
              <div className="summary-row total">
                <span>Total charge:</span>
                <span className="amount">${finalAmount ? finalAmount.toFixed(2) : '0.00'}</span>
              </div>
            </div>

            {(error || walletError) && (
              <div className="error-message">
                <AlertTriangle size={16} />
                <p>{error || walletError}</p>
              </div>
            )}

            <div className="form-actions">
              <button 
                type="button"
                className="secondary-btn"
                onClick={onClose}
                disabled={processing}
              >
                Cancel
              </button>
              <button 
                type="submit"
                className="primary-btn"
                disabled={processing || !stripe || !finalAmount || finalAmount < 1}
              >
                {processing ? (
                  <div className="processing-content">
                    <div className="spinner"></div>
                    Processing...
                  </div>
                ) : (
                  <div className="button-content">
                    <CreditCard size={16} />
                    Add ${finalAmount ? finalAmount.toFixed(2) : '0.00'}
                  </div>
                )}
              </button>
            </div>

            <div className="security-notice">
              <p>🔒 Your payment information is secure and encrypted.</p>
            </div>
          </form>
        )}
      </div>
    </div>
  );
};

export default WalletTopUp;