// src/firebase/performance-init.js
// Safe initialization of Firebase Performance Monitoring

import { getApp } from 'firebase/app';
import { getPerformance, trace } from 'firebase/performance';

// Store active traces
const activeTraces = new Map();

/**
 * Initialize Firebase Performance Monitoring safely
 * @returns {Object|null} Firebase Performance instance or null if initialization fails
 */
export const initializePerformance = () => {
  try {
    // Get the Firebase app instance
    const app = getApp();
    
    // Initialize Performance Monitoring
    const performance = getPerformance(app);
    
    console.log('Firebase Performance initialized successfully');
    
    return performance;
  } catch (error) {
    console.warn('Error initializing Firebase Performance:', error);
    return null;
  }
};

/**
 * Create a performance trace
 * @param {string} traceName - Name of the trace
 * @returns {Object|null} - Trace object or null if creation fails
 */
export const createTrace = (traceName) => {
  try {
    // Check if Performance is available
    const performance = initializePerformance();
    if (!performance) {
      console.debug(`[Performance] Firebase Performance not available for trace: ${traceName}`);
      return null;
    }
    
    // Create the trace
    const traceObj = trace(performance, traceName);
    
    // Store it for reference
    activeTraces.set(traceName, traceObj);
    
    return traceObj;
  } catch (error) {
    console.warn(`[Performance] Error creating trace ${traceName}:`, error);
    return null;
  }
};

/**
 * Start a performance trace
 * @param {string} traceName - Name of the trace to start
 * @returns {Object|null} - The trace object or null if creation fails
 */
export const startTrace = (traceName) => {
  try {
    // Create a trace
    const traceObj = createTrace(traceName);
    if (!traceObj) {
      return null;
    }
    
    // Start the trace
    console.debug(`⏱️ Started: ${traceName}`);
    traceObj.start();
    
    return traceObj;
  } catch (error) {
    console.warn(`[Performance] Error starting trace ${traceName}:`, error);
    return null;
  }
};

/**
 * Stop a performance trace
 * @param {string} traceName - Name of the trace to stop
 */
export const stopTrace = (traceName) => {
  try {
    // Get the trace
    const traceObj = activeTraces.get(traceName);
    if (!traceObj) {
      console.debug(`[Performance] No active trace found for: ${traceName}`);
      return;
    }
    
    // Stop the trace
    traceObj.stop();
    
    // Remove from active traces
    activeTraces.delete(traceName);
    
    console.debug(`🟢 Completed: ${traceName}`);
  } catch (error) {
    console.warn(`[Performance] Error stopping trace ${traceName}:`, error);
    // Remove from active traces even if there was an error
    activeTraces.delete(traceName);
  }
};

/**
 * Record a performance trace for an async operation
 * @param {string} traceName - Name of the trace
 * @param {Function} asyncFn - Async function to execute
 * @returns {Promise<any>} - Result of the async function
 */
export const traceAsync = async (traceName, asyncFn) => {
  const traceObj = startTrace(traceName);
  
  try {
    // Execute the async function
    const result = await asyncFn();
    
    // Stop the trace
    if (traceObj) {
      stopTrace(traceName);
    }
    
    return result;
  } catch (error) {
    // Stop the trace even if there's an error
    if (traceObj) {
      stopTrace(traceName);
    }
    
    // Re-throw the error
    throw error;
  }
};

/**
 * Create a timing context that can be used with async/await
 * @param {string} traceName - Name of the trace to start
 * @returns {Object} - A timing context object with done() method
 */
export const createTimingContext = (traceName) => {
  const traceObj = startTrace(traceName);
  
  return {
    traceName,
    startTime: Date.now(),
    done: () => {
      try {
        if (traceObj) {
          stopTrace(traceName);
        }
        return Date.now() - this.startTime;
      } catch (error) {
        console.warn(`[Performance] Error in timing context for ${traceName}:`, error);
        return 0;
      }
    }
  };
};

/**
 * Get all active timing traces
 * @returns {Array} Array of trace names
 */
export const getAllTimings = () => {
  return Array.from(activeTraces.keys());
};

/**
 * Clear all active timing traces
 */
export const clearTimings = () => {
  try {
    // Get all active trace names
    const traceNames = Array.from(activeTraces.keys());
    
    // Stop each trace
    traceNames.forEach(traceName => {
      try {
        stopTrace(traceName);
      } catch (err) {
        console.warn(`[Performance] Error clearing trace ${traceName}:`, err);
      }
    });
    
    // Clear all active traces
    activeTraces.clear();
    
    console.debug(`[Performance] Cleared all ${traceNames.length} traces`);
  } catch (error) {
    console.warn('[Performance] Error clearing traces:', error);
  }
};

export default {
  initializePerformance,
  createTrace,
  startTrace,
  stopTrace,
  traceAsync,
  createTimingContext,
  getAllTimings,
  clearTimings
};
