// src/predict/contexts/AuthContext.jsx
//
// Shim: adapts TalkStudio's AuthContext to the shape Predict components expect.
// Predict code used `{ currentUser, isAdmin, login, logout }`.
// TalkStudio uses `{ currentUser, userRole, logout, loading, ... }`.

import { useAuth as useTalkStudioAuth } from '../../contexts/AuthContext';

export const useAuth = () => {
  const ts = useTalkStudioAuth();
  const currentUser = ts.currentUser;

  // Predict used a mock user shape with `.id` and `.isAdmin`.
  // Adapt Firebase user -> Predict-shaped object.
  const adapted = currentUser
    ? {
        ...currentUser,
        id: currentUser.uid,
        isAdmin: ts.userRole === 'admin',
      }
    : null;

  return {
    currentUser: adapted,
    isAdmin: ts.userRole === 'admin',
    login: () => {
      // Not used in Predict Pass 1. TalkStudio handles auth via its own flow.
      console.warn('Predict login() called — use TalkStudio auth instead.');
    },
    logout: ts.logout,
  };
};
