import {
  TrendingUp, Disc3, Trophy, Ticket,
  Star, Radio, Users, Flame
} from 'lucide-react'

// Music & culture prediction categories.
// Predict is a forecasting layer for the music/art community on the platform.
// Each category is a slice of the music world that fans, artists, and labels
// actively bet on: chart movement, release timing, awards, touring, breakouts,
// scene/genre momentum, collaborations, and cultural virality.
//
// Legacy category ids from earlier themes (news + real-estate dealmaker) are
// kept as aliases at the bottom so existing mock/in-flight predictions still
// resolve to a sensible music category.

export const categories = [
  { id: 'charts',       label: 'Charts & Streaming',   icon: TrendingUp, color: 'bg-blue-500',    textColor: 'text-blue-400',    borderColor: 'border-blue-500' },
  { id: 'releases',     label: 'Releases & Drops',     icon: Disc3,      color: 'bg-violet-500',  textColor: 'text-violet-400',  borderColor: 'border-violet-500' },
  { id: 'awards',       label: 'Awards & Recognition', icon: Trophy,     color: 'bg-amber-500',   textColor: 'text-amber-400',   borderColor: 'border-amber-500' },
  { id: 'touring',      label: 'Touring & Live',       icon: Ticket,     color: 'bg-emerald-500', textColor: 'text-emerald-400', borderColor: 'border-emerald-500' },
  { id: 'breakouts',    label: 'Artist Breakouts',     icon: Star,       color: 'bg-pink-500',    textColor: 'text-pink-400',    borderColor: 'border-pink-500' },
  { id: 'scene_trends', label: 'Genre & Scene Trends', icon: Radio,      color: 'bg-cyan-500',    textColor: 'text-cyan-400',    borderColor: 'border-cyan-500' },
  { id: 'collabs',      label: 'Collabs & Features',   icon: Users,      color: 'bg-orange-500',  textColor: 'text-orange-400',  borderColor: 'border-orange-500' },
  { id: 'culture',      label: 'Culture & Virality',   icon: Flame,      color: 'bg-red-500',     textColor: 'text-red-400',     borderColor: 'border-red-500' },
]

// Map legacy ids (original news theme + real-estate dealmaker theme) → music
// ids so existing data still renders. Remove once all data is migrated.
const LEGACY_ALIASES = {
  // Real-estate dealmaker theme
  capital_markets: 'charts',
  rates:           'charts',
  cap_rates:       'charts',
  local_economies: 'touring',
  demographics:    'scene_trends',
  regulation:      'culture',
  climate_risk:    'culture',
  construction:    'releases',
  // Original news/events theme
  politics:        'culture',
  economics:       'charts',
  sports:          'touring',
  entertainment:   'awards',
  tech:            'releases',
  science:         'breakouts',
  weather:         'culture',
  geopolitics:     'culture',
}

export function getCategoryById(id) {
  const resolved = LEGACY_ALIASES[id] ?? id
  return categories.find(c => c.id === resolved) || categories[0]
}

export function getCategoryColor(id) {
  const cat = getCategoryById(id)
  return { bg: cat.color, text: cat.textColor, border: cat.borderColor }
}
