// Enhanced Event Status Management Service
// Path: src/services/events/EventStatusManager.js

import { doc, getDoc, updateDoc, collection, query, where, getDocs, onSnapshot, serverTimestamp } from 'firebase/firestore';
import { ref, set, get, update, serverTimestamp as rtdbServerTimestamp } from 'firebase/database';
import { db, rtdb } from '../../firebase';

class EventStatusManager {
  constructor() {
    this.statusCheckInterval = null;
    this.STATUS_CHECK_FREQUENCY = 30 * 1000; // Check every 30 seconds
    this.LIVE_WINDOW_BUFFER = 5 * 60 * 1000; // 5 minutes before scheduled start
    this.AUTO_END_BUFFER = 15 * 60 * 1000; // Auto-end 15 minutes after scheduled end
    this.eventListeners = new Map(); // eventId -> unsubscribe function
    this.isInitialized = false;

    console.log('🎯 EventStatusManager created (monitoring will start when Firebase is ready)');

    // Delay initialization to allow Firebase to initialize first
    setTimeout(() => {
      this.startStatusMonitoring();
    }, 2000);
  }

  /**
   * Start monitoring event statuses
   */
  startStatusMonitoring() {
    if (this.statusCheckInterval) {
      clearInterval(this.statusCheckInterval);
    }

    // Run initial check
    this.checkAllEventStatuses();

    // Set up periodic checking
    this.statusCheckInterval = setInterval(() => {
      this.checkAllEventStatuses();
    }, this.STATUS_CHECK_FREQUENCY);

    console.log('🔄 Event status monitoring started (every 30 seconds)');
  }

  /**
   * Stop monitoring event statuses
   */
  stopStatusMonitoring() {
    if (this.statusCheckInterval) {
      clearInterval(this.statusCheckInterval);
      this.statusCheckInterval = null;
    }

    // Cancel all event listeners
    for (const [eventId, unsubscribe] of this.eventListeners) {
      unsubscribe();
    }
    this.eventListeners.clear();

    console.log('⏹️ Event status monitoring stopped');
  }

  /**
   * Check all events and update their status based on time
   */
  async checkAllEventStatuses() {
    try {

      // Check if Firebase is initialized
      let db;
      try {
        db = getFirestore();
      } catch (error) {
        if (!this.isInitialized) {
          console.log('⏳ Firebase not ready yet, skipping status check');
          return;
        }
        throw error;
      }

      this.isInitialized = true;
      const now = Date.now();

      console.log('🔍 Checking event statuses...');

      // Get all events that might need status updates
      const eventsQuery = query(
        collection(db, 'events'),
        where('status', 'in', ['scheduled', 'live'])
      );

      const eventsSnapshot = await getDocs(eventsQuery);
      
      const statusUpdates = [];

      for (const eventDoc of eventsSnapshot.docs) {
        const eventData = eventDoc.data();
        const eventId = eventDoc.id;
        const currentStatus = eventData.status;
        
        const startTime = eventData.startTime;
        const endTime = eventData.endTime;
        
        // Convert Firebase timestamps to milliseconds
        const startMs = this.getTimestamp(startTime);
        const endMs = endTime ? this.getTimestamp(endTime) : null;
        
        // Calculate if event should be live based on time windows
        const shouldBeLive = this.shouldEventBeLive(startMs, endMs, now);
        const shouldBeEnded = this.shouldEventBeEnded(startMs, endMs, now);

        let newStatus = null;
        let reason = '';

        // Determine what the status should be
        if (shouldBeEnded && currentStatus !== 'ended') {
          newStatus = 'ended';
          reason = 'auto-ended (past end time + buffer)';
        } else if (shouldBeLive && currentStatus === 'scheduled') {
          newStatus = 'live';
          reason = 'auto-started (within live window)';
        } else if (!shouldBeLive && currentStatus === 'live' && !eventData.manuallyStarted) {
          // Only auto-end live events that were auto-started (not manually started by creator)
          if (now > startMs + (2 * 60 * 60 * 1000)) { // 2 hours after scheduled start
            newStatus = 'ended';
            reason = 'auto-ended (timeout after 2 hours)';
          }
        }

        // Queue status update if needed
        if (newStatus && newStatus !== currentStatus) {
          statusUpdates.push({
            eventId,
            eventData,
            currentStatus,
            newStatus,
            reason,
            startMs,
            endMs,
            now
          });
        }
      }

      // Execute all status updates
      for (const update of statusUpdates) {
        await this.updateEventStatus(update);
      }

      if (statusUpdates.length > 0) {
        console.log(`✅ Updated ${statusUpdates.length} event statuses`);
      } else {
        console.log('📊 No event status updates needed');
      }

    } catch (error) {
      console.error('❌ Failed to check event statuses:', error);
    }
  }

  /**
   * Update a single event's status
   */
  async updateEventStatus({ eventId, eventData, currentStatus, newStatus, reason, startMs, endMs, now }) {
    try {
      console.log(`🔄 Updating event ${eventId}: ${currentStatus} → ${newStatus} (${reason})`);

      // Prepare update data
      const updateData = {
        status: newStatus,
        lastStatusUpdate: serverTimestamp(),
        statusUpdateReason: reason,
        autoUpdated: true,
        updatedAt: serverTimestamp()
      };

      // Add specific timestamps based on new status
      if (newStatus === 'live') {
        updateData.actualStartTime = now;
        updateData.streamStartTime = now;
        updateData.lastActivityTime = now;
        updateData.activityGracePeriod = 30 * 60 * 1000; // 30 minutes grace period
      } else if (newStatus === 'ended') {
        updateData.actualEndTime = now;
        updateData.endReason = 'auto_timeout';
      }

      // Update in Firestore
      const eventRef = doc(db, 'events', eventId);
      await updateDoc(eventRef, updateData);

      // Update activity tracking in RTDB if going live
      if (newStatus === 'live') {
        const activityRef = ref(rtdb, `eventActivity/${eventId}`);
        const activityData = {
          eventId,
          status: 'live',
          startTime: now,
          lastHeartbeat: now,
          endTime: endMs,
          gracePeriod: 30 * 60 * 1000,
          isActive: true,
          viewerCount: 0,
          streamQuality: 'pending',
          autoStarted: true
        };

        await set(activityRef, activityData);
        console.log(`🎯 Created activity tracking for auto-started event ${eventId}`);
      }

      console.log(`✅ Event ${eventId} status updated successfully`);

    } catch (error) {
      console.error(`❌ Failed to update event ${eventId} status:`, error);
    }
  }

  /**
   * Check if event should be live based on time windows
   */
  shouldEventBeLive(startMs, endMs, now) {
    if (!startMs) return false;

    // Event should be live if:
    // 1. We're within the buffer time before start (5 minutes early)
    // 2. OR we're after start time
    // 3. AND we're before end time (if specified) + buffer
    
    const liveWindowStart = startMs - this.LIVE_WINDOW_BUFFER;
    const liveWindowEnd = endMs ? endMs + this.AUTO_END_BUFFER : startMs + (2 * 60 * 60 * 1000); // Default 2 hours

    return now >= liveWindowStart && now <= liveWindowEnd;
  }

  /**
   * Check if event should be ended
   */
  shouldEventBeEnded(startMs, endMs, now) {
    if (!startMs) return false;

    // Event should be ended if:
    // 1. We have an end time and we're past end time + buffer
    // 2. OR we're more than 3 hours past start time (fallback)
    
    if (endMs) {
      return now > endMs + this.AUTO_END_BUFFER;
    } else {
      // Fallback: auto-end 3 hours after start
      return now > startMs + (3 * 60 * 60 * 1000);
    }
  }

  /**
   * Convert various timestamp formats to milliseconds
   */
  getTimestamp(value) {
    if (!value) return null;

    // Firebase Timestamp
    if (value.toDate) {
      return value.toDate().getTime();
    }

    // Already milliseconds
    if (typeof value === 'number') {
      return value;
    }

    // Seconds (convert to milliseconds)
    if (typeof value === 'number' && value < 10000000000) {
      return value * 1000;
    }

    // String timestamp
    if (typeof value === 'string') {
      const parsed = parseInt(value);
      if (!isNaN(parsed)) {
        return parsed < 10000000000 ? parsed * 1000 : parsed;
      }
    }

    console.warn('⚠️ Could not parse timestamp:', value);
    return null;
  }

  /**
   * Force status check for a specific event
   */
  async checkEventStatus(eventId) {
    try {
      const eventRef = doc(db, 'events', eventId);
      const eventDoc = await getDoc(eventRef);

      if (!eventDoc.exists()) {
        console.log(`⚠️ Event ${eventId} not found`);
        return null;
      }

      const eventData = eventDoc.data();
      const currentStatus = eventData.status;
      const now = Date.now();

      const startMs = this.getTimestamp(eventData.startTime);
      const endMs = eventData.endTime ? this.getTimestamp(eventData.endTime) : null;

      const shouldBeLive = this.shouldEventBeLive(startMs, endMs, now);
      const shouldBeEnded = this.shouldEventBeEnded(startMs, endMs, now);

      console.log(`🔍 Event ${eventId} status check:`, {
        currentStatus,
        shouldBeLive,
        shouldBeEnded,
        startTime: new Date(startMs),
        endTime: endMs ? new Date(endMs) : null,
        now: new Date(now)
      });

      let newStatus = null;
      let reason = '';

      if (shouldBeEnded && currentStatus !== 'ended') {
        newStatus = 'ended';
        reason = 'manual check - past end time';
      } else if (shouldBeLive && currentStatus === 'scheduled') {
        newStatus = 'live';
        reason = 'manual check - within live window';
      }

      if (newStatus) {
        await this.updateEventStatus({
          eventId,
          eventData,
          currentStatus,
          newStatus,
          reason,
          startMs,
          endMs,
          now
        });
      }

      return {
        eventId,
        currentStatus,
        newStatus,
        shouldBeLive,
        shouldBeEnded,
        reason
      };

    } catch (error) {
      console.error(`❌ Failed to check event ${eventId} status:`, error);
      return null;
    }
  }

  /**
   * Cleanup and dispose
   */
  dispose() {
    this.stopStatusMonitoring();
    console.log('🧹 EventStatusManager disposed');
  }
}

// Export singleton instance
export const eventStatusManager = new EventStatusManager();
export default eventStatusManager;

// Make available globally for debugging
if (typeof window !== 'undefined') {
  window.eventStatusManager = eventStatusManager;
}
