// src/services/melodyComposer.js
//
// The composition brain behind Jam Studio. Pure JS — no Tone.js, no DOM —
// so it can be reasoned about (and tested) on its own.
//
// The old engine built a "melody" out of a random walk: every note picked an
// independent random step, all notes were quarter notes, and nothing ever
// repeated. That can't produce a tune, because a tune is repetition with
// variation. This module composes the way a songwriter does:
//
//   1. Write a one-bar MOTIF   — a rhythm cell + a pitch shape.
//   2. Build a 4-bar PHRASE    — motif, variation, motif, cadence.
//   3. Build a FORM            — intro / A / A' / B / A'' with an energy arc.
//   4. Harmonise it            — voice-led chords, a bassline that follows the
//                                roots, an optional arpeggio counter-line.
//   5. Perform it              — groove + swing + velocity phrasing + humanised
//                                timing, so it doesn't sound like a grid.
//
// Everything is driven by a seeded RNG, so a sketch you like can be recalled
// exactly (same seed + same settings = same song) and "vary" can move one knob
// without throwing the whole piece away.
//
//   const song = composeSong({ style: 'lofi', keyName: 'F', bars: 20 });
//   song.events  // [{ t, instr, notes: ['C4'], midi, dur, vel }, ...]
//   song.melody  // just the melody events, for the piano roll
//
// Event objects stay in the { t, instr, notes, dur, vel } shape the jam
// persistence layer already stores, so published jams keep working.

/* ============================== Theory ============================== */

const STEPS_PER_BAR = 16; // 16th-note grid, 4/4
const NOTE_NAMES = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];

export const KEYS = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];

export const SCALES = {
  minor:      [0, 2, 3, 5, 7, 8, 10],
  dorian:     [0, 2, 3, 5, 7, 9, 10],
  phrygian:   [0, 1, 3, 5, 7, 8, 10],
  harmonic:   [0, 2, 3, 5, 7, 8, 11],
  major:      [0, 2, 4, 5, 7, 9, 11],
  mixolydian: [0, 2, 4, 5, 7, 9, 10],
  lydian:     [0, 2, 4, 6, 7, 9, 11],
};

export const SCALE_LABELS = {
  minor: 'minor', dorian: 'dorian', phrygian: 'phrygian',
  harmonic: 'harmonic minor', major: 'major',
  mixolydian: 'mixolydian', lydian: 'lydian',
};

export function midiToNoteName(midi) {
  const m = Math.round(midi);
  return NOTE_NAMES[((m % 12) + 12) % 12] + (Math.floor(m / 12) - 1);
}

export function noteNameToMidi(name) {
  const match = /^([A-G]#?)(-?\d+)$/.exec(name);
  if (!match) return 60;
  return NOTE_NAMES.indexOf(match[1]) + 12 * (parseInt(match[2], 10) + 1);
}

/** Map a scale-degree index (may be negative or beyond one octave) to MIDI. */
export function degreeToMidi(rootMidi, scale, degree) {
  const n = scale.length;
  const oct = Math.floor(degree / n);
  const idx = ((degree % n) + n) % n;
  return rootMidi + scale[idx] + 12 * oct;
}

/* ============================== RNG ============================== */

/** Deterministic PRNG — same seed always yields the same song. */
function makeRng(seed) {
  let a = (seed >>> 0) || 1;
  const next = () => {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  return {
    next,
    int: (n) => Math.floor(next() * n),
    pick: (arr) => arr[Math.floor(next() * arr.length)],
    chance: (p) => next() < p,
    range: (lo, hi) => lo + next() * (hi - lo),
  };
}

export function randomSeed() {
  return Math.floor(Math.random() * 0xFFFFFF);
}

