/* ========================== Rhythm vocabulary ========================== */
//
// Each cell is a bar of [startStep, lengthInSteps]. Rests are the gaps.
// Cells are grouped by how busy they are so density can choose a bank.

const RHYTHM_CELLS = {
  sparse: [
    [[0, 8], [8, 8]],
    [[0, 12]],
    [[0, 6], [8, 8]],
    [[4, 4], [8, 8]],
    [[0, 4], [6, 10]],
  ],
  medium: [
    [[0, 4], [4, 4], [8, 4], [12, 4]],
    [[0, 4], [6, 2], [8, 4], [12, 4]],
    [[0, 2], [2, 2], [4, 4], [10, 6]],
    [[0, 6], [6, 2], [8, 6], [14, 2]],
    [[0, 3], [3, 3], [6, 2], [8, 8]],
    [[0, 4], [4, 2], [6, 2], [8, 8]],
  ],
  busy: [
    [[0, 2], [2, 2], [4, 2], [6, 2], [8, 4], [12, 2], [14, 2]],
    [[0, 2], [3, 1], [4, 2], [6, 2], [8, 2], [11, 1], [12, 4]],
    [[0, 3], [3, 3], [6, 2], [8, 3], [11, 3], [14, 2]],
    [[0, 2], [2, 2], [4, 4], [8, 2], [10, 2], [12, 2], [14, 2]],
  ],
};

// Bar 4 of a phrase: longer notes, room to breathe, lands the line.
const CADENCE_CELLS = [
  [[0, 8], [8, 8]],
  [[0, 4], [4, 12]],
  [[0, 16]],
  [[0, 6], [6, 10]],
  [[0, 4], [4, 4], [8, 8]],
];

function rhythmBank(density) {
  if (density < 0.4) return RHYTHM_CELLS.sparse;
  if (density < 0.72) return RHYTHM_CELLS.medium;
  return RHYTHM_CELLS.busy;
}

/* ========================== Chord progressions ========================== */
//
// Degrees are scale-degree indices: 0 = tonic triad, 5 = submediant, etc.
// The triad on degree d is {d, d+2, d+4} within the current scale, so the
// qualities come out right for whichever mode is selected.

const PROGRESSIONS_MINORISH = [
  [0, 5, 2, 6],   // i - VI - III - VII   (the workhorse)
  [0, 3, 5, 4],   // i - iv - VI - v
  [0, 6, 5, 6],   // i - VII - VI - VII
  [0, 2, 5, 4],   // i - III - VI - v
  [5, 6, 0, 0],   // VI - VII - i
  [0, 3, 6, 2],   // i - iv - VII - III
  [0, 5, 3, 4],   // i - VI - iv - v
];

const PROGRESSIONS_MAJORISH = [
  [0, 4, 5, 3],   // I - V - vi - IV
  [0, 3, 4, 4],   // I - IV - V
  [5, 3, 0, 4],   // vi - IV - I - V
  [0, 5, 3, 4],   // I - vi - IV - V
  [0, 1, 4, 0],   // I - ii - V - I
];

function progressionsFor(scaleName) {
  return (scaleName === 'major' || scaleName === 'lydian' || scaleName === 'mixolydian')
    ? PROGRESSIONS_MAJORISH
    : PROGRESSIONS_MINORISH;
}

/* ========================== Melodic construction ========================== */

const CONTOURS = {
  arch:   (p) => Math.sin(Math.PI * p),
  fall:   (p) => 1 - p,
  rise:   (p) => p,
  valley: (p) => -Math.sin(Math.PI * p),
  wave:   (p) => Math.sin(2 * Math.PI * p) * 0.8,
};

const isBeat = (step) => step % 4 === 0;
const isDownbeat = (step) => step === 0 || step === 8;

/**
 * A motif is a rhythm cell plus a pitch shape expressed in scale degrees,
 * relative to the phrase's home degree. Rendering it over a chord snaps the
 * beat-aligned notes to that chord's tones, so the same shape stays singable
 * as the harmony moves underneath it — that's a musical sequence, and it's
 * what makes a line feel composed rather than stumbled into.
 */
function makeMotif(rng, { density, span, contourName }) {
  const cell = rng.pick(rhythmBank(density));
  const contour = CONTOURS[contourName] || CONTOURS.arch;
  const notes = [];
  let prev = 0;
  let lastLeap = 0;

  cell.forEach(([step, len], i) => {
    const pos = cell.length > 1 ? i / (cell.length - 1) : 0;
    const target = Math.round(contour(pos) * span);
    let deg;

    if (isBeat(step)) {
      // Structural note: move TOWARD the contour target rather than jumping to
      // it. Walking the arc keeps the line singable; jumping to it every beat
      // is what turns a melody into a series of unrelated leaps.
      const desired = target + (rng.chance(0.3) ? rng.pick([-1, 1]) : 0);
      const reach = isDownbeat(step) ? 3 : 2;
      deg = i === 0 ? desired : prev + clamp(desired - prev, -reach, reach);
    } else if (lastLeap !== 0) {
      // Classic voice-leading: after a leap, step back the other way.
      deg = prev - Math.sign(lastLeap);
    } else {
      // Weak beat: mostly stepwise, occasionally a skip, rarely a repeat.
      const move = rng.chance(0.78) ? rng.pick([-1, 1])
        : rng.chance(0.6) ? rng.pick([-2, 2])
          : 0;
      deg = prev + move;
    }

    const leap = deg - prev;
    lastLeap = Math.abs(leap) >= 3 ? leap : 0;
    prev = deg;

    // Only the downbeats are hard anchors. If every beat had to be a chord
    // tone the line would collapse into an arpeggio — the colour of a melody
    // lives in the 2nds, 6ths and passing tones on the weaker beats.
    const anchor = isDownbeat(step) || (isBeat(step) && rng.chance(0.35));
    notes.push({ step, len, deg, anchor });
  });

  return { cell, notes, contourName };
}

/* --- motif transformations: how one idea becomes a whole section --- */

const transposeMotif = (m, n) => ({
  ...m, notes: m.notes.map(x => ({ ...x, deg: x.deg + n })),
});

const invertMotif = (m) => {
  const pivot = m.notes[0].deg;
  return { ...m, notes: m.notes.map(x => ({ ...x, deg: 2 * pivot - x.deg })) };
};

const retrogradeMotif = (m) => {
  const degs = m.notes.map(x => x.deg).reverse();
  return { ...m, notes: m.notes.map((x, i) => ({ ...x, deg: degs[i] })) };
};

/** Split the longest note in two — a small decoration that keeps interest up. */
const ornamentMotif = (m, rng) => {
  const notes = m.notes.map(x => ({ ...x }));
  let idx = 0;
  notes.forEach((n, i) => { if (n.len > notes[idx].len) idx = i; });
  const target = notes[idx];
  if (target.len < 4) return m;
  const half = Math.floor(target.len / 2);
  const added = {
    step: target.step + half, len: target.len - half,
    deg: target.deg + rng.pick([-1, 1, 2]), anchor: false,
  };
  target.len = half;
  notes.splice(idx + 1, 0, added);
  return { ...m, notes };
};

/** Drop some notes — how a busy idea answers itself quietly. */
const thinMotif = (m, rng, keep = 0.6) => ({
  ...m,
  notes: m.notes.filter((n, i) => i === 0 || n.anchor || rng.chance(keep)),
});

function varyMotif(motif, rng) {
  const how = rng.pick(['transpose', 'ornament', 'invert', 'thin', 'retrograde', 'transpose']);
  switch (how) {
    case 'transpose':  return transposeMotif(motif, rng.pick([-2, -1, 1, 2, 3]));
    case 'ornament':   return ornamentMotif(motif, rng);
    case 'invert':     return invertMotif(motif);
    case 'thin':       return thinMotif(motif, rng);
    case 'retrograde': return retrogradeMotif(motif);
    default:           return motif;
  }
}

/* ========================== Voicing ========================== */

function chordDegrees(degree, withSeventh) {
  const tones = [degree, degree + 2, degree + 4];
  if (withSeventh) tones.push(degree + 6);
  return tones;
}

/** Pick the inversion that moves least from the previous chord. */
function voiceChord(prev, midis, low = 50, high = 76) {
  const candidates = [];
  for (let inv = 0; inv <= midis.length; inv++) {
    for (let oct = -1; oct <= 1; oct++) {
      const v = midis
        .map((m, i) => m + (i < inv ? 12 : 0) + oct * 12)
        .sort((a, b) => a - b);
      if (v[0] >= low && v[v.length - 1] <= high) candidates.push(v);
    }
  }
  if (!candidates.length) return midis;
  if (!prev) {
    // No history: choose the voicing sitting nearest the middle of the window.
    const mid = (low + high) / 2;
    return candidates.reduce((best, c) =>
      Math.abs(avg(c) - mid) < Math.abs(avg(best) - mid) ? c : best);
  }
  const cost = (v) => v.reduce((s, n) => s + Math.min(...prev.map(p => Math.abs(p - n))), 0);
  return candidates.reduce((best, c) => (cost(c) < cost(best) ? c : best));
}

const avg = (a) => a.reduce((s, n) => s + n, 0) / a.length;

