function grooveFor(styleGroove, density) {
  if (density < 0.12) return 'none';
  if (density < 0.3 && styleGroove !== 'trap') return 'pulse';
  return styleGroove;
}

/* ========================== Form & arrangement ========================== */
//
// The arrangement matrix is what separates a song from a loop. Turning the
// same parts up and down just gives you a loop with dynamics — a breakdown is
// not a quieter drop, it's a drop with the kick and the bass TAKEN OUT. Parts
// leaving and coming back is the whole effect, and it's why a drop lands.
//
//   melody/chords/arp/bass/pad — false = silent, 'thin' = present but sparse
//   drums — 'none' | 'hats' | 'sparse' | 'build' | 'full'

const ARRANGEMENT = {
  intro:     { intensity: 0.30, melody: false,  chords: 'thin', arp: false, bass: false, pad: true, drums: 'hats' },
  breakdown: { intensity: 0.55, melody: true,   chords: true,   arp: false, bass: false, pad: true, drums: 'none' },
  build:     { intensity: 0.78, melody: 'thin', chords: true,   arp: true,  bass: false, pad: true, drums: 'build' },
  drop:      { intensity: 1.00, melody: true,   chords: true,   arp: true,  bass: true,  pad: true, drums: 'full' },
  outro:     { intensity: 0.42, melody: 'thin', chords: true,   arp: false, bass: true,  pad: true, drums: 'sparse' },
  // Loop mode keeps everything playing throughout — it's a sketchpad, not an
  // arrangement, and you want to hear all the parts while writing.
  loop:      { intensity: 0.85, melody: true,   chords: true,   arp: true,  bass: true,  pad: true, drums: 'full' },
};

// A radio edit: no DJ intro/outro, straight into the music, ~4 minutes.
// Weights are bars at the reference length and get scaled to hit the target.
const RADIO_PLAN = [
  { kind: 'intro',     weight: 8,  motif: 'A' },
  { kind: 'breakdown', weight: 16, motif: 'A' },
  { kind: 'build',     weight: 8,  motif: 'A' },
  { kind: 'drop',      weight: 16, motif: 'A' },
  { kind: 'breakdown', weight: 16, motif: 'B' },   // second half contrasts
  { kind: 'build',     weight: 8,  motif: 'B' },
  { kind: 'drop',      weight: 32, motif: 'B' },   // the main event
  { kind: 'outro',     weight: 16, motif: 'A' },
];

const RADIO_TARGET_SECONDS = 240;

/** Scale the plan so a radio edit lands near four minutes at any tempo. */
function buildRadioForm(barSec) {
  const totalWeight = RADIO_PLAN.reduce((n, s) => n + s.weight, 0);
  const targetBars = Math.max(64, Math.round(RADIO_TARGET_SECONDS / barSec / 4) * 4);
  const scale = targetBars / totalWeight;
  let startBar = 0;
  return RADIO_PLAN.map((s, i) => {
    const lengthBars = Math.max(4, Math.round((s.weight * scale) / 4) * 4);
    const section = {
      name: `${s.kind}${i}`, kind: s.kind, motif: s.motif,
      intensity: ARRANGEMENT[s.kind].intensity,
      startBar, lengthBars,
    };
    startBar += lengthBars;
    return section;
  });
}

/** Loop mode: 4-bar blocks with an energy arc, for sketching. */
function buildLoopForm(bars) {
  const blocks = Math.max(3, Math.round(bars / 4));
  const plan = [{ kind: 'intro', motif: 'A' }];
  const body = ['A', 'A2', 'B', 'A3', 'B2', 'A4'];
  const intensities = { A: 0.72, A2: 0.85, B: 1.0, A3: 0.9, B2: 1.0, A4: 0.8 };
  for (let i = 0; i < blocks - 2; i++) {
    const name = body[i % body.length];
    plan.push({ kind: 'loop', name, motif: name.startsWith('B') ? 'B' : 'A', intensity: intensities[name] });
  }
  plan.push({ kind: 'outro', motif: 'A' });
  return plan.map((s, i) => ({
    name: s.name || s.kind,
    kind: s.kind,
    motif: s.motif,
    intensity: s.intensity ?? ARRANGEMENT[s.kind].intensity,
    startBar: i * 4,
    lengthBars: 4,
  }));
}

/* ========================== Performance shaping ========================== */

/** Delay offbeats to taste. 0 = straight, 1 ≈ triplet swing. */
function swungStep(step, swing) {
  if (!swing) return step;
  if (step % 4 === 2) return step + swing * 0.62;   // offbeat 8ths
  if (step % 2 === 1) return step + swing * 0.31;   // offbeat 16ths
  return step;
}

const ACCENT = (step) =>
  step % 16 === 0 ? 1 : step % 8 === 0 ? 0.94 : step % 4 === 0 ? 0.88 : step % 2 === 0 ? 0.8 : 0.72;

/* ============================== Compose ============================== */

/**
 * Compose a full arrangement.
 *
 * @param {object}   opts
 * @param {string}   opts.style      key of STYLES
 * @param {string}   [opts.keyName]  e.g. 'F' — random-but-seeded if omitted
 * @param {string}   [opts.scaleName] overrides the style's mode
 * @param {number}   [opts.tempo]    overrides the style's tempo band
 * @param {number}   [opts.bars]     total length in bars (rounded to 4)
 * @param {number}   [opts.seed]       arrangement seed — groove, harmony, form
 * @param {number}   [opts.melodySeed] tune seed — the motifs themselves
 * @param {string[]} [opts.palette]  which parts to render
 * @param {object}   [opts.params]   { brightness, motion, tension, density } 0-100
 * @param {string}   [opts.lead]     melody patch override
 *
 * The two seeds are separate on purpose: you can keep a tune you like and roll
 * a different arrangement under it, or keep an arrangement and try new tunes.
 */
export function composeSong({
  style = 'lofi',
  keyName,
  scaleName,
  tempo,
  bars = 20,
  seed = randomSeed(),
  melodySeed,
  arrangement = 'loop',
  palette = ['melody', 'chords', 'bass', 'drums', 'arp', 'fx'],
  params = {},
  lead,
} = {}) {
  const st = STYLES[style] || STYLES.lofi;
  const rng = makeRng(seed);
  const tuneSeed = melodySeed ?? seed;
  const mrng = makeRng((tuneSeed ^ 0x9E3779B9) >>> 0);   // motif material only
  const pal = new Set(palette);

  const p = {
    brightness: params.brightness ?? 50,
    motion:     params.motion     ?? 55,
    tension:    params.tension    ?? 40,
    density:    params.density    ?? 55,
  };

  // --- global settings -------------------------------------------------
  const finalKey = keyName || rng.pick(KEYS);
  const finalScaleName = scaleName || (
    p.tension > 78 ? 'phrygian' :
      p.tension > 58 ? 'harmonic' :
        st.scale
  );
  const scale = SCALES[finalScaleName] || SCALES.minor;
  const finalTempo = Math.round(
    tempo || (st.tempo[0] + (st.tempo[1] - st.tempo[0]) * (p.motion / 100)),
  );
  const secPerStep = 60 / finalTempo / 4;
  const barSec = secPerStep * STEPS_PER_BAR;
  const swing = st.swing;
  const density = clamp01(p.density / 100);

  // In radio mode the form decides the length; in loop mode the length
  // decides the form.
  const form = arrangement === 'radio'
    ? buildRadioForm(barSec)
    : buildLoopForm(Math.max(8, Math.round(bars / 4) * 4));
  const totalBars = form.reduce((n, s) => n + s.lengthBars, 0);

  // Normalise the root into one octave band so B-flat songs don't sit a
  // seventh below C songs — otherwise the "same" style changes weight by key.
  let rootMidi = noteNameToMidi(finalKey + '3');
  while (rootMidi > 56) rootMidi -= 12;
  while (rootMidi < 45) rootMidi += 12;
  const melodyRoot = rootMidi + 12 * (st.melodyOctave ?? 1);

  // --- harmony ---------------------------------------------------------
  const prog = rng.pick(progressionsFor(finalScaleName));
  const useSevenths = rng.chance(st.seventhChance ?? 0.4);

  // Chord per bar, plus a cadential twist on the final bar of the piece.
  const chordPerBar = [];
  for (let bar = 0; bar < totalBars; bar++) {
    let degree = prog[bar % prog.length];
    const isFinalBar = bar === totalBars - 1;
    if (isFinalBar) degree = 0; // land home
    chordPerBar.push({
      bar,
      degree,
      tones: chordDegrees(degree, useSevenths && !isFinalBar),
    });
  }

  // --- melodic material ------------------------------------------------
  const melodyDensity = clamp01((st.melodyDensity ?? 0.5) * 0.6 + density * 0.6);
  const motifA = makeMotif(mrng, {
    density: melodyDensity,
    span: mrng.pick([2, 3, 3, 4]),
    contourName: mrng.pick(['arch', 'fall', 'wave', 'rise']),
  });
  const motifB = transposeMotif(
    makeMotif(mrng, {
      density: clamp01(melodyDensity + 0.15),
      span: mrng.pick([3, 4, 5]),
      contourName: mrng.pick(['rise', 'arch', 'valley']),
    }),
    mrng.pick([2, 3, 4]),
  );

  const events = [];
  const melody = [];
  const chordsOut = [];
  let prevVoicing = null;

  const melodyLow = melodyRoot - 4;
  const melodyHigh = melodyRoot + 15;
  let octaveShift = 0;   // carried bar to bar so the melody stays in one register

  const push = (instr, step, lenSteps, midis, vel, barOffsetSec, legato = 0.92) => {
    const jitter = (rng.next() - 0.5) * 0.008;              // ±4ms of human
    const t = Math.max(0, barOffsetSec + swungStep(step, swing) * secPerStep + jitter);
    const dur = Math.max(0.04, lenSteps * secPerStep * legato);
    const list = Array.isArray(midis) ? midis : [midis];
    const ev = {
      t: round3(t),
      instr,
      notes: list.map(midiToNoteName),
      midi: list.map(m => Math.round(m)),
      dur: round3(dur),
      vel: round3(clamp(vel, 0.05, 1)),
    };
    events.push(ev);
    return ev;
  };

  /**
   * Render one motif over one bar's chord.
   *
   * All pitch work happens in SCALE-DEGREE space and only converts to MIDI at
   * the very end. That is the whole trick: a degree is diatonic by
   * construction, so nothing can wander out of key, and transposing by degrees
   * gives a real musical sequence rather than a chromatic slide.
   *
   * opts.degrees       — replay these exact degrees (what an earlier bar
   *                      actually played) instead of the abstract motif, so a
   *                      restatement echoes what the listener heard.
   * opts.preserveShape — no chord snapping; the shape survives untouched.
   * opts.cadence       — resolve the final note onto the chord's root or third.
   * opts.thin          — drop some non-structural notes.
   *
   * Returns the degrees it played, so a later bar can quote them.
   */
  function renderMelodyBar(motif, chord, barIndex, section, opts = {}) {
    const barOffsetSec = barIndex * barSec;
    const n = scale.length;
    const octaves = [-2, -1, 0, 1, 2];
    const spread = (degrees) => degrees.flatMap(d => octaves.map(o => d + o * n));

    const chordCandidates = spread(chord.tones);
    const resolutionCandidates = spread([chord.tones[0], chord.tones[1]]);
    const transpose = opts.transpose || 0;
    const notes = motif.notes;

    // 1. degrees
    const degs = [];
    let prevDeg = null;
    notes.forEach((note, i) => {
      const last = i === notes.length - 1;
      if (opts.thin && !note.anchor && rng.chance(0.45)) { degs.push(null); return; }

      const source = opts.degrees && opts.degrees[i] != null ? opts.degrees[i] : note.deg;
      let deg = source + transpose;
      if (!opts.preserveShape) {
        if (note.anchor) {
          // Snap to a chord tone — but a snap must never widen the interval
          // from the note before it. Without that rule a gentle wobble around
          // a chord tone gets pulled onto alternating octave-displaced tones
          // and the melody turns into a string of thirds. Downbeats get more
          // licence, because that's where the harmony has to be heard.
          const snapped = nearest(deg, chordCandidates);
          const pull = Math.abs(snapped - deg);
          const widens = prevDeg !== null && Math.abs(snapped - prevDeg) > Math.abs(deg - prevDeg);
          if (isDownbeat(note.step) ? pull <= 2 : (pull <= 1 && !widens)) deg = snapped;
        }
        if (opts.cadence && last) deg = nearest(deg, resolutionCandidates);
        // Don't hammer the same pitch — step away by one scale degree.
        if (prevDeg === deg && !note.anchor) deg += rng.pick([-1, 1]);
      }
      prevDeg = deg;
      degs.push(deg);
    });

    // 2. one octave shift for the whole bar, so the contour survives the range
    //    check intact instead of being folded note by note. Start from the
    //    previous bar's shift so the line doesn't hop octaves mid-phrase.
    const midis = degs.map(d => (d === null ? null : degreeToMidi(melodyRoot, scale, d)));
    const sounding = midis.filter(m => m !== null);
    if (!sounding.length) return degs;
    let shift = octaveShift;
    for (let guard = 0; guard < 4 && Math.max(...sounding) + shift > melodyHigh; guard++) shift -= 12;
    for (let guard = 0; guard < 4 && Math.min(...sounding) + shift < melodyLow; guard++) shift += 12;
    octaveShift = shift;

    // 3. emit
    notes.forEach((note, i) => {
      if (midis[i] === null) return;
      const last = i === notes.length - 1;
      const midi = clamp(midis[i] + shift, melodyLow - 7, melodyHigh + 7);

      const phrasePos = i / Math.max(1, notes.length - 1);
      const vel = 0.42 + 0.34 * ACCENT(note.step) * section.intensity
        + 0.06 * Math.sin(Math.PI * phrasePos)
        + (rng.next() - 0.5) * 0.07;

      const len = last && opts.cadence ? Math.max(note.len, 8) : note.len;
      const ev = push('melody', note.step, len, midi, vel, barOffsetSec, st.legato ?? 0.9);
      melody.push({ ...ev, bar: barIndex, step: note.step, lenSteps: len, deg: degs[i] });
    });

    return degs;
  }

  // --- render the form -------------------------------------------------
  form.forEach((section, sectionIndex) => {
    const plan = ARRANGEMENT[section.kind] || ARRANGEMENT.loop;
    const sectionMotif = section.motif === 'B' ? motifB : motifA;
    let phraseHook = null;          // what bar 1 of this phrase actually played
    let phraseStartChord = null;

    /* ---- transition FX at section boundaries ---- */
    if (pal.has('fx') && sectionIndex > 0) {
      const t0 = section.startBar * barSec;
      if (section.kind === 'drop') {
        // A crash on the downbeat is most of what makes a drop land.
        events.push({ t: round3(t0), instr: 'impact', notes: [], midi: [], dur: 2.2, vel: 0.85 });
      }
      if (section.kind === 'breakdown') {
        events.push({ t: round3(t0), instr: 'downlifter', notes: [], midi: [], dur: barSec * 2, vel: 0.5 });
      }
    }
    if (pal.has('fx') && section.kind === 'build') {
      // Riser spanning the back half of the build, landing on the next section.
      const riseBars = Math.min(4, section.lengthBars);
      const startSec = (section.startBar + section.lengthBars - riseBars) * barSec;
      events.push({
        t: round3(startSec), instr: 'riser', notes: [], midi: [],
        dur: round3(riseBars * barSec), vel: 0.6,
      });
    }

    for (let b = 0; b < section.lengthBars; b++) {
      const barIndex = section.startBar + b;
      if (barIndex >= totalBars) break;
      const chord = chordPerBar[barIndex];
      const barOffsetSec = barIndex * barSec;
      // Phrases are 4 bars regardless of how long the section is.
      const phrasePos = b % 4;
      const isPhraseEnd = phrasePos === 3;
      const isLastBar = barIndex === totalBars - 1;
      const barsLeftInSection = section.lengthBars - 1 - b;
      if (phrasePos === 0) { phraseHook = null; phraseStartChord = chord; }

      /* ---- melody: motif · variation · motif · cadence ---- */
      if (pal.has('melody') && plan.melody) {
        let motif = sectionMotif;
        const opts = { cadence: isPhraseEnd };
        if (phrasePos === 1) {
          motif = varyMotif(sectionMotif, rng);            // the answer
        } else if (phrasePos === 2 && phraseHook) {
          // Restate the hook: quote exactly what bar 1 of this phrase played,
          // moved by however far the harmony moved. A strict diatonic sequence
          // — this is the bar the listener actually remembers.
          opts.degrees = phraseHook;
          opts.preserveShape = true;
          opts.transpose = shortestDegreeMove(
            chord.degree - phraseStartChord.degree, scale.length,
          );
        } else if (phrasePos === 3) {
          motif = { ...sectionMotif, notes: cadenceNotes(sectionMotif, rng) };
        }
        if (plan.melody === 'thin') opts.thin = true;
        const played = renderMelodyBar(motif, chord, barIndex, section, opts);
        if (phrasePos === 0) phraseHook = played;
      }

      /* ---- chords ---- */
      if (pal.has('chords') && plan.chords) {
        const midis = chord.tones.map(d => degreeToMidi(rootMidi, scale, d));
        const voiced = voiceChord(prevVoicing, midis);
        prevVoicing = voiced;
        chordsOut.push({ bar: barIndex, degree: chord.degree, midi: voiced, t: barOffsetSec });
        // A breakdown leans on sustained chords rather than the style's stabs —
        // it's the section where the harmony gets to be the whole texture.
        const rhythm = plan.chords === 'thin' || section.kind === 'breakdown'
          ? CHORD_RHYTHMS.sustain
          : (CHORD_RHYTHMS[st.chordRhythm] || CHORD_RHYTHMS.sustain);
        rhythm.forEach(([step, len]) => {
          if (section.intensity < 0.5 && step !== 0 && rng.chance(0.5)) return;
          push('chords', step, len, voiced, 0.3 + 0.22 * section.intensity * ACCENT(step), barOffsetSec, 0.96);
        });
      }

      /* ---- pad wash (texture, not harmony) ---- */
      if (pal.has('pad') && plan.pad) {
        const midis = chord.tones.slice(0, 3).map(d => degreeToMidi(rootMidi, scale, d) + 12);
        push('pad', 0, 16, midis, 0.16 + 0.14 * section.intensity, barOffsetSec, 1.05);
      }

      /* ---- bass ---- */
      if (pal.has('bass') && plan.bass) {
        const pattern = BASS_PATTERNS[st.bassPat] || BASS_PATTERNS.sustain;
        const nextChord = chordPerBar[(barIndex + 1) % totalBars];
        pattern.forEach(([step, len, offset], i) => {
          if (section.kind === 'intro' && step !== 0) return;
          let deg = chord.degree + offset;
          // Walk into the next chord on the last note of a phrase.
          if (isPhraseEnd && i === pattern.length - 1 && !isLastBar && rng.chance(0.6)) {
            deg = nextChord.degree - 1;
          }
          const midi = degreeToMidi(rootMidi - 12, scale, deg);
          push('bass', step, len, midi, 0.55 + 0.25 * ACCENT(step) * section.intensity, barOffsetSec, 0.95);
        });
      }

      /* ---- arpeggio counter-line ---- */
      const arp = ARP_PATTERNS[st.arp];
      if (pal.has('arp') && plan.arp && arp && section.intensity >= 0.7) {
        const chordMidis = chord.tones.map(d => degreeToMidi(rootMidi + 12, scale, d));
        for (let s = 0, i = 0; s < STEPS_PER_BAR; s += arp.rate, i++) {
          const shapeIdx = arp.shape[i % arp.shape.length];
          const midi = chordMidis[shapeIdx % chordMidis.length]
            + 12 * Math.floor(shapeIdx / chordMidis.length);
          push('arp', s, arp.rate, midi, 0.22 + 0.18 * ACCENT(s) * section.intensity, barOffsetSec, 0.8);
        }
      }

      /* ---- drums ---- */
      // The drum mode is where the arrangement is most audible: 'none' in a
      // breakdown is what gives the next drop somewhere to land, and pulling
      // the kick out over the last bars of a build is the oldest trick there is.
      if (pal.has('drums') && plan.drums !== 'none') {
        const mode = plan.drums;
        const groove = GROOVES[grooveFor(st.groove, mode === 'hats' ? density * 0.4 : density)];
        const gain = 0.55 + 0.45 * section.intensity;
        const kickOff = mode === 'hats'
          || (mode === 'build' && barsLeftInSection < 2);   // clear the way for the drop
        const fullKit = mode === 'full' || mode === 'build';

        if (!kickOff) {
          groove.kick.forEach(([step, v]) => push('kick', step, 1, 24, v * gain, barOffsetSec, 1));
        }
        if (fullKit) {
          groove.snare.forEach(([step, v]) =>
            push(v < 0.35 ? 'ghost' : 'snare', step, 1, 38, v * gain, barOffsetSec, 1));
        }
        groove.hat.forEach(([step, v]) => {
          if (mode === 'sparse' && step % 4 !== 0) return;
          if (density < 0.5 && step % 4 !== 0 && rng.chance(0.35)) return;
          push('hat', step, 1, 42, v * gain * (0.85 + rng.next() * 0.3), barOffsetSec, 1);
        });

        // Snare roll through a build: doubles up as it approaches the drop.
        if (mode === 'build' && barsLeftInSection < 2) {
          const div = barsLeftInSection === 0 ? 1 : 2;      // 16ths in the last bar
          for (let step = 0; step < STEPS_PER_BAR; step += div) {
            push('snare', step, 1, 38, (0.25 + (step / STEPS_PER_BAR) * 0.5) * gain, barOffsetSec, 1);
          }
        }
        // Fill at the end of a phrase — the thing that says "here comes the next bit".
        if (isPhraseEnd && fullKit && section.intensity > 0.6 && rng.chance(0.7)) {
          [12, 13, 14, 15].forEach((step, i) =>
            push('snare', step, 1, 38, (0.4 + i * 0.14) * gain, barOffsetSec, 1));
        }
      }
    }
  });

  events.sort((a, b) => a.t - b.t);
  melody.sort((a, b) => a.t - b.t);

  const duration = totalBars * barSec;

  return {
    events,
    melody,
    chords: chordsOut,
    tracks: computeTrackOccupancy(events),
    style,
    styleLabel: st.label,
    lead: lead || st.lead,
    keyName: finalKey,
    scaleName: finalScaleName,
    tempo: finalTempo,
    bars: totalBars,
    duration: round3(duration),
    barSec: round3(barSec),
    seed,
    melodySeed: tuneSeed,
    prog,
    useSevenths,
    groove: grooveFor(st.groove, density),
    swing,
    form,
    arrangement,
    palette: Array.from(pal),
    params: p,
  };
}

/** The 4th bar of a phrase: fewer notes, longer values, lands on the chord. */
function cadenceNotes(motif, rng) {
  const cell = rng.pick(CADENCE_CELLS);
  const src = motif.notes;
  return cell.map(([step, len], i) => {
    const ref = src[Math.min(i, src.length - 1)];
    return { step, len, deg: ref.deg, anchor: true };
  });
}

/* ============================== Helpers ============================== */

const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const clamp01 = (v) => clamp(v, 0, 1);
const round3 = (v) => Math.round(v * 1000) / 1000;

function nearest(value, options) {
  return options.reduce((best, o) => (Math.abs(o - value) < Math.abs(best - value) ? o : best));
}

/**
 * Re-spell a degree interval as the smallest equivalent move. A sequence up a
 * sixth and one down a third are the same gesture; the small one is the one
 * that stays singable.
 */
function shortestDegreeMove(delta, scaleLength) {
  let d = delta;
  while (d > Math.floor(scaleLength / 2)) d -= scaleLength;
  while (d < -Math.floor(scaleLength / 2)) d += scaleLength;
  return d;
}

export function computeTrackOccupancy(events) {
  const tracks = {};
  events.forEach(e => {
    const g = trackGroup(e.instr);
    if (!g) return;
    (tracks[g] = tracks[g] || []).push({ start: e.t, end: e.t + (e.dur || 0) });
  });
  Object.keys(tracks).forEach(k => {
    const arr = tracks[k].sort((a, b) => a.start - b.start);
    const merged = [];
    arr.forEach(r => {
      const last = merged[merged.length - 1];
      if (last && r.start <= last.end + 0.3) last.end = Math.max(last.end, r.end);
      else merged.push({ ...r });
    });
    tracks[k] = merged;
  });
  return tracks;
}

/** Which mixer group an instrument belongs to (covers legacy jam events too). */
export function trackGroup(instr) {
  switch (instr) {
    case 'melody': case 'lead':                     return 'melody';
    case 'chords': case 'poly':                     return 'chords';
    case 'bass':   case 'sub':                      return 'bass';
    case 'arp':                                     return 'arp';
    case 'pad':    case 'voice':                    return 'pad';
    case 'kick': case 'snare': case 'hat':
    case 'ghost': case 'clap': case 'ride':         return 'drums';
    case 'riser': case 'downlifter': case 'impact': return 'fx';
    default:
      return instr && instr.startsWith('perf-') ? 'perf' : null;
  }
}

export const TRACK_GROUPS = ['melody', 'chords', 'arp', 'bass', 'pad', 'drums', 'fx'];

export default composeSong;
