// src/utils/devMode.js
//
// Single source of truth for "should we show developer overlays?"
//
// Rules:
//   1. On production (talkstudio.space), overlays are NEVER shown, regardless
//      of localStorage flags or build mode.
//   2. In dev or preview builds on any other host, overlays respect the
//      `developerMode` localStorage flag, toggled via Ctrl+Alt+D.
//   3. Overlays default to OFF so a clean session shows no debug chrome.

import { useEffect, useState } from 'react';

const PRODUCTION_HOSTS = new Set(['talkstudio.space', 'www.talkstudio.space']);

/**
 * True when running on the production domain. URL-based, not build-flag-based,
 * so a preview build pointed at talkstudio.space still counts as production and
 * a production build served from a staging host does not.
 */
export function isProduction() {
  if (typeof window === 'undefined') return false;
  return PRODUCTION_HOSTS.has(window.location.hostname);
}

/** True if the user has toggled developer mode on (localStorage=='true'). */
export function isDeveloperModeFlagSet() {
  if (typeof window === 'undefined') return false;
  try {
    return localStorage.getItem('developerMode') === 'true';
  } catch {
    return false;
  }
}

/**
 * Combined check: should we render debug overlays right now?
 * Returns false on production no matter what; otherwise respects the flag.
 */
export function shouldShowDevOverlays() {
  if (isProduction()) return false;
  return isDeveloperModeFlagSet();
}

/**
 * React hook that returns the current developer-mode state and keeps it
 * in sync with the Ctrl+Alt+D toggle + localStorage changes across tabs.
 *
 * Usage:
 *   const devMode = useDeveloperMode();
 *   if (!devMode) return null;
 */
export function useDeveloperMode() {
  const [on, setOn] = useState(() => shouldShowDevOverlays());

  useEffect(() => {
    if (isProduction()) {
      // Production is permanently off — skip listeners to save work.
      setOn(false);
      return;
    }

    const recompute = () => setOn(shouldShowDevOverlays());

    // Ctrl+Alt+D toggles the localStorage flag. We only need to re-read it
    // after the key fires — App.jsx owns the actual toggle, we just listen.
    const onKey = (e) => {
      if (e.ctrlKey && e.altKey && (e.key === 'd' || e.key === 'D')) {
        // App.jsx handler updates localStorage then re-render of its own
        // state triggers a new render; ours needs a microtask to see the
        // new localStorage value.
        setTimeout(recompute, 0);
      }
    };

    // Cross-tab sync (storage event fires in OTHER tabs when one changes
    // localStorage).
    const onStorage = (e) => {
      if (e.key === 'developerMode') recompute();
    };

    window.addEventListener('keydown', onKey);
    window.addEventListener('storage', onStorage);
    return () => {
      window.removeEventListener('keydown', onKey);
      window.removeEventListener('storage', onStorage);
    };
  }, []);

  return on;
}
