import React, { useState } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { getFirestore, addDoc, collection, serverTimestamp } from 'firebase/firestore';
import { getDatabase, ref, set, push } from 'firebase/database';
import liveKitIngressService from '../../services/livekit/LiveKitIngressService.js';
import eventLiveStatusManager from '../../services/events/EventLiveStatusManager';
import { 
  formatLocalTime, 
  getCurrentTimeRounded, 
  getUserTimezone,
  validateEventDateTime 
} from '../../utils/timezoneUtils.js';
import { 
  Calendar, 
  Clock, 
  Users, 
  Settings, 
  X,
  Play,
  Crown,
  Music,
  Mic,
  Video as VideoIcon,
  BookOpen,
  Star,
  MapPin,
  Timer,
  Activity
} from 'lucide-react';

const CreateEventModalWithActivityTracking = ({ isOpen, onClose, onEventCreated }) => {
  const { currentUser } = useAuth();
  const [loading, setLoading] = useState(false);
  const userTimezone = getUserTimezone();

  const _showStreamingInfoWithUrls = (eventId, urls, activityOptions) => {
    // Create a modal to show streaming information with actual LiveKit URLs and activity tracking
    const modal = document.createElement('div');
    modal.className = 'fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4';
    
    const statusText = urls.fallback ? 
      '<div class="mb-3 p-2 bg-amber-50 border border-amber-200 rounded text-amber-800 text-sm">📡 Using fallback configuration - stream should work</div>' : 
      '<div class="mb-3 p-2 bg-green-50 border border-green-200 rounded text-green-800 text-sm">✅ LiveKit RTMP stream created successfully!</div>';
    
    const activityInfo = activityOptions.maxDuration ? 
      `<div class="mb-2 p-2 bg-blue-50 border border-blue-200 rounded text-blue-800 text-sm">
        ⏰ Stream will auto-end after ${activityOptions.maxDuration} minutes
       </div>` : '';
    
    modal.innerHTML = `
      <div class="bg-white rounded-lg max-w-lg w-full p-6 max-h-[90vh] overflow-y-auto">
        <div class="flex items-center gap-3 mb-4">
          <div class="w-10 h-10 bg-gradient-to-r from-purple-500 to-pink-500 rounded-lg flex items-center justify-center">
            <svg class="w-5 h-5 text-white" fill="currentColor" viewBox="0 0 20 20">
              <path d="M2 6a2 2 0 012-2h6a2 2 0 012 2v8a2 2 0 01-2 2H4a2 2 0 01-2-2V6zM14.553 7.106A1 1 0 0014 8v4a1 1 0 00.553.894l2 1A1 1 0 0018 13V7a1 1 0 00-1.447-.894l-2 1z"></path>
            </svg>
          </div>
          <div>
            <h3 class="text-lg font-bold text-gray-900">RTMP Stream Ready!</h3>
            <p class="text-sm text-gray-500">Event: ${eventId}</p>
          </div>
        </div>
        
        ${statusText}
        ${activityInfo}
        
        <div class="mb-4 p-3 bg-purple-50 border border-purple-200 rounded-lg">
          <h4 class="text-sm font-medium text-purple-800 mb-2">📊 Activity Tracking Enabled</h4>
          <div class="text-xs text-purple-700 space-y-1">
            <div>• Stream automatically marked as LIVE when you start broadcasting</div>
            <div>• Activity monitored every 30 seconds</div>
            <div>• Auto-cleanup after ${activityOptions.graceMinutes} minutes of inactivity</div>
            ${activityOptions.maxDuration ? `<div>• Maximum duration: ${activityOptions.maxDuration} minutes</div>` : ''}
          </div>
        </div>
        
        <div class="space-y-3 mb-6">
          <div class="p-3 bg-gray-50 rounded-lg">
            <div class="text-xs font-medium text-gray-600 mb-1">📺 Stream URL (For viewers)</div>
            <div class="text-sm font-mono text-gray-800 break-all">${urls.streamUrl}</div>
          </div>
          <div class="p-3 bg-purple-50 rounded-lg border border-purple-200">
            <div class="text-xs font-medium text-purple-600 mb-1">📡 RTMP URL (For OBS)</div>
            <div class="text-sm font-mono text-purple-800 break-all">${urls.rtmpUrl}</div>
          </div>
          ${urls.streamKey ? `
          <div class="p-3 bg-blue-50 rounded-lg border border-blue-200">
            <div class="text-xs font-medium text-blue-600 mb-1">🔑 Stream Key</div>
            <div class="text-sm font-mono text-blue-800 break-all">${urls.streamKey}</div>
          </div>
          ` : ''}
        </div>
        
        <div class="p-4 bg-gradient-to-r from-purple-50 to-pink-50 border border-purple-200 rounded-lg mb-4">
          <div class="text-sm font-medium text-purple-800 mb-2">🎯 Quick OBS Setup:</div>
          <div class="text-xs text-purple-700 space-y-1">
            <div>1. Open OBS Studio</div>
            <div>2. Settings → Stream</div>
            <div>3. Service: <strong>Custom</strong></div>
            <div>4. Server: <strong>rtmp://talkstudio-2c55dh9q.livekit.cloud/live/</strong></div>
            <div>5. Stream Key: <strong>${urls.streamKey || 'Use full RTMP URL above'}</strong></div>
            <div>6. Click <strong>"Start Streaming"</strong></div>
            <div>7. 🎉 You're live! (Activity tracking will automatically begin)</div>
          </div>
        </div>
        
        <div class="flex gap-2">
          <button onclick="navigator.clipboard.writeText('${urls.rtmpUrl}'); this.textContent='✅ Copied!'; setTimeout(() => this.textContent='📡 Copy RTMP', 2000)" 
                  class="flex-1 px-3 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition-colors text-sm font-medium">
            📡 Copy RTMP
          </button>
          <button onclick="navigator.clipboard.writeText('${urls.streamUrl}'); this.textContent='✅ Copied!'; setTimeout(() => this.textContent='🔗 Copy Watch URL', 2000)" 
                  class="flex-1 px-3 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 transition-colors text-sm font-medium">
            🔗 Copy Watch URL
          </button>
          <button onclick="this.closest('.fixed').remove()" 
                  class="px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors text-sm font-medium">
            Close
          </button>
        </div>
        
        <div class="mt-3 text-xs text-gray-500 text-center">
          💡 Tip: Start streaming to automatically activate live status with activity tracking!
        </div>
      </div>
    `;
    
    document.body.appendChild(modal);
    
    // Remove modal when clicking outside
    modal.addEventListener('click', (e) => {
      if (e.target === modal) {
        modal.remove();
      }
    });
  };

  const [eventForm, setEventForm] = useState({
    title: '',
    description: '',
    category: 'music',
    accessLevel: 'free', // Default to free for non-artists
    maxViewers: 100,
    duration: 60,
    startTime: getCurrentTimeRounded(), // Use timezone-aware current time
    recordingEnabled: true,
    chatEnabled: true,
    reactionsEnabled: true,
    tipsEnabled: false, // Will be dynamically set based on access level
    
    // New activity tracking options
    autoEndEnabled: false, // Whether to auto-end after duration
    activityGraceMinutes: 30, // Grace period for inactivity
    maxStreamDuration: null // Maximum stream duration in minutes (null = no limit)
  });

  // Create LiveKit RTMP ingress for the event
  const createLiveKitStream = async (eventId, roomName) => {
    try {
      console.log('🎬 Creating LiveKit RTMP ingress for event:', eventId);
      
      // Create RTMP ingress using the service
      const result = await liveKitIngressService.createRTMPIngress(roomName || eventId, {
        eventId,
        videoBitrate: 2000000,
        audioBitrate: 128000,
        width: 1280,
        height: 720,
        framerate: 30
      });
      
      if (result.success) {
        console.log('✅ LiveKit RTMP ingress created successfully:', result);
        return {
          success: true,
          streamUrl: result.streamUrl,
          rtmpUrl: result.rtmpUrl,
          streamKey: result.streamKey,
          ingressId: result.ingress?.ingressId
        };
      } else {
        console.warn('⚠️ LiveKit ingress creation failed, using fallback:', result.error);
        return {
          success: false,
          fallback: true,
          streamUrl: result.streamUrl,
          rtmpUrl: result.rtmpUrl,
          streamKey: result.streamKey,
          error: result.error
        };
      }
    } catch (error) {
      console.error('❌ Error creating LiveKit stream:', error);
      
      // Return fallback URLs with correct LiveKit domain
      return {
        success: false,
        fallback: true,
        error: error.message,
        streamUrl: `https://talkstudio-2c55dh9q.livekit.cloud/room/${eventId}`,
        rtmpUrl: `rtmp://talkstudio-2c55dh9q.livekit.cloud/live/${eventId}`,
        streamKey: eventId
      };
    }
  };

  const createEventChatRoom = async (eventId, eventData) => {
    try {
      const database = getDatabase();
      
      const chatRoomPath = `chats/public/event_${eventId}`;
      console.log('🏗️ Creating event chat room at:', chatRoomPath);
      
      const chatRoomData = {
        type: 'event',
        eventId: eventId,
        eventTitle: eventData.title,
        artistId: eventData.artistId,
        artistName: eventData.artistName,
        artistAvatar: eventData.artistAvatar,
        
        // Chat room settings
        isActive: false, // Will be activated when event goes live
        allowUserStreaming: true,
        artistPriority: true,
        maxConcurrentUserStreams: 8,
        
        // Moderation settings
        moderationEnabled: true,
        autoModeration: true,
        slowModeEnabled: false,
        slowModeDelay: 0,
        
        // Access control
        accessLevel: eventData.accessLevel,
        allowAnonymous: eventData.accessLevel === 'free', // Only allow anonymous in free streams
        
        // Video streaming settings
        artistVideoActive: false,
        userStreams: {},
        
        // Analytics
        totalMessages: 0,
        activeUsers: 0,
        peakUsers: 0,
        
        // FIXED: Timezone-aware timestamps
        createdAt: Date.now(),
        updatedAt: Date.now(),
        timezone: userTimezone.timezone,
        timezoneOffset: userTimezone.offsetString
      };
      
      await set(ref(database, chatRoomPath), chatRoomData);
      
      // Create initial system message with timezone info
      const messagesRef = ref(database, `${chatRoomPath}/messages`);
      await push(messagesRef, {
        type: 'system',
        message: `Welcome to ${eventData.title}! Event starts at ${formatLocalTime(eventData.startTime)}.`,
        timestamp: Date.now(),
        userId: 'system',
        userName: 'System'
      });
      
      console.log('💬 Event chat room created with timezone info:', chatRoomPath);
      
    } catch (error) {
      console.error('Failed to create event chat room:', error);
      // Don't block event creation if chat room fails
    }
  };

  const createEvent = async () => {
    try {
      if (!eventForm.title.trim()) {
        alert('Please enter an event title');
        return;
      }

      if (!currentUser || currentUser.isAnonymous) {
        alert('Please log in to create events');
        return;
      }

      // FIXED: Validate event datetime
      if (!validateEventDateTime(eventForm.startTime)) {
        alert('Please select a valid start time (must be in the future)');
        return;
      }
      
      setLoading(true);
      const db = getFirestore();
      
      // FIXED: Restrict tipping based on access level - only registered and VIP can receive tips
      const tipsEnabled = eventForm.accessLevel !== 'free' && eventForm.tipsEnabled;
      
      // Calculate stream end time if auto-end is enabled
      const streamEndTime = eventForm.autoEndEnabled && eventForm.maxStreamDuration ? 
        new Date(eventForm.startTime).getTime() + (eventForm.maxStreamDuration * 60 * 1000) : 
        null;
      
      const startTimeMs = new Date(eventForm.startTime).getTime();
      const endTimeMs = startTimeMs + (eventForm.duration * 60 * 1000); // duration is in minutes

      const eventData = {
        title: eventForm.title,
        description: eventForm.description,
        category: eventForm.category,
        artistId: currentUser.uid,
        artistName: currentUser.displayName || 'Event Creator',
        artistAvatar: currentUser.photoURL || null,
        artistVerified: false, // Non-artists are not verified by default,

        status: 'scheduled',
        startTime: startTimeMs,
        endTime: endTimeMs,
        duration: eventForm.duration,
        maxViewers: eventForm.maxViewers,
        
        accessLevel: eventForm.accessLevel,
        
        chatEnabled: eventForm.chatEnabled,
        reactionsEnabled: eventForm.reactionsEnabled,
        recordingEnabled: eventForm.recordingEnabled,
        tipsEnabled: tipsEnabled, // FIXED: Only allow tips for registered/VIP
        
        // Activity tracking settings
        activityGracePeriod: eventForm.activityGraceMinutes * 60 * 1000,
        streamEndTime: streamEndTime,
        autoEndEnabled: eventForm.autoEndEnabled,
        maxStreamDuration: eventForm.maxStreamDuration,
        
        // FIXED: Add timezone information
        timezone: userTimezone.timezone,
        timezoneOffset: userTimezone.offsetString,
        localStartTime: formatLocalTime(eventForm.startTime),
        
        viewerCount: 0,
        peakViewers: 0,
        totalViews: 0,
        revenue: 0,
        
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp()
      };
      
      // Create the event
      const eventRef = await addDoc(collection(db, 'events'), eventData);
      const eventId = eventRef.id;
      
      // FIXED: Create proper LiveKit RTMP stream
      console.log('🚀 Creating LiveKit RTMP stream for event:', eventId);
      const streamResult = await createLiveKitStream(eventId, `event_${eventId}`);
      
      // Prepare activity tracking options for the modal
      const activityOptions = {
        graceMinutes: eventForm.activityGraceMinutes,
        maxDuration: eventForm.autoEndEnabled ? eventForm.maxStreamDuration : null
      };
      
      // Always show streaming info to user with the actual URLs and activity tracking info
      setTimeout(() => {
        _showStreamingInfoWithUrls(eventId, {
          streamUrl: streamResult.streamUrl,
          rtmpUrl: streamResult.rtmpUrl,
          streamKey: streamResult.streamKey,
          fallback: streamResult.fallback || false
        }, activityOptions);
      }, 1000);
      
      // Create chat room for the event
      await createEventChatRoom(eventId, eventData);
      
      console.log('🎭 Event created with LiveKit integration and activity tracking:', {
        eventId,
        streamUrl: streamResult.streamUrl,
        rtmpUrl: streamResult.rtmpUrl,
        timezone: userTimezone.timezone,
        tipsEnabled: tipsEnabled,
        activityTracking: {
          gracePeriod: eventForm.activityGraceMinutes,
          maxDuration: eventForm.maxStreamDuration,
          autoEnd: eventForm.autoEndEnabled
        }
      });
      
      // Reset form
      setEventForm({
        title: '',
        description: '',
        category: 'music',
        accessLevel: 'free',
        maxViewers: 100,
        duration: 60,
        startTime: getCurrentTimeRounded(), // Reset to current time with timezone
        recordingEnabled: true,
        chatEnabled: true,
        reactionsEnabled: true,
        tipsEnabled: false,
        autoEndEnabled: false,
        activityGraceMinutes: 30,
        maxStreamDuration: null
      });
      
      // Close modal and notify parent
      onClose();
      if (onEventCreated) {
        onEventCreated(eventId);
      }
      
    } catch (error) {
      console.error('Error creating event:', error);
      alert('Failed to create event: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  const getCategoryIcon = (category) => {
    switch (category) {
      case 'music': return <Music size={16} />;
      case 'talk': return <Mic size={16} />;
      case 'performance': return <VideoIcon size={16} />;
      case 'education': return <BookOpen size={16} />;
      default: return <Play size={16} />;
    }
  };

  const getAccessLevelIcon = (level) => {
    switch (level) {
      case 'premium': return <Crown className="text-purple-500" size={16} />;
      case 'vip': return <Crown className="text-yellow-500" size={16} />;
      case 'free': return <Users className="text-green-500" size={16} />;
      default: return <Users className="text-gray-500" size={16} />;
    }
  };

  // FIXED: Update tips enabled when access level changes
  const handleAccessLevelChange = (newAccessLevel) => {
    setEventForm(prev => ({
      ...prev,
      accessLevel: newAccessLevel,
      // FIXED: Disable tipping for free streams, allow for registered/VIP
      tipsEnabled: newAccessLevel !== 'free' ? prev.tipsEnabled : false
    }));
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-lg max-w-2xl w-full max-h-[90vh] overflow-y-auto">
        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-gradient-to-r from-purple-500 to-pink-500 rounded-lg flex items-center justify-center">
              <Calendar className="text-white" size={20} />
            </div>
            <div>
              <h2 className="text-xl font-bold text-gray-900">Create New Event</h2>
              <p className="text-sm text-gray-500">
                LiveKit RTMP streaming • Activity tracking • {userTimezone.timezone}
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 hover:bg-gray-100 rounded-lg transition-colors"
          >
            <X size={20} className="text-gray-500" />
          </button>
        </div>

        {/* Form */}
        <div className="p-6 space-y-6">
          {/* Basic Info */}
          <div className="space-y-4">
            <h3 className="font-semibold text-gray-900 flex items-center gap-2">
              <Settings size={18} />
              Event Details
            </h3>
            
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Event Title *
              </label>
              <input
                type="text"
                value={eventForm.title}
                onChange={(e) => setEventForm({...eventForm, title: e.target.value})}
                placeholder="Enter your event title..."
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent"
                maxLength={100}
              />
              <div className="text-xs text-gray-500 mt-1">
                {eventForm.title.length}/100 characters
              </div>
            </div>
            
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Description
              </label>
              <textarea
                value={eventForm.description}
                onChange={(e) => setEventForm({...eventForm, description: e.target.value})}
                placeholder="Describe what your event is about..."
                rows={3}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent"
                maxLength={500}
              />
              <div className="text-xs text-gray-500 mt-1">
                {eventForm.description.length}/500 characters
              </div>
            </div>
          </div>

          {/* Category and Access */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Category
              </label>
              <div className="relative">
                <select
                  value={eventForm.category}
                  onChange={(e) => setEventForm({...eventForm, category: e.target.value})}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent appearance-none"
                >
                  <option value="music">🎵 Music</option>
                  <option value="talk">🎤 Talk Show</option>
                  <option value="performance">🎭 Performance</option>
                  <option value="education">📚 Education</option>
                  <option value="gaming">🎮 Gaming</option>
                  <option value="other">✨ Other</option>
                </select>
                <div className="absolute right-3 top-1/2 transform -translate-y-1/2 pointer-events-none">
                  {getCategoryIcon(eventForm.category)}
                </div>
              </div>
            </div>
            
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Access Level
              </label>
              <div className="relative">
                <select
                  value={eventForm.accessLevel}
                  onChange={(e) => handleAccessLevelChange(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent appearance-none"
                >
                  <option value="free">🌟 Free Access</option>
                  <option value="premium">👑 Premium Members</option>
                  <option value="vip">💎 VIP Members Only</option>
                </select>
                <div className="absolute right-3 top-1/2 transform -translate-y-1/2 pointer-events-none">
                  {getAccessLevelIcon(eventForm.accessLevel)}
                </div>
              </div>
            </div>
          </div>

          {/* FIXED: Schedule and Duration with timezone awareness */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                <div className="flex items-center gap-2">
                  <Clock size={16} />
                  Start Time
                  <span className="ml-2 px-2 py-1 bg-green-100 text-green-700 text-xs rounded-full font-medium">
                    ⚡ Local Time
                  </span>
                </div>
              </label>
              <div className="relative">
                <input
                  type="datetime-local"
                  value={eventForm.startTime}
                  onChange={(e) => setEventForm({...eventForm, startTime: e.target.value})}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent"
                  min={new Date().toISOString().slice(0, 16)}
                />
                <MapPin className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 pointer-events-none" size={16} />
              </div>
              <div className="text-xs text-gray-500 mt-1">
                <div>🌍 {userTimezone.timezone} ({userTimezone.offsetString})</div>
                <div>💡 Times display in your local timezone</div>
              </div>
            </div>
            
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Duration (minutes)
              </label>
              <input
                type="number"
                value={eventForm.duration}
                onChange={(e) => setEventForm({...eventForm, duration: parseInt(e.target.value) || 60})}
                min="15"
                max="300"
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent"
              />
            </div>
          </div>

          {/* Activity Tracking Settings */}
          <div className="space-y-4">
            <h3 className="font-semibold text-gray-900 flex items-center gap-2">
              <Activity size={18} />
              Activity Tracking
              <span className="ml-2 px-2 py-1 bg-blue-100 text-blue-700 text-xs rounded-full font-medium">
                NEW
              </span>
            </h3>
            
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Inactivity Grace Period (minutes)
                </label>
                <select
                  value={eventForm.activityGraceMinutes}
                  onChange={(e) => setEventForm({...eventForm, activityGraceMinutes: parseInt(e.target.value)})}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent"
                >
                  <option value={15}>15 minutes</option>
                  <option value={30}>30 minutes (recommended)</option>
                  <option value={60}>1 hour</option>
                  <option value={120}>2 hours</option>
                </select>
                <div className="text-xs text-gray-500 mt-1">
                  Event will auto-end after this period of inactivity
                </div>
              </div>
              
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  <div className="flex items-center gap-2">
                    <input
                      type="checkbox"
                      checked={eventForm.autoEndEnabled}
                      onChange={(e) => setEventForm({...eventForm, autoEndEnabled: e.target.checked})}
                      className="rounded border-gray-300 text-purple-600 focus:ring-purple-500"
                    />
                    Maximum Stream Duration
                  </div>
                </label>
                <select
                  value={eventForm.maxStreamDuration || ''}
                  onChange={(e) => setEventForm({...eventForm, maxStreamDuration: e.target.value ? parseInt(e.target.value) : null})}
                  disabled={!eventForm.autoEndEnabled}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent disabled:opacity-50"
                >
                  <option value="">No limit</option>
                  <option value={60}>1 hour</option>
                  <option value={120}>2 hours</option>
                  <option value={180}>3 hours</option>
                  <option value={240}>4 hours</option>
                  <option value={360}>6 hours</option>
                </select>
                <div className="text-xs text-gray-500 mt-1">
                  {eventForm.autoEndEnabled ? 'Event will auto-end at this time limit' : 'Enable checkbox to set time limit'}
                </div>
              </div>
            </div>
          </div>

          {/* Max Viewers */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Maximum Viewers
            </label>
            <input
              type="number"
              value={eventForm.maxViewers}
              onChange={(e) => setEventForm({...eventForm, maxViewers: parseInt(e.target.value) || 100})}
              min="10"
              max="1000"
              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent"
            />
          </div>

          {/* Features */}
          <div className="space-y-3">
            <h3 className="font-semibold text-gray-900 flex items-center gap-2">
              <Star size={18} />
              Event Features
            </h3>
            
            <div className="grid grid-cols-2 gap-3">
              <label className="flex items-center gap-2 p-3 border border-gray-200 rounded-lg hover:bg-gray-50 cursor-pointer">
                <input
                  type="checkbox"
                  checked={eventForm.recordingEnabled}
                  onChange={(e) => setEventForm({...eventForm, recordingEnabled: e.target.checked})}
                  className="rounded border-gray-300 text-purple-600 focus:ring-purple-500"
                />
                <span className="text-sm font-medium">📹 Recording</span>
              </label>
              
              <label className="flex items-center gap-2 p-3 border border-gray-200 rounded-lg hover:bg-gray-50 cursor-pointer">
                <input
                  type="checkbox"
                  checked={eventForm.chatEnabled}
                  onChange={(e) => setEventForm({...eventForm, chatEnabled: e.target.checked})}
                  className="rounded border-gray-300 text-purple-600 focus:ring-purple-500"
                />
                <span className="text-sm font-medium">💬 Live Chat</span>
              </label>
              
              <label className="flex items-center gap-2 p-3 border border-gray-200 rounded-lg hover:bg-gray-50 cursor-pointer">
                <input
                  type="checkbox"
                  checked={eventForm.reactionsEnabled}
                  onChange={(e) => setEventForm({...eventForm, reactionsEnabled: e.target.checked})}
                  className="rounded border-gray-300 text-purple-600 focus:ring-purple-500"
                />
                <span className="text-sm font-medium">😍 Reactions</span>
              </label>
              
              {/* FIXED: Tips only available for registered/VIP streams */}
              <label className={`flex items-center gap-2 p-3 border rounded-lg cursor-pointer transition-all ${
                eventForm.accessLevel === 'free' 
                  ? 'border-gray-200 bg-gray-50 opacity-50 cursor-not-allowed' 
                  : 'border-gray-200 hover:bg-gray-50'
              }`}>
                <input
                  type="checkbox"
                  checked={eventForm.tipsEnabled}
                  onChange={(e) => setEventForm({...eventForm, tipsEnabled: e.target.checked})}
                  disabled={eventForm.accessLevel === 'free'}
                  className="rounded border-gray-300 text-purple-600 focus:ring-purple-500 disabled:opacity-50"
                />
                <span className="text-sm font-medium">💰 Tips</span>
                {eventForm.accessLevel === 'free' && (
                  <span className="text-xs text-gray-500 ml-auto">Premium/VIP only</span>
                )}
              </label>
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between p-6 border-t bg-gray-50">
          <div className="text-sm text-gray-500">
            <div>🎬 LiveKit RTMP streaming enabled</div>
            <div>📊 Activity tracking with {eventForm.activityGraceMinutes}min grace period</div>
            <div>🌍 Times in {userTimezone.timezone}</div>
          </div>
          <div className="flex gap-3">
            <button
              onClick={onClose}
              disabled={loading}
              className="px-4 py-2 text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 disabled:opacity-50"
            >
              Cancel
            </button>
            <button
              onClick={createEvent}
              disabled={loading || !eventForm.title.trim()}
              className="px-6 py-2 bg-gradient-to-r from-purple-600 to-pink-600 text-white rounded-lg hover:from-purple-700 hover:to-pink-700 disabled:opacity-50 flex items-center gap-2"
            >
              {loading && (
                <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
              )}
              <Calendar size={16} />
              {loading ? 'Creating...' : 'Create Event'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CreateEventModalWithActivityTracking;