// src/utils/firebaseAuditUtils.js
import { db, auth } from '../firebase';
import { 
  collection, 
  addDoc, 
  serverTimestamp, 
  getDocs, 
  query, 
  where, 
  getDoc, 
  doc, 
  setDoc,
  deleteDoc,
  orderBy,
  limit
} from 'firebase/firestore';
import { checkUserAuditPermission } from './fileAuditUtils';

// Check if firebase auditing is enabled via environment variable
const isAuditEnabled = import.meta.env.VITE_ENABLE_FIREBASE_AUDIT === 'true';

// Track if we've already wrapped a method for a given path
const wrappedPaths = new Set();

// Cache of detected access patterns
const accessPatterns = new Map();

/**
 * Logs Firebase access to Firestore
 * @param {string} operation - The operation type (read, write, create, update, delete)
 * @param {string} path - The Firestore path accessed
 * @param {Object} data - The data involved in the operation
 * @param {boolean} success - Whether the operation succeeded
 * @param {Object} error - Any error that occurred
 * @param {string} userId - The user ID performing the operation
 */
export const logFirebaseAccess = async (operation, path, data, success, error = null, userId = null) => {
  if (!isAuditEnabled) return;
  
  try {
    // Check if the current user has audit permissions
    const canAudit = await checkUserAuditPermission(auth);
    if (!canAudit) return;
    
    // If userId is not provided, try to get it from auth
    const actualUserId = userId || (auth.currentUser ? auth.currentUser.uid : 'anonymous');
    
    // Log to Firestore
    await addDoc(collection(db, 'firebaseAudit'), {
      operation,
      path,
      data: JSON.stringify(data || {}),
      success,
      error: error ? JSON.stringify(error) : null,
      userId: actualUserId,
      timestamp: serverTimestamp(),
      userAgent: typeof navigator !== 'undefined' ? navigator.userAgent : 'unknown'
    });
    
    // Add to access patterns cache
    const patternKey = `${operation}:${path}`;
    if (!accessPatterns.has(patternKey)) {
      accessPatterns.set(patternKey, {
        operation,
        path,
        count: 1,
        successes: success ? 1 : 0,
        failures: success ? 0 : 1,
        lastError: success ? null : error
      });
    } else {
      const pattern = accessPatterns.get(patternKey);
      pattern.count += 1;
      pattern.successes += success ? 1 : 0;
      pattern.failures += success ? 0 : 1;
      if (!success) pattern.lastError = error;
    }
    
    // If this was an error, log it more prominently for rule generation
    if (!success && error) {
      console.error(`[Firebase Audit] Access denied at ${path} for ${operation}:`, error);
      
      // Save the denied access pattern for rule generation
      await addDoc(collection(db, 'firebaseAccessDenied'), {
        operation,
        path,
        data: JSON.stringify(data || {}),
        error: JSON.stringify(error),
        userId: actualUserId,
        timestamp: serverTimestamp()
      });
    }
  } catch (e) {
    // Don't let the audit logging break the application
    console.error('[Firebase Audit] Error logging access:', e);
  }
};

/**
 * Gets all Firebase access logs
 * @param {number} limit - Maximum number of logs to return
 * @returns {Promise<Array>} Access logs
 */
export const getFirebaseAccessLogs = async (maxResults = 100) => {
  if (!isAuditEnabled) return [];
  
  try {
    const q = query(
      collection(db, 'firebaseAudit'),
      orderBy('timestamp', 'desc'),
      limit(maxResults)
    );
    
    const querySnapshot = await getDocs(q);
    
    return querySnapshot.docs.map(doc => ({
      id: doc.id,
      ...doc.data(),
      timestamp: doc.data().timestamp?.toDate()
    }));
  } catch (error) {
    console.error('[Firebase Audit] Error getting access logs:', error);
    return [];
  }
};

/**
 * Gets all denied Firebase access logs
 * @returns {Promise<Array>} Denied access logs
 */
export const getDeniedAccessLogs = async () => {
  if (!isAuditEnabled) return [];
  
  try {
    const querySnapshot = await getDocs(collection(db, 'firebaseAccessDenied'));
    
    return querySnapshot.docs.map(doc => ({
      id: doc.id,
      ...doc.data(),
      timestamp: doc.data().timestamp?.toDate()
    }));
  } catch (error) {
    console.error('[Firebase Audit] Error getting denied access logs:', error);
    return [];
  }
};

/**
 * Create wrapper functions for common Firestore operations
 */
export const auditedFirestore = {
  // Read operations
  async getDoc(docRef) {
    try {
      const result = await getDoc(docRef);
      await logFirebaseAccess('read', docRef.path, null, true);
      return result;
    } catch (error) {
      await logFirebaseAccess('read', docRef.path, null, false, error);
      throw error;
    }
  },
  
  async getDocs(queryRef) {
    try {
      const result = await getDocs(queryRef);
      await logFirebaseAccess('read', queryRef.path || 'query', null, true);
      return result;
    } catch (error) {
      await logFirebaseAccess('read', queryRef.path || 'query', null, false, error);
      throw error;
    }
  },
  
  // Write operations
  async addDoc(collectionRef, data) {
    try {
      const result = await addDoc(collectionRef, data);
      await logFirebaseAccess('create', collectionRef.path, data, true);
      return result;
    } catch (error) {
      await logFirebaseAccess('create', collectionRef.path, data, false, error);
      throw error;
    }
  },
  
  async setDoc(docRef, data, options) {
    try {
      const result = await setDoc(docRef, data, options);
      await logFirebaseAccess('set', docRef.path, data, true);
      return result;
    } catch (error) {
      await logFirebaseAccess('set', docRef.path, data, false, error);
      throw error;
    }
  },
  
  async updateDoc(docRef, data) {
    try {
      const result = await updateDoc(docRef, data);
      await logFirebaseAccess('update', docRef.path, data, true);
      return result;
    } catch (error) {
      await logFirebaseAccess('update', docRef.path, data, false, error);
      throw error;
    }
  },
  
  async deleteDoc(docRef) {
    try {
      const result = await deleteDoc(docRef);
      await logFirebaseAccess('delete', docRef.path, null, true);
      return result;
    } catch (error) {
      await logFirebaseAccess('delete', docRef.path, null, false, error);
      throw error;
    }
  }
};

/**
 * Instructs how to use the audit system instead of trying to modify Firebase
 */
export const instrumentFirestore = () => {
  if (!isAuditEnabled) return;
  
  console.info(`
    [Firebase Audit] Firebase auditing is enabled.
    To track Firestore operations, use the 'auditedFirestore' object from firebaseAuditUtils.js:
    
    import { auditedFirestore } from './utils/firebaseAuditUtils';
    
    // Then use:
    auditedFirestore.getDoc(docRef);
    auditedFirestore.addDoc(collectionRef, data);
    // etc.
  `);
};

/**
 * Clears all Firebase audit data
 */
export const clearFirebaseAuditData = async () => {
  if (!isAuditEnabled) return;
  
  try {
    // Clear regular audit logs
    const auditSnapshot = await getDocs(collection(db, 'firebaseAudit'));
    const auditDeletePromises = [];
    auditSnapshot.forEach((doc) => {
      auditDeletePromises.push(deleteDoc(doc.ref));
    });
    
    // Clear denied access logs
    const deniedSnapshot = await getDocs(collection(db, 'firebaseAccessDenied'));
    const deniedDeletePromises = [];
    deniedSnapshot.forEach((doc) => {
      deniedDeletePromises.push(deleteDoc(doc.ref));
    });
    
    await Promise.all([...auditDeletePromises, ...deniedDeletePromises]);
    console.debug('[Firebase Audit] Cleared all audit data');
  } catch (error) {
    console.error('[Firebase Audit] Error clearing audit data:', error);
  }
};

/**
 * Gets access patterns statistics
 * @returns {Promise<Array>} Access pattern statistics
 */
export const getAccessPatterns = async () => {
  if (!isAuditEnabled) return [];
  
  try {
    const snapshot = await getDocs(collection(db, 'firebaseAudit'));
    
    // Map to track access patterns
    const patterns = new Map();
    
    snapshot.forEach((doc) => {
      const data = doc.data();
      const key = `${data.operation}:${data.path}`;
      
      if (!patterns.has(key)) {
        patterns.set(key, {
          operation: data.operation,
          path: data.path,
          count: 1,
          successes: data.success ? 1 : 0,
          failures: data.success ? 0 : 1,
          lastError: data.success ? null : data.error
        });
      } else {
        const pattern = patterns.get(key);
        pattern.count += 1;
        pattern.successes += data.success ? 1 : 0;
        pattern.failures += data.success ? 0 : 1;
        
        if (!data.success) {
          pattern.lastError = data.error;
        }
      }
    });
    
    return Array.from(patterns.values());
  } catch (error) {
    console.error('[Firebase Audit] Error getting access patterns:', error);
    return [];
  }
};

// Export flags and functions
export const isFirebaseAuditEnabled = isAuditEnabled;