// src/utils/firebase-trace-optimizer.js
// Performance-optimized tracing that conditionally activates based on environment and settings

// Import original tracer utilities
import {
  tracedRef,
  tracedOnValue,
  tracedSet,
  tracedUpdate,
  tracedRemove,
  tracedPush,
  tracedGet,
  tracedDoc,
  tracedGetDoc,
  tracedSetDoc,
  tracedUpdateDoc,
  tracedDeleteDoc,
  tracedCollection,
  tracedQuery,
  tracedGetDocs,
  getAllAccessedPaths,
  clearAccessedPaths,
  addAccessedPath
} from './firebaseTracer';

// Import original Firebase operations
import { 
  ref, 
  onValue, 
  set, 
  update, 
  remove, 
  push, 
  get 
} from 'firebase/database';

import { 
  doc, 
  getDoc, 
  setDoc, 
  updateDoc, 
  deleteDoc, 
  collection, 
  query, 
  getDocs 
} from 'firebase/firestore';

// Import performance monitoring
import { createTimingContext } from './performance-monitor';

// Setup performance tracking
const tracePerformance = createTimingContext('firebase_tracing');

// Tracing configuration - use a static value based on environment to avoid localStorage reads on every operation
const TRACING_ENABLED = import.meta.env.DEV && (
  localStorage.getItem('enableFirebaseTracing') === 'true' || 
  import.meta.env.VITE_DEFAULT_FIREBASE_TRACING === 'true'
);

// Cache to avoid repeated function creation - dramatic performance improvement
const CACHED_OPTIMIZED_FUNCTIONS = {
  // Will be filled with optimized functions
};

/**
 * Get current tracing status
 * @returns {boolean} - Whether tracing is enabled
 */
export const isTracingEnabled = () => {
  return TRACING_ENABLED && import.meta.env.MODE !== 'test';
};

/**
 * Toggle tracing on/off - requires page reload to take effect
 * @returns {boolean} - New tracing state
 */
export const toggleTracing = () => {
  if (!import.meta.env.DEV) return false;
  
  const newState = localStorage.getItem('enableFirebaseTracing') !== 'true';
  localStorage.setItem('enableFirebaseTracing', newState.toString());
  
  // Alert the developer that a reload is needed
  if (typeof window !== 'undefined') {
    window.alert('Firebase tracing setting changed. Please reload the page for it to take effect.');
  }
  
  // Return the new state
  return newState;
};

// Create conditional exports based on environment
// In production or when tracing is disabled, use original Firebase operations
// In development with tracing enabled, use traced operations

// PERFORMANCE OPTIMIZATION: Create enhanced traced functions that include performance monitoring
const createEnhancedTracedFunction = (originalFunction, tracedFunction, operationName) => {
  const cachedKey = `${operationName}_traced`;
  
  // Return from cache if available
  if (CACHED_OPTIMIZED_FUNCTIONS[cachedKey]) {
    return CACHED_OPTIMIZED_FUNCTIONS[cachedKey];
  }
  
  // Create enhanced function with performance tracking
  const enhancedFunction = (...args) => {
    tracePerformance.start(operationName);
    try {
      const result = tracedFunction(...args);
      return result;
    } finally {
      tracePerformance.end(operationName);
    }
  };
  
  // Cache for future use
  CACHED_OPTIMIZED_FUNCTIONS[cachedKey] = enhancedFunction;
  return enhancedFunction;
};

// Performance-optimized function selector
const getOptimizedFunction = (operationName, originalFunction, tracedFunction) => {
  if (!isTracingEnabled()) {
    // For production or tracing disabled - use original functions
    const cachedKey = `${operationName}_original`;
    
    if (CACHED_OPTIMIZED_FUNCTIONS[cachedKey]) {
      return CACHED_OPTIMIZED_FUNCTIONS[cachedKey];
    }
    
    CACHED_OPTIMIZED_FUNCTIONS[cachedKey] = originalFunction;
    return originalFunction;
  } else {
    // For development with tracing - use enhanced traced functions
    return createEnhancedTracedFunction(originalFunction, tracedFunction, operationName);
  }
};

// Realtime Database operations
export const optimizedRef = getOptimizedFunction('ref', ref, tracedRef);
export const optimizedOnValue = getOptimizedFunction('onValue', onValue, tracedOnValue);
export const optimizedSet = getOptimizedFunction('set', set, tracedSet);
export const optimizedUpdate = getOptimizedFunction('update', update, tracedUpdate);
export const optimizedRemove = getOptimizedFunction('remove', remove, tracedRemove);
export const optimizedPush = getOptimizedFunction('push', push, tracedPush);
export const optimizedGet = getOptimizedFunction('get', get, tracedGet);

// Firestore operations
export const optimizedDoc = getOptimizedFunction('doc', doc, tracedDoc);
export const optimizedGetDoc = getOptimizedFunction('getDoc', getDoc, tracedGetDoc);
export const optimizedSetDoc = getOptimizedFunction('setDoc', setDoc, tracedSetDoc);
export const optimizedUpdateDoc = getOptimizedFunction('updateDoc', updateDoc, tracedUpdateDoc);
export const optimizedDeleteDoc = getOptimizedFunction('deleteDoc', deleteDoc, tracedDeleteDoc);
export const optimizedCollection = getOptimizedFunction('collection', collection, tracedCollection);
export const optimizedQuery = getOptimizedFunction('query', query, tracedQuery);
export const optimizedGetDocs = getOptimizedFunction('getDocs', getDocs, tracedGetDocs);

// Tracing utilities - only active in development with tracing enabled
export const optimizedGetAllAccessedPaths = isTracingEnabled() ? getAllAccessedPaths : () => [];
export const optimizedClearAccessedPaths = isTracingEnabled() ? clearAccessedPaths : () => {};
export const optimizedAddAccessedPath = isTracingEnabled() ? addAccessedPath : () => {};

// Export helper to get path information when needed
export const getTracingInfo = () => {
  if (isTracingEnabled()) {
    tracePerformance.start('getTracingInfo');
    try {
      return {
        enabled: true,
        paths: getAllAccessedPaths()
      };
    } finally {
      tracePerformance.end('getTracingInfo');
    }
  }
  
  return {
    enabled: false,
    paths: []
  };
};

// Analysis of tracing impact on performance
export const analyzeTracingPerformance = () => {
  if (!isTracingEnabled()) {
    return {
      enabled: false,
      message: 'Tracing is not enabled. Enable it in development for performance analysis.'
    };
  }
  
  const timings = tracePerformance.getAll();
  const operations = Object.keys(timings)
    .filter(key => key.startsWith('firebase_tracing:'))
    .map(key => {
      const opName = key.split(':')[1];
      return {
        operation: opName,
        averageDuration: timings[key].duration || 0,
        callCount: timings[key].count || 1
      };
    })
    .sort((a, b) => b.averageDuration - a.averageDuration);
  
  const totalTime = operations.reduce((sum, op) => sum + op.averageDuration, 0);
  const slowestOperations = operations.filter(op => op.averageDuration > 50).slice(0, 5);
  
  return {
    enabled: true,
    totalTracingTime: totalTime,
    operationCount: operations.length,
    operations,
    slowestOperations,
    recommendation: totalTime > 500 
      ? 'Consider disabling tracing in this session to improve performance'
      : 'Tracing overhead is acceptable'
  };
};

// Export all operations for ease of use
export default {
  // Configuration
  isTracingEnabled,
  toggleTracing,
  getTracingInfo,
  analyzeTracingPerformance,
  
  // Database operations
  ref: optimizedRef,
  onValue: optimizedOnValue,
  set: optimizedSet,
  update: optimizedUpdate,
  remove: optimizedRemove,
  push: optimizedPush,
  get: optimizedGet,
  
  // Firestore operations
  doc: optimizedDoc,
  getDoc: optimizedGetDoc,
  setDoc: optimizedSetDoc,
  updateDoc: optimizedUpdateDoc,
  deleteDoc: optimizedDeleteDoc,
  collection: optimizedCollection,
  query: optimizedQuery,
  getDocs: optimizedGetDocs,
  
  // Tracing utilities
  getAllAccessedPaths: optimizedGetAllAccessedPaths,
  clearAccessedPaths: optimizedClearAccessedPaths,
  addAccessedPath: optimizedAddAccessedPath
};