// src/components/streaming/VideoStream.jsx
import React, { useRef, useEffect, useState } from 'react';
import { Mic, MicOff, Video, VideoOff, Settings, User } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';

const VideoStream = ({ 
  stream, 
  isSelf = false, 
  displayName, 
  photoURL, 
  hasAudio = true, 
  hasVideo = true,
  onToggleAudio,
  onToggleVideo,
  minimized = false,
  onExpand
}) => {
  const videoRef = useRef(null);
  const { currentUser } = useAuth();
  const [isMuted, setIsMuted] = useState(!hasAudio);
  const [isVideoEnabled, setIsVideoEnabled] = useState(hasVideo);
  const [showControls, setShowControls] = useState(true);
  const [controlsTimeout, setControlsTimeout] = useState(null);
  const [imageError, setImageError] = useState(false);
  
  // Connect stream to video element
  useEffect(() => {
    if (videoRef.current && stream) {
      videoRef.current.srcObject = stream;
      
      // Handle video failure to determine if video is really enabled
      const handleVideoError = () => {
        console.warn('Video element error, switching to placeholder');
        setIsVideoEnabled(false);
      };
      
      videoRef.current.addEventListener('error', handleVideoError);
      
      return () => {
        if (videoRef.current) {
          videoRef.current.removeEventListener('error', handleVideoError);
        }
      };
    }
  }, [stream]);
  
  // Auto-hide controls after inactivity
  useEffect(() => {
    if (!isSelf || minimized) return;
    
    if (showControls) {
      if (controlsTimeout) {
        clearTimeout(controlsTimeout);
      }
      
      const timeout = setTimeout(() => {
        setShowControls(false);
      }, 3000);
      
      setControlsTimeout(timeout);
    }
    
    return () => {
      if (controlsTimeout) {
        clearTimeout(controlsTimeout);
      }
    };
  }, [showControls, isSelf, minimized, controlsTimeout]);
  
  // Handle toggling audio
  const toggleAudio = () => {
    if (onToggleAudio) {
      onToggleAudio(!isMuted);
    }
    setIsMuted(!isMuted);
  };
  
  // Handle toggling video
  const toggleVideo = () => {
    if (onToggleVideo) {
      onToggleVideo(!isVideoEnabled);
    }
    setIsVideoEnabled(!isVideoEnabled);
  };
  
  // Show controls on mouse movement
  const handleMouseMove = () => {
    if (isSelf && !minimized) {
      setShowControls(true);
    }
  };
  
  // Handle click on minimized stream to expand
  const handleMinimizedClick = () => {
    if (minimized && onExpand) {
      onExpand();
    }
  };
  
  // Handle profile image error
  const handleImageError = () => {
    console.warn('Profile image failed to load');
    setImageError(true);
  };
  
  return (
    <div 
      className={`video-stream-container ${minimized ? 'minimized' : ''} ${isSelf ? 'self-stream' : ''}`}
      onMouseMove={handleMouseMove}
      onClick={minimized ? handleMinimizedClick : undefined}
    >
      {/* Video Element */}
      {stream && isVideoEnabled ? (
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted={isSelf || isMuted}
          className="video-element"
        />
      ) : (
        <div className="video-placeholder">
          {photoURL && !imageError ? (
            <img 
              src={photoURL} 
              alt={displayName || 'User'} 
              className="user-avatar" 
              onError={handleImageError}
            />
          ) : (
            <div className="avatar-placeholder">
              <User size={minimized ? 24 : 48} />
            </div>
          )}
        </div>
      )}
      
      {/* User Display Name */}
      <div className="user-display-name">
        {displayName || 'Anonymous'}
        {!hasAudio && <MicOff size={14} className="status-icon muted" />}
      </div>
      
      {/* Stream Controls (only for self) */}
      {isSelf && !minimized && showControls && (
        <div className="stream-controls">
          <button 
            className={`control-button ${isMuted ? 'disabled' : ''}`}
            onClick={toggleAudio}
            title={isMuted ? 'Unmute' : 'Mute'}
          >
            {isMuted ? <MicOff size={18} /> : <Mic size={18} />}
          </button>
          
          <button 
            className={`control-button ${!isVideoEnabled ? 'disabled' : ''}`}
            onClick={toggleVideo}
            title={isVideoEnabled ? 'Turn off camera' : 'Turn on camera'}
          >
            {isVideoEnabled ? <Video size={18} /> : <VideoOff size={18} />}
          </button>
          
          <button 
            className="control-button"
            title="Settings"
          >
            <Settings size={18} />
          </button>
        </div>
      )}
      
      {/* Minimized Status Indicators */}
      {minimized && (
        <div className="minimized-status">
          {!hasVideo && <VideoOff size={14} className="status-icon" />}
          {!hasAudio && <MicOff size={14} className="status-icon" />}
        </div>
      )}
    </div>
  );
};

export default VideoStream;