import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import TopicService from '../services/TopicService';
import CategoryService from '../services/CategoryService';
import './TopicsPage.css';

const TopicsPage = () => {
  const { categoryId } = useParams();
  const [category, setCategory] = useState(null);
  const [topics, setTopics] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    // Load category
    CategoryService.getCategory(categoryId).then(setCategory);

    // Subscribe to real-time topic updates for this category
    const unsubscribe = TopicService.streamTopicsByCategory(categoryId, (updatedTopics) => {
      setTopics(updatedTopics);
      setLoading(false);
    });

    // Cleanup subscription on unmount
    return () => unsubscribe();
  }, [categoryId]);

  const handleTopicClick = (topic) => {
    navigate(`/topics/${topic.id}/ideas`);
  };

  const getTopicIcon = (topic) => {
    if (topic.iconName) {
      const iconMap = {
        music: '🎵',
        art: '🎨',
        gaming: '🎮',
        education: '📚',
        fitness: '💪',
        talk: '💬',
        performance: '🎭',
      };
      return iconMap[topic.iconName?.toLowerCase()] || '🏷️';
    }
    return '🏷️';
  };

  if (loading || !category) {
    return (
      <div className="topics-page">
        <div className="loading">Loading topics...</div>
      </div>
    );
  }

  return (
    <div className="topics-page">
      <div className="topics-header">
        <button className="back-button" onClick={() => navigate('/categories')}>
          ← Back to Categories
        </button>
        <div className="category-title">
          <h1 style={{ color: category.colorHex }}>{category.name}</h1>
          <p>{category.description}</p>
        </div>
      </div>

      {topics.length === 0 ? (
        <div className="empty-state">
          <div className="empty-icon">🏷️</div>
          <h2>No Topics Yet</h2>
          <p>Be the first to create a topic in this category!</p>
        </div>
      ) : (
        <div className="topics-grid">
          {topics.map((topic) => (
            <div
              key={topic.id}
              className="topic-card"
              onClick={() => handleTopicClick(topic)}
              style={{
                borderTop: `3px solid ${topic.colorHex || category.colorHex}`,
              }}
            >
              <div className="topic-icon">
                {getTopicIcon(topic)}
              </div>
              <div className="topic-content">
                <h3>{topic.name}</h3>
                <p>{topic.description}</p>
                <div className="topic-stats">
                  <span className="stat">
                    <span className="stat-icon">💡</span>
                    {topic.ideaCount} ideas
                  </span>
                  <span className="stat">
                    <span className="stat-icon">📅</span>
                    {topic.eventCount} events
                  </span>
                  <span className="stat">
                    <span className="stat-icon">👥</span>
                    {topic.followerCount} followers
                  </span>
                </div>
              </div>
              <div className="topic-arrow">→</div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default TopicsPage;
