// Enhanced EventChatRoom with Multi-Stream Video Support
// Path: C:\Users\Tom\Documents\GitHub\presence-react3\presence-react\src\components\events\EventChatRoomEnhanced.jsx

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { getFirestore, doc, getDoc } from 'firebase/firestore';
import { getDatabase, ref, onValue, push, set, off } from 'firebase/database';
import { 
  MessageCircle, 
  Users, 
  Video, 
  VideoOff, 
  Mic, 
  MicOff, 
  Settings, 
  Send,
  Play,
  Square,
  Crown,
  ArrowLeft,
  Monitor,
  User,
  Lock,
  RefreshCw,
  Eye,
  Wifi,
  WifiOff
} from 'lucide-react';
import MultiStreamPlayer from '../video/MultiStreamPlayer';
// REMOVED: Go2rtc import - migrated to LiveKit
// import Go2rtcMultiStreamService from '../../services/Go2rtcMultiStreamService';
import './EventChatRoom.css';

const EventChatRoomEnhanced = () => {
  const { eventId } = useParams();
  const { currentUser } = useAuth();
  const navigate = useNavigate();
  
  // UI State
  const [loading, setLoading] = useState(true);
  const [event, setEvent] = useState(null);
  const [chatRoom, setChatRoom] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [activeUsers, setActiveUsers] = useState({});
  
  // Multi-Stream State
  const [roomStreamConfig, setRoomStreamConfig] = useState(null);
  const [streamStatus, setStreamStatus] = useState('initializing');
  const [userStreamSlot, setUserStreamSlot] = useState(null);
  const [isUserStreaming, setIsUserStreaming] = useState(false);
  const [streamingPermission, setStreamingPermission] = useState(false);
  
  // Real-time monitoring
  const [monitoringActive, setMonitoringActive] = useState(false);
  const [lastStatusUpdate, setLastStatusUpdate] = useState(null);
  const [streamStats, setStreamStats] = useState({
    totalStreams: 0,
    artistActive: false,
    userStreamsActive: 0,
    availableSlots: 0
  });
  
  // Detect if component is being rendered in an iframe
  const [isEmbedded, setIsEmbedded] = useState(false);
  
  // Refs
  const messagesEndRef = useRef(null);
  const chatInputRef = useRef(null);
  const cleanupRef = useRef(null);
  const rtmpEndpointRef = useRef(null);

  useEffect(() => {
    // Check if we're in an iframe
    const inIframe = window.self !== window.top;
    setIsEmbedded(inIframe);
  }, []);
  
  useEffect(() => {
    if (!eventId) {
      navigate('/events');
      return;
    }
    
    initializeEventChat();
    
    return () => {
      // Cleanup listeners and streams
      if (cleanupRef.current) {
        cleanupRef.current();
      }
      cleanupListeners();
      cleanupUserStream();
    };
  }, [eventId, currentUser]);

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const initializeEventChat = async () => {
    try {
      setLoading(true);
      setStreamStatus('initializing');
      
      // Load event data
      await loadEventData();
      
      // Setup chat room
      await setupChatRoom();
      
      // Initialize multi-stream system
      await initializeMultiStreamSystem();
      
      // Start monitoring
      await startStreamMonitoring();
      
    } catch (error) {
      console.error('❌ Failed to initialize event chat:', error);
      setStreamStatus('error');
    } finally {
      setLoading(false);
    }
  };

  const loadEventData = async () => {
    try {
      const db = getFirestore();
      const eventDoc = await getDoc(doc(db, 'events', eventId));
      
      if (!eventDoc.exists()) {
        throw new Error('Event not found');
      }
      
      const eventData = { id: eventDoc.id, ...eventDoc.data() };
      setEvent(eventData);
      
      // Check if user has streaming permission
      const hasPermission = currentUser && (
        eventData.artistId === currentUser.uid || // Event creator
        eventData.allowUserStreaming === true || // Event allows user streaming
        currentUser.isPremium === true // Premium users
      );
      
      setStreamingPermission(hasPermission);
      
      console.log('📺 Event loaded:', {
        title: eventData.title,
        artistId: eventData.artistId,
        allowUserStreaming: eventData.allowUserStreaming,
        userCanStream: hasPermission
      });
      
    } catch (error) {
      console.error('❌ Failed to load event:', error);
      throw error;
    }
  };

  const setupChatRoom = () => {
    const rtdb = getDatabase();
    const chatRoomPath = `chats/public/event_${eventId}`;
    console.log('🔗 Setting up chat room listeners for:', chatRoomPath);
    
    // Listen to chat room data
    const chatRoomRef = ref(rtdb, chatRoomPath);
    onValue(chatRoomRef, (snapshot) => {
      const data = snapshot.val();
      console.log('📡 Chat room data received:', data);
      if (data) {
        setChatRoom(data);
        setActiveUsers(data.activeUsers || {});
      }
    }, (error) => {
      console.error('❌ Error listening to chat room:', error);
    });
    
    // Listen to messages
    const messagesRef = ref(rtdb, `${chatRoomPath}/messages`);
    console.log('💬 Setting up messages listener for:', `${chatRoomPath}/messages`);
    onValue(messagesRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        const messagesList = Object.entries(data).map(([id, message]) => ({
          id,
          ...message
        })).sort((a, b) => a.timestamp - b.timestamp);
        setMessages(messagesList);
      } else {
        setMessages([]);
      }
    }, (error) => {
      console.error('❌ Error listening to messages:', error);
    });
    
    // Add user to active users if logged in
    if (currentUser) {
      const userRef = ref(rtdb, `${chatRoomPath}/activeUsers/${currentUser.uid}`);
      console.log('👤 Adding user to active users:', currentUser.uid);
      set(userRef, {
        uid: currentUser.uid,
        name: currentUser.displayName || 'Anonymous',
        avatar: currentUser.photoURL || null,
        joinedAt: Date.now(),
        isStreaming: false,
        hasStreamingPermission: streamingPermission
      }).catch(error => {
        console.error('❌ Error adding user to active users:', error);
      });
      
      // Cleanup function
      cleanupRef.current = () => {
        console.log('🧹 Removing user from active users on cleanup');
        set(userRef, null);
      };
    }
  };

  const initializeMultiStreamSystem = async () => {
    try {
      console.log('🎬 Initializing LiveKit multi-stream system for event:', eventId);
      setStreamStatus('setting-up');
      
      // REMOVED: Go2rtc multi-stream setup - migrated to LiveKit
      // TODO: Implement LiveKit room creation and configuration
      console.log('🔧 LiveKit room setup will be implemented here');
      
      // Placeholder for LiveKit room configuration
      const livekitRoomConfig = {
        roomName: eventId,
        maxParticipants: 50,
        enableVideo: true,
        enableAudio: true,
        enableChat: true,
        artistStreamName: `${eventId}_artist`,
        userStreamPrefix: `${eventId}_user_`,
        maxUserStreams: 8
      };
      
      setRoomStreamConfig(livekitRoomConfig);
      setStreamStatus('ready');
      
      console.log('✅ LiveKit multi-stream system initialized (placeholder):', {
        roomName: livekitRoomConfig.roomName,
        maxParticipants: livekitRoomConfig.maxParticipants,
        maxUserStreams: livekitRoomConfig.maxUserStreams
      });
      
    } catch (error) {
      console.error('❌ Error initializing LiveKit multi-stream system:', error);
      setStreamStatus('error');
    }
  };

  const startStreamMonitoring = async () => {
    if (!roomStreamConfig) {
      console.warn('⚠️ Cannot start monitoring without room config');
      return;
    }
    
    console.log('🎯 Starting LiveKit stream monitoring for room:', eventId);
    setMonitoringActive(true);
    
    // REMOVED: Go2rtc monitoring - migrated to LiveKit
    // TODO: Implement LiveKit room monitoring
    console.log('🔧 LiveKit monitoring will be implemented here');
    
    // Placeholder monitoring that updates stats periodically
    const monitoringInterval = setInterval(() => {
      // TODO: Replace with actual LiveKit room status
      const mockStatus = {
        artistActive: false,
        activeUserStreams: 0,
        availableSlots: 8,
        totalStreams: 0
      };
      
      setStreamStats(mockStatus);
      setLastStatusUpdate(Date.now());
      setStreamStatus('monitoring');
      
      console.log('📊 LiveKit monitoring update (placeholder):', mockStatus);
    }, 5000); // Update every 5 seconds
    
    // Store cleanup function
    cleanupRef.current = () => {
      clearInterval(monitoringInterval);
      setMonitoringActive(false);
      console.log('🧹 LiveKit monitoring stopped');
    };
  };

  const requestUserStreamSlot = async () => {
    if (!currentUser || !streamingPermission || !roomStreamConfig) {
      alert('You do not have permission to stream in this room.');
      return;
    }
    
    try {
      console.log('🎥 Requesting stream slot for user:', currentUser.uid);
      
      // REMOVED: Go2rtc slot assignment - migrated to LiveKit
      // TODO: Implement LiveKit participant joining
      console.log('🔧 LiveKit participant joining will be implemented here');
      
      // const result = await Go2rtcMultiStreamService.assignUserStreamSlot(
      //   eventId,
      //   currentUser.uid,
      //   currentUser.displayName || 'Anonymous User'
      // );
      
      // Placeholder result
      const result = {
        success: true,
        slot: {
          slot: 1,
          streamUrl: `https://your-livekit-domain.com/room/${eventId}`,
          rtmpUrl: `rtmp://your-livekit-ingress.com/live/${eventId}_user_${currentUser.uid}`,
          userId: currentUser.uid,
          userName: currentUser.displayName || 'Anonymous User'
        }
      };
      
      if (result.success) {
        setUserStreamSlot(result.slot);
        
        console.log('✅ Stream slot assigned:', {
          slot: result.slot.slot,
          rtmpUrl: result.slot.rtmpUrl,
          streamUrl: result.slot.streamUrl
        });
        
        // Update RTDB with user stream assignment
        if (currentUser) {
          const rtdb = getDatabase();
          const userRef = ref(rtdb, `chats/public/event_${eventId}/activeUsers/${currentUser.uid}`);
          set(userRef, {
            uid: currentUser.uid,
            name: currentUser.displayName || 'Anonymous',
            avatar: currentUser.photoURL || null,
            joinedAt: Date.now(),
            isStreaming: true,
            streamSlot: result.slot.slot,
            hasStreamingPermission: streamingPermission
          });
        }
        
        return result.slot;
        
      } else {
        alert(result.error || 'Failed to get stream slot');
        return null;
      }
      
    } catch (error) {
      console.error('❌ Failed to request stream slot:', error);
      alert('Failed to request streaming slot');
      return null;
    }
  };

  const startUserStreaming = async () => {
    if (!streamingPermission) {
      alert('You do not have permission to stream in this room.');
      return;
    }
    
    try {
      // Get stream slot if not already assigned
      let slot = userStreamSlot;
      if (!slot) {
        slot = await requestUserStreamSlot();
        if (!slot) return;
      }
      
      console.log('🎥 Starting user streaming with slot:', slot.slot);
      
      // Get user media
      const stream = await navigator.mediaDevices.getUserMedia({
        video: true,
        audio: true
      });
      
      // TODO: Implement WebRTC to RTMP bridge or direct RTMP streaming
      // For now, we'll just mark the user as streaming
      setIsUserStreaming(true);
      
      // Show RTMP endpoint to user for external streaming software
      const rtmpInfo = `
RTMP Endpoint: ${slot.rtmpUrl}
Stream Key: (Use your streaming software like OBS)

Your stream will appear to other viewers automatically.
      `;
      
      console.log('📡 RTMP Streaming Info:', rtmpInfo);
      
      // TODO: Integrate with WebRTC-to-RTMP bridge
      
    } catch (error) {
      console.error('❌ Failed to start user streaming:', error);
      alert('Failed to start streaming. Please check camera and microphone permissions.');
    }
  };

  const stopUserStreaming = async () => {
    if (!currentUser || !userStreamSlot) return;
    
    try {
      console.log('🛑 Stopping user streaming');
      
      // REMOVED: Go2rtc slot release - migrated to LiveKit
      // TODO: Implement LiveKit participant leaving
      console.log('🔧 LiveKit participant leaving will be implemented here');
      
      // const result = await Go2rtcMultiStreamService.releaseUserStreamSlot(eventId, currentUser.uid);
      
      // Placeholder result
      const result = { success: true };
      
      if (result.success) {
        setUserStreamSlot(null);
        setIsUserStreaming(false);
        
        // Update RTDB
        const rtdb = getDatabase();
        const userRef = ref(rtdb, `chats/public/event_${eventId}/activeUsers/${currentUser.uid}`);
        set(userRef, {
          uid: currentUser.uid,
          name: currentUser.displayName || 'Anonymous',
          avatar: currentUser.photoURL || null,
          joinedAt: Date.now(),
          isStreaming: false,
          streamSlot: null,
          hasStreamingPermission: streamingPermission
        });
        
        console.log('✅ User streaming stopped and slot released');
      }
      
    } catch (error) {
      console.error('❌ Failed to stop user streaming:', error);
    }
  };

  const cleanupUserStream = async () => {
    if (isUserStreaming && currentUser) {
      await stopUserStreaming();
    }
  };

  const cleanupListeners = () => {
    if (eventId) {
      const rtdb = getDatabase();
      const chatRoomPath = `chats/public/event_${eventId}`;
      off(ref(rtdb, chatRoomPath));
      off(ref(rtdb, `${chatRoomPath}/messages`));
    }
  };

  const sendMessage = async () => {
    if (!newMessage.trim()) {
      console.log('⚠️ Message is empty, not sending');
      return;
    }
    
    if (!currentUser) {
      console.log('❌ User not authenticated, cannot send message');
      alert('Please log in to send messages');
      return;
    }
    
    const rtdb = getDatabase();
    const messagesPath = `chats/public/event_${eventId}/messages`;
    const messagesRef = ref(rtdb, messagesPath);
    
    const messageData = {
      type: 'user',
      message: newMessage.trim(),
      timestamp: Date.now(),
      userId: currentUser.uid,
      userName: currentUser.displayName || currentUser.email || 'User',
      userAvatar: currentUser.photoURL || null,
      isStreaming: isUserStreaming
    };
    
    console.log('🚀 Sending message to:', messagesPath);
    
    try {
      const result = await push(messagesRef, messageData);
      console.log('✅ Message sent successfully:', result.key);
      setNewMessage('');
      chatInputRef.current?.focus();
      
      // Update total message count
      const chatRoomRef = ref(rtdb, `chats/public/event_${eventId}/totalMessages`);
      const currentCount = chatRoom?.totalMessages || 0;
      await set(chatRoomRef, currentCount + 1);
      
    } catch (error) {
      console.error('❌ Failed to send message:', error);
      alert('Failed to send message. Please try again.');
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  };

  const refreshStreamStatus = async () => {
    if (roomStreamConfig) {
      console.log('🔄 Manual LiveKit stream status refresh');
      
      // REMOVED: Go2rtc status refresh - migrated to LiveKit
      // TODO: Implement LiveKit room status refresh
      console.log('🔧 LiveKit room status refresh will be implemented here');
      
      // const status = await Go2rtcMultiStreamService.getRoomStreamStatus(eventId);
      
      // Placeholder status
      const status = {
        success: true,
        artistActive: false,
        activeUserStreams: 0,
        availableSlots: 8,
        totalStreams: 0
      };
      
      console.log('📊 Manual refresh result (placeholder):', status);
    }
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const formatTime = (timestamp) => {
    return new Date(timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  const isAnonymousUser = () => {
    return !currentUser;
  };

  const handleStreamChange = useCallback((newStreamStats) => {
    console.log('📊 Stream stats updated:', newStreamStats);
    setStreamStats(newStreamStats);
  }, []);

  if (loading) {
    return (
      <div className="event-chat-loading">
        <div className="loading-spinner"></div>
        <p>Loading event chat...</p>
      </div>
    );
  }

  return (
    <div className={`event-chat-room enhanced ${isEmbedded ? 'embedded' : ''}`}>
      {/* Header - Hidden when embedded */}
      {!isEmbedded && (
        <div className="chat-room-header">
          <button className="back-btn" onClick={() => navigate('/events')}>
            <ArrowLeft size={20} />
          </button>
          <div className="event-info">
            <h2>{event?.title}</h2>
            <p>{event?.artistName} • {Object.keys(activeUsers).length} viewers</p>
          </div>
          <div className="event-status">
            <div className={`status-indicator ${event?.status}`}>
              {event?.status?.toUpperCase()}
            </div>
            <div className="stream-status">
              <div className={`stream-indicator ${streamStatus}`}>
                {streamStatus === 'monitoring' && monitoringActive && (
                  <>
                    <Wifi size={14} />
                    <span>{streamStats.totalStreams} streaming</span>
                  </>
                )}
                {streamStatus === 'error' && (
                  <>
                    <WifiOff size={14} />
                    <span>Error</span>
                  </>
                )}
                {streamStatus === 'ready' && (
                  <>
                    <Play size={14} />
                    <span>Ready</span>
                  </>
                )}
              </div>
              <button onClick={refreshStreamStatus} className="refresh-btn">
                <RefreshCw size={14} />
              </button>
            </div>
          </div>
        </div>
      )}

      <div className={`chat-room-body enhanced ${isEmbedded ? 'embedded-body' : ''}`}>
        {/* Multi-Stream Video Area - Hidden when embedded */}
        {!isEmbedded && roomStreamConfig && (
          <div className="video-pane enhanced">
            <MultiStreamPlayer
              roomId={eventId}
              streamConfig={roomStreamConfig}
              onStreamChange={handleStreamChange}
              currentUser={currentUser}
              userCanStream={streamingPermission}
            />
          </div>
        )}

        {/* Chat Pane - Always visible, full width when embedded */}
        <div className={`chat-pane enhanced ${isEmbedded ? 'embedded-chat' : ''}`}>
          {/* Stream Controls */}
          <div className="stream-controls enhanced">
            <div className="controls-header">
              <h3>
                <Video size={16} />
                Stream Controls
              </h3>
              <div className="stream-stats">
                <span>{streamStats.totalStreams} active</span>
                <span>{streamStats.availableSlots} slots available</span>
              </div>
            </div>
            
            {currentUser && streamingPermission ? (
              <div className="user-controls enhanced">
                {!isUserStreaming ? (
                  <button className="start-stream-btn enhanced" onClick={startUserStreaming}>
                    <Video size={16} />
                    Start Streaming
                  </button>
                ) : (
                  <div className="streaming-controls enhanced">
                    <button className="stop-stream-btn enhanced" onClick={stopUserStreaming}>
                      <Square size={16} />
                      Stop Stream
                    </button>
                    {userStreamSlot && (
                      <div className="rtmp-info">
                        <small>Slot {userStreamSlot.slot} • Use OBS or streaming software</small>
                      </div>
                    )}
                  </div>
                )}
              </div>
            ) : (
              <div className="no-permission-controls">
                {!currentUser ? (
                  <p>Login to stream in this event</p>
                ) : (
                  <p>Streaming not available for this event</p>
                )}
                {!currentUser && (
                  <button className="login-btn" onClick={() => navigate('/login')}>
                    Login
                  </button>
                )}
              </div>
            )}
          </div>

          {/* Chat Messages */}
          <div className="chat-messages enhanced">
            <div className="messages-header">
              <MessageCircle size={16} />
              <span>Event Chat</span>
              <span className="message-count">({messages.length})</span>
            </div>
            
            <div className="messages-container">
              {messages.map((message) => (
                <div key={message.id} className={`message ${message.type} ${message.isStreaming ? 'streaming' : ''}`}>
                  {message.type === 'system' ? (
                    <div className="system-message">
                      <span className="system-text">{message.message}</span>
                      <span className="message-time">{formatTime(message.timestamp)}</span>
                    </div>
                  ) : (
                    <div className="user-message">
                      <div className="message-avatar">
                        {message.userAvatar ? (
                          <img src={message.userAvatar} alt={message.userName} />
                        ) : (
                          <div className="avatar-placeholder">
                            {message.userName?.charAt(0) || 'A'}
                          </div>
                        )}
                        {message.isStreaming && (
                          <div className="streaming-badge">
                            <Video size={10} />
                          </div>
                        )}
                      </div>
                      <div className="message-content">
                        <div className="message-header">
                          <span className="message-author">{message.userName}</span>
                          {message.isStreaming && (
                            <span className="streaming-indicator">
                              <Video size={12} />
                              LIVE
                            </span>
                          )}
                          <span className="message-time">{formatTime(message.timestamp)}</span>
                        </div>
                        <p className="message-text">{message.message}</p>
                      </div>
                    </div>
                  )}
                </div>
              ))}
              <div ref={messagesEndRef} />
            </div>
          </div>

          {/* Chat Input */}
          <div className="chat-input-container enhanced">
            <div className="chat-input">
              <input
                ref={chatInputRef}
                type="text"
                value={newMessage}
                onChange={(e) => setNewMessage(e.target.value)}
                onKeyPress={handleKeyPress}
                placeholder={isAnonymousUser() ? "Please login to chat" : "Type a message..."}
                maxLength={500}
                disabled={isAnonymousUser()}
              />
              <button 
                className="send-btn"
                onClick={sendMessage}
                disabled={!newMessage.trim() || isAnonymousUser()}
              >
                <Send size={16} />
              </button>
            </div>
            {isAnonymousUser() && (
              <div className="anonymous-note">
                <p>You're viewing anonymously. <button onClick={() => navigate('/login')}>Login</button> to chat and stream.</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default EventChatRoomEnhanced;
