// src/components/stars/StarBadge.jsx
import React from 'react';
import { Star } from 'lucide-react';
import {
  STAR_TIERS,
  STAR_COLORS,
  STAR_LABELS,
  deriveStarTier,
} from '../../utils/stars';
import './StarBadge.css';

const SIZE_PX = {
  sm: 16,
  md: 24,
  lg: 48,
};

/**
 * Renders a single star icon colored by tier, optionally with the closed-deal
 * count next to it. Pass either `tier` directly or `count` to derive the tier.
 *
 * <StarBadge count={127} size="lg" showCount />
 * <StarBadge tier="purple" size="sm" />
 */
const StarBadge = ({
  tier,
  count,
  size = 'md',
  showCount = false,
  className = '',
  title,
}) => {
  const resolvedTier =
    tier && Object.values(STAR_TIERS).includes(tier)
      ? tier
      : deriveStarTier(count);

  const color = STAR_COLORS[resolvedTier];
  const pixels = SIZE_PX[size] || SIZE_PX.md;
  const isEmpty = resolvedTier === STAR_TIERS.NONE;
  const tooltip = title || STAR_LABELS[resolvedTier];

  return (
    <span
      className={`star-badge star-badge--${size} star-badge--${resolvedTier} ${className}`}
      title={tooltip}
      aria-label={tooltip}
    >
      <Star
        size={pixels}
        color={color}
        fill={isEmpty ? 'none' : color}
        strokeWidth={isEmpty ? 1.75 : 1.25}
      />
      {showCount && (
        <span className="star-badge__count" style={{ color }}>
          {Number.isFinite(Number(count)) ? Number(count) : 0}
        </span>
      )}
    </span>
  );
};

export default StarBadge;
