// src/utils/storageTester.js
import { storage } from '../firebase';
import { ref, uploadBytes, getDownloadURL } from 'firebase/storage';

/**
 * Tests Firebase Storage connectivity by uploading a small test file
 * @returns {Promise<Object>} Results of the test
 */
export const testStorageConnection = async () => {
  console.log('🔍 Testing Firebase Storage connection...');
  
  const results = {
    success: false,
    url: null,
    error: null
  };
  
  try {
    // Check if storage is properly initialized
    if (!storage || !storage.app) {
      throw new Error('Firebase Storage is not properly initialized');
    }
    
    console.log('Storage bucket:', storage.app.options.storageBucket);
    
    // Create a test file path in the backgrounds folder
    const testFilePath = `backgrounds/test_${Date.now()}.txt`;
    const storageRef = ref(storage, testFilePath);
    
    // Upload a small test file
    const testBlob = new Blob(['test content'], { type: 'text/plain' });
    const metadata = {
      contentType: 'text/plain',
      customMetadata: {
        purpose: 'connectivity-test',
        timestamp: new Date().toISOString()
      }
    };
    
    // Upload the file
    console.log('Uploading test file to:', testFilePath);
    const snapshot = await uploadBytes(storageRef, testBlob, metadata);
    console.log('Test file uploaded successfully');
    
    // Get download URL
    const downloadURL = await getDownloadURL(snapshot.ref);
    console.log('Download URL obtained:', downloadURL);
    
    results.success = true;
    results.url = downloadURL;
    
    return results;
  } catch (error) {
    console.error('Storage test failed:', error);
    results.error = {
      code: error.code || 'unknown',
      message: error.message || 'Unknown error'
    };
    return results;
  }
};

// Add to window for console debugging
window.testStorageConnection = testStorageConnection;

export default { testStorageConnection };