export const ADROLL_CONFIG = {
  advId: import.meta.env.VITE_ADROLL_ADV_ID || 'K5YFSMC27BF6ZEHYPHRM5R',
  pixId: import.meta.env.VITE_ADROLL_PIX_ID || 'LPBSVJLQN5GEJFFTIEDLQE',
  
  // Ad placement configuration
  videoAd: {
    containerId: 'adroll-video-container',
    width: 300,
    height: 250,
    position: 'top-right',
    zIndex: 999,
    marginTop: '10px',
    marginRight: '10px'
  },
  
  // Text ad configuration
  textAd: {
    containerId: 'adroll-text-container',
    width: 728,
    height: 90,
    position: 'bottom-center'
  },
  
  // Timing configuration for anonymous users
  anonymousUserAdDelay: 5 * 60 * 1000, // 5 minutes in milliseconds
  adDisplayDuration: 30 * 1000, // 30 seconds
  
  // Ad types
  adTypes: {
    VIDEO: 'video',
    TEXT: 'text',
    BANNER: 'banner'
  }
};

// Helper function to initialize AdRoll with config
export const initializeAdRoll = () => {
  if (!window.adroll_adv_id || window.adroll_adv_id === 'REPLACE_WITH_YOUR_ADV_ID') {
    window.adroll_adv_id = ADROLL_CONFIG.advId;
    window.adroll_pix_id = ADROLL_CONFIG.pixId;
  }
};

// Track custom events
export const trackAdRollEvent = (eventName, properties = {}) => {
  if (window.adroll && window.adroll.track) {
    window.adroll.track(eventName, properties);
  }
};

// Track conversions
export const trackAdRollConversion = (value = null, currency = 'USD') => {
  const conversionData = {};
  if (value !== null) {
    conversionData.conversion_value = value;
    conversionData.currency = currency;
  }
  trackAdRollEvent('conversion', conversionData);
};