import { createContext, useContext, useReducer, useEffect } from 'react'
import firebaseStorage, { subscribePredictions } from '../services/firebaseStorage'
// Legacy storageService retained as fallback when firebase is unreachable
// (import preserves localStorage seeding for fully-offline preview).
import storageService from '../services/storageService'

const PredictionContext = createContext()

const initialState = {
  predictions: [],
  loading: true,
  error: null,
  filters: { category: 'all', sort: 'confidence', search: '' },
}

function reducer(state, action) {
  switch (action.type) {
    case 'SET_PREDICTIONS':
      return { ...state, predictions: action.payload, loading: false }
    case 'UPDATE_PREDICTION': {
      const updated = state.predictions.map(p =>
        p.id === action.payload.id ? action.payload : p
      )
      return { ...state, predictions: updated }
    }
    case 'ADD_PREDICTION':
      return { ...state, predictions: [action.payload, ...state.predictions] }
    case 'DELETE_PREDICTION':
      return { ...state, predictions: state.predictions.filter(p => p.id !== action.payload) }
    case 'SET_FILTERS':
      return { ...state, filters: { ...state.filters, ...action.payload } }
    case 'SET_LOADING':
      return { ...state, loading: action.payload }
    case 'SET_ERROR':
      return { ...state, error: action.payload, loading: false }
    default:
      return state
  }
}

function applyFilters(predictions, filters) {
  let result = [...predictions]

  if (filters.category && filters.category !== 'all') {
    result = result.filter(p => p.category === filters.category)
  }

  if (filters.search) {
    const q = filters.search.toLowerCase()
    result = result.filter(p =>
      p.title.toLowerCase().includes(q) || p.description.toLowerCase().includes(q)
    )
  }

  switch (filters.sort) {
    case 'confidence':
      result.sort((a, b) => b.outcomes[0].probability - a.outcomes[0].probability)
      break
    case 'trending':
      result.sort((a, b) => {
        const trendVal = t => t === 'up' ? 2 : t === 'stable' ? 1 : 0
        return trendVal(b.outcomes[0].trend) - trendVal(a.outcomes[0].trend)
      })
      break
    case 'deadline':
      result.sort((a, b) => new Date(a.deadline) - new Date(b.deadline))
      break
    case 'newest':
      result.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
      break
    default:
      break
  }

  return result
}

export function PredictionProvider({ children }) {
  const [state, dispatch] = useReducer(reducer, initialState)

  useEffect(() => {
    // Live subscription to Firebase RTDB. Returns unsub fn.
    // The first callback fires immediately with cached data (if any),
    // then again whenever the underlying ref updates — so adds/edits/deletes
    // from any client appear here without manual refresh.
    let unsubscribe;
    try {
      unsubscribe = subscribePredictions((data) => {
        dispatch({ type: 'SET_PREDICTIONS', payload: data });
      });
    } catch (e) {
      // Firebase init failed (e.g. no network in dev). Fall back to
      // localStorage seed so the page still renders with mock data.
      console.warn('[predict] Firebase subscribe failed, falling back to localStorage:', e?.message);
      storageService.getPredictions()
        .then(data => dispatch({ type: 'SET_PREDICTIONS', payload: data }))
        .catch(err => dispatch({ type: 'SET_ERROR', payload: err.message }));
    }
    return () => { try { unsubscribe?.(); } catch {} };
  }, [])

  const filteredPredictions = applyFilters(state.predictions, state.filters)

  const value = {
    predictions: filteredPredictions,
    allPredictions: state.predictions,
    loading: state.loading,
    error: state.error,
    filters: state.filters,
    dispatch,
    setCategory: category => dispatch({ type: 'SET_FILTERS', payload: { category } }),
    setSort: sort => dispatch({ type: 'SET_FILTERS', payload: { sort } }),
    setSearch: search => dispatch({ type: 'SET_FILTERS', payload: { search } }),
    getPrediction: id => state.predictions.find(p => p.id === id),
    addPrediction: async prediction => {
      // Live snapshot will pick up the new record; we don't need to dispatch
      // ADD_PREDICTION manually — but do so anyway for instant UI feedback
      // in case the snapshot lags (e.g. cold connection).
      const saved = await firebaseStorage.savePrediction(prediction)
      dispatch({ type: 'ADD_PREDICTION', payload: saved })
    },
    deletePrediction: async id => {
      await firebaseStorage.deletePrediction(id)
      dispatch({ type: 'DELETE_PREDICTION', payload: id })
    },
  }

  return (
    <PredictionContext.Provider value={value}>
      {children}
    </PredictionContext.Provider>
  )
}

export function usePredictions() {
  const ctx = useContext(PredictionContext)
  if (!ctx) throw new Error('usePredictions must be used within PredictionProvider')
  return ctx
}
