import newsService from './newsService'
import rssService from './rssService'
import aiService from './aiService'
import apiKeyService from './apiKeyService'

const PIPELINE_CACHE_KEY = 'predict_pipeline_results'
const PIPELINE_CACHE_TTL = 10 * 60 * 1000 // 10 minutes

function getCachedResults() {
  try {
    const raw = localStorage.getItem(PIPELINE_CACHE_KEY)
    if (!raw) return null
    const cached = JSON.parse(raw)
    if (Date.now() - cached.timestamp > PIPELINE_CACHE_TTL) return null
    return cached
  } catch {
    return null
  }
}

function setCachedResults(data) {
  localStorage.setItem(PIPELINE_CACHE_KEY, JSON.stringify({ ...data, timestamp: Date.now() }))
}

const inputPipeline = {
  async runFullScan(predictions) {
    const results = {
      newsInputs: [],
      rssInputs: [],
      aiInputs: [],
      newsArticles: [],
      rssItems: [],
      errors: [],
      sources: { news: false, rss: false, ai: false },
      timestamp: Date.now(),
    }

    // Run news and RSS fetches in parallel
    const [newsResult, rssResult] = await Promise.allSettled([
      apiKeyService.hasNewsApiKey() ? newsService.fetchHeadlines() : Promise.resolve({ articles: [], error: 'No API key' }),
      rssService.fetchAllFeeds(),
    ])

    // Process news results
    if (newsResult.status === 'fulfilled') {
      const { articles, error } = newsResult.value
      if (error) {
        results.errors.push({ source: 'NewsAPI', error })
      } else {
        results.newsArticles = articles
        results.newsInputs = newsService.generateInputsFromArticles(articles, predictions)
        results.sources.news = true
      }
    }

    // Process RSS results
    if (rssResult.status === 'fulfilled') {
      const { items, errors } = rssResult.value
      results.rssItems = items
      results.rssInputs = rssService.generateInputsFromRss(items, predictions)
      results.sources.rss = items.length > 0
      if (errors.length) {
        results.errors.push(...errors.map(e => ({ source: `RSS: ${e.feed}`, error: e.error })))
      }
    }

    setCachedResults(results)
    return results
  },

  async runAiAnalysis(prediction, articles = []) {
    if (!apiKeyService.hasClaudeApiKey()) {
      return { input: null, analysis: null, error: 'No Claude API key configured' }
    }

    const { analysis, error, fromCache } = await aiService.analyzePrediction(prediction, articles)
    if (error) return { input: null, analysis: null, error }

    const input = aiService.generateInputFromAnalysis(analysis, prediction.id)
    return { input, analysis, error: null, fromCache }
  },

  mergeInputsWithPrediction(prediction, liveInputs) {
    const staticInputs = prediction.inputs.filter(i => !i.isLive)
    const allInputs = [...staticInputs, ...liveInputs]

    // Deduplicate by source + predictionId, keeping most recent
    const seen = new Map()
    for (const input of allInputs) {
      const key = `${input.source}_${input.type}`
      const existing = seen.get(key)
      if (!existing || new Date(input.timestamp) > new Date(existing.timestamp)) {
        seen.set(key, input)
      }
    }

    return Array.from(seen.values()).sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp))
  },

  recalculateOutcomes(prediction, liveInputs, aiAnalysis = null) {
    if (aiAnalysis?.adjustedOutcomes) {
      return aiAnalysis.adjustedOutcomes.map(o => ({
        label: o.label,
        probability: Math.round(o.probability),
        trend: o.trend || 'stable',
      }))
    }

    if (liveInputs.length === 0) return prediction.outcomes

    // Calculate weighted sentiment from live inputs
    let totalWeight = 0
    let weightedSentiment = 0
    for (const input of liveInputs) {
      const w = (input.weight || 0.5) * (input.reliability || 0.5)
      weightedSentiment += input.sentiment * w
      totalWeight += w
    }

    if (totalWeight === 0) return prediction.outcomes

    const avgSentiment = weightedSentiment / totalWeight
    // Blend original probabilities with live sentiment
    const blendFactor = Math.min(0.3, liveInputs.length * 0.05) // Max 30% influence from live data

    return prediction.outcomes.map((outcome, i) => {
      const original = outcome.probability / 100
      let adjusted
      if (i === 0) {
        adjusted = original * (1 - blendFactor) + avgSentiment * blendFactor
      } else {
        adjusted = original * (1 - blendFactor) + (1 - avgSentiment) * blendFactor / (prediction.outcomes.length - 1)
      }

      // Determine trend
      const diff = adjusted * 100 - outcome.probability
      let trend = 'stable'
      if (diff > 2) trend = 'up'
      else if (diff < -2) trend = 'down'

      return {
        label: outcome.label,
        probability: Math.max(1, Math.min(99, Math.round(adjusted * 100))),
        trend,
      }
    })
  },

  getCachedResults,

  clearAllCaches() {
    for (const key of Object.keys(localStorage)) {
      if (key.startsWith('predict_news_cache') ||
          key.startsWith('predict_rss_cache') ||
          key.startsWith('predict_ai_cache') ||
          key.startsWith('predict_pipeline')) {
        localStorage.removeItem(key)
      }
    }
  },
}

export default inputPipeline
