/**
 * Format a date/time to the user's local timezone
 * @param {Date|string|number} date - Date to format
 * @param {object} options - Formatting options
 * @returns {string} Formatted local time string
 */
export const formatLocalTime = (date, options = {}) => {
  try {
    const dateObj = new Date(date);
    
    if (isNaN(dateObj.getTime())) {
      return 'Invalid Date';
    }

    const defaultOptions = {
      timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone,
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      hour12: true,
      ...options
    };

    return new Intl.DateTimeFormat('en-US', defaultOptions).format(dateObj);
  } catch (error) {
    console.error('❌ Error formatting local time:', error);
    return new Date(date).toLocaleString();
  }
};

/**
 * Format date for datetime-local input
 * @param {Date|string|number} date - Date to format
 * @returns {string} Formatted datetime-local string
 */
export const formatDateTimeLocal = (date) => {
  try {
    const dateObj = new Date(date);
    
    if (isNaN(dateObj.getTime())) {
      return '';
    }

    // Format as YYYY-MM-DDTHH:mm for datetime-local input
    const year = dateObj.getFullYear();
    const month = String(dateObj.getMonth() + 1).padStart(2, '0');
    const day = String(dateObj.getDate()).padStart(2, '0');
    const hours = String(dateObj.getHours()).padStart(2, '0');
    const minutes = String(dateObj.getMinutes()).padStart(2, '0');
    
    return `${year}-${month}-${day}T${hours}:${minutes}`;
  } catch (error) {
    console.error('❌ Error formatting datetime-local:', error);
    return '';
  }
};

/**
 * Get current time rounded to nearest 5 minutes for cleaner scheduling
 * @returns {string} Formatted datetime-local string
 */
export const getCurrentTimeRounded = () => {
  try {
    const now = new Date();
    
    // Round to nearest 5 minutes for cleaner scheduling
    const minutes = Math.ceil(now.getMinutes() / 5) * 5;
    now.setMinutes(minutes);
    now.setSeconds(0);
    now.setMilliseconds(0);
    
    return formatDateTimeLocal(now);
  } catch (error) {
    console.error('❌ Error getting current time rounded:', error);
    return formatDateTimeLocal(new Date());
  }
};

/**
 * Format time with timezone abbreviation
 * @param {Date|string|number} date - Date to format
 * @returns {string} Time with timezone abbreviation
 */
export const formatTimeWithTimezone = (date) => {
  try {
    const dateObj = new Date(date);
    
    if (isNaN(dateObj.getTime())) {
      return 'Invalid Date';
    }

    const timeString = formatLocalTime(date, { 
      year: undefined, 
      month: undefined, 
      day: undefined 
    });
    const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;
    const tzAbbr = new Intl.DateTimeFormat('en', {
      timeZoneName: 'short'
    }).format(dateObj).split(' ').pop();

    return `${timeString} ${tzAbbr}`;
  } catch (error) {
    console.error('❌ Error formatting time with timezone:', error);
    return new Date(date).toLocaleTimeString();
  }
};

/**
 * Get user's timezone information
 * @returns {object} Timezone information
 */
export const getUserTimezone = () => {
  try {
    const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;
    const now = new Date();
    const offset = now.getTimezoneOffset();
    const offsetHours = Math.abs(Math.floor(offset / 60));
    const offsetMinutes = Math.abs(offset % 60);
    const offsetSign = offset <= 0 ? '+' : '-';
    
    return {
      timezone,
      offset,
      offsetString: `UTC${offsetSign}${offsetHours.toString().padStart(2, '0')}:${offsetMinutes.toString().padStart(2, '0')}`,
      isDST: now.getTimezoneOffset() < Math.max(
        new Date(now.getFullYear(), 0, 1).getTimezoneOffset(),
        new Date(now.getFullYear(), 6, 1).getTimezoneOffset()
      )
    };
  } catch (error) {
    console.error('❌ Error getting user timezone:', error);
    return {
      timezone: 'UTC',
      offset: 0,
      offsetString: 'UTC+00:00',
      isDST: false
    };
  }
};

/**
 * Format event start time with context
 * @param {Date|string|number} startTime - Event start time
 * @returns {string} Formatted time with context
 */
export const formatEventStartTime = (startTime) => {
  try {
    const startDate = new Date(startTime);
    const now = new Date();
    const diffMs = startDate.getTime() - now.getTime();
    const diffMins = Math.floor(diffMs / (1000 * 60));
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);

    // Format the time
    const timeStr = formatLocalTime(startTime);
    
    // Add context based on timing
    if (diffMs < 0) {
      // Event has started
      if (Math.abs(diffMins) < 60) {
        return `${timeStr} (Started ${Math.abs(diffMins)} mins ago)`;
      } else if (Math.abs(diffHours) < 24) {
        return `${timeStr} (Started ${Math.abs(diffHours)} hours ago)`;
      } else {
        return `${timeStr} (Past event)`;
      }
    } else if (diffMins < 5) {
      // Starting very soon
      return `${timeStr} (Starting in ${diffMins} mins)`;
    } else if (diffMins < 60) {
      // Starting soon
      return `${timeStr} (Starting in ${diffMins} mins)`;
    } else if (diffHours < 24) {  
      // Starting today
      return `${timeStr} (Starting in ${diffHours} hours)`;
    } else if (diffDays === 1) {
      // Tomorrow
      return `${timeStr} (Tomorrow)`;
    } else if (diffDays < 7) {
      // This week
      return `${timeStr} (In ${diffDays} days)`;
    } else {
      // Future
      return timeStr;
    }
  } catch (error) {
    console.error('❌ Error formatting event start time:', error);
    return formatLocalTime(startTime);
  }
};

/**
 * Check if a time is "now" (within current time range)
 * @param {Date|string|number} startTime - Event start time
 * @param {number} durationMinutes - Event duration in minutes
 * @returns {boolean} Whether the event is happening now
 */
export const isEventHappeningNow = (startTime, durationMinutes = 60) => {
  try {
    const startDate = new Date(startTime);
    const endDate = new Date(startDate.getTime() + (durationMinutes * 60 * 1000));
    const now = new Date();

    return now >= startDate && now <= endDate;
  } catch (error) {
    console.error('❌ Error checking if event is happening now:', error);
    return false;
  }
};

/**
 * Validate datetime-local input value
 * @param {string} value - datetime-local input value
 * @returns {boolean} Whether the value is valid and in the future
 */
export const validateEventDateTime = (value) => {
  try {
    if (!value) return false;
    
    const eventTime = new Date(value);
    const now = new Date();
    
    // Must be a valid date and in the future (allowing 1 minute buffer for immediate events)
    return !isNaN(eventTime.getTime()) && eventTime >= (now - 60000);
  } catch (error) {
    console.error('❌ Error validating event datetime:', error);
    return false;
  }
};

// Export all functions
export default {
  formatLocalTime,
  formatDateTimeLocal,
  getCurrentTimeRounded,
  formatTimeWithTimezone,
  getUserTimezone,
  formatEventStartTime,
  isEventHappeningNow,
  validateEventDateTime
};
