// src/components/layout/ProductSwitcher.jsx
//
// Talk Studio is the company, so the wordmark in the nav opens onto the rest
// of the family: this app, SmartInvestor CRM and the Store. Sits next to the
// brand in TalkStudioNav and links out to /products for the full rundown.

import React, { useCallback, useEffect, useRef, useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { ChevronDown, ExternalLink, Check } from 'lucide-react';
import { PRODUCTS, CURRENT_PRODUCT_ID } from '../../config/products';

const ProductSwitcher = ({ currentId = CURRENT_PRODUCT_ID }) => {
  const [open, setOpen] = useState(false);
  const { pathname } = useLocation();
  const onProductsPage = pathname === '/products';
  const wrapRef = useRef(null);
  const buttonRef = useRef(null);

  const close = useCallback(() => setOpen(false), []);

  // Click-away and Escape — the menu is a popover, not a page.
  useEffect(() => {
    if (!open) return undefined;

    const onPointerDown = (e) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target)) close();
    };
    const onKeyDown = (e) => {
      if (e.key === 'Escape') {
        close();
        buttonRef.current?.focus();
      }
    };

    document.addEventListener('mousedown', onPointerDown);
    document.addEventListener('keydown', onKeyDown);
    return () => {
      document.removeEventListener('mousedown', onPointerDown);
      document.removeEventListener('keydown', onKeyDown);
    };
  }, [open, close]);

  const renderItem = (product) => {
    const isCurrent = product.id === currentId;
    const body = (
      <>
        <span className="ts-product-dot" style={{ background: product.accent }} />
        <span className="ts-product-text">
          <span className="ts-product-name">
            {product.name}
            {product.external && <ExternalLink size={11} className="ts-product-out" />}
          </span>
          <span className="ts-product-tagline">{product.tagline}</span>
        </span>
        {isCurrent && <Check size={14} className="ts-product-check" />}
      </>
    );

    const className = `ts-product-item ${isCurrent ? 'current' : ''}`;

    if (product.external) {
      return (
        <a
          key={product.id}
          href={product.href}
          target="_blank"
          rel="noopener noreferrer"
          className={className}
          role="menuitem"
          onClick={close}
        >
          {body}
        </a>
      );
    }

    return (
      <Link
        key={product.id}
        to={product.to}
        className={className}
        role="menuitem"
        onClick={close}
        aria-current={isCurrent ? 'page' : undefined}
      >
        {body}
      </Link>
    );
  };

  return (
    <div className="ts-product-switcher" ref={wrapRef}>
      <button
        ref={buttonRef}
        type="button"
        className={`ts-product-trigger ${open ? 'open' : ''} ${onProductsPage ? 'active' : ''}`}
        onClick={() => setOpen(v => !v)}
        aria-haspopup="menu"
        aria-expanded={open}
        aria-label="Switch product"
      >
        Products
        <ChevronDown size={13} />
      </button>

      {open && (
        <div className="ts-product-menu" role="menu">
          <div className="ts-product-menu-head">Talk Studio products</div>
          {PRODUCTS.map(renderItem)}
          <Link to="/products" className="ts-product-menu-foot" role="menuitem" onClick={close}>
            All products
          </Link>
        </div>
      )}
    </div>
  );
};

export default ProductSwitcher;
