import { getDatabase, ref, onValue, set, update, remove, push, get } from "firebase/database";
import { getFirestore, doc, getDoc, setDoc, updateDoc, deleteDoc, collection, query, where, getDocs } from "firebase/firestore";

// Store for tracked paths
const accessedPaths = new Set();

// Helper function to log path access
const logPathAccess = (type, path) => {
  console.log(`%c🔍 Traced ${type} path: ${path}`, 'color: blue');
  accessedPaths.add(`${type}/${path}`);
};

// Realtime Database tracing
export const tracedRef = (path) => {
  logPathAccess('database', path);
  return ref(getDatabase(), path);
};

export const tracedOnValue = (reference, callback, options) => {
  if (reference._path) {
    logPathAccess('database', reference._path.toString());
  }
  return onValue(reference, callback, options);
};

export const tracedSet = (reference, value) => {
  if (reference._path) {
    accessedPaths.add(`database/${reference._path.toString()}`);
  }
  return set(reference, value);
};

export const tracedUpdate = (reference, values) => {
  if (reference._path) {
    accessedPaths.add(`database/${reference._path.toString()}`);
  }
  return update(reference, values);
};

export const tracedRemove = (reference) => {
  if (reference._path) {
    accessedPaths.add(`database/${reference._path.toString()}`);
  }
  return remove(reference);
};

export const tracedPush = (reference, value) => {
  if (reference._path) {
    accessedPaths.add(`database/${reference._path.toString()}`);
  }
  return push(reference, value);
};

export const tracedGet = (reference) => {
  if (reference._path) {
    accessedPaths.add(`database/${reference._path.toString()}`);
  }
  return get(reference);
};

// Firestore tracing
export const tracedDoc = (collectionPath, ...pathSegments) => {
  const fullPath = [collectionPath, ...pathSegments].join('/');
  accessedPaths.add(`firestore/${fullPath}`);
  return doc(getFirestore(), collectionPath, ...pathSegments);
};

export const tracedGetDoc = async (docRef) => {
  if (docRef.path) {
    accessedPaths.add(`firestore/${docRef.path}`);
  }
  return await getDoc(docRef);
};

export const tracedSetDoc = async (docRef, data, options) => {
  if (docRef.path) {
    accessedPaths.add(`firestore/${docRef.path}`);
  }
  return await setDoc(docRef, data, options);
};

export const tracedUpdateDoc = async (docRef, data) => {
  if (docRef.path) {
    accessedPaths.add(`firestore/${docRef.path}`);
  }
  return await updateDoc(docRef, data);
};

export const tracedDeleteDoc = async (docRef) => {
  if (docRef.path) {
    accessedPaths.add(`firestore/${docRef.path}`);
  }
  return await deleteDoc(docRef);
};

export const tracedCollection = (path, ...pathSegments) => {
  const fullPath = [path, ...pathSegments].join('/');
  accessedPaths.add(`firestore/${fullPath}`);
  return collection(getFirestore(), path, ...pathSegments);
};

export const tracedQuery = (collectionRef, ...queryConstraints) => {
  if (collectionRef.path) {
    accessedPaths.add(`firestore/${collectionRef.path}`);
  }
  return query(collectionRef, ...queryConstraints);
};

export const tracedGetDocs = async (queryRef) => {
  if (queryRef.path) {
    accessedPaths.add(`firestore/${queryRef.path}`);
  }
  return await getDocs(queryRef);
};

// Export function to get all accessed paths
export const getAllAccessedPaths = () => {
  const paths = Array.from(accessedPaths);
  console.log(`%c🔍 Total traced paths: ${paths.length}`, 'color: blue; font-weight: bold');
  console.log('Traced paths:', paths);
  return paths;
};

// Clear the tracked paths
export const clearAccessedPaths = () => {
  console.log('%c🔍 Clearing all traced paths', 'color: orange');
  accessedPaths.clear();
};

// Add path manually - useful for custom operations
export const addAccessedPath = (type, path) => {
  accessedPaths.add(`${type}/${path}`);
};
