// src/pages/Home.jsx
import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import Feed from '../components/posts/Feed';
import { Users, MessageCircle, Music, LogIn } from 'lucide-react';
import './Home.css';

const Home = () => {
  const { currentUser } = useAuth();
  const navigate = useNavigate();

  return (
    <div className="home-container">
      <div className="home-header">
        <h1>Home Feed</h1>
        <p>See what's happening in your community</p>
        
        {/* Show welcome message for unauthenticated users */}
        {(!currentUser || currentUser.isAnonymous) && (
          <div className="anonymous-welcome-banner">
            <p>
              You're browsing as a guest. 
              <button 
                className="inline-link-button"
                onClick={() => navigate('/signup')}
              >
                Create an account
              </button> 
              or 
              <button 
                className="inline-link-button"
                onClick={() => navigate('/login')}
              >
                log in
              </button> 
              to create posts and interact with the community.
            </p>
          </div>
        )}
      </div>
      
      {/* Show feed to everyone, but limit posting to authenticated users */}
      <Feed showCreatePost={currentUser && !currentUser.isAnonymous} />
    </div>
  );
};

export default Home;