// src/admin/AuditManager.jsx
import React, { useState, useEffect, useContext } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { useAdminAuth } from '../contexts/AdminAuthContext';
import { 
  getAuditUsers, 
  setUserAuditPermission, 
  getFirestoreRuleUploads,
  uploadFirestoreRules,
  exportAuditLogs
} from '../services/AuditService.js';
import { collection, getDocs } from 'firebase/firestore';
import FirebasePathTracer from '../components/AuditManager/TraceCommand';
import { db } from '../firebase';
import { getFileUsageStats } from '../utils/fileAuditUtils';
import { getAccessPatterns, getDeniedAccessLogs } from '../utils/firebaseAuditUtils';
import { getSuggestedRulesUpdates } from '../utils/firebaseRulesBuilder';

/**
 * Admin page to manage audit permissions and rules
 */
const AuditManager = () => {
  const { currentUser } = useAuth();
  const { isAdmin, isAudit } = useAdminAuth();
  
  // State for users with audit permissions
  const [auditUsers, setAuditUsers] = useState([]);
  const [allUsers, setAllUsers] = useState([]);
  const [selectedUserId, setSelectedUserId] = useState('');
  
  // State for rule management
  const [ruleUploads, setRuleUploads] = useState([]);
  const [currentRules, setCurrentRules] = useState('');
  const [suggestedRules, setSuggestedRules] = useState('');
  const [isGeneratingRules, setIsGeneratingRules] = useState(false);
  
  // UI state
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('trace');
  const [message, setMessage] = useState(null);
  
  // Load data on component mount
  useEffect(() => {
    if (!isAdmin && !isAudit) return;
    
    const loadData = async () => {
      setLoading(true);
      
      try {
        // Get users with audit permissions
        const users = await getAuditUsers();
        setAuditUsers(users);
        
        // Get all users from database
        const usersRef = collection(db, 'users');
        const usersSnapshot = await getDocs(usersRef);
        const allUsersList = usersSnapshot.docs.map(doc => ({
          id: doc.id,
          displayName: doc.data().displayName || doc.data().username || doc.data().email || 'Unnamed User',
          email: doc.data().email || 'No email',
          ...doc.data()
        }));
        
        setAllUsers(allUsersList);
        
        // Get rule uploads
        const uploads = await getFirestoreRuleUploads();
        setRuleUploads(uploads);
        
        // Get current rules (most recent upload or example)
        if (uploads.length > 0) {
          const mostRecent = uploads.sort((a, b) => 
            b.timestamp?.toDate().getTime() - a.timestamp?.toDate().getTime()
          )[0];
          
          setCurrentRules(mostRecent.content);
        } else {
          // Example rules
          setCurrentRules(`rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    // Add your rules here
  }
}`);
        }
      } catch (error) {
        console.error('[Audit Manager] Error loading data:', error);
        setMessage({ type: 'error', text: 'Error loading data: ' + error.message });
      } finally {
        setLoading(false);
      }
    };
    
    loadData();
  }, [isAdmin, isAudit]);
  
  // Handle changing user audit permission
  const handleChangePermission = async (userId, grant) => {
    if ((!isAdmin && !isAudit) || !userId) return;
    
    try {
      setLoading(true);
      await setUserAuditPermission(userId, grant);
      
      // Refresh user list
      const users = await getAuditUsers();
      setAuditUsers(users);
      
      setMessage({ 
        type: 'success', 
        text: `Successfully ${grant ? 'granted' : 'revoked'} audit permission for user ${userId}` 
      });
    } catch (error) {
      console.error('[Audit Manager] Error changing permission:', error);
      setMessage({ type: 'error', text: 'Error changing permission: ' + error.message });
    } finally {
      setLoading(false);
    }
  };
  
  // State for trace data
  const [tracedPaths, setTracedPaths] = useState([]);

  // Handle generating suggested rules
  const handleGenerateRules = async () => {
    if (!isAdmin && !isAudit) return;
    
    try {
      setIsGeneratingRules(true);
      setMessage({ type: 'info', text: 'Generating suggested rules...' });
      
      // Generate rules based on traced paths if available
      if (tracedPaths && tracedPaths.length > 0) {
        // Import the rule generation function
        const { generateFirebaseRules } = await import('../components/AuditManager/FirebaseTraceManager');
        
        // Generate rules from the traced paths
        const rules = generateFirebaseRules(tracedPaths);
        setSuggestedRules(rules.firestore);
        
        setMessage({ type: 'success', text: `Successfully generated rules from ${tracedPaths.length} traced paths` });
      } else {
        // Fall back to legacy method if no traced paths
        // Get access patterns and denied logs
        await getAccessPatterns();
        await getDeniedAccessLogs();
        
        // Generate suggested rules
        const suggested = await getSuggestedRulesUpdates(currentRules);
        setSuggestedRules(suggested);
        
        setMessage({ type: 'success', text: 'Successfully generated suggested rules using legacy method' });
      }
    } catch (error) {
      console.error('[Audit Manager] Error generating rules:', error);
      setMessage({ type: 'error', text: 'Error generating rules: ' + error.message });
    } finally {
      setIsGeneratingRules(false);
    }
  };
  
  // Handle uploading rules
  const handleUploadRules = async () => {
    if (!isAdmin && !isAudit) return;
    
    try {
      setLoading(true);
      
      // Use suggested rules if available, otherwise use current rules
      const rulesToUpload = suggestedRules || currentRules;
      
      // Upload rules
      await uploadFirestoreRules(rulesToUpload);
      
      // Refresh rule uploads
      const uploads = await getFirestoreRuleUploads();
      setRuleUploads(uploads);
      
      setMessage({ type: 'success', text: 'Successfully uploaded rules' });
    } catch (error) {
      console.error('[Audit Manager] Error uploading rules:', error);
      setMessage({ type: 'error', text: 'Error uploading rules: ' + error.message });
    } finally {
      setLoading(false);
    }
  };
  
  // Handle exporting audit logs
  const handleExportLogs = async (type) => {
    if (!isAdmin && !isAudit) return;
    
    try {
      setLoading(true);
      
      // Export logs
      const blob = await exportAuditLogs(type);
      
      // Create download link
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `audit-logs-${type}-${new Date().toISOString()}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      
      setMessage({ type: 'success', text: `Successfully exported ${type} logs` });
    } catch (error) {
      console.error('[Audit Manager] Error exporting logs:', error);
      setMessage({ type: 'error', text: 'Error exporting logs: ' + error.message });
    } finally {
      setLoading(false);
    }
  };
  
  // Check if user has admin or audit permission
  if (!isAdmin && !isAudit) {
    return (
      <div className="audit-manager" style={{ padding: '20px' }}>
        <h2>Audit Manager</h2>
        <div className="alert alert-danger">
          You don't have permission to access this page. You need admin or audit permissions to access this page.
        </div>
      </div>
    );
  }
  
  return (
    <div className="audit-manager" style={{ padding: '20px' }}>
      <h2>Audit Manager</h2>
      
      {message && (
        <div className={`alert alert-${message.type}`} style={{ 
          padding: '10px', 
          marginBottom: '20px',
          backgroundColor: message.type === 'success' ? '#d4edda' : 
                           message.type === 'error' ? '#f8d7da' : 
                           message.type === 'info' ? '#cce5ff' : '#fff3cd',
          color: message.type === 'success' ? '#155724' : 
                 message.type === 'error' ? '#721c24' : 
                 message.type === 'info' ? '#004085' : '#856404',
          borderRadius: '4px'
        }}>
          {message.text}
          <button 
            onClick={() => setMessage(null)}
            style={{ 
              float: 'right', 
              background: 'none', 
              border: 'none', 
              cursor: 'pointer',
              fontWeight: 'bold'
            }}
          >
            &times;
          </button>
        </div>
      )}
      
      <div className="tabs" style={{ marginBottom: '20px' }}>
        <div style={{ display: 'flex', gap: '10px' }}>
          <button 
            onClick={() => setActiveTab('trace')} 
            style={{ 
              padding: '10px 15px', 
              backgroundColor: activeTab === 'trace' ? '#007bff' : '#f8f9fa',
              color: activeTab === 'trace' ? 'white' : 'black',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer'
            }}
          >
            Path Tracer
          </button>
          
          <button 
            onClick={() => setActiveTab('users')} 
            style={{ 
              padding: '10px 15px', 
              backgroundColor: activeTab === 'users' ? '#007bff' : '#f8f9fa',
              color: activeTab === 'users' ? 'white' : 'black',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer'
            }}
          >
            Manage Users
          </button>
          
          <button 
            onClick={() => setActiveTab('rules')} 
            style={{ 
              padding: '10px 15px', 
              backgroundColor: activeTab === 'rules' ? '#007bff' : '#f8f9fa',
              color: activeTab === 'rules' ? 'white' : 'black',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer'
            }}
          >
            Manage Rules
          </button>
          
          <button 
            onClick={() => setActiveTab('export')} 
            style={{ 
              padding: '10px 15px', 
              backgroundColor: activeTab === 'export' ? '#007bff' : '#f8f9fa',
              color: activeTab === 'export' ? 'white' : 'black',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer'
            }}
          >
            Export Data
          </button>
        </div>
      </div>
      
      {loading ? (
        <div>Loading...</div>
      ) : (
        <>
          {/* Path Tracer Tab */}
          {activeTab === 'trace' && (
            <div className="trace-tab">
              <FirebasePathTracer onPathsGenerated={(paths, rules) => {
                // Store the traced paths and update the suggested rules
                setTracedPaths(paths);
                setSuggestedRules(rules.firestore);
                setMessage({ type: 'success', text: `Successfully generated rules from ${paths.length} traced paths` });
              }} />
            </div>
          )}
          
          {/* Users Tab */}
          {activeTab === 'users' && (
            <div className="users-tab">
              <h3>Manage Audit Permissions</h3>
              
              <div style={{ marginBottom: '20px' }}>
                <h4>Current Audit Users</h4>
                <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                  <thead>
                    <tr style={{ backgroundColor: '#f3f3f3' }}>
                      <th style={{ padding: '10px', textAlign: 'left', borderBottom: '1px solid #ddd' }}>User ID</th>
                      <th style={{ padding: '10px', textAlign: 'left', borderBottom: '1px solid #ddd' }}>Display Name</th>
                      <th style={{ padding: '10px', textAlign: 'left', borderBottom: '1px solid #ddd' }}>Email</th>
                      <th style={{ padding: '10px', textAlign: 'center', borderBottom: '1px solid #ddd' }}>Action</th>
                    </tr>
                  </thead>
                  <tbody>
                    {auditUsers.length === 0 ? (
                      <tr>
                        <td colSpan={4} style={{ padding: '10px', textAlign: 'center' }}>
                          No users with audit permissions yet.
                        </td>
                      </tr>
                    ) : (
                      auditUsers.map(user => (
                        <tr key={user.id}>
                          <td style={{ padding: '10px', borderBottom: '1px solid #eee' }}>{user.id}</td>
                          <td style={{ padding: '10px', borderBottom: '1px solid #eee' }}>{user.displayName}</td>
                          <td style={{ padding: '10px', borderBottom: '1px solid #eee' }}>{user.email}</td>
                          <td style={{ padding: '10px', textAlign: 'center', borderBottom: '1px solid #eee' }}>
                            <button 
                              onClick={() => handleChangePermission(user.id, false)}
                              style={{ 
                                padding: '5px 10px', 
                                backgroundColor: '#dc3545', 
                                color: 'white',
                                border: 'none',
                                borderRadius: '4px',
                                cursor: 'pointer'
                              }}
                            >
                              Revoke
                            </button>
                          </td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              </div>
              
              <div>
                <h4>Grant Audit Permission</h4>
                <div style={{ display: 'flex', gap: '10px' }}>
                  <select 
                    value={selectedUserId}
                    onChange={(e) => setSelectedUserId(e.target.value)}
                    style={{ 
                      padding: '8px',
                      borderRadius: '4px',
                      border: '1px solid #ddd',
                      flex: 1
                    }}
                  >
                    <option value="">Select a user</option>
                    {allUsers
                      .filter(user => !auditUsers.some(au => au.id === user.id) && !user.isAudit)
                      .map(user => (
                        <option key={user.id} value={user.id}>
                          {user.displayName} ({user.email})
                        </option>
                      ))
                    }
                  </select>
                  
                  <button 
                    onClick={() => handleChangePermission(selectedUserId, true)}
                    disabled={!selectedUserId}
                    style={{ 
                      padding: '8px 15px', 
                      backgroundColor: selectedUserId ? '#28a745' : '#6c757d',
                      color: 'white',
                      border: 'none',
                      borderRadius: '4px',
                      cursor: selectedUserId ? 'pointer' : 'not-allowed'
                    }}
                  >
                    Grant Permission
                  </button>
                </div>
              </div>
            </div>
          )}
          
          {/* Rules Tab */}
          {activeTab === 'rules' && (
            <div className="rules-tab">
              <h3>Manage Firestore Rules</h3>
              
              {tracedPaths.length > 0 && (
                <div style={{ 
                  backgroundColor: '#e3f2fd', 
                  padding: '10px 15px', 
                  borderRadius: '4px',
                  marginBottom: '15px',
                  borderLeft: '4px solid #2196f3',
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center'
                }}>
                  <div>
                    <strong>{tracedPaths.length} Firebase paths</strong> have been traced and are available for rule generation.
                  </div>
                  <button
                    onClick={async () => {
                      try {
                        // Generate rules from the traced paths
                        const module = await import('../components/AuditManager/FirebaseTraceManager');
                        const rules = module.generateFirebaseRules(tracedPaths);
                        setSuggestedRules(rules.firestore);
                        setMessage({ type: 'success', text: `Generated rules from ${tracedPaths.length} traced paths` });
                      } catch (error) {
                        console.error('Error generating rules from traced paths:', error);
                        setMessage({ type: 'error', text: 'Error generating rules: ' + error.message });
                      }
                    }}
                    style={{ 
                      padding: '5px 10px', 
                      backgroundColor: '#2196f3',
                      color: 'white',
                      border: 'none',
                      borderRadius: '4px',
                      cursor: 'pointer',
                      fontSize: '0.9rem'
                    }}
                  >
                    Use Traced Paths
                  </button>
                </div>
              )}
              
              <div style={{ display: 'flex', gap: '20px', marginBottom: '20px' }}>
                <button 
                  onClick={handleGenerateRules}
                  disabled={isGeneratingRules}
                  style={{ 
                    padding: '8px 15px', 
                    backgroundColor: isGeneratingRules ? '#6c757d' : '#007bff',
                    color: 'white',
                    border: 'none',
                    borderRadius: '4px',
                    cursor: isGeneratingRules ? 'not-allowed' : 'pointer'
                  }}
                >
                  {isGeneratingRules ? 'Generating...' : 'Generate Suggested Rules'}
                </button>
                
                <button 
                  onClick={() => {
                    // Switch to the trace tab 
                    setActiveTab('trace');
                    // Show a message to guide the user
                    setMessage({ 
                      type: 'info', 
                      text: 'Use the Path Tracer to generate rules based on actual Firebase usage' 
                    });
                  }}
                  style={{ 
                    padding: '8px 15px', 
                    backgroundColor: '#6610f2',
                    color: 'white',
                    border: 'none',
                    borderRadius: '4px',
                    cursor: 'pointer'
                  }}
                >
                  Use Path Tracer
                </button>
                
                <button 
                  onClick={handleUploadRules}
                  style={{ 
                    padding: '8px 15px', 
                    backgroundColor: '#28a745',
                    color: 'white',
                    border: 'none',
                    borderRadius: '4px',
                    cursor: 'pointer'
                  }}
                >
                  Upload Rules
                </button>
              </div>
              
              <div style={{ display: 'flex', gap: '20px', flexDirection: 'column' }}>
                <div>
                  <h4>Current Rules</h4>
                  <pre style={{ 
                    backgroundColor: '#f5f5f5', 
                    padding: '15px',
                    borderRadius: '4px',
                    maxHeight: '300px',
                    overflowY: 'auto',
                    fontSize: '0.9rem',
                    whiteSpace: 'pre-wrap'
                  }}>
                    {currentRules}
                  </pre>
                </div>
                
                {suggestedRules && (
                  <div>
                    <h4>Suggested Rules</h4>
                    <pre style={{ 
                      backgroundColor: '#f5f5f5', 
                      padding: '15px',
                      borderRadius: '4px',
                      maxHeight: '300px',
                      overflowY: 'auto',
                      fontSize: '0.9rem',
                      whiteSpace: 'pre-wrap'
                    }}>
                      {suggestedRules}
                    </pre>
                  </div>
                )}
              </div>
              
              <div style={{ marginTop: '20px' }}>
                <h4>Rule Upload History</h4>
                <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                  <thead>
                    <tr style={{ backgroundColor: '#f3f3f3' }}>
                      <th style={{ padding: '10px', textAlign: 'left', borderBottom: '1px solid #ddd' }}>Timestamp</th>
                      <th style={{ padding: '10px', textAlign: 'left', borderBottom: '1px solid #ddd' }}>Uploaded By</th>
                      <th style={{ padding: '10px', textAlign: 'center', borderBottom: '1px solid #ddd' }}>Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {ruleUploads.length === 0 ? (
                      <tr>
                        <td colSpan={3} style={{ padding: '10px', textAlign: 'center' }}>
                          No rule uploads yet.
                        </td>
                      </tr>
                    ) : (
                      ruleUploads.map(upload => (
                        <tr key={upload.id}>
                          <td style={{ padding: '10px', borderBottom: '1px solid #eee' }}>
                            {upload.timestamp?.toDate().toLocaleString()}
                          </td>
                          <td style={{ padding: '10px', borderBottom: '1px solid #eee' }}>{upload.uploadedBy}</td>
                          <td style={{ 
                            padding: '10px', 
                            textAlign: 'center', 
                            borderBottom: '1px solid #eee',
                            color: upload.status === 'error' ? '#721c24' : 
                                  upload.status === 'validated' ? '#155724' : 
                                  upload.status === 'deployed' ? '#004085' : '#856404'
                          }}>
                            {upload.status}
                          </td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          )}
          
          {/* Export Tab */}
          {activeTab === 'export' && (
            <div className="export-tab">
              <h3>Export Audit Data</h3>
              
              <div style={{ display: 'flex', gap: '10px', marginBottom: '20px' }}>
                <button 
                  onClick={() => handleExportLogs('file')}
                  style={{ 
                    padding: '10px 15px', 
                    backgroundColor: '#007bff',
                    color: 'white',
                    border: 'none',
                    borderRadius: '4px',
                    cursor: 'pointer'
                  }}
                >
                  Export File Audit Logs
                </button>
                
                <button 
                  onClick={() => handleExportLogs('firebase')}
                  style={{ 
                    padding: '10px 15px', 
                    backgroundColor: '#28a745',
                    color: 'white',
                    border: 'none',
                    borderRadius: '4px',
                    cursor: 'pointer'
                  }}
                >
                  Export Firebase Audit Logs
                </button>
                
                <button 
                  onClick={() => handleExportLogs('all')}
                  style={{ 
                    padding: '10px 15px', 
                    backgroundColor: '#6610f2',
                    color: 'white',
                    border: 'none',
                    borderRadius: '4px',
                    cursor: 'pointer'
                  }}
                >
                  Export All Audit Logs
                </button>
              </div>
              
              <p style={{ marginBottom: '20px' }}>
                Exported logs will be downloaded as a JSON file that you can import into other tools for analysis.
              </p>
              
              <div className="export-info">
                <h4>Export Format</h4>
                <pre style={{ 
                  backgroundColor: '#f5f5f5', 
                  padding: '15px',
                  borderRadius: '4px',
                  maxHeight: '300px',
                  overflowY: 'auto',
                  fontSize: '0.9rem',
                  whiteSpace: 'pre-wrap'
                }}>
{`{
  "exportedAt": "2023-06-01T12:34:56.789Z",
  "exportedBy": "admin-user-id",
  "fileAuditLogs": [
    {
      "id": "log-id",
      "filePath": "/path/to/file.js",
      "importedBy": "AppRoot",
      "userId": "user-id",
      "timestamp": "2023-06-01T12:30:00.000Z",
      "userAgent": "Mozilla/5.0...",
      "md5Hash": "d41d8cd98f00b204e9800998ecf8427e",
      "fileSize": 12345,
      "lastModified": "2023-06-01T12:00:00.000Z"
    }
  ],
  "firebaseAuditLogs": [
    {
      "id": "log-id",
      "operation": "read",
      "path": "/posts/post-id",
      "success": true,
      "userId": "user-id",
      "timestamp": "2023-06-01T12:31:00.000Z",
      "userAgent": "Mozilla/5.0..."
    }
  ]
}`}
                </pre>
              </div>
            </div>
          )}
        </>
      )}
    </div>
  );
};

export default AuditManager;