// src/pages/ReplaysPage.jsx
//
// Everything recorded, newest first — the "All replays →" destination.
// Replays stay up 30 days on the free tier.

import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import TalkStudioNav from '../components/layout/TalkStudioNav';
import {
  listReplays,
  formatDuration,
  occurrenceDate,
} from '../services/scheduledRoomsService';
import './DiscoverPage.css';
import './SchedulePage.css';

const ReplaysPage = () => {
  const [replays, setReplays] = useState(null);

  useEffect(() => {
    listReplays({ max: 40 })
      .then(setReplays)
      .catch(err => {
        console.warn('[Replays] load failed:', err.message);
        setReplays([]);
      });
  }, []);

  return (
    <div className="ts-app">
      <TalkStudioNav active="replays" />

      <div className="ts-page">
        <div className="discover-controls">
          <h1 className="schedule-list-title">Replays</h1>
          <span className="discover-band-meta">Every recorded room stays up for 30 days</span>
        </div>

        {replays === null && (
          <div className="discover-replays">
            {[0, 1, 2, 3].map(i => <div key={i} className="ts-skeleton discover-replay-skeleton" />)}
          </div>
        )}

        {replays && replays.length === 0 && <div className="ts-empty">No replays yet.</div>}

        {replays && replays.length > 0 && (
          <div className="discover-replays">
            {replays.map(replay => (
              <Link
                key={replay.id}
                to={`/r/${replay.slug}/replay/${replay.id}`}
                className="ts-card ts-card--sm discover-replay"
              >
                <div
                  className="ts-art discover-replay-art"
                  style={replay.artworkUrl ? { backgroundImage: `url(${replay.artworkUrl})` } : undefined}
                >
                  <span className="ts-mono discover-replay-len">{formatDuration(replay.durationMin)}</span>
                  <span className="discover-replay-plays">▶ {replay.playCount || 0}</span>
                </div>
                <div className="discover-replay-caption">
                  <div className="discover-replay-title">{replay.title}</div>
                  <div className="discover-replay-sub">
                    {replay.hostName} ·{' '}
                    {occurrenceDate(replay.startAt)?.toLocaleDateString([], { month: 'short', day: 'numeric' })}
                  </div>
                </div>
              </Link>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default ReplaysPage;
