// src/components/premium/DataMask.jsx
import React from 'react';
import { Link } from 'react-router-dom';
import { Lock } from 'lucide-react';
import { useSubscription } from '../../hooks/useSubscription';
import { useAuth } from '../../contexts/AuthContext';
import './DataMask.css';

/**
 * Wraps actionable/numeric content and masks it for users below `minTier`.
 * Unlike PremiumGuard (which replaces content with an upgrade card),
 * DataMask keeps the UI shape visible but obscures values, so free users
 * see what the product offers without getting the actual data.
 *
 * Props:
 *   minTier?: 'data' | 'crm' | 'elite'   — defaults to 'data'
 *   children                              — the real value/content
 *   placeholder?: ReactNode               — what to show when masked (default: blurred children)
 *   mode?: 'blur' | 'block' | 'dots'     — masking style
 *   inline?: boolean                      — use span instead of div
 *   upgradeLink?: boolean                 — wrap in a link to /premium-membership
 *   allowAnonymous?: boolean              — when true, anonymous visitors (not
 *                                           signed in, or Firebase anonymous
 *                                           auth) see the unmasked value;
 *                                           signed-in accounts still gated
 */
const DataMask = ({
  children,
  minTier = 'data',
  placeholder,
  mode = 'blur',
  inline = false,
  upgradeLink = true,
  allowAnonymous = false,
  className = '',
  title,
}) => {
  const { meetsTier, loading } = useSubscription();
  const { currentUser } = useAuth();
  // "Anonymous" = a not-signed-in visitor or a Firebase anonymous-auth user.
  // A signed-in real account (even on the free tier) is not anonymous.
  const isAnonymous = !currentUser || currentUser.isAnonymous;

  // While loading, render content to avoid layout shift; assume no access.
  if (loading) {
    return inline ? <span className={className}>{children}</span> : <div className={className}>{children}</div>;
  }

  if (meetsTier(minTier) || (allowAnonymous && isAnonymous)) {
    return inline ? <span className={className}>{children}</span> : <div className={className}>{children}</div>;
  }

  const tooltipText = title ?? `Upgrade to unlock — ${minTier === 'crm' ? 'CRM plan' : minTier === 'elite' ? 'Elite plan' : 'Data plan'}`;

  let maskedContent;
  if (placeholder !== undefined) {
    maskedContent = placeholder;
  } else if (mode === 'block') {
    maskedContent = <span className="data-mask-block">████</span>;
  } else if (mode === 'dots') {
    maskedContent = <span className="data-mask-dots">•••</span>;
  } else {
    // blur mode: render children with blur filter
    maskedContent = <span className="data-mask-blur">{children}</span>;
  }

  const Wrapper = inline ? 'span' : 'div';
  const content = (
    <Wrapper className={`data-mask data-mask-${mode} ${className}`} title={tooltipText}>
      {maskedContent}
      <Lock size={10} className="data-mask-lock" aria-hidden="true" />
    </Wrapper>
  );

  if (upgradeLink) {
    return (
      <Link to="/premium-membership" className="data-mask-link" title={tooltipText}>
        {content}
      </Link>
    );
  }
  return content;
};

export default DataMask;
