// src/admin/AnnouncementManager.jsx
import React, { useState, useEffect } from 'react';
import { 
  getDB, 
  collection,
  doc,
  getDocs,
  getDoc,
  addDoc,
  updateDoc,
  deleteDoc,
  query,
  orderBy,
  serverTimestamp 
} from '../utils/firebase-utils';
import { useAuth } from '../contexts/AuthContext';

const AnnouncementManager = () => {
  const [announcements, setAnnouncements] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [linkUrl, setLinkUrl] = useState('');
  const [linkText, setLinkText] = useState('');
  const [editingId, setEditingId] = useState(null);
  const [submitting, setSubmitting] = useState(false);
  const { currentUser } = useAuth();
  
  // Fetch announcements when component mounts
  useEffect(() => {
    fetchAnnouncements();
  }, []);
  
  // Function to fetch announcements from Firestore
  const fetchAnnouncements = async () => {
    setLoading(true);
    setError(null);
    
    try {
      // Get db instance using the utility function to ensure proper region handling
      const db = getDB();
      if (!db) {
        console.error('Firestore database not available');
        setError('Database connection failed. Please try again later.');
        setLoading(false);
        return;
      }
      
      console.log('Fetching announcements from US-CENTRAL-1 region');
      
      // Create a query for the announcements collection, ordered by creation time
      const announcementsCollection = collection(db, 'announcements');
      const announcementsQuery = query(
        announcementsCollection,
        orderBy('createdAt', 'desc')
      );
      
      const querySnapshot = await getDocs(announcementsQuery);
      
      const fetchedAnnouncements = [];
      querySnapshot.forEach((doc) => {
        // Convert Firestore timestamps to JavaScript Date objects
        const data = doc.data();
        fetchedAnnouncements.push({
          id: doc.id,
          ...data,
          createdAt: data.createdAt ? 
            (data.createdAt.toDate ? data.createdAt.toDate() : data.createdAt) : 
            new Date()
        });
      });
      
      setAnnouncements(fetchedAnnouncements);
    } catch (err) {
      console.error('Error fetching announcements:', err);
      setError(`Failed to fetch announcements: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };
  
  // Function to handle form submission (create or update)
  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!title.trim() || !content.trim()) {
      setError('Title and content are required');
      return;
    }
    
    setSubmitting(true);
    setError(null);
    
    try {
      // Get db instance using the utility function to ensure proper region handling
      const db = getDB();
      if (!db) {
        throw new Error('Firestore database not available');
      }
      
      const announcementData = {
        title: title.trim(),
        content: content.trim(),
        linkUrl: linkUrl.trim() || null,
        linkText: linkText.trim() || null,
        updatedAt: serverTimestamp(),
        updatedBy: currentUser ? currentUser.displayName || currentUser.email || currentUser.uid : 'Unknown'
      };
      
      if (editingId) {
        // Update existing announcement
        const announcementRef = doc(db, 'announcements', editingId);
        await updateDoc(announcementRef, announcementData);
        console.log('Announcement updated successfully');
      } else {
        // Create new announcement
        announcementData.createdAt = serverTimestamp();
        announcementData.authorId = currentUser ? currentUser.uid : 'system';
        announcementData.authorName = currentUser ? currentUser.displayName || currentUser.email || currentUser.uid : 'System';
        announcementData.createdBy = currentUser ? currentUser.displayName || currentUser.email || currentUser.uid : 'System';
        announcementData.viewCount = 0;
        announcementData.viewedBy = [];
        announcementData.priority = 'normal';
        announcementData.type = 'ANNOUNCEMENT';
        
        const announcementsCollection = collection(db, 'announcements');
        await addDoc(announcementsCollection, announcementData);
        console.log('Announcement created successfully');
      }
      
      // Reset form and refresh announcements list
      resetForm();
      await fetchAnnouncements();
    } catch (err) {
      console.error('Error saving announcement:', err);
      setError(`Failed to save announcement: ${err.message}`);
    } finally {
      setSubmitting(false);
    }
  };
  
  // Function to load an announcement for editing
  const handleEdit = async (id) => {
    try {
      // Get db instance using the utility function to ensure proper region handling
      const db = getDB();
      if (!db) {
        throw new Error('Firestore database not available');
      }
      
      const announcementRef = doc(db, 'announcements', id);
      const announcementSnap = await getDoc(announcementRef);
      
      if (announcementSnap.exists()) {
        const data = announcementSnap.data();
        setTitle(data.title || '');
        setContent(data.content || '');
        setLinkUrl(data.linkUrl || '');
        setLinkText(data.linkText || '');
        setEditingId(id);
      } else {
        setError('Announcement not found');
      }
    } catch (err) {
      console.error('Error loading announcement for edit:', err);
      setError(`Failed to load announcement: ${err.message}`);
    }
  };
  
  // Function to delete an announcement
  const handleDelete = async (id) => {
    if (!window.confirm('Are you sure you want to delete this announcement?')) {
      return;
    }
    
    try {
      // Get db instance using the utility function to ensure proper region handling
      const db = getDB();
      if (!db) {
        throw new Error('Firestore database not available');
      }
      
      const announcementRef = doc(db, 'announcements', id);
      await deleteDoc(announcementRef);
      console.log('Announcement deleted successfully');
      
      // Refresh announcements list
      await fetchAnnouncements();
    } catch (err) {
      console.error('Error deleting announcement:', err);
      setError(`Failed to delete announcement: ${err.message}`);
    }
  };
  
  // Function to reset the form
  const resetForm = () => {
    setTitle('');
    setContent('');
    setLinkUrl('');
    setLinkText('');
    setEditingId(null);
    setError(null);
  };
  
  // Function to format dates
  const formatDate = (date) => {
    if (!date) return 'Unknown date';
    
    try {
      // Handle both Date objects and Firestore timestamps
      const dateObj = date instanceof Date ? date : 
                     (date.toDate ? date.toDate() : new Date(date));
      
      return new Intl.DateTimeFormat('en-US', {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      }).format(dateObj);
    } catch (err) {
      console.error('Error formatting date:', err);
      return 'Invalid date';
    }
  };
  
  return (
    <div className="announcement-manager">
      <h2 className="section-title">
        {editingId ? 'Edit Announcement' : 'Create Announcement'}
      </h2>
      
      {error && (
        <div className="error-message">
          {error}
        </div>
      )}
      
      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <label htmlFor="title">Title *</label>
          <input
            id="title"
            type="text"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            required
            disabled={submitting}
            placeholder="Announcement title"
          />
        </div>
        
        <div className="form-group">
          <label htmlFor="content">Content *</label>
          <textarea
            id="content"
            value={content}
            onChange={(e) => setContent(e.target.value)}
            required
            disabled={submitting}
            rows={5}
            placeholder="Announcement content"
          />
        </div>
        
        <div className="form-group">
          <label htmlFor="linkUrl">Link URL (optional)</label>
          <input
            id="linkUrl"
            type="url"
            value={linkUrl}
            onChange={(e) => setLinkUrl(e.target.value)}
            disabled={submitting}
            placeholder="https://example.com"
          />
        </div>
        
        <div className="form-group">
          <label htmlFor="linkText">Link Text (optional)</label>
          <input
            id="linkText"
            type="text"
            value={linkText}
            onChange={(e) => setLinkText(e.target.value)}
            disabled={submitting}
            placeholder="Learn More"
          />
        </div>
        
        <div className="form-actions">
          <button
            type="submit"
            className="submit-button"
            disabled={submitting}
          >
            {submitting 
              ? 'Saving...' 
              : (editingId ? 'Update Announcement' : 'Create Announcement')}
          </button>
          
          {editingId && (
            <button
              type="button"
              className="cancel-button"
              onClick={resetForm}
              disabled={submitting}
            >
              Cancel
            </button>
          )}
        </div>
      </form>
      
      <h2 className="section-title">Existing Announcements</h2>
      
      {loading ? (
        <div className="loading-indicator">
          Loading announcements...
        </div>
      ) : announcements.length === 0 ? (
        <div className="empty-state">
          No announcements found. Create your first announcement above.
        </div>
      ) : (
        <div className="announcements-list">
          {announcements.map((announcement) => (
            <div key={announcement.id} className="announcement-item">
              <div className="announcement-item-content">
                <h3 className="announcement-item-title">{announcement.title}</h3>
                <div className="announcement-item-meta">
                  <span className="announcement-item-date">
                    Created: {formatDate(announcement.createdAt)}
                  </span>
                  {announcement.viewCount !== undefined && (
                    <span className="announcement-item-views">
                      Views: {announcement.viewCount}
                    </span>
                  )}
                </div>
                <div className="announcement-item-preview">
                  {announcement.content && announcement.content.length > 100 
                    ? `${announcement.content.substring(0, 100)}...` 
                    : announcement.content}
                </div>
              </div>
              <div className="announcement-item-actions">
                <button
                  className="edit-button"
                  onClick={() => handleEdit(announcement.id)}
                  disabled={submitting}
                >
                  Edit
                </button>
                <button
                  className="delete-button"
                  onClick={() => handleDelete(announcement.id)}
                  disabled={submitting}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default AnnouncementManager;