// src/components/premium/MembershipPage.jsx
//
// TalkStudio membership + pricing, served at /premium-membership.
// Free is implicit (every account starts there); the paid column is a single
// Premium subscription billed monthly or yearly. Upgrading opens
// PremiumCheckoutModal, which runs Stripe Elements against the payment proxy.

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Check,
  Crown,
  Headphones,
  Lock,
  MessageCircle,
  Mic2,
  PlayCircle,
  Radio,
  Sparkles,
  Star,
  Users,
  Zap,
} from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { useSubscription } from '../../hooks/useSubscription';
import PremiumCheckoutModal from './PremiumCheckoutModal';
import { PREMIUM_PLANS } from '../../services/PremiumCheckoutService';
import './MembershipPage.css';

// Shared benefit list — both paid cards unlock exactly the same features, they
// only differ on billing period, so keeping one list avoids them drifting.
const PREMIUM_FEATURES = [
  { Icon: Users,         text: 'VIP chat rooms — members-only rooms and priority seats in busy ones' },
  { Icon: Radio,         text: 'Full live event access — no preview timer, no paywall on ticketed streams' },
  { Icon: PlayCircle,    text: 'Watch replays — the whole back catalogue of past live shows' },
  { Icon: Zap,           text: 'Ad-free across the platform' },
  { Icon: Crown,         text: 'Premium badge next to your name everywhere you post' },
  { Icon: Headphones,    text: 'Advanced audio profiles and matching' },
  { Icon: MessageCircle, text: 'Priority support and early access to new features' },
];

const FREE_FEATURES = [
  { Icon: Check,  text: 'Create a profile and follow artists' },
  { Icon: Check,  text: 'Join public rooms and chat' },
  { Icon: Check,  text: 'Direct messages' },
  { Icon: Mic2,   text: 'Jam Studio and Set Studio — make music in your browser' },
  { Icon: Check,  text: 'Free live events and preview clips of ticketed ones' },
];

const FREE_LOCKED = [
  'VIP chat rooms',
  'Full-length ticketed streams',
  'Replay library',
  'Ad-free listening',
];

const MembershipPage = () => {
  const { currentUser } = useAuth();
  const { isActive, plan, loading, formattedExpiryDate } = useSubscription();
  const navigate = useNavigate();
  const [checkoutPlanId, setCheckoutPlanId] = useState(null);

  const handleUpgrade = (planId) => {
    if (!currentUser) {
      navigate('/login', { state: { returnTo: '/premium-membership' } });
      return;
    }
    setCheckoutPlanId(planId);
  };

  return (
    <div className="membership-shell">
      <div className="membership">
        <div className="membership-header">
          <h1>Membership and pricing</h1>
          <p className="membership-subtitle">
            Free gets you into the rooms. Premium unlocks the live shows, the replay
            library and an ad-free platform — for listeners and creators alike.
          </p>
          {!loading && isActive && (
            <div className="membership-current-banner">
              <Crown size={16} />
              You&apos;re on <strong>{plan || 'Premium'}</strong>
              {formattedExpiryDate ? ` — renews ${formattedExpiryDate}` : ''}.
            </div>
          )}
        </div>

        <div className="membership-grid">
          {/* Free tier — informational only */}
          <div className="membership-card membership-card-free">
            <div className="membership-card-header">
              <div className="membership-card-icon"><Star size={24} /></div>
              <h2>Free</h2>
              <div className="membership-price">
                <span className="membership-price-amount">$0</span>
                <span className="membership-price-interval">/mo</span>
              </div>
              <p className="membership-tagline">Listen, chat, create</p>
            </div>

            <ul className="membership-features">
              {FREE_FEATURES.map(({ Icon, text }, i) => (
                <li key={i}><Icon size={16} /> {text}</li>
              ))}
              {FREE_LOCKED.map((text, i) => (
                <li key={`locked-${i}`} className="membership-feature-locked">
                  <Lock size={14} /> {text}
                </li>
              ))}
            </ul>

            <button className="membership-cta membership-cta-disabled" disabled>
              {isActive ? 'Free tier' : 'Current plan'}
            </button>
          </div>

          {PREMIUM_PLANS.map((p) => {
            const featured = p.id === 'yearly';
            return (
              <div
                key={p.id}
                className={`membership-card ${featured ? 'membership-card-featured' : ''}`}
              >
                {featured && <div className="membership-badge">Best value</div>}

                <div className="membership-card-header">
                  <div className="membership-card-icon">
                    {featured ? <Sparkles size={24} /> : <Crown size={24} />}
                  </div>
                  <h2>{p.name}</h2>
                  <div className="membership-price">
                    <span className="membership-price-amount">{p.displayPrice}</span>
                    <span className="membership-price-interval">{p.interval}</span>
                  </div>
                  <p className="membership-tagline">{p.tagline}</p>
                </div>

                <ul className="membership-features">
                  {PREMIUM_FEATURES.map(({ Icon, text }, i) => (
                    <li key={i}><Icon size={16} /> {text}</li>
                  ))}
                </ul>

                <button
                  className={`membership-cta ${isActive ? 'membership-cta-current' : ''}`}
                  onClick={() => handleUpgrade(p.id)}
                  disabled={loading || isActive}
                >
                  {isActive ? 'Already a member' : `Get ${p.name} — ${p.displayPrice}`}
                </button>
              </div>
            );
          })}
        </div>

        <div className="membership-footer">
          <p>
            Payments are processed by Stripe; we never see your card details.
            Cancel anytime from <button className="membership-link" onClick={() => navigate('/settings')}>Settings</button>.
          </p>
          <p>
            Questions? <button className="membership-link" onClick={() => navigate('/messages')}>Send us a message</button>.
          </p>
        </div>
      </div>

      <PremiumCheckoutModal
        isOpen={!!checkoutPlanId}
        planId={checkoutPlanId}
        userId={currentUser?.uid}
        onClose={() => setCheckoutPlanId(null)}
      />
    </div>
  );
};

export default MembershipPage;
