import React, { useState, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import PaymentForm from '../components/monetization/PaymentForm';
import { Shield, ArrowLeft } from 'lucide-react';
import { getStripeInstance } from '../services/StripeInitializer.js';
import { loadStripe } from '@stripe/stripe-js';
import { Elements } from '@stripe/react-stripe-js';

const PaymentPage = () => {
  const { currentUser } = useAuth();
  const location = useLocation();
  const navigate = useNavigate();
  const [tier, setTier] = useState('');
  const [duration, setDuration] = useState(30);
  const [amount, setAmount] = useState(0);
  const [loading, setLoading] = useState(true);
  const [clientSecret, setClientSecret] = useState('');
  const [stripePromise, setStripePromise] = useState(null);

  // Initialize Stripe
  useEffect(() => {
    const initStripe = async () => {
      try {
        // Import directly from environment config to get consistent key usage
        let stripePromiseInstance;
        try {
          // For consistent key usage, import from environmentConfig
          const { getCurrentEnvironment } = require('../config/environmentConfig');
          const env = getCurrentEnvironment();
          const stripePublicKey = env.stripePublicKey;
          
          // Validate key format
          if (!/^pk_(test|live)_[a-zA-Z0-9]{10,}$/.test(stripePublicKey)) {
            console.error('Payment page: Invalid Stripe key format:', stripePublicKey);
            throw new Error('Invalid Stripe key format');
          }
          
          console.log('Payment page: Using Stripe key from environmentConfig:', 
            `${stripePublicKey.substring(0, 12)}...${stripePublicKey.substring(stripePublicKey.length - 4)}`);
          stripePromiseInstance = await loadStripe(stripePublicKey);
        } catch (configErr) {
          console.warn('Payment page: Could not load from environmentConfig, using getStripeInstance fallback', configErr);
          stripePromiseInstance = await getStripeInstance();
        }
        
        setStripePromise(stripePromiseInstance);
        console.log('Payment page: Stripe instance initialized successfully');
      } catch (err) {
        console.error('Payment page: Error initializing Stripe:', err);
      }
    };
    
    initStripe();
  }, []);

  // Parse URL parameters
  useEffect(() => {
    setLoading(true);
    
    const params = new URLSearchParams(location.search);
    const tierParam = params.get('tier');
    const durationParam = params.get('duration');
    
    if (tierParam) {
      setTier(tierParam);
    }
    
    if (durationParam) {
      setDuration(parseInt(durationParam));
    }
    
    // Calculate amount based on tier and duration
    calculateAmount(tierParam || tier, parseInt(durationParam) || duration);
    
    setLoading(false);
  }, [location.search]);

  // Initialize Stripe
  useEffect(() => {
    if (currentUser) {
      // Check URL for client_secret parameter
      const params = new URLSearchParams(location.search);
      const urlClientSecret = params.get('client_secret');
      
      // Check sessionStorage for client secret
      const storedClientSecret = sessionStorage.getItem('checkoutClientSecret');
      
      // Use client secret from URL or sessionStorage
      if (urlClientSecret) {
        console.log('Using client secret from URL');
        setClientSecret(urlClientSecret);
        // Clear from sessionStorage if it exists
        sessionStorage.removeItem('checkoutClientSecret');
      } else if (storedClientSecret) {
        console.log('Using client secret from sessionStorage');
        setClientSecret(storedClientSecret);
        // Clear from sessionStorage after using it
        sessionStorage.removeItem('checkoutClientSecret');
      } else if (amount > 0) {
        // If no client secret but we have an amount, fetch one from server
        console.log('No client secret found, would fetch for amount:', amount);
        // In a real implementation, you would fetch from your server
      }
    }
  }, [currentUser, location.search]);


  // Calculate the payment amount
  const calculateAmount = (selectedTier, selectedDuration) => {
    let basePrice = 9.99; // Default to premium price
    
    // Set base price based on tier
    switch (selectedTier) {
      case 'basic':
        basePrice = 4.99;
        break;
      case 'premium':
        basePrice = 9.99;
        break;
      case 'vip':
        basePrice = 19.99;
        break;
      default:
        basePrice = 9.99;
    }
    
    // Apply discounts based on duration
    const months = selectedDuration / 30;
    let discount = 0;
    
    if (selectedDuration === 90) discount = 0.1; // 10% discount for 3 months
    if (selectedDuration === 180) discount = 0.15; // 15% discount for 6 months
    if (selectedDuration === 365) discount = 0.25; // 25% discount for 12 months
    
    const finalAmount = basePrice * months * (1 - discount);
    setAmount(parseFloat(finalAmount.toFixed(2)));
  };

  // Handle navigation back to membership page
  const handleBackToMembership = () => {
    navigate('/premium-membership');
  };

  // Get tier display name
  const getTierDisplayName = () => {
    switch (tier) {
      case 'basic':
        return 'Basic';
      case 'premium':
        return 'Premium';
      case 'vip':
        return 'VIP';
      default:
        return 'Premium';
    }
  };

  // Get duration display text
  const getDurationDisplayText = () => {
    switch (duration) {
      case 30:
        return '1 Month';
      case 90:
        return '3 Months';
      case 180:
        return '6 Months';
      case 365:
        return '12 Months';
      default:
        return '1 Month';
    }
  };

  if (!currentUser) {
    return (
      <div className="payment-page">
        <div className="container">
          <div className="auth-needed">
            <h2>Authentication Required</h2>
            <p>Please log in or sign up to continue with your subscription purchase.</p>
            <div className="auth-actions">
              <button 
                onClick={() => navigate('/login', { 
                  state: { from: `/payment?tier=${tier}&duration=${duration}` } 
                })}
                className="login-button"
              >
                Log In
              </button>
              <button 
                onClick={() => navigate('/signup', { 
                  state: { from: `/payment?tier=${tier}&duration=${duration}` } 
                })}
                className="signup-button"
              >
                Sign Up
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="payment-page">
      <div className="payment-header">
        <div className="header-content">
          <h1>Complete Your Purchase</h1>
        </div>
      </div>

      <div className="payment-container">
        {loading ? (
          <div className="loading-spinner">Loading payment information...</div>
        ) : (
          <>
            <div className="back-link" onClick={handleBackToMembership}>
              <ArrowLeft size={16} />
              <span>Back to membership options</span>
            </div>

            <div className="payment-summary">
              <div className="summary-header">
                <div className="summary-icon">
                  <Shield size={24} />
                </div>
                <h2>Subscription Summary</h2>
              </div>

              <div className="summary-details">
                <div className="summary-row">
                  <span className="label">Plan:</span>
                  <span className="value">{getTierDisplayName()} Membership</span>
                </div>
                <div className="summary-row">
                  <span className="label">Duration:</span>
                  <span className="value">{getDurationDisplayText()}</span>
                </div>
                <div className="summary-row total">
                  <span className="label">Total:</span>
                  <span className="value">${amount.toFixed(2)}</span>
                </div>
              </div>
            </div>

            <div className="payment-form-wrapper">
              {clientSecret && stripePromise ? (
                <Elements stripe={stripePromise} options={{ clientSecret }}>
                  <PaymentForm 
                    streamId="premium_membership" // Using a fixed streamId for premium membership
                    accessLevel={tier}
                    accessDuration={duration}
                    initialAmount={amount}
                    clientSecret={clientSecret}
                  />
                </Elements>
              ) : (
                <div className="loading-client-secret">
                  <div className="spinner"></div>
                  <p>Preparing payment form...</p>
                </div>
              )}
            </div>

            <div className="secure-payment-notice">
              <div className="lock-icon">🔒</div>
              <p>Your payment information is secure and encrypted. We use industry-standard security measures to protect your data.</p>
            </div>
          </>
        )}
      </div>

      <style>{`
        .payment-page {
          font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
          background-color: #f9fafb;
          min-height: 100vh;
        }
        
        .payment-header {
          background-color: #4f46e5;
          color: white;
          padding: 2rem;
          text-align: center;
          background-image: linear-gradient(135deg, #4f46e5 0%, #6366f1 100%);
        }
        
        .header-content h1 {
          font-size: 2rem;
          margin: 0;
          font-weight: 700;
        }
        
        .payment-container {
          max-width: 800px;
          margin: 0 auto;
          padding: 2rem;
        }
        
        .loading-spinner {
          display: flex;
          justify-content: center;
          align-items: center;
          min-height: 300px;
          font-size: 1.25rem;
          color: #6b7280;
        }
        
        .back-link {
          display: inline-flex;
          align-items: center;
          gap: 0.5rem;
          color: #4f46e5;
          margin-bottom: 2rem;
          cursor: pointer;
          font-size: 0.875rem;
        }
        
        .back-link:hover {
          text-decoration: underline;
        }
        
        .payment-summary {
          background-color: white;
          border-radius: 12px;
          box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
          padding: 1.5rem;
          margin-bottom: 2rem;
        }
        
        .summary-header {
          display: flex;
          align-items: center;
          gap: 1rem;
          margin-bottom: 1.5rem;
        }
        
        .summary-icon {
          width: 48px;
          height: 48px;
          border-radius: 50%;
          background-color: #eef2ff;
          color: #4f46e5;
          display: flex;
          align-items: center;
          justify-content: center;
        }
        
        .summary-header h2 {
          font-size: 1.5rem;
          margin: 0;
          color: #111827;
        }
        
        .summary-details {
          display: flex;
          flex-direction: column;
          gap: 1rem;
        }
        
        .summary-row {
          display: flex;
          justify-content: space-between;
          font-size: 1rem;
          padding-bottom: 0.75rem;
          border-bottom: 1px solid #e5e7eb;
        }
        
        .summary-row.total {
          font-weight: 600;
          font-size: 1.25rem;
          color: #111827;
          margin-top: 0.5rem;
        }
        
        .label {
          color: #6b7280;
        }
        
        .value {
          color: #111827;
        }
        
        .payment-form-wrapper {
          margin-bottom: 2rem;
        }
        
        .secure-payment-notice {
          display: flex;
          align-items: center;
          gap: 1rem;
          background-color: #f3f4f6;
          border-radius: 8px;
          padding: 1rem;
        }
        
        .lock-icon {
          font-size: 1.5rem;
        }
        
        .secure-payment-notice p {
          margin: 0;
          font-size: 0.875rem;
          color: #4b5563;
        }
        
        .auth-needed {
          background-color: white;
          border-radius: 12px;
          box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
          padding: 2rem;
          text-align: center;
          max-width: 500px;
          margin: 0 auto;
        }
        
        .auth-needed h2 {
          font-size: 1.5rem;
          margin-top: 0;
          margin-bottom: 1rem;
          color: #111827;
        }
        
        .auth-needed p {
          color: #6b7280;
          margin-bottom: 2rem;
        }
        
        .auth-actions {
          display: flex;
          gap: 1rem;
          justify-content: center;
        }
        
        .login-button, .signup-button {
          padding: 0.75rem 1.5rem;
          border-radius: 8px;
          font-weight: 500;
          cursor: pointer;
          transition: background-color 0.2s;
        }
        
        .login-button {
          background-color: #4f46e5;
          color: white;
          border: none;
        }
        
        .login-button:hover {
          background-color: #4338ca;
        }
        
        .signup-button {
          background-color: white;
          color: #4f46e5;
          border: 1px solid #4f46e5;
        }
        
        .signup-button:hover {
          background-color: #eef2ff;
        }
        
        @media (max-width: 640px) {
          .payment-container {
            padding: 1rem;
          }
          
          .auth-actions {
            flex-direction: column;
          }
          
          .login-button, .signup-button {
            width: 100%;
          }
        }
      `}</style>
    </div>
  );
};

export default PaymentPage;
