// Global persistent context for DJ Mixer to prevent track unloading on navigation
import React, { createContext, useContext, useState, useRef, useEffect } from 'react';

const DJMixerContext = createContext();

export const useDJMixer = () => {
  const context = useContext(DJMixerContext);
  if (!context) {
    throw new Error('useDJMixer must be used within a DJMixerProvider');
  }
  return context;
};

export const DJMixerProvider = ({ children }) => {
  // Persistent DJ state that survives navigation
  const [deckAState, setDeckAState] = useState(null);
  const [deckBState, setDeckBState] = useState(null);
  const [library, setLibrary] = useState([]);
  const [masterVolume, setMasterVolume] = useState(80);
  const [crossfaderPosition, setCrossfaderPosition] = useState(50);

  // Global audio context - keep alive across navigation
  const audioContextRef = useRef(null);
  const masterNodesRef = useRef({});
  const deckANodesRef = useRef({});
  const deckBNodesRef = useRef({});
  const mediaStreamDestinationRef = useRef(null);

  // Persistent playback handles so a playing deck survives navigation:
  // the mixer stores its live BufferSource + start-time here (instead of in
  // component-local refs that die on unmount), so on remount it can re-attach
  // to the still-playing audio rather than orphaning it and showing empty decks.
  const deckASourceRef = useRef(null);
  const deckBSourceRef = useRef(null);
  const deckAStartTimeRef = useRef(null);
  const deckBStartTimeRef = useRef(null);

  // Initialize audio context once globally
  useEffect(() => {
    if (!audioContextRef.current) {
      console.log('🎛️ Initializing global DJ audio context');
      audioContextRef.current = new (window.AudioContext || window.webkitAudioContext)();

      // Setup master audio chain
      setupMasterAudioChain();
      setupDeckAudioChain('A');
      setupDeckAudioChain('B');

      console.log('✅ Global DJ audio context initialized');
    }

    return () => {
      // Only close on app unmount, not on navigation
      console.log('⚠️ DJMixerContext cleanup - audio context kept alive');
    };
  }, []);

  const setupMasterAudioChain = () => {
    const context = audioContextRef.current;

    // Create master gain and compressor
    masterNodesRef.current.gain = context.createGain();
    masterNodesRef.current.compressor = context.createDynamicsCompressor();
    masterNodesRef.current.analyser = context.createAnalyser();

    // Create MediaStreamDestination for LiveKit streaming
    mediaStreamDestinationRef.current = context.createMediaStreamDestination();

    // Connect master chain
    masterNodesRef.current.gain.connect(masterNodesRef.current.compressor);
    masterNodesRef.current.compressor.connect(masterNodesRef.current.analyser);
    masterNodesRef.current.analyser.connect(context.destination);
    masterNodesRef.current.analyser.connect(mediaStreamDestinationRef.current);

    // Configure compressor for DJ-style processing
    masterNodesRef.current.compressor.threshold.value = -24;
    masterNodesRef.current.compressor.knee.value = 30;
    masterNodesRef.current.compressor.ratio.value = 12;
    masterNodesRef.current.compressor.attack.value = 0.003;
    masterNodesRef.current.compressor.release.value = 0.25;

    // Configure analyser
    masterNodesRef.current.analyser.fftSize = 2048;

    // Set initial volume
    masterNodesRef.current.gain.gain.value = masterVolume / 100;
  };

  const setupDeckAudioChain = (deck) => {
    const context = audioContextRef.current;
    const nodes = deck === 'A' ? deckANodesRef.current : deckBNodesRef.current;

    // Create audio nodes for deck
    nodes.gain = context.createGain();
    nodes.eqHigh = context.createBiquadFilter();
    nodes.eqMid = context.createBiquadFilter();
    nodes.eqLow = context.createBiquadFilter();
    nodes.analyser = context.createAnalyser();

    // Effects
    nodes.filter = context.createBiquadFilter();

    // Configure EQ
    nodes.eqHigh.type = 'highshelf';
    nodes.eqHigh.frequency.value = 10000;
    nodes.eqMid.type = 'peaking';
    nodes.eqMid.frequency.value = 1000;
    nodes.eqMid.Q.value = 1;
    nodes.eqLow.type = 'lowshelf';
    nodes.eqLow.frequency.value = 100;

    // Configure effects
    nodes.filter.type = 'lowpass';
    nodes.filter.frequency.value = 22000;

    // Configure analyser
    nodes.analyser.fftSize = 2048;
  };

  // Get the DJ audio stream for LiveKit integration
  const getDJAudioStream = () => {
    if (mediaStreamDestinationRef.current) {
      return mediaStreamDestinationRef.current.stream;
    }
    return null;
  };

  // Resume audio context if suspended
  const resumeAudioContext = async () => {
    if (audioContextRef.current && audioContextRef.current.state === 'suspended') {
      console.log('🔊 Resuming DJ audio context');
      await audioContextRef.current.resume();
    }
  };

  const value = {
    // Persistent state
    deckAState,
    setDeckAState,
    deckBState,
    setDeckBState,
    library,
    setLibrary,
    masterVolume,
    setMasterVolume,
    crossfaderPosition,
    setCrossfaderPosition,

    // Audio context and nodes (refs)
    audioContextRef,
    masterNodesRef,
    deckANodesRef,
    deckBNodesRef,
    mediaStreamDestinationRef,

    // Persistent playback handles (survive navigation)
    deckASourceRef,
    deckBSourceRef,
    deckAStartTimeRef,
    deckBStartTimeRef,

    // Helper functions
    getDJAudioStream,
    resumeAudioContext
  };

  return (
    <DJMixerContext.Provider value={value}>
      {children}
    </DJMixerContext.Provider>
  );
};

export default DJMixerContext;
