// Updated to use new Google Cloud Run streaming services

import React, { useState, useEffect, useRef } from 'react';
import { 
  Camera, Mic, MicOff, Video, VideoOff, X, Settings, Users, 
  MessageSquare, Play, AlertTriangle, DollarSign, Repeat, Star,
  RotateCw, Smartphone, Monitor, Check, Wifi, WifiOff
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { recordStreamStarted, recordStreamEnded } from '../../services/activityService';
import { useStreamingLiveKit as useStreaming } from '../../contexts/StreamingContextLiveKit';
import { 
  getStorage, ref as storageRef, uploadBytesResumable, getDownloadURL 
} from 'firebase/storage';
import { 
  getFirestore, doc, updateDoc, setDoc, onSnapshot, 
  serverTimestamp, getDoc, collection, getDocs, query, where, addDoc, increment
} from 'firebase/firestore';
import { getDatabase, ref as dbRef, onValue, set } from 'firebase/database';
import './TalentStreamingPortal.css';
import { streamingConfigFixed as streamingConfig } from "../../config/streaming-fixed.js"

const TalentStreamingPortal = ({ isMobile = false }) => {
  const { currentUser } = useAuth();
  const { 
    startEventStream, 
    stopEventStream, 
    streamingServiceReady, 
    getStreamingStats,
    testStreamingConnectivity,
    getRecommendedStreamSettings,
    error: streamingError 
  } = useStreaming();
  const navigate = useNavigate();
  
  // User and talent state
  const [isTalent, setIsTalent] = useState(false);
  
  // Streaming state
  const [isStreaming, setIsStreaming] = useState(false);
  const [streamData, setStreamData] = useState(null);
  const [currentStreamConfig, setCurrentStreamConfig] = useState(null);
  const [streamStats, setStreamStats] = useState(null);
  const [connectivityTest, setConnectivityTest] = useState(null);
  
  // Media controls
  const [isMicEnabled, setIsMicEnabled] = useState(true);
  const [isCameraEnabled, setIsCameraEnabled] = useState(true);
  const [facingMode, setFacingMode] = useState('user'); // 'user' for front camera, 'environment' for back
  
  // Stream configuration
  const [streamError, setStreamError] = useState(null);
  const [viewerCount, setViewerCount] = useState(0);
  const [streamKey, setStreamKey] = useState('');
  const [showSettings, setShowSettings] = useState(false);
  const [streamTitle, setStreamTitle] = useState(isMobile ? 'Mobile Live Stream' : 'Talent Live Stream');
  const [streamDescription, setStreamDescription] = useState('');
  const [streamSettings, setStreamSettings] = useState({
    quality: 'medium', // low, medium, high, ultra
    orientation: isMobile ? 'portrait' : 'landscape', // portrait, landscape
    camera: 'user' // environment (back) or user (front)
  });
  
  // Upload and recording
  const [isUploading, setIsUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  
  // Earnings
  const [totalTips, setTotalTips] = useState(0);
  const [currentSessionTips, setCurrentSessionTips] = useState(0);
  
  // Events
  const [availableEvents, setAvailableEvents] = useState([]);
  const [selectedEventId, setSelectedEventId] = useState('');
  
  // Refs for media elements
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const mediaRecorderRef = useRef(null);
  const chunksRef = useRef([]);
  const uploadIntervalRef = useRef(null);
  const streamStartedAtRef = useRef(null);
  
  // Check if user is talent
  useEffect(() => {
    const checkUserStatus = async () => {
      // Every signed-in user is a creator by default, so anyone who reaches
      // this portal is treated as talent. Access no longer depends on the
      // isArtist/canStream Firestore fields (which may be absent or unwritable).
      setIsTalent(!!currentUser);
    };
    
    checkUserStatus();
  }, [currentUser]);

  // Fetch available events for streaming
  useEffect(() => {
    const fetchEvents = async () => {
      try {
        const db = getFirestore();
        
        // Query for events - both streamEvents and events collections
        const streamEventsQuery = query(
          collection(db, 'streamEvents'),
          where('isActive', '==', true),
          where('allowsStreaming', '==', true)
        );
        
        const eventsQuery = query(
          collection(db, 'events'),
          where('status', 'in', ['scheduled', 'live'])
        );
        
        const [streamEventsSnapshot, eventsSnapshot] = await Promise.all([
          getDocs(streamEventsQuery),
          getDocs(eventsQuery)
        ]);
        
        const eventsList = [];
        
        streamEventsSnapshot.forEach((doc) => {
          eventsList.push({
            id: doc.id,
            source: 'streamEvents',
            ...doc.data()
          });
        });
        
        eventsSnapshot.forEach((doc) => {
          const data = doc.data();
          eventsList.push({
            id: doc.id,
            source: 'events',
            name: data.title,
            ...data
          });
        });
        
        setAvailableEvents(eventsList);
        
        // Auto-select first event if available
        if (eventsList.length > 0 && !selectedEventId) {
          setSelectedEventId(eventsList[0].id);
        }
      } catch (err) {
        console.error('Error fetching events:', err);
        setStreamError('Failed to load available events');
      }
    };
    
    fetchEvents();
  }, [selectedEventId]);
  
  // Check current stream status
  useEffect(() => {
    if (!currentUser) return;
    
    const db = getFirestore();
    const streamDocRef = doc(db, 'streams', `user_${currentUser.uid}`);
    
    const unsubscribe = onSnapshot(streamDocRef, (docSnapshot) => {
      if (docSnapshot.exists()) {
        const data = docSnapshot.data();
        setStreamData(data);
        setIsStreaming(data.isLive || false);
        setStreamTitle(data.title || (isMobile ? 'Mobile Live Stream' : 'Talent Live Stream'));
        setStreamDescription(data.description || '');
        
        // Update stream settings if available
        if (data.settings) {
          setStreamSettings(data.settings);
          setFacingMode(data.settings.camera || 'user');
        }
      }
    });
    
    return () => unsubscribe();
  }, [currentUser, isMobile]);
  
  // Initialize viewer count listener
  useEffect(() => {
    if (!isStreaming || !currentUser) return;
    
    // Use Firestore for view counting
    const db = getFirestore();
    const streamStatsRef = doc(db, 'streamStats', `user_${currentUser.uid}`);
    
    const unsubscribe = onSnapshot(streamStatsRef, (docSnapshot) => {
      if (docSnapshot.exists()) {
        setViewerCount(docSnapshot.data().viewerCount || 0);
        setCurrentSessionTips(docSnapshot.data().currentSessionTips || 0);
      }
    });
    
    // Also check the real-time database for viewer count
    const rtdb = getDatabase();
    const viewersRef = dbRef(rtdb, `streamViewers/${currentUser.uid}`);
    
    const rtdbUnsubscribe = onValue(viewersRef, (snapshot) => {
      if (snapshot.exists()) {
        // Use the greater of the two counts
        const rtdbCount = Object.keys(snapshot.val()).length;
        setViewerCount(prev => Math.max(prev, rtdbCount));
      }
    });
    
    return () => {
      unsubscribe();
      rtdbUnsubscribe();
    };
  }, [isStreaming, currentUser]);
  
  // Get total tips received
  useEffect(() => {
    if (!currentUser) return;
    
    const fetchTotalTips = async () => {
      try {
        const db = getFirestore();
        const tipsQuery = query(
          collection(db, 'tips'),
          where('recipientId', '==', currentUser.uid)
        );
        
        const querySnapshot = await getDocs(tipsQuery);
        let total = 0;
        
        querySnapshot.forEach(doc => {
          const tipData = doc.data();
          total += tipData.amount || 0;
        });
        
        setTotalTips(total);
      } catch (error) {
        console.error('Error fetching total tips:', error);
      }
    };
    
    fetchTotalTips();
    
    // Set up real-time listener for new tips
    const db = getFirestore();
    const tipsRef = collection(db, 'tips');
    const recentTipsQuery = query(
      tipsRef,
      where('recipientId', '==', currentUser.uid),
      where('timestamp', '>=', new Date(Date.now() - 86400000)) // Last 24 hours
    );
    
    const unsubscribe = onSnapshot(recentTipsQuery, (snapshot) => {
      fetchTotalTips(); // Refresh total when new tips come in
    });
    
    return () => unsubscribe();
  }, [currentUser]);
  
  // Update streaming error from context
  useEffect(() => {
    if (streamingError) {
      setStreamError(streamingError);
    }
  }, [streamingError]);
  
  // Function to initialize camera when needed
  const initCamera = async () => {
    if (!videoRef.current) return null;
    
    try {
      // Stop any existing stream
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
      
      // Get user media with appropriate constraints
      const constraints = {
        audio: isMicEnabled,
        video: isCameraEnabled ? {
          facingMode: facingMode, // Use selected camera mode
          width: { ideal: 1280 },
          height: { ideal: 720 }
        } : false
      };
      
      const mediaStream = await navigator.mediaDevices.getUserMedia(constraints);
      streamRef.current = mediaStream;
      
      // Set the video source
      videoRef.current.srcObject = mediaStream;
      await videoRef.current.play().catch(err => {
        console.error("Error playing video:", err);
        setStreamError(`Video playback error: ${err.message}`);
      });
      
      return mediaStream;
    } catch (err) {
      console.error('Error accessing camera:', err);
      setStreamError(`Camera access error: ${err.message}. Please check your camera permissions.`);
      return null;
    }
  };
  
  // Test streaming connectivity before starting
  const testConnectivity = async () => {
    if (!selectedEventId) {
      setStreamError('Please select an event first');
      return;
    }
    
    try {
      setStreamError(null);
      const result = await testStreamingConnectivity(selectedEventId);
      setConnectivityTest(result);
      
      if (result.success) {
        alert('✅ Connectivity test passed! You can start streaming.');
      } else {
        alert(`❌ Connectivity test failed: ${result.message}`);
      }
    } catch (error) {
      console.error('Connectivity test error:', error);
      setStreamError(`Connectivity test failed: ${error.message}`);
    }
  };

  // Get recommended settings based on connection
  const getRecommendedSettings = async () => {
    try {
      // Mock upload speed test - in real implementation, you'd measure this
      const mockUploadSpeed = 5; // Mbps
      const recommendations = await getRecommendedStreamSettings(mockUploadSpeed);
      
      setStreamSettings(prev => ({
        ...prev,
        quality: recommendations.quality
      }));
      
      alert(`Recommended quality: ${recommendations.quality}\n${recommendations.recommendation}`);
    } catch (error) {
      console.error('Failed to get recommendations:', error);
    }
  };

  // Handle starting the stream with new service
  const startStream = async () => {
    if (isStreaming) return;
    
    if (!streamingServiceReady) {
      setStreamError('Streaming services are not ready. Please wait a moment and try again.');
      return;
    }
    
    if (!selectedEventId) {
      setStreamError('Please select an event to stream to.');
      return;
    }
    
    try {
      setStreamError(null);
      
      console.log('🎬 Starting stream with new service...', {
        eventId: selectedEventId,
        quality: streamSettings.quality,
        audio: isMicEnabled,
        video: isCameraEnabled
      });
      
      // Initialize camera/microphone when starting stream
      const mediaStream = await initCamera();
      if (!mediaStream) {
        setStreamError('Failed to access camera/microphone. Please check your permissions.');
        return;
      }
      
      // Start stream using new event streaming service
      const streamResult = await startEventStream(selectedEventId, {
        quality: streamSettings.quality,
        enableAudio: isMicEnabled,
        enableVideo: isCameraEnabled,
        deviceType: isMobile ? 'mobile' : 'desktop'
      });
      
      if (!streamResult || !streamResult.success) {
        throw new Error('Failed to start event stream');
      }
      
      // Store stream configuration
      setCurrentStreamConfig(streamResult);
      console.log('✅ Stream started successfully:', streamResult);
      
      // Update the video source to show the stream key info
      if (videoRef.current) {
        // Add stream info overlay
        const streamInfo = document.createElement('div');
        streamInfo.innerHTML = `
          <div style="position: absolute; top: 10px; left: 10px; background: rgba(0,0,0,0.7); color: white; padding: 8px; border-radius: 4px; font-size: 12px; z-index: 10;">
            🔴 LIVE - Event: ${selectedEventId}<br/>
            Stream Key: ${streamResult.streamKey}<br/>
            Quality: ${streamSettings.quality}
          </div>
        `;
        videoRef.current.parentNode.appendChild(streamInfo);
      }
      
      // Use the stream key from the new service
      setStreamKey(streamResult.streamKey);
      
      // Put "live now" on the artist's activity feed.
      streamStartedAtRef.current = Date.now();
      recordStreamStarted({
        user: currentUser,
        streamId: `user_${currentUser.uid}`,
        eventId: selectedEventId,
        title: streamTitle,
        streamType: isMobile ? 'mobile' : 'desktop',
        text: streamDescription
      });
      
      setIsStreaming(true);
      
      // Start periodic stats updates
      const statsInterval = setInterval(async () => {
        try {
          const stats = await getStreamingStats(selectedEventId);
          setStreamStats(stats);
        } catch (error) {
          console.error('Failed to get stream stats:', error);
        }
      }, 5000); // Update every 5 seconds
      
      // Store interval for cleanup
      window.streamStatsInterval = statsInterval;
      
    } catch (error) {
      console.error('Error starting stream:', error);
      setStreamError(`Failed to start stream: ${error.message}`);
    }
  };
  
  // Handle stopping the stream with new service
  const stopStream = async () => {
    try {
      console.log('🛑 Stopping stream with new service...');
      
      // Clear stats interval
      if (window.streamStatsInterval) {
        clearInterval(window.streamStatsInterval);
        window.streamStatsInterval = null;
      }
      
      // Stop media recorder if it's recording
      if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
        mediaRecorderRef.current.stop();
      }
      
      // Stop media tracks
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
      
      // Stop the event stream using new service
      if (selectedEventId) {
        const stopResult = await stopEventStream(selectedEventId);
        if (!stopResult) {
          console.warn('Failed to stop event stream through new service');
        } else {
          console.log('✅ Event stream stopped successfully');
        }
      }
      
      // Clear any upload interval
      if (uploadIntervalRef.current) {
        clearInterval(uploadIntervalRef.current);
        uploadIntervalRef.current = null;
      }
      
      // Update stream status in Firestore
      if (currentUser) {
        const db = getFirestore();
        const streamDocRef = doc(db, 'streams', `user_${currentUser.uid}`);
        
        try {
          await updateDoc(streamDocRef, {
            isLive: false,
            endedAt: serverTimestamp()
          });
        } catch (error) {
          console.warn('Failed to update stream status in Firestore:', error);
        }
        
        // Update active streams collection
        try {
          const activeStreamRef = doc(db, 'activeStreams', currentUser.uid);
          await updateDoc(activeStreamRef, {
            isActive: false,
            endedAt: serverTimestamp()
          });
        } catch (error) {
          console.warn('Failed to update active streams:', error);
        }
        
        // If there's a selected event, update it
        if (selectedEventId) {
          try {
            const eventRef = doc(db, 'events', selectedEventId);
            const eventDoc = await getDoc(eventRef);
            if (eventDoc.exists()) {
              await updateDoc(eventRef, {
                liveStreamersCount: increment(-1)
              });
            }
          } catch (error) {
            console.warn('Failed to update event streamer count:', error);
          }
        }
        
        // Add to stream history
        try {
          const historyRef = collection(db, 'streamHistory');
          await addDoc(historyRef, {
            streamId: `user_${currentUser.uid}`,
            talentId: currentUser.uid,
            talentName: currentUser.displayName || 'Talent',
            talentPhotoURL: currentUser.photoURL || null,
            title: streamTitle,
            description: streamDescription,
            deviceType: isMobile ? 'mobile' : 'desktop',
            startedAt: streamData?.startedAt || serverTimestamp(),
            endedAt: serverTimestamp(),
            viewerCount: viewerCount,
            tipsReceived: currentSessionTips || 0,
            eventId: selectedEventId || null
          });
        } catch (error) {
          console.warn('Failed to add to stream history:', error);
        }
        
        // Close out the activity entry with how the session went.
        await recordStreamEnded({
          user: currentUser,
          streamId: `user_${currentUser.uid}`,
          viewerCount,
          title: streamTitle,
          eventId: selectedEventId || null,
          streamType: isMobile ? 'mobile' : 'desktop',
          startedAt: streamStartedAtRef.current
        });
      }
      
      // Update local state
      setIsStreaming(false);
      setCurrentStreamConfig(null);
      setStreamStats(null);
      setStreamKey('');
      
      // Clear video source
      if (videoRef.current) {
        videoRef.current.srcObject = null;
      }
      
      console.log('✅ Stream stopped successfully');
      
    } catch (error) {
      console.error('Error stopping stream:', error);
      setStreamError(`Failed to stop stream: ${error.message}`);
    }
  };
  
  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
      
      // Clear stats interval
      if (window.streamStatsInterval) {
        clearInterval(window.streamStatsInterval);
        window.streamStatsInterval = null;
      }
    };
  }, []);
  
  // Toggle microphone
  const toggleMic = () => {
    if (streamRef.current) {
      const audioTracks = streamRef.current.getAudioTracks();
      
      audioTracks.forEach(track => {
        track.enabled = !isMicEnabled;
      });
      
      setIsMicEnabled(!isMicEnabled);
    }
  };
  
  // Toggle camera
  const toggleCamera = () => {
    if (streamRef.current) {
      const videoTracks = streamRef.current.getVideoTracks();
      
      videoTracks.forEach(track => {
        track.enabled = !isCameraEnabled;
      });
      
      setIsCameraEnabled(!isCameraEnabled);
    }
  };
  
  // Switch camera (front/back)
  const flipCamera = async () => {
    try {
      // Toggle facing mode
      const newFacingMode = facingMode === 'user' ? 'environment' : 'user';
      setFacingMode(newFacingMode);
      
      // Update stream settings
      setStreamSettings({
        ...streamSettings,
        camera: newFacingMode
      });
      
    } catch (error) {
      console.error('Error flipping camera:', error);
      setStreamError(`Failed to flip camera: ${error.message}`);
    }
  };
  
  // Format currency amount
  const formatCurrency = (amount) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 2
    }).format(amount);
  };
  
  // Handle event selection
  const handleSelectEvent = (eventId) => {
    setSelectedEventId(eventId);
  };
  
  // If user is not talent, show access denied
  if (!isTalent) {
    return (
      <div className="talent-streaming-access-denied">
        <h2>Access Denied</h2>
        <p>You need to be a registered talent to access the streaming portal.</p>
        <p>Please contact an administrator to request streaming permissions.</p>
      </div>
    );
  }
  
  return (
    <div className={`talent-streaming-portal ${isMobile ? 'mobile' : 'desktop'}`}>
      <div className="stream-header">
        <h2>{!isStreaming ? (isMobile ? 'Mobile Stream' : 'Talent Streaming Portal') : 'LIVE: ' + streamTitle}</h2>
        {isStreaming && (
          <div className="stream-stats">
            <div className="viewer-count">
              <Users size={16} />
              <span>{viewerCount} viewers</span>
            </div>
            <div className="tips-count">
              <DollarSign size={16} />
              <span>Session: {formatCurrency(currentSessionTips)}</span>
            </div>
            {streamStats && (
              <div className="stream-technical-stats">
                <span>FPS: {streamStats.fps || 0}</span>
                <span>Bitrate: {streamStats.bitrate || 0}kbps</span>
                <span>Duration: {streamStats.duration || '00:00:00'}</span>
              </div>
            )}
            <div className="stream-status live">LIVE</div>
          </div>
        )}
      </div>
      
      {streamError && (
        <div className="stream-error">
          <p>{streamError}</p>
          <button onClick={() => setStreamError(null)} className="close-error">
            <X size={16} />
          </button>
        </div>
      )}
      
      <div className="stream-preview">
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted
          className={`${!isStreaming && !isCameraEnabled ? 'hidden' : ''} ${streamSettings.orientation === 'portrait' ? 'portrait' : 'landscape'}`}
        />
        {!isStreaming && !isCameraEnabled && (
          <div className="camera-placeholder">
            <Camera size={48} />
            <p>Camera is disabled</p>
          </div>
        )}
        
        {isUploading && (
          <div className="upload-progress">
            <div className="progress-bar">
              <div className="progress" style={{ width: `${uploadProgress}%` }}></div>
            </div>
            <p>{Math.round(uploadProgress)}% Uploading...</p>
          </div>
        )}
      </div>
      
      <div className="stream-controls">
        <button 
          onClick={toggleMic} 
          className={`control-button ${!isMicEnabled ? 'disabled' : ''}`}
          title={isMicEnabled ? 'Disable Microphone' : 'Enable Microphone'}
          disabled={isStreaming && !isMicEnabled}
        >
          {isMicEnabled ? <Mic size={20} /> : <MicOff size={20} />}
        </button>
        
        <button
          onClick={toggleCamera}
          className={`control-button ${!isCameraEnabled ? 'disabled' : ''}`}
          title={isCameraEnabled ? 'Disable Camera' : 'Enable Camera'}
          disabled={isStreaming && !isCameraEnabled}
        >
          {isCameraEnabled ? <Video size={20} /> : <VideoOff size={20} />}
        </button>
        
        <button
          onClick={flipCamera}
          className="control-button"
          title="Flip Camera"
          disabled={!isCameraEnabled}
        >
          <RotateCw size={20} />
        </button>
        
        <button
          onClick={() => setShowSettings(!showSettings)}
          className="control-button"
          title="Stream Settings"
        >
          <Settings size={20} />
        </button>
        
        <button
          onClick={isStreaming ? stopStream : startStream}
          className={`stream-button ${isStreaming ? 'stop' : 'start'}`}
          disabled={(!isCameraEnabled && !isMicEnabled) || (!isStreaming && (!streamingServiceReady || !selectedEventId))}
        >
          {isStreaming ? 'Stop Streaming' : 
           !streamingServiceReady ? 'Services Loading...' : 
           !selectedEventId ? 'Select Event First' :
           'Start Streaming'}
        </button>
      </div>
      
      {showSettings && !isStreaming && (
        <div className="stream-settings">
          <h3>Stream Settings</h3>
          
          <div className="settings-form">
            <div className="form-group">
              <label htmlFor="stream-title">Stream Title</label>
              <input
                id="stream-title"
                type="text"
                value={streamTitle}
                onChange={(e) => setStreamTitle(e.target.value)}
                placeholder="Enter stream title"
              />
            </div>
            
            <div className="form-group">
              <label htmlFor="stream-description">Description (optional)</label>
              <textarea
                id="stream-description"
                value={streamDescription}
                onChange={(e) => setStreamDescription(e.target.value)}
                placeholder="Tell viewers about your stream"
                rows={3}
              />
            </div>
            
            {isMobile && (
              <div className="form-group">
                <label htmlFor="stream-orientation">Orientation</label>
                <select
                  id="stream-orientation"
                  value={streamSettings.orientation}
                  onChange={(e) => setStreamSettings({...streamSettings, orientation: e.target.value})}
                >
                  <option value="landscape">Landscape</option>
                  <option value="portrait">Portrait</option>
                </select>
              </div>
            )}
            
            <div className="form-group">
              <label htmlFor="stream-quality">Stream Quality</label>
              <select
                id="stream-quality"
                value={streamSettings.quality}
                onChange={(e) => setStreamSettings({...streamSettings, quality: e.target.value})}
              >
                <option value="low">Low (Data Saver)</option>
                <option value="medium">Medium (Recommended)</option>
                <option value="high">High (Best Quality)</option>
                <option value="ultra">Ultra (Premium)</option>
              </select>
            </div>
            
            {availableEvents.length > 0 && (
              <div className="form-group">
                <label>Select Event</label>
                <div className="event-options">
                  {availableEvents.map(event => (
                    <div 
                      key={event.id}
                      className={`event-option ${selectedEventId === event.id ? 'selected' : ''}`}
                      onClick={() => handleSelectEvent(event.id)}
                    >
                      <div className="event-info">
                        <div className="event-name">{event.name || event.title}</div>
                        {event.location && <div className="event-location">{event.location}</div>}
                        <div className="event-source">Source: {event.source}</div>
                      </div>
                      {selectedEventId === event.id && (
                        <div className="event-selected-indicator">
                          <Check size={16} />
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            )}
            
            <div className="streaming-service-tools">
              <h4>Streaming Tools</h4>
              <div className="tool-buttons">
                <button 
                  onClick={testConnectivity}
                  className="tool-btn"
                  disabled={!selectedEventId || !streamingServiceReady}
                >
                  <Wifi size={16} />
                  Test Connection
                </button>
                <button 
                  onClick={getRecommendedSettings}
                  className="tool-btn"
                >
                  <Settings size={16} />
                  Get Recommendations
                </button>
              </div>
              
              {connectivityTest && (
                <div className={`connectivity-result ${connectivityTest.success ? 'success' : 'error'}`}>
                  <p>
                    {connectivityTest.success ? 
                      <Wifi size={16} /> : 
                      <WifiOff size={16} />
                    }
                    {connectivityTest.message}
                  </p>
                </div>
              )}
              
              {currentStreamConfig && (
                <div className="current-stream-config">
                  <h5>Current Stream Configuration:</h5>
                  <div className="config-details">
                    <span>Stream Key: {currentStreamConfig.streamKey}</span>
                    <span>RTMP URL: {currentStreamConfig.rtmpUrl}</span>
                    <span>Quality: {currentStreamConfig.config?.quality || 'Unknown'}</span>
                  </div>
                </div>
              )}
            </div>
            
            <div className="service-status">
              <h4>Service Status</h4>
              <div className={`status-indicator ${streamingServiceReady ? 'ready' : 'not-ready'}`}>
                <span>Streaming Services: {streamingServiceReady ? '✅ Ready' : '❌ Not Ready'}</span>
              </div>
            </div>
            
            <div className="settings-note">
              <AlertTriangle size={16} />
              <p>
                Note: Changes to settings will apply to new streams. 
                If you're currently streaming, stop and restart to apply changes.
              </p>
            </div>
          </div>
        </div>
      )}
      
      <div className="talent-earnings">
        <h3>Your Earnings</h3>
        <div className="earnings-stats">
          <div className="stat-item">
            <DollarSign size={24} className="stat-icon" />
            <div className="stat-content">
              <div className="stat-label">Total Earnings</div>
              <div className="stat-value">{formatCurrency(totalTips)}</div>
            </div>
          </div>
          
          <div className="stat-item">
            <Star size={24} className="stat-icon" />
            <div className="stat-content">
              <div className="stat-label">Current Session</div>
              <div className="stat-value">{formatCurrency(currentSessionTips)}</div>
            </div>
          </div>
        </div>
        
        <div className="earnings-actions">
          <button 
            className="earnings-button"
            onClick={() => navigate('/payments/history')}
          >
            View Payment History
          </button>
          <button 
            className="earnings-button primary"
            onClick={() => navigate('/payments/withdraw')}
          >
            Withdraw Funds
          </button>
        </div>
      </div>
      
      {isStreaming && (
        <div className="chat-integration">
          <h3>Live Chat</h3>
          <div className="chat-container">
            <div className="chat-messages">
              {/* Chat messages will appear here, integrated with your existing chat system */}
              <p className="placeholder">Live chat messages will appear here</p>
            </div>
            <div className="chat-input">
              <input
                type="text"
                placeholder="Type a message to viewers..."
                disabled={!isStreaming}
              />
              <button className="send-button">Send</button>
            </div>
          </div>
        </div>
      )}
      
      <div className="streaming-tips">
        <h3>Streaming Tips</h3>
        <ul>
          <li>
            <strong>Internet Connection:</strong> Ensure you have a stable, high-speed internet connection.
            Upload speed of at least 5 Mbps is recommended for 720p streaming.
          </li>
          <li>
            <strong>Background:</strong> Stream in a well-lit area with minimal background noise.
          </li>
          <li>
            <strong>Battery:</strong> Keep your device plugged in to prevent interruptions.
          </li>
          <li>
            <strong>Engage:</strong> Interact with viewers through the chat to keep them engaged.
          </li>
          <li>
            <strong>Test First:</strong> Use the "Test Connection" button to verify your setup before going live.
          </li>
          <li>
            <strong>New Service:</strong> This streaming portal now uses our upgraded cloud infrastructure for better reliability and quality.
          </li>
        </ul>
      </div>
    </div>
  );
};

export default TalentStreamingPortal;
