import apiKeyService from './apiKeyService'

const RSS_CACHE_KEY = 'predict_rss_cache'
const RSS_CACHE_TTL = 30 * 60 * 1000 // 30 minutes

function getCachedFeed(url) {
  try {
    const raw = localStorage.getItem(`${RSS_CACHE_KEY}_${btoa(url)}`)
    if (!raw) return null
    const cached = JSON.parse(raw)
    if (Date.now() - cached.timestamp > RSS_CACHE_TTL) return null
    return cached.data
  } catch {
    return null
  }
}

function setCachedFeed(url, data) {
  localStorage.setItem(`${RSS_CACHE_KEY}_${btoa(url)}`, JSON.stringify({ data, timestamp: Date.now() }))
}

function parseRssXml(xmlText) {
  const parser = new DOMParser()
  const doc = parser.parseFromString(xmlText, 'text/xml')
  const items = doc.querySelectorAll('item')

  return Array.from(items).map(item => ({
    title: item.querySelector('title')?.textContent || '',
    description: item.querySelector('description')?.textContent?.replace(/<[^>]*>/g, '') || '',
    link: item.querySelector('link')?.textContent || '',
    pubDate: item.querySelector('pubDate')?.textContent || '',
  })).slice(0, 20)
}

// Use a CORS proxy for RSS feeds since browsers block cross-origin XML
const CORS_PROXIES = [
  url => `https://api.allorigins.win/raw?url=${encodeURIComponent(url)}`,
  url => `https://corsproxy.io/?${encodeURIComponent(url)}`,
]

const rssService = {
  async fetchFeed(feedConfig) {
    const cached = getCachedFeed(feedConfig.url)
    if (cached) return { items: cached, error: null, fromCache: true }

    let lastError = null
    for (const proxyFn of CORS_PROXIES) {
      try {
        const proxyUrl = proxyFn(feedConfig.url)
        const res = await fetch(proxyUrl, { signal: AbortSignal.timeout(10000) })
        if (!res.ok) throw new Error(`HTTP ${res.status}`)

        const text = await res.text()
        const items = parseRssXml(text).map(item => ({
          ...item,
          feedName: feedConfig.name,
          feedCategory: feedConfig.category,
          sentiment: extractBasicSentiment(item.title + ' ' + item.description),
        }))

        setCachedFeed(feedConfig.url, items)
        return { items, error: null, fromCache: false }
      } catch (err) {
        lastError = err.message
      }
    }

    return { items: [], error: lastError || 'All proxies failed', fromCache: false }
  },

  async fetchAllFeeds() {
    const feeds = apiKeyService.getRssFeeds()
    const results = await Promise.allSettled(feeds.map(f => this.fetchFeed(f)))

    const allItems = []
    const errors = []

    results.forEach((result, i) => {
      if (result.status === 'fulfilled') {
        if (result.value.error) {
          errors.push({ feed: feeds[i].name, error: result.value.error })
        }
        allItems.push(...result.value.items)
      } else {
        errors.push({ feed: feeds[i].name, error: result.reason?.message || 'Unknown error' })
      }
    })

    allItems.sort((a, b) => new Date(b.pubDate || 0) - new Date(a.pubDate || 0))

    return { items: allItems, errors, feedCount: feeds.length }
  },

  generateInputsFromRss(items, predictions) {
    const inputs = []

    for (const item of items) {
      const text = `${item.title} ${item.description}`.toLowerCase()

      for (const prediction of predictions) {
        const titleWords = prediction.title.toLowerCase().split(/\W+/).filter(w => w.length > 3)
        const matchCount = titleWords.filter(w => text.includes(w)).length
        const matchRatio = matchCount / titleWords.length

        if (matchRatio >= 0.25 || matchCount >= 2) {
          inputs.push({
            predictionId: prediction.id,
            source: item.feedName,
            sourceUrl: item.link,
            type: 'rss',
            weight: 0.5 + (matchRatio * 0.3),
            sentiment: item.sentiment,
            reliability: 0.70,
            timestamp: item.pubDate ? new Date(item.pubDate).toISOString() : new Date().toISOString(),
            title: item.title,
            category: item.feedCategory,
            isLive: true,
          })
        }
      }
    }

    return inputs
  },
}

function extractBasicSentiment(text) {
  const lower = text.toLowerCase()
  const positive = ['success', 'growth', 'win', 'gain', 'rise', 'surge', 'boost', 'record', 'breakthrough', 'agreement', 'peace', 'strong', 'progress', 'improve']
  const negative = ['fail', 'crisis', 'loss', 'drop', 'fall', 'decline', 'crash', 'threat', 'war', 'conflict', 'risk', 'weak', 'concern', 'fear', 'danger']

  let score = 0.5
  for (const w of positive) if (lower.includes(w)) score += 0.04
  for (const w of negative) if (lower.includes(w)) score -= 0.04
  return Math.max(0.05, Math.min(0.95, score))
}

export default rssService
