// VideoUploadService.js
// Service class for handling video upload operations
// Pattern: Follows AudioUploadService.js structure

import { ref, uploadBytesResumable, getDownloadURL } from 'firebase/storage';
import { storage } from '../firebase';

class VideoUploadService {
  constructor() {
    this.storage = storage;
    this.maxFileSize = 1024 * 1024 * 1024; // 1GB
    this.allowedTypes = [
      'video/mp4',
      'video/webm',
      'video/ogg',
      'video/quicktime' // MOV files
    ];
  }

  /**
   * Validate video file
   * @param {File} file - The video file to validate
   * @returns {Object} - { valid: boolean, error: string }
   */
  validateVideoFile(file) {
    if (!file) {
      return { valid: false, error: 'No file provided' };
    }

    // Check if it's a file
    if (!(file instanceof File)) {
      return { valid: false, error: 'Invalid file object' };
    }

    // Check file type
    if (!this.allowedTypes.includes(file.type)) {
      const allowedExts = this.allowedTypes
        .map(type => type.split('/')[1].toUpperCase())
        .join(', ');
      return {
        valid: false,
        error: `Invalid file type. Allowed formats: ${allowedExts}`
      };
    }

    // Check file size (1GB limit)
    if (file.size > this.maxFileSize) {
      const sizeMB = (this.maxFileSize / (1024 * 1024)).toFixed(0);
      return {
        valid: false,
        error: `File too large. Maximum size is ${sizeMB}MB (1GB)`
      };
    }

    // Check for empty files
    if (file.size === 0) {
      return { valid: false, error: 'File is empty' };
    }

    return { valid: true, error: null };
  }

  /**
   * Generate thumbnail from video file using Canvas API
   * @param {File} videoFile - The video file
   * @returns {Promise<Blob>} - Thumbnail blob
   */
  generateThumbnail(videoFile) {
    return new Promise((resolve, reject) => {
      const video = document.createElement('video');
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');

      video.preload = 'metadata';
      video.muted = true;
      video.playsInline = true;

      // Seek to 1 second or 10% of duration (whichever is less)
      video.addEventListener('loadedmetadata', () => {
        const seekTime = Math.min(1, video.duration * 0.1);
        video.currentTime = seekTime;
      });

      // Capture frame when seeked
      video.addEventListener('seeked', () => {
        try {
          // Set canvas dimensions to video dimensions
          canvas.width = video.videoWidth;
          canvas.height = video.videoHeight;

          // Draw video frame to canvas
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

          // Convert canvas to blob
          canvas.toBlob(
            (blob) => {
              if (blob) {
                resolve(blob);
              } else {
                reject(new Error('Failed to create thumbnail blob'));
              }
              // Cleanup
              URL.revokeObjectURL(video.src);
            },
            'image/jpeg',
            0.8 // Quality
          );
        } catch (error) {
          reject(new Error(`Thumbnail generation failed: ${error.message}`));
          URL.revokeObjectURL(video.src);
        }
      });

      video.addEventListener('error', (e) => {
        reject(new Error('Failed to load video for thumbnail generation'));
        URL.revokeObjectURL(video.src);
      });

      // Load video
      video.src = URL.createObjectURL(videoFile);
    });
  }

  /**
   * Get video duration
   * @param {File} videoFile - The video file
   * @returns {Promise<number>} - Duration in seconds
   */
  getVideoDuration(videoFile) {
    return new Promise((resolve, reject) => {
      const video = document.createElement('video');
      video.preload = 'metadata';
      video.muted = true;
      video.playsInline = true;

      video.addEventListener('loadedmetadata', () => {
        resolve(video.duration);
        URL.revokeObjectURL(video.src);
      });

      video.addEventListener('error', () => {
        reject(new Error('Failed to load video metadata'));
        URL.revokeObjectURL(video.src);
      });

      video.src = URL.createObjectURL(videoFile);
    });
  }

  /**
   * Upload video file to Firebase Storage
   * @param {File} file - The video file
   * @param {string} userId - User ID
   * @param {Function} onProgress - Progress callback (progress: number)
   * @returns {Promise<Object>} - { downloadUrl, storagePath, size, format }
   */
  async uploadVideo(file, userId, onProgress = null) {
    // Validate file
    const validation = this.validateVideoFile(file);
    if (!validation.valid) {
      throw new Error(validation.error);
    }

    try {
      // Create unique filename
      const timestamp = Date.now();
      const randomString = Math.random().toString(36).substring(2, 9);
      const fileExtension = file.name.split('.').pop().toLowerCase();
      const fileName = `${timestamp}_${randomString}.${fileExtension}`;

      // Storage path: user-videos/{userId}/{fileName}
      const storagePath = `user-videos/${userId}/${fileName}`;
      const storageRef = ref(this.storage, storagePath);

      console.log(`Uploading video: ${fileName}`);
      console.log(`Storage path: ${storagePath}`);
      console.log(`File size: ${(file.size / 1024 / 1024).toFixed(2)}MB`);

      // Upload with progress tracking
      const uploadTask = uploadBytesResumable(storageRef, file);

      return new Promise((resolve, reject) => {
        uploadTask.on(
          'state_changed',
          (snapshot) => {
            const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
            console.log(`Upload progress: ${progress.toFixed(1)}%`);
            if (onProgress) {
              onProgress(progress);
            }
          },
          (error) => {
            console.error('Video upload error:', error);
            console.error('Error code:', error.code);
            console.error('Error message:', error.message);
            console.error('Error serverResponse:', error.serverResponse);
            console.error('Full error object:', JSON.stringify(error, null, 2));

            // Provide user-friendly error messages
            if (error.code === 'storage/unauthorized') {
              reject(new Error('Permission denied. Please make sure you are logged in.'));
            } else if (error.code === 'storage/quota-exceeded') {
              reject(new Error('Storage quota exceeded. Please try again later.'));
            } else if (error.code === 'storage/canceled') {
              reject(new Error('Upload canceled'));
            } else if (error.code === 'storage/unknown') {
              reject(new Error(`Upload failed (unknown error). Check browser console for details. Code: ${error.code}`));
            } else {
              reject(new Error(`Upload failed: ${error.message}`));
            }
          },
          async () => {
            try {
              const downloadUrl = await getDownloadURL(uploadTask.snapshot.ref);
              console.log('Video uploaded successfully:', downloadUrl);

              resolve({
                downloadUrl,
                storagePath,
                size: file.size,
                format: fileExtension
              });
            } catch (error) {
              reject(new Error(`Failed to get download URL: ${error.message}`));
            }
          }
        );
      });
    } catch (error) {
      console.error('Upload preparation error:', error);
      throw error;
    }
  }

  /**
   * Upload thumbnail to Firebase Storage
   * @param {Blob} thumbnailBlob - The thumbnail blob
   * @param {string} userId - User ID
   * @param {string} videoFileName - Original video filename (without extension)
   * @returns {Promise<string>} - Download URL
   */
  async uploadThumbnail(thumbnailBlob, userId, videoFileName) {
    try {
      const fileName = `${videoFileName}_thumb.jpg`;
      const storagePath = `user-videos/${userId}/thumbnails/${fileName}`;
      const storageRef = ref(this.storage, storagePath);

      console.log(`Uploading thumbnail: ${fileName}`);

      const uploadTask = uploadBytesResumable(storageRef, thumbnailBlob, {
        contentType: 'image/jpeg'
      });

      return new Promise((resolve, reject) => {
        uploadTask.on(
          'state_changed',
          (snapshot) => {
            const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
            console.log(`Thumbnail upload progress: ${progress.toFixed(1)}%`);
          },
          (error) => {
            console.error('Thumbnail upload error:', error);
            reject(new Error(`Thumbnail upload failed: ${error.message}`));
          },
          async () => {
            try {
              const downloadUrl = await getDownloadURL(uploadTask.snapshot.ref);
              console.log('Thumbnail uploaded successfully:', downloadUrl);
              resolve(downloadUrl);
            } catch (error) {
              reject(new Error(`Failed to get thumbnail URL: ${error.message}`));
            }
          }
        );
      });
    } catch (error) {
      console.error('Thumbnail preparation error:', error);
      throw error;
    }
  }

  /**
   * Upload video with thumbnail generation
   * @param {File} file - The video file
   * @param {string} userId - User ID
   * @param {Function} onProgress - Progress callback
   * @returns {Promise<Object>} - Complete video data
   */
  async uploadVideoWithThumbnail(file, userId, onProgress = null) {
    try {
      // Get video duration
      const duration = await this.getVideoDuration(file);
      console.log(`Video duration: ${duration.toFixed(2)}s`);

      // Generate thumbnail
      console.log('Generating thumbnail...');
      const thumbnailBlob = await this.generateThumbnail(file);
      console.log('Thumbnail generated successfully');

      // Upload video
      const videoData = await this.uploadVideo(file, userId, onProgress);

      // Extract filename without extension for thumbnail
      const videoFileNameWithoutExt = videoData.storagePath
        .split('/')
        .pop()
        .split('.')
        .slice(0, -1)
        .join('.');

      // Upload thumbnail
      const thumbnailUrl = await this.uploadThumbnail(
        thumbnailBlob,
        userId,
        videoFileNameWithoutExt
      );

      return {
        url: videoData.downloadUrl,
        thumbnail: thumbnailUrl,
        duration: Math.round(duration),
        size: videoData.size,
        format: videoData.format,
        storagePath: videoData.storagePath
      };
    } catch (error) {
      console.error('Video upload with thumbnail failed:', error);
      throw error;
    }
  }

  /**
   * Format file size for display
   * @param {number} bytes - File size in bytes
   * @returns {string} - Formatted size
   */
  formatFileSize(bytes) {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return Math.round((bytes / Math.pow(k, i)) * 100) / 100 + ' ' + sizes[i];
  }

  /**
   * Format duration for display
   * @param {number} seconds - Duration in seconds
   * @returns {string} - Formatted duration (HH:MM:SS or MM:SS)
   */
  formatDuration(seconds) {
    const hrs = Math.floor(seconds / 3600);
    const mins = Math.floor((seconds % 3600) / 60);
    const secs = Math.floor(seconds % 60);

    if (hrs > 0) {
      return `${hrs}:${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
    }
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  }
}

// Export singleton instance
const videoUploadService = new VideoUploadService();
export default videoUploadService;
