// Fallback for startEventStreamFallback method (used by services)
streamingConfigFixed.startEventStreamFallback = async function(eventId, userId, quality = 'medium', options = {}) {
  if (isProduction) {
    // In production, use the main method
    return await this.startEventStream(eventId, userId, quality, options);
  } else {
    // In development, try fallback if available
    try {
      return await streamingConfigFallback.startEventStreamFallback(eventId, userId, quality, options);
    } catch (error) {
      console.warn('⚠️ Fallback failed, using main method:', error);
      return await this.startEventStream(eventId, userId, quality, options);
    }
  }
};

