// src/admin/hooks/useUserList.js
import { useState, useEffect, useCallback } from 'react';
import { getFirestore, collection, getDocs, query, orderBy, where, limit, startAfter } from 'firebase/firestore';

/**
 * Custom hook for user list management
 * @param {number} pageSize - Number of users per page
 * @returns {Object} - User list state and methods
 */
export const useUserList = (pageSize = 25) => {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [lastVisible, setLastVisible] = useState(null);
  const [isLastPage, setIsLastPage] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalUsers, setTotalUsers] = useState(0);
  const [filterParams, setFilterParams] = useState({
    searchQuery: '',
    filterRole: 'all',
    filterStatus: 'all',
    sortBy: 'createdAt',
    sortDirection: 'desc'
  });

  // Destructure filter params for easier access
  const { searchQuery, filterRole, filterStatus, sortBy, sortDirection } = filterParams;

  /**
   * Fetch users from Firestore
   * @param {boolean} reset - Whether to reset pagination
   */
  const fetchUsers = useCallback(async (reset = false) => {
    if (reset) {
      setLastVisible(null);
      setCurrentPage(1);
      setIsLastPage(false);
    }
    
    setLoading(true);
    setError(null);
    
    try {
      const db = getFirestore();
      let usersRef = collection(db, 'users');
      
      // Create a base query with sorting
      let queryConstraints = [
        orderBy(sortBy, sortDirection),
        limit(pageSize)
      ];
      
      // Add filter conditions
      if (filterRole === 'admin') {
        queryConstraints.unshift(where('isAdmin', '==', true));
      } else if (filterRole === 'premium') {
        queryConstraints.unshift(where('isPremium', '==', true));
      }
      
      // Add pagination
      if (lastVisible && !reset) {
        queryConstraints.push(startAfter(lastVisible));
      }
      
      // Execute query
      const userSnapshot = await getDocs(query(usersRef, ...queryConstraints));
      
      // Check if we reached the last page
      if (userSnapshot.docs.length < pageSize) {
        setIsLastPage(true);
      } else {
        setIsLastPage(false);
      }
      
      // Update last visible for pagination
      const lastDoc = userSnapshot.docs[userSnapshot.docs.length - 1];
      setLastVisible(lastDoc);
      
      // Format data
      const userData = userSnapshot.docs.map(doc => {
        const data = doc.data();
        // Properly handle Firestore timestamps with Vite
        return {
          id: doc.id,
          ...data,
          createdAt: data.createdAt?.toDate ? data.createdAt.toDate() : null,
          lastLogin: data.lastLogin?.toDate ? data.lastLogin.toDate() : null,
          premiumSince: data.premiumSince?.toDate ? data.premiumSince.toDate() : null
        };
      });
      
      // Count total users (only on first load)
      if (reset || currentPage === 1) {
        const totalQuery = query(collection(db, 'users'));
        const totalSnapshot = await getDocs(totalQuery);
        setTotalUsers(totalSnapshot.size);
      }
      
      // Filter by search query (client-side filtering)
      const filteredData = searchQuery 
        ? userData.filter(user => {
            const searchLower = searchQuery.toLowerCase();
            return (
              (user.displayName && user.displayName.toLowerCase().includes(searchLower)) ||
              (user.email && user.email.toLowerCase().includes(searchLower)) ||
              (user.uid && user.uid.toLowerCase().includes(searchLower))
            );
          })
        : userData;
        
      setUsers(filteredData);
    } catch (err) {
      console.error('Error fetching users:', err);
      setError('Failed to load users. Please try again.');
    } finally {
      setLoading(false);
    }
  }, [pageSize, filterRole, filterStatus, sortBy, sortDirection, lastVisible, currentPage, searchQuery]);

  // Load users when filter params change
  useEffect(() => {
    fetchUsers(true);
  }, [fetchUsers, filterRole, filterStatus, sortBy, sortDirection]);

  // Handle search with debounce
  useEffect(() => {
    const delaySearch = setTimeout(() => {
      fetchUsers(true);
    }, 500);
    
    return () => clearTimeout(delaySearch);
  }, [fetchUsers, searchQuery]);

  /**
   * Handle next page navigation
   */
  const handleNextPage = useCallback(() => {
    if (!isLastPage) {
      setCurrentPage(prev => prev + 1);
      fetchUsers(false);
    }
  }, [fetchUsers, isLastPage]);

  /**
   * Handle previous page navigation
   */
  const handlePrevPage = useCallback(() => {
    if (currentPage > 1) {
      // This is a limitation of Firestore pagination
      // Need to reset and fetch from beginning for previous page
      setCurrentPage(prev => prev - 1);
      fetchUsers(true);
      // Then skip pages until we reach the desired page
      for (let i = 1; i < currentPage - 1; i++) {
        fetchUsers(false);
      }
    }
  }, [fetchUsers, currentPage]);

  /**
   * Handle sort change
   * @param {string} field - Field to sort by
   */
  const handleSortChange = useCallback((field) => {
    setFilterParams(prev => {
      if (prev.sortBy === field) {
        // Toggle direction if same field
        return {
          ...prev,
          sortDirection: prev.sortDirection === 'asc' ? 'desc' : 'asc'
        };
      } else {
        // New field, set default direction
        return {
          ...prev,
          sortBy: field,
          sortDirection: 'desc'
        };
      }
    });
  }, []);

  /**
   * Update filter params
   * @param {Object} newParams - New filter parameters
   */
  const updateFilters = useCallback((newParams) => {
    setFilterParams(prev => ({
      ...prev,
      ...newParams
    }));
  }, []);

  return {
    users,
    loading,
    error,
    isLastPage,
    currentPage,
    totalUsers,
    filterParams,
    fetchUsers,
    handleNextPage,
    handlePrevPage,
    handleSortChange,
    updateFilters
  };
};
