// src/admin/UserManagement.js
import React, { useState, useEffect } from 'react';
import { getFirestore, collection, getDocs, doc, updateDoc, query } from 'firebase/firestore';
import { Search, Shield, ShieldOff, UserX, RefreshCw, Users, ArrowLeft } from 'lucide-react';
import { Link } from 'react-router-dom';

const UserManagement = () => {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [processingUser, setProcessingUser] = useState(null);

  // Fetch users
  const fetchUsers = async () => {
    setLoading(true);
    setError(null);
    
    try {
      const db = getFirestore();
      const usersCollection = collection(db, 'users');
      const userDocs = await getDocs(query(usersCollection));
      
      const userData = [];
      userDocs.forEach(doc => {
        const data = doc.data();
        userData.push({
          id: doc.id,
          ...data,
          lastLogin: data.lastLogin?.toDate ? data.lastLogin.toDate() : null
        });
      });
      
      setUsers(userData);
    } catch (err) {
      console.error('Error fetching users:', err);
      setError('Failed to load users. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  // Load users on component mount
  useEffect(() => {
    fetchUsers();
  }, []);

  // Toggle admin status
  const toggleAdminStatus = async (userId, currentStatus) => {
    setProcessingUser(userId);
    
    try {
      const db = getFirestore();
      const userRef = doc(db, 'users', userId);
      
      await updateDoc(userRef, {
        isAdmin: !currentStatus
      });
      
      // Update local state
      setUsers(prevUsers => 
        prevUsers.map(user => 
          user.id === userId ? { ...user, isAdmin: !currentStatus } : user
        )
      );
      
    } catch (err) {
      console.error('Error updating admin status:', err);
      setError(`Failed to update admin status: ${err.message}`);
    } finally {
      setProcessingUser(null);
    }
  };

  // Filter users based on search query
  const filteredUsers = users.filter(user => {
    const searchTerm = searchQuery.toLowerCase();
    const displayName = user.displayName?.toLowerCase() || '';
    const email = user.email?.toLowerCase() || '';
    
    return displayName.includes(searchTerm) || email.includes(searchTerm);
  });

  return (
    <div className="bg-white rounded-lg shadow-md">
      <div className="border-b p-4">
        <div className="flex justify-between items-center">
          <div>
            <h2 className="text-xl font-semibold">Admin Role Management</h2>
            <p className="text-gray-600">Manage admin privileges for your users</p>
          </div>
          <Link 
            to="/admin/users" 
            className="flex items-center text-indigo-600 hover:text-indigo-800"
          >
            <ArrowLeft className="h-4 w-4 mr-1" />
            <span>Back to User List</span>
          </Link>
        </div>
      </div>
      
      {/* Search and refresh */}
      <div className="flex flex-col md:flex-row gap-3 p-4 border-b">
        <div className="relative flex-grow">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
            <Search className="h-5 w-5 text-gray-400" />
          </div>
          <input
            type="text"
            className="block w-full pl-10 pr-3 py-2 border border-gray-300 rounded-md leading-5 bg-white placeholder-gray-500 focus:outline-none focus:placeholder-gray-400 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500"
            placeholder="Search users..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
        
        <button
          onClick={fetchUsers}
          className="flex items-center justify-center px-4 py-2 border border-gray-300 rounded-md text-sm font-medium text-gray-700 bg-white hover:bg-gray-50"
        >
          <RefreshCw className="h-4 w-4 mr-2" />
          Refresh
        </button>
      </div>
      
      {/* Error message */}
      {error && (
        <div className="p-4 bg-red-50 border-b border-red-200">
          <p className="text-red-600">{error}</p>
        </div>
      )}
      
      {/* Users list */}
      <div className="overflow-x-auto">
        {loading ? (
          <div className="flex justify-center items-center p-8">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600"></div>
          </div>
        ) : filteredUsers.length === 0 ? (
          <div className="text-center p-8 text-gray-500">
            {searchQuery ? 'No users match your search' : 'No users found'}
          </div>
        ) : (
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  User
                </th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Status
                </th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Last Login
                </th>
                <th scope="col" className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Actions
                </th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {filteredUsers.map((user) => (
                <tr key={user.id} className="hover:bg-gray-50">
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="flex items-center">
                      <div className="flex-shrink-0 h-10 w-10 relative">
                        {user.photoURL ? (
                          <img className="h-10 w-10 rounded-full" src={user.photoURL} alt="" />
                        ) : (
                          <div className="h-10 w-10 rounded-full bg-indigo-100 flex items-center justify-center">
                            <span className="text-xl font-medium text-indigo-600">
                              {user.displayName ? user.displayName[0].toUpperCase() : (user.email ? user.email[0].toUpperCase() : '?')}
                            </span>
                          </div>
                        )}
                        {user.isAdmin && (
                          <div className="absolute bottom-0 right-0 h-4 w-4 bg-indigo-600 rounded-full border-2 border-white" 
                            title="Admin user">
                          </div>
                        )}
                      </div>
                      <div className="ml-4">
                        <div className="text-sm font-medium text-gray-900">
                          {user.displayName || 'Unnamed User'}
                        </div>
                        <div className="text-sm text-gray-500">
                          {user.email || 'No email'}
                        </div>
                        <div className="text-xs text-gray-400">
                          {user.id}
                        </div>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full 
                      ${user.isAdmin 
                        ? 'bg-indigo-100 text-indigo-800' 
                        : 'bg-gray-100 text-gray-800'}`}>
                      {user.isAdmin ? 'Admin' : 'User'}
                    </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                    {user.lastLogin ? new Date(user.lastLogin).toLocaleString() : 'Never'}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                    <button
                      onClick={() => toggleAdminStatus(user.id, user.isAdmin)}
                      disabled={processingUser === user.id}
                      className={`inline-flex items-center px-3 py-1.5 border border-transparent text-xs font-medium rounded 
                        ${user.isAdmin
                          ? 'text-indigo-700 bg-indigo-100 hover:bg-indigo-200'
                          : 'text-gray-700 bg-gray-100 hover:bg-gray-200'
                        } ${processingUser === user.id ? 'opacity-50 cursor-not-allowed' : ''}`}
                    >
                      {processingUser === user.id ? (
                        <div className="animate-spin h-4 w-4 border-2 border-indigo-500 border-t-transparent rounded-full mr-1"></div>
                      ) : user.isAdmin ? (
                        <ShieldOff className="w-4 h-4 mr-1" />
                      ) : (
                        <Shield className="w-4 h-4 mr-1" />
                      )}
                      {user.isAdmin ? 'Remove Admin' : 'Make Admin'}
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
};

export default UserManagement;