// Redirects legacy stream URLs to the unified session screen

import React, { useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';

const StreamRedirect = () => {
  const { eventId } = useParams();
  const navigate = useNavigate();

  useEffect(() => {
    if (eventId) {
      console.log(`🔗 Redirecting legacy stream URL /stream/${eventId} to /events/${eventId}/session`);
      navigate(`/events/${eventId}/session`, { replace: true });
    } else {
      // If no eventId, redirect to events list
      console.log('🔗 No eventId found, redirecting to events list');
      navigate('/events', { replace: true });
    }
  }, [eventId, navigate]);

  // Show loading while redirecting
  return (
    <div style={{
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      height: '100vh',
      backgroundColor: '#0f0f0f',
      color: 'white',
      flexDirection: 'column',
      gap: '1rem'
    }}>
      <div style={{
        width: '40px',
        height: '40px',
        border: '4px solid #333',
        borderTop: '4px solid #9146ff',
        borderRadius: '50%',
        animation: 'spin 1s linear infinite'
      }} />
      <style>
        {`
          @keyframes spin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
          }
        `}
      </style>
      <p>Redirecting to session...</p>
    </div>
  );
};

export default StreamRedirect;
