// Enhanced Error Boundary for LiveKit/Streaming Components
// Path: C:\Users\Tom\Documents\GitHub\presence-react3\presence-react\src\components\common\LiveKitErrorBoundary.jsx

import React from 'react';

class LiveKitErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null, errorInfo: null };
  }

  static getDerivedStateFromError(error) {
    // Update state so the next render will show the fallback UI
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    // Log the error for debugging
    console.error('LiveKit Error Boundary caught an error:', error, errorInfo);
    
    // Check if this is the specific destructuring error we're trying to fix
    if (error.message && error.message.includes('startEventStream')) {
      console.error('🔴 Streaming context destructuring error detected:', error.message);
    }
    
    this.setState({
      error: error,
      errorInfo: errorInfo
    });
  }

  render() {
    if (this.state.hasError) {
      // Custom fallback UI for streaming-related errors
      return (
        <div style={{
          backgroundColor: 'rgba(239, 68, 68, 0.1)',
          border: '2px solid rgba(239, 68, 68, 0.3)',
          borderRadius: '12px',
          padding: '2rem',
          margin: '1rem',
          textAlign: 'center',
          color: '#dc2626'
        }}>
          <div style={{
            fontSize: '3rem',
            marginBottom: '1rem'
          }}>
            ⚠️
          </div>
          
          <h2 style={{
            margin: '0 0 1rem 0',
            fontSize: '1.5rem',
            fontWeight: 'bold'
          }}>
            Streaming Component Error
          </h2>
          
          <p style={{
            margin: '0 0 1rem 0',
            fontSize: '1rem',
            lineHeight: '1.5'
          }}>
            A streaming component encountered an error and has been safely contained.
          </p>
          
          {process.env.NODE_ENV === 'development' && (
            <details style={{
              backgroundColor: 'rgba(255, 255, 255, 0.8)',
              border: '1px solid rgba(239, 68, 68, 0.3)',
              borderRadius: '8px',
              padding: '1rem',
              marginTop: '1rem',
              textAlign: 'left'
            }}>
              <summary style={{
                cursor: 'pointer',
                fontWeight: 'bold',
                marginBottom: '0.5rem'
              }}>
                🔧 Debug Information (Development Mode)
              </summary>
              
              <div style={{
                fontSize: '0.8rem',
                fontFamily: 'monospace',
                color: '#374151'
              }}>
                <div style={{ marginBottom: '1rem' }}>
                  <strong>Error:</strong>
                  <div style={{ marginTop: '0.5rem', padding: '0.5rem', backgroundColor: '#f3f4f6', borderRadius: '4px' }}>
                    {this.state.error?.message || 'Unknown error'}
                  </div>
                </div>
                
                {this.state.error?.stack && (
                  <div>
                    <strong>Stack Trace:</strong>
                    <div style={{ 
                      marginTop: '0.5rem', 
                      padding: '0.5rem', 
                      backgroundColor: '#f3f4f6', 
                      borderRadius: '4px',
                      whiteSpace: 'pre-wrap',
                      maxHeight: '200px',
                      overflow: 'auto'
                    }}>
                      {this.state.error.stack}
                    </div>
                  </div>
                )}
              </div>
            </details>
          )}
          
          <div style={{
            marginTop: '1.5rem',
            display: 'flex',
            gap: '1rem',
            justifyContent: 'center',
            flexWrap: 'wrap'
          }}>
            <button
              onClick={() => window.location.reload()}
              style={{
                backgroundColor: '#dc2626',
                color: 'white',
                border: 'none',
                borderRadius: '8px',
                padding: '0.75rem 1.5rem',
                cursor: 'pointer',
                fontSize: '0.9rem',
                fontWeight: '600'
              }}
            >
              🔄 Reload Page
            </button>
            
            <button
              onClick={() => this.setState({ hasError: false, error: null, errorInfo: null })}
              style={{
                backgroundColor: '#6b7280',
                color: 'white',
                border: 'none',
                borderRadius: '8px',
                padding: '0.75rem 1.5rem',
                cursor: 'pointer',
                fontSize: '0.9rem',
                fontWeight: '600'
              }}
            >
              🔧 Try Again
            </button>
            
            <button
              onClick={() => window.location.href = '/'}
              style={{
                backgroundColor: '#10b981',
                color: 'white',
                border: 'none',
                borderRadius: '8px',
                padding: '0.75rem 1.5rem',
                cursor: 'pointer',
                fontSize: '0.9rem',
                fontWeight: '600'
              }}
            >
              🏠 Go Home
            </button>
          </div>
          
          <div style={{
            marginTop: '1rem',
            fontSize: '0.8rem',
            color: '#6b7280'
          }}>
            This error has been safely contained and won't affect other parts of the application.
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

export default LiveKitErrorBoundary;