import React, { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAudioProfileHybrid } from '../hooks/useAudioProfileHybrid';
import { useAudioDetectionFixed } from '../hooks/useAudioDetectionFixed';
import { AudioMatchingService } from '../services/AudioMatchingService';
import { app, getDb, getRtdb } from '../firebase';

export const AudioListenerComponent = () => {
  const [isRecording, setIsRecording] = useState(false);
  const [recordedBlob, setRecordedBlob] = useState(null);
  const [keywords, setKeywords] = useState('');
  const [title, setTitle] = useState('');
  const [matchResult, setMatchResult] = useState(null);
  const [error, setError] = useState(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [audioLevel, setAudioLevel] = useState(0);
  const [searchingForMatch, setSearchingForMatch] = useState(false);
  const [audioUrl, setAudioUrl] = useState(null);
  const [waveformData, setWaveformData] = useState([]);
  const [audioStats, setAudioStats] = useState(null);
  
  const mediaRecorderRef = useRef(null);
  const audioChunksRef = useRef(null);
  const streamRef = useRef(null);
  const audioContextRef = useRef(null);
  const analyserRef = useRef(null);
  const animationFrameRef = useRef(null);
  const canvasRef = useRef(null);
  
  const navigate = useNavigate();
  
  const {
    isReady,
    isAuthenticated,
    currentUser,
    createProfile,
    ensureAuth
  } = useAudioProfileHybrid(app);
  
  const audioDetection = useAudioDetectionFixed();
  
  const [matchingService] = useState(() => new AudioMatchingService(getDb(), getRtdb()));
  
  // Draw waveform on canvas
  const drawWaveform = (data) => {
    if (!canvasRef.current) return;
    
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;
    
    ctx.clearRect(0, 0, width, height);
    ctx.fillStyle = '#f0f0f0';
    ctx.fillRect(0, 0, width, height);
    
    if (data.length === 0) return;
    
    ctx.beginPath();
    ctx.moveTo(0, height / 2);
    ctx.strokeStyle = '#2196F3';
    ctx.lineWidth = 2;
    
    const sliceWidth = width / data.length;
    let x = 0;
    
    for (let i = 0; i < data.length; i++) {
      const y = (data[i] + 1) * height / 2;
      
      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
      
      x += sliceWidth;
    }
    
    ctx.lineTo(width, height / 2);
    ctx.stroke();
  };
  
  // Audio level visualization
  const updateAudioLevel = () => {
    if (analyserRef.current) {
      const dataArray = new Uint8Array(analyserRef.current.frequencyBinCount);
      analyserRef.current.getByteFrequencyData(dataArray);
      const average = dataArray.reduce((a, b) => a + b, 0) / dataArray.length;
      setAudioLevel(average / 255); // Normalize to 0-1
      
      if (isRecording) {
        animationFrameRef.current = requestAnimationFrame(updateAudioLevel);
      }
    }
  };
  
  // Start recording
  const startRecording = async () => {
    try {
      setError(null);
      audioChunksRef.current = [];
      
      // Ensure authentication
      if (!isAuthenticated) {
        await ensureAuth();
      }
      
      // Request microphone access
      const stream = await navigator.mediaDevices.getUserMedia({ 
        audio: {
          channelCount: 1,
          sampleRate: 44100,
          echoCancellation: true,
          noiseSuppression: true
        } 
      });
      streamRef.current = stream;
      
      // Setup audio level analysis
      audioContextRef.current = new (window.AudioContext || window.webkitAudioContext)();
      const source = audioContextRef.current.createMediaStreamSource(stream);
      analyserRef.current = audioContextRef.current.createAnalyser();
      analyserRef.current.fftSize = 256;
      source.connect(analyserRef.current);
      
      // Start recording
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      
      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          audioChunksRef.current.push(event.data);
        }
      };
      
      mediaRecorder.onstop = async () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/wav' });
        setRecordedBlob(audioBlob);
        
        // Create URL for playback
        const url = URL.createObjectURL(audioBlob);
        setAudioUrl(url);
        
        // Analyze the audio to check if it has content
        await analyzeAudio(audioBlob);
        
        // Clean up
        if (streamRef.current) {
          streamRef.current.getTracks().forEach(track => track.stop());
        }
        if (animationFrameRef.current) {
          cancelAnimationFrame(animationFrameRef.current);
        }
        setAudioLevel(0);
      };
      
      mediaRecorder.start();
      setIsRecording(true);
      updateAudioLevel();
      
    } catch (error) {
      console.error('Error starting recording:', error);
      setError('Failed to start recording: ' + error.message);
    }
  };
  
  // Stop recording
  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };
  
  // Analyze audio to create waveform and check for silence
  const analyzeAudio = async (audioBlob) => {
    try {
      const audioContext = new (window.AudioContext || window.webkitAudioContext)();
      const arrayBuffer = await audioBlob.arrayBuffer();
      const audioBuffer = await audioContext.decodeAudioData(arrayBuffer);
      
      // Get audio data
      const channelData = audioBuffer.getChannelData(0);
      const sampleRate = audioBuffer.sampleRate;
      const duration = audioBuffer.duration;
      
      // Create waveform data (downsampled for visualization)
      const downsampleRate = 200; // points per second
      const totalSamples = Math.floor(duration * downsampleRate);
      const blockSize = Math.floor(channelData.length / totalSamples);
      const waveform = [];
      
      let maxAmplitude = 0;
      let totalEnergy = 0;
      
      for (let i = 0; i < totalSamples; i++) {
        const start = i * blockSize;
        const end = Math.min(start + blockSize, channelData.length);
        
        let min = 1;
        let max = -1;
        let sum = 0;
        
        for (let j = start; j < end; j++) {
          const sample = channelData[j];
          min = Math.min(min, sample);
          max = Math.max(max, sample);
          sum += Math.abs(sample);
          totalEnergy += sample * sample;
          maxAmplitude = Math.max(maxAmplitude, Math.abs(sample));
        }
        
        const avg = (max + min) / 2;
        waveform.push(avg);
      }
      
      setWaveformData(waveform);
      
      // Calculate audio statistics
      const rms = Math.sqrt(totalEnergy / channelData.length);
      const isSilent = maxAmplitude < 0.01 && rms < 0.001;
      
      setAudioStats({
        duration: duration.toFixed(2),
        maxAmplitude: maxAmplitude.toFixed(4),
        rms: rms.toFixed(4),
        isSilent
      });
      
      // Draw waveform
      drawWaveform(waveform);
      
      // Alert if audio is silent
      if (isSilent) {
        setError('Warning: The recording appears to be silent. Please try again with audio playing.');
      } else {
        // Process for matching if not silent
        await processRecordingForMatching(audioBlob);
      }
      
      audioContext.close();
    } catch (error) {
      console.error('Error analyzing audio:', error);
      setError('Failed to analyze audio: ' + error.message);
    }
  };
  
  // Process recording for matching
  const processRecordingForMatching = async (audioBlob) => {
    setSearchingForMatch(true);
    setError(null);
    
    try {
      // Create audio fingerprint
      const audioContext = new (window.AudioContext || window.webkitAudioContext)();
      const fingerprint = await audioDetection.processAudioData(audioBlob, audioContext);
      audioContext.close();
      
      console.log('Fingerprint created:', fingerprint.slice(0, 10)); // Log first 10 values
      
      // Search for matches
      const matchingRoom = await matchingService.findMatchingRoom(fingerprint, currentUser?.uid);
      
      if (matchingRoom) {
        // Match found - join the room immediately
        console.log(`Match found with ${(matchingRoom.similarity * 100).toFixed(2)}% similarity`);
        
        const result = await matchingService.createOrJoinAudioRoom({
          fingerprint,
          userId: currentUser?.uid,
          keywords: '',
          title: ''
        }, {
          userName: currentUser?.displayName || 'Anonymous',
          fileSize: audioBlob.size,
          recordedAt: Date.now()
        });
        
        setMatchResult(result);
        setSearchingForMatch(false);
        
        // Show match notification before redirecting
        setTimeout(() => {
          navigate(`/room/${result.roomId}`);
        }, 1500); // Show match result for 1.5 seconds before redirecting
      } else {
        // No match found - show the form
        console.log('No match found');
        setSearchingForMatch(false);
      }
    } catch (error) {
      console.error('Error searching for match:', error);
      setError('Failed to search for matches: ' + error.message);
      setSearchingForMatch(false);
    }
  };
  
  // Create new room with details
  const createNewRoom = async () => {
    if (!recordedBlob) {
      setError('No recording to process');
      return;
    }
    
    setIsProcessing(true);
    setError(null);
    
    try {
      // Create audio fingerprint
      const audioContext = new (window.AudioContext || window.webkitAudioContext)();
      const fingerprint = await audioDetection.processAudioData(recordedBlob, audioContext);
      audioContext.close();
      
      // Create new room with details
      const result = await matchingService.createOrJoinAudioRoom({
        fingerprint,
        userId: currentUser?.uid,
        keywords,
        title
      }, {
        userName: currentUser?.displayName || 'Anonymous',
        fileSize: recordedBlob.size,
        recordedAt: Date.now()
      });
      
      setMatchResult(result);
      
      // Clear form
      setKeywords('');
      setTitle('');
      setRecordedBlob(null);
      
      // Redirect to room
      navigate(`/room/${result.roomId}`);
      
    } catch (error) {
      console.error('Error creating room:', error);
      setError('Failed to create room: ' + error.message);
    } finally {
      setIsProcessing(false);
    }
  };
  
  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
      if (audioContextRef.current) {
        audioContextRef.current.close();
      }
      if (audioUrl) {
        URL.revokeObjectURL(audioUrl);
      }
    };
  }, [audioUrl]);
  
  if (!isReady) {
    return <div>Loading audio services...</div>;
  }
  
  return (
    <div style={{ 
      padding: '20px', 
      maxWidth: '600px', 
      margin: '0 auto',
      fontFamily: 'Arial, sans-serif'
    }}>
      <h2>Audio Listener</h2>
      
      {/* Authentication Status */}
      <div style={{ 
        marginBottom: '20px',
        padding: '10px',
        backgroundColor: isAuthenticated ? '#e8f5e9' : '#fff3e0',
        borderRadius: '4px'
      }}>
        <strong>Status:</strong> {
          isAuthenticated 
            ? `Ready (${currentUser?.uid?.substring(0, 8)}...)`
            : 'Not authenticated'
        }
      </div>
      
      {/* Error Display */}
      {error && (
        <div style={{ 
          marginBottom: '20px',
          padding: '10px',
          backgroundColor: '#ffebee',
          color: '#c62828',
          borderRadius: '4px'
        }}>
          <strong>Error:</strong> {error}
        </div>
      )}
      
      {/* Recording Interface */}
      <div style={{ 
        textAlign: 'center',
        marginBottom: '30px'
      }}>
        {!isRecording && !recordedBlob && !searchingForMatch && (
          <button
            onClick={startRecording}
            style={{
              width: '120px',
              height: '120px',
              borderRadius: '50%',
              backgroundColor: '#f44336',
              color: 'white',
              border: 'none',
              fontSize: '18px',
              cursor: 'pointer',
              boxShadow: '0 4px 6px rgba(0,0,0,0.1)',
              transition: 'all 0.3s'
            }}
            onMouseOver={(e) => e.target.style.transform = 'scale(1.1)'}
            onMouseOut={(e) => e.target.style.transform = 'scale(1.0)'}
          >
            🎤 Listen
          </button>
        )}
        
        {isRecording && (
          <div>
            <button
              onClick={stopRecording}
              style={{
                width: '120px',
                height: '120px',
                borderRadius: '50%',
                backgroundColor: '#2196F3',
                color: 'white',
                border: 'none',
                fontSize: '18px',
                cursor: 'pointer',
                boxShadow: '0 4px 6px rgba(0,0,0,0.1)',
                animation: 'pulse 1.5s infinite'
              }}
            >
              ⏹️ Stop
            </button>
            
            {/* Audio Level Indicator */}
            <div style={{ 
              marginTop: '20px',
              height: '30px',
              backgroundColor: '#e0e0e0',
              borderRadius: '15px',
              overflow: 'hidden'
            }}>
              <div style={{
                height: '100%',
                width: `${audioLevel * 100}%`,
                backgroundColor: '#4CAF50',
                transition: 'width 0.1s ease'
              }}></div>
            </div>
          </div>
        )}
        
        {searchingForMatch && (
          <div>
            <div style={{
              width: '120px',
              height: '120px',
              margin: '0 auto',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              borderRadius: '50%',
              backgroundColor: '#2196F3',
              color: 'white',
              animation: 'pulse 1.5s infinite'
            }}>
              <div>🔍</div>
            </div>
            <p style={{ marginTop: '20px', fontSize: '18px' }}>
              Searching for matching rooms...
            </p>
            <p style={{ marginTop: '10px', color: '#666' }}>
              This may take a few seconds
            </p>
          </div>
        )}
      </div>
      
      {/* Audio Playback and Waveform */}
      {recordedBlob && !searchingForMatch && (
        <div style={{ 
          marginBottom: '20px',
          padding: '15px',
          backgroundColor: '#f9f9f9',
          borderRadius: '4px'
        }}>
          <h4>Recording Preview</h4>
          
          {/* Audio Player */}
          <audio 
            controls 
            src={audioUrl}
            style={{ width: '100%', marginBottom: '15px' }}
          />
          
          {/* Waveform Canvas */}
          <canvas
            ref={canvasRef}
            width={550}
            height={100}
            style={{
              width: '100%',
              border: '1px solid #ddd',
              borderRadius: '4px',
              backgroundColor: '#f0f0f0'
            }}
          />
          
          {/* Audio Stats */}
          {audioStats && (
            <div style={{ 
              marginTop: '10px',
              fontSize: '14px',
              color: '#666'
            }}>
              <div>Duration: {audioStats.duration}s</div>
              <div>Max Amplitude: {audioStats.maxAmplitude}</div>
              <div>RMS: {audioStats.rms}</div>
              {audioStats.isSilent && (
                <div style={{ color: '#f44336', fontWeight: 'bold' }}>
                  ⚠️ Recording appears to be silent
                </div>
              )}
            </div>
          )}
        </div>
      )}
      
      {/* Match Result Notification */}
      {matchResult && !matchResult.isNew && (
        <div style={{ 
          textAlign: 'center',
          marginBottom: '20px',
          padding: '15px',
          backgroundColor: '#e8f5e9',
          borderRadius: '4px',
          animation: 'fadeIn 0.5s ease-in'
        }}>
          <h3>🎵 Match Found!</h3>
          <p>Found a room with {(matchResult.similarity * 100).toFixed(0)}% similarity</p>
          <p style={{ marginTop: '10px', color: '#666' }}>Redirecting to room...</p>
        </div>
      )}
      
      {/* Recording Details - Only show if no match found */}
      {recordedBlob && !matchResult && !searchingForMatch && !audioStats?.isSilent && (
        <div style={{ 
          marginBottom: '20px',
          padding: '15px',
          backgroundColor: '#f5f5f5',
          borderRadius: '4px'
        }}>
          <h3>No Match Found - Create New Room</h3>
          <p style={{ color: '#666', marginBottom: '15px' }}>
            No existing rooms match your audio. Create a new room:
          </p>
          
          <div style={{ marginBottom: '15px' }}>
            <label style={{ display: 'block', marginBottom: '5px' }}>
              Title:
            </label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="Give this audio a title"
              style={{
                width: '100%',
                padding: '8px',
                border: '1px solid #ddd',
                borderRadius: '4px'
              }}
            />
          </div>
          
          <div style={{ marginBottom: '15px' }}>
            <label style={{ display: 'block', marginBottom: '5px' }}>
              Keywords:
            </label>
            <input
              type="text"
              value={keywords}
              onChange={(e) => setKeywords(e.target.value)}
              placeholder="Enter keywords (e.g., genre, mood, artist)"
              style={{
                width: '100%',
                padding: '8px',
                border: '1px solid #ddd',
                borderRadius: '4px'
              }}
            />
          </div>
          
          <div style={{ 
            display: 'flex', 
            gap: '10px',
            marginTop: '20px'
          }}>
            <button
              onClick={createNewRoom}
              disabled={isProcessing}
              style={{
                flex: 1,
                padding: '10px',
                backgroundColor: '#4CAF50',
                color: 'white',
                border: 'none',
                borderRadius: '4px',
                cursor: 'pointer',
                opacity: isProcessing ? 0.6 : 1
              }}
            >
              {isProcessing ? 'Creating...' : 'Create Room'}
            </button>
            
            <button
              onClick={() => {
                setRecordedBlob(null);
                setTitle('');
                setKeywords('');
                setAudioUrl(null);
                setWaveformData([]);
                setAudioStats(null);
              }}
              style={{
                padding: '10px 20px',
                backgroundColor: '#f44336',
                color: 'white',
                border: 'none',
                borderRadius: '4px',
                cursor: 'pointer'
              }}
            >
              Cancel
            </button>
          </div>
        </div>
      )}
      
      <style jsx>{`
        @keyframes pulse {
          0% {
            box-shadow: 0 0 0 0 rgba(33, 150, 243, 0.7);
          }
          70% {
            box-shadow: 0 0 0 15px rgba(33, 150, 243, 0);
          }
          100% {
            box-shadow: 0 0 0 0 rgba(33, 150, 243, 0);
          }
        }
        
        @keyframes fadeIn {
          from {
            opacity: 0;
            transform: translateY(10px);
          }
          to {
            opacity: 1;
            transform: translateY(0);
          }
        }
      `}</style>
    </div>
  );
};