import { getConfidenceColor } from '../../utils/weights'
import DataMask from '../../../components/premium/DataMask'

export default function ConfidenceBar({ value, size = 'md', showLabel = true }) {
  const { bg, text } = getConfidenceColor(value)
  const height = size === 'sm' ? 'h-1.5' : size === 'md' ? 'h-2' : 'h-3'

  return (
    <div className="flex items-center gap-3 w-full">
      <div className={`flex-1 bg-gray-800 rounded-full ${height} overflow-hidden`}>
        {/* Bar width masked for signed-in free users so they can't eyeball
            the probability; anonymous visitors see the real value. */}
        <DataMask minTier="data" mode="block" allowAnonymous placeholder={
          <div className={`bg-gray-600 ${height} rounded-full animate-fill-bar`} style={{ width: '45%' }} />
        } inline={false} upgradeLink={false}>
          <div
            className={`${bg} ${height} rounded-full animate-fill-bar`}
            style={{ width: `${value}%` }}
          />
        </DataMask>
      </div>
      {showLabel && (
        <span className={`${text} font-mono text-sm font-semibold min-w-[3ch] text-right`}>
          <DataMask minTier="data" mode="blur" inline allowAnonymous>
            {value}%
          </DataMask>
        </span>
      )}
    </div>
  )
}
