/**
 * WatchReplaysPage.jsx - Complete Watch Replays page for TalkStudio.space
 * Path: C:\Users\Tom\Documents\GitHub\presence-react3\presence-react\src\pages\WatchReplaysPage.jsx
 * 
 * Combines ReplayPlayer and ReplayList into a complete replay viewing experience
 */

console.log('📺📺📺 WatchReplaysPage.jsx FILE LOADED 📺📺📺');

import React, { useState, useCallback, useEffect } from 'react';
import { useParams, useNavigate, useSearchParams } from 'react-router-dom';
// import ReplayPlayer from '../components/WatchReplays/ReplayPlayer';
import WorkingReplayPlayer from '../components/WatchReplays/WorkingReplayPlayer';  // Using working version
const ReplayPlayer = WorkingReplayPlayer; // Alias for easier replacement
import ReplayList from '../components/WatchReplays/ReplayList';

const WatchReplaysPage = () => {
  console.log('📺 WatchReplaysPage: Component function called');
  window.WatchReplaysPageLoaded = true; // Add a global flag we can check
  
  const { eventId } = useParams();
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  
  console.log('📺 WatchReplaysPage: Mounted with eventId:', eventId);
  
  // Get event ID from URL params or query params
  const getEventIdFromUrl = () => {
    // Check URL params first (/watch-replays/:eventId)
    if (eventId) return eventId;
    
    // Check query params (?event=eventId)
    const queryEventId = searchParams.get('event');
    if (queryEventId) return queryEventId;
    
    return null;
  };
  
  // State management
  const [selectedEvent, setSelectedEvent] = useState(null);
  const [currentEventId, setCurrentEventId] = useState(getEventIdFromUrl());
  const [isPlayerReady, setIsPlayerReady] = useState(false);
  const [playerError, setPlayerError] = useState(null);
  const [showList, setShowList] = useState(!eventId); // Show list if no specific event
  const [isMobile, setIsMobile] = useState(window.innerWidth < 768);
  
  console.log('📺 WatchReplaysPage: currentEventId:', currentEventId);

  // Layout state
  const [layoutMode, setLayoutMode] = useState(
    searchParams.get('layout') || (isMobile ? 'mobile' : 'theater')
  );

  /**
   * Handle replay selection from list
   */
  const handleReplaySelect = useCallback((replay) => {
    setSelectedEvent(replay);
    setCurrentEventId(replay.id);
    setPlayerError(null);
    
    // Update URL
    navigate(`/watch-replays/${replay.id}`, { replace: true });
    
    // On mobile, hide the list when selecting a video
    if (isMobile) {
      setShowList(false);
    }
  }, [navigate, isMobile]);

  /**
   * Handle event load in player
   */
  const handleEventLoad = useCallback((event) => {
    setSelectedEvent(event);
  }, []);

  /**
   * Handle player ready
   */
  const handlePlayerReady = useCallback(() => {
    setIsPlayerReady(true);
  }, []);

  /**
   * Handle player error
   */
  const handlePlayerError = useCallback((error) => {
    setPlayerError(error);
  }, []);

  /**
   * Handle layout mode change
   */
  const handleLayoutChange = useCallback((mode) => {
    setLayoutMode(mode);
    const newSearchParams = new URLSearchParams(searchParams);
    newSearchParams.set('layout', mode);
    setSearchParams(newSearchParams);
  }, [searchParams, setSearchParams]);

  /**
   * Handle back to list (mobile)
   */
  const handleBackToList = useCallback(() => {
    setShowList(true);
    setCurrentEventId(null);
    navigate('/watch-replays', { replace: true });
  }, [navigate]);

  /**
   * Handle URL changes and event ID updates
   */
  useEffect(() => {
    const newEventId = getEventIdFromUrl();
    if (newEventId !== currentEventId) {
      setCurrentEventId(newEventId);
      setShowList(!newEventId);
    }
  }, [eventId, searchParams, currentEventId]);

  /**
   * Handle window resize
   */
  React.useEffect(() => {
    const handleResize = () => {
      const mobile = window.innerWidth < 768;
      setIsMobile(mobile);
      
      // Auto-adjust layout for mobile
      if (mobile && layoutMode === 'theater') {
        setLayoutMode('mobile');
      }
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [layoutMode]);

  /**
   * Render layout controls
   */
  const renderLayoutControls = () => (
    <div className="flex items-center gap-2 mb-4">
      <span className="text-sm font-medium text-gray-700">Layout:</span>
      
      <button
        onClick={() => handleLayoutChange('theater')}
        className={`px-3 py-1.5 text-sm rounded-md transition-colors ${
          layoutMode === 'theater'
            ? 'bg-indigo-100 text-indigo-700 border border-indigo-200'
            : 'bg-gray-100 text-gray-600 hover:bg-gray-200 border border-gray-200'
        }`}
        disabled={isMobile}
      >
        🎭 Theater
      </button>
      
      <button
        onClick={() => handleLayoutChange('split')}
        className={`px-3 py-1.5 text-sm rounded-md transition-colors ${
          layoutMode === 'split'
            ? 'bg-indigo-100 text-indigo-700 border border-indigo-200'
            : 'bg-gray-100 text-gray-600 hover:bg-gray-200 border border-gray-200'
        }`}
        disabled={isMobile}
      >
        📱 Split
      </button>
      
      <button
        onClick={() => handleLayoutChange('mobile')}
        className={`px-3 py-1.5 text-sm rounded-md transition-colors ${
          layoutMode === 'mobile'
            ? 'bg-indigo-100 text-indigo-700 border border-indigo-200'
            : 'bg-gray-100 text-gray-600 hover:bg-gray-200 border border-gray-200'
        }`}
      >
        📱 Mobile
      </button>
    </div>
  );

  /**
   * Render event info panel
   */
  const renderEventInfo = () => {
    if (!selectedEvent) return null;

    return (
      <div className="bg-white rounded-lg shadow-sm border p-6 mb-6">
        <div className="flex items-start justify-between mb-4">
          <div className="flex-1">
            <h1 className="text-2xl font-bold text-gray-900 mb-2">
              {selectedEvent.title || 'Untitled Replay'}
            </h1>
            
            {selectedEvent.description && (
              <p className="text-gray-600 mb-4">
                {selectedEvent.description}
              </p>
            )}
            
            <div className="flex flex-wrap items-center gap-4 text-sm text-gray-500">
              <span className="flex items-center gap-1">
                <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M6 2a1 1 0 00-1 1v1H4a2 2 0 00-2 2v10a2 2 0 002 2h12a2 2 0 002-2V6a2 2 0 00-2-2h-1V3a1 1 0 10-2 0v1H7V3a1 1 0 00-1-1zm0 5a1 1 0 000 2h8a1 1 0 100-2H6z" clipRule="evenodd" />
                </svg>
                {new Date(selectedEvent.createdAt).toLocaleDateString()}
              </span>
              
              {selectedEvent.duration && (
                <span className="flex items-center gap-1">
                  <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm1-12a1 1 0 10-2 0v4a1 1 0 00.293.707l2.828 2.829a1 1 0 101.415-1.415L11 9.586V6z" clipRule="evenodd" />
                  </svg>
                  {Math.floor(selectedEvent.duration / 60)}m {selectedEvent.duration % 60}s
                </span>
              )}
              
              {selectedEvent.viewCount !== undefined && (
                <span className="flex items-center gap-1">
                  <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
                    <path d="M10 12a2 2 0 100-4 2 2 0 000 4z" />
                    <path fillRule="evenodd" d="M.458 10C1.732 5.943 5.522 3 10 3s8.268 2.943 9.542 7c-1.274 4.057-5.064 7-9.542 7S1.732 14.057.458 10zM14 10a4 4 0 11-8 0 4 4 0 018 0z" clipRule="evenodd" />
                  </svg>
                  {selectedEvent.viewCount} views
                </span>
              )}
            </div>
          </div>
          
          {/* Share Button */}
          <button
            onClick={() => {
              navigator.clipboard.writeText(window.location.href);
              // You could add a toast notification here
            }}
            className="flex items-center gap-2 px-3 py-2 text-sm text-gray-600 hover:text-gray-800 hover:bg-gray-100 rounded-lg transition-colors"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 6.632a3 3 0 105.367-2.684 1.5 1.5 0 00-1.045-1.316m0 1.316a1.5 1.5 0 001.045 1.316m0-1.316l-6.632 3.316" />
            </svg>
            Share
          </button>
        </div>
        
        {/* Tags */}
        {selectedEvent.tags && selectedEvent.tags.length > 0 && (
          <div className="flex flex-wrap gap-2">
            {selectedEvent.tags.map(tag => (
              <span
                key={tag}
                className="inline-block bg-indigo-100 text-indigo-700 text-sm px-3 py-1 rounded-full"
              >
                {tag}
              </span>
            ))}
          </div>
        )}
      </div>
    );
  };

  /**
   * Render mobile layout
   */
  const renderMobileLayout = () => {
    if (showList || !currentEventId) {
      return (
        <div className="min-h-screen bg-gray-50 p-4">
          <div className="mb-4">
            <h1 className="text-2xl font-bold text-gray-900">Watch Replays</h1>
          </div>
          
          <ReplayList
            onReplaySelect={handleReplaySelect}
            selectedEventId={currentEventId}
            className="mb-6"
          />
        </div>
      );
    }

    return (
      <div className="min-h-screen bg-black">
        {/* Mobile Header */}
        <div className="bg-black text-white p-4 flex items-center justify-between">
          <button
            onClick={handleBackToList}
            className="flex items-center gap-2 text-white hover:text-indigo-400 transition-colors"
          >
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
            </svg>
            Back to List
          </button>
          
          {selectedEvent && (
            <h2 className="text-lg font-medium truncate max-w-48">
              {selectedEvent.title || 'Untitled Replay'}
            </h2>
          )}
        </div>
        
        {/* Player */}
        <ReplayPlayer
          eventId={currentEventId}
          autoPlay={false}
          showControls={true}
          onEventLoad={handleEventLoad}
          onPlayerReady={handlePlayerReady}
          onError={handlePlayerError}
          className="w-full"
        />
        
        {/* Event Info (Collapsible on mobile) */}
        {selectedEvent && (
          <div className="bg-white p-4">
            <div className="max-w-4xl mx-auto">
              {renderEventInfo()}
            </div>
          </div>
        )}
      </div>
    );
  };

  /**
   * Render theater layout
   */
  const renderTheaterLayout = () => {
    return (
      <div className="min-h-screen bg-gray-50">
        {/* Header */}
        <div className="bg-white border-b border-gray-200 p-6">
          <div className="max-w-7xl mx-auto">
            <div className="flex items-center justify-between mb-4">
              <h1 className="text-3xl font-bold text-gray-900">Watch Replays</h1>
              {!isMobile && renderLayoutControls()}
            </div>
          </div>
        </div>

        <div className="max-w-7xl mx-auto p-6">
          {currentEventId ? (
            <div className="space-y-6">
              {/* Player */}
              <div className="bg-black rounded-lg overflow-hidden shadow-lg">
                <ReplayPlayer
                  eventId={currentEventId}
                  autoPlay={false}
                  showControls={true}
                  onEventLoad={handleEventLoad}
                  onPlayerReady={handlePlayerReady}
                  onError={handlePlayerError}
                />
              </div>
              
              {/* Event Info */}
              {renderEventInfo()}
              
              {/* Related Replays */}
              <div>
                <h2 className="text-xl font-bold text-gray-900 mb-4">More Replays</h2>
                <ReplayList
                  onReplaySelect={handleReplaySelect}
                  selectedEventId={currentEventId}
                  showSearch={false}
                  showFilters={false}
                  itemsPerPage={8}
                />
              </div>
            </div>
          ) : (
            <ReplayList
              onReplaySelect={handleReplaySelect}
              selectedEventId={currentEventId}
            />
          )}
        </div>
      </div>
    );
  };

  /**
   * Render split layout
   */
  const renderSplitLayout = () => {
    return (
      <div className="min-h-screen bg-gray-50">
        {/* Header */}
        <div className="bg-white border-b border-gray-200 p-6">
          <div className="max-w-7xl mx-auto">
            <div className="flex items-center justify-between">
              <h1 className="text-3xl font-bold text-gray-900">Watch Replays</h1>
              {renderLayoutControls()}
            </div>
          </div>
        </div>

        <div className="max-w-7xl mx-auto p-6">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Player Section */}
            <div className="lg:col-span-2 space-y-6">
              {currentEventId ? (
                <>                  
                  <div className="bg-black rounded-lg overflow-hidden shadow-lg">
                    <ReplayPlayer
                      eventId={currentEventId}
                      autoPlay={false}
                      showControls={true}
                      onEventLoad={handleEventLoad}
                      onPlayerReady={handlePlayerReady}
                      onError={handlePlayerError}
                    />
                  </div>
                  
                  {renderEventInfo()}
                </>
              ) : (
                <div className="bg-white rounded-lg shadow-sm border p-12 text-center">
                  <div className="text-gray-400 text-6xl mb-4">🎬</div>
                  <h2 className="text-xl font-medium text-gray-600 mb-2">
                    Select a replay to watch
                  </h2>
                  <p className="text-gray-500">
                    Choose from the available replays in the sidebar
                  </p>
                </div>
              )}
            </div>
            
            {/* Sidebar with Replay List */}
            <div className="lg:col-span-1">
              <div className="bg-white rounded-lg shadow-sm border overflow-hidden">
                <div className="p-4 bg-gray-50 border-b">
                  <h2 className="font-semibold text-gray-900">Available Replays</h2>
                </div>
                <div className="max-h-screen overflow-y-auto">
                  <ReplayList
                    onReplaySelect={handleReplaySelect}
                    selectedEventId={currentEventId}
                    showSearch={true}
                    showFilters={true}
                    itemsPerPage={20}
                    className="p-4"
                  />
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  };

  /**
   * Main render
   */
  if (isMobile || layoutMode === 'mobile') {
    return renderMobileLayout();
  }

  if (layoutMode === 'split') {
    return renderSplitLayout();
  }

  return renderTheaterLayout();
};

export default WatchReplaysPage;
