// src/pages/SketchPage.jsx
//
// "Jam Studio" — write a melody, dress it, play over it, share it.
//
// Flow: pick a vibe → write a melody → keep the tune and reroll the
// arrangement (or vice versa) → play over it on the JamPad → record takes as
// layers → publish to the jam feed → others remix.
//
// Routes to this page:
//   /sketch                — empty studio
//   /sketch?from=mic       — hum recording is in sessionStorage (SmartMic)
//   /sketch?remix=<jamId>  — load a published jam's layers to remix it
//
// Composition lives in src/services/melodyComposer.js.
// Sound lives in src/services/sketchEngine.js.
// Persistence lives in src/services/jamService.js.

import React, { useEffect, useRef, useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import {
  Play,
  Pause,
  Sparkles,
  Shuffle,
  Repeat,
  Share2,
  Mic,
  Square,
  ChevronLeft,
  ChevronDown,
  ChevronRight,
  Circle,
  Trash2,
  GitBranch,
  ListMusic,
  Volume2,
  VolumeX,
  Lock,
  Unlock,
  Star,
  X,
} from 'lucide-react';

import {
  createSketchEngine,
  sketchToLayers,
  STYLES,
  STYLE_KEYS,
  KEYS,
  SCALE_LABELS,
  randomSeed,
} from '../services/sketchEngine';
import { publishJam, getJam } from '../services/jamService';
import { listCuts, saveCut, deleteCut, recipeFromSong, describeCut } from '../services/cutStore';
import { useAuth } from '../contexts/AuthContext';
import JamPad from '../components/audio/JamPad';
import MelodyRoll from '../components/audio/MelodyRoll';

export const SMARTMIC_BLOB_KEY = 'smartmic:lastRecordingBlob';

const LEAD_OPTIONS = [
  { key: 'rhodes',  label: 'rhodes' },
  { key: 'saw',     label: 'saw' },
  { key: 'pluck',   label: 'pluck' },
  { key: 'bell',    label: 'bell' },
  { key: 'voxlead', label: 'voice' },
];

const SCALE_OPTIONS = ['minor', 'dorian', 'phrygian', 'harmonic', 'major', 'mixolydian', 'lydian'];

const MIXER_TRACKS = [
  { key: 'melody', label: 'melody' },
  { key: 'chords', label: 'chords' },
  { key: 'arp',    label: 'arp'    },
  { key: 'bass',   label: 'bass'   },
  { key: 'pad',    label: 'pad'    },
  { key: 'drums',  label: 'drums'  },
  { key: 'fx',     label: 'fx'     },
];

// Loop lengths are for sketching; "song" hands off to the arrangement engine,
// which decides its own length (a ~4 minute radio edit).
const LENGTHS = [
  { value: 'loop:12', arrangement: 'loop',  bars: 12, label: 'loop · short' },
  { value: 'loop:20', arrangement: 'loop',  bars: 20, label: 'loop · medium' },
  { value: 'loop:28', arrangement: 'loop',  bars: 28, label: 'loop · long' },
  { value: 'radio',   arrangement: 'radio', bars: 20, label: 'song (~4 min)' },
];

// Club-tempo territory is where most sessions start, so the studio opens there
// instead of at a style's own default.
const DEFAULT_STYLE = 'house';
const DEFAULT_TEMPO = 128;
const TEMPO_MIN = 60;
const TEMPO_MAX = 170;

let takeCounter = 0;

const SketchPage = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { currentUser } = useAuth();

  // ---- composition settings ----
  const [style, setStyle] = useState(DEFAULT_STYLE);
  const [keyName, setKeyName] = useState(() => KEYS[Math.floor(Math.random() * KEYS.length)]);
  const [scaleName, setScaleName] = useState(STYLES[DEFAULT_STYLE].scale);
  const [tempo, setTempo] = useState(DEFAULT_TEMPO);
  // Locked by default: switching vibes should audition a new groove at YOUR
  // tempo, not drag the session off to the style's own.
  const [tempoLocked, setTempoLocked] = useState(true);
  const [bars, setBars] = useState(20);
  const [arrangement, setArrangement] = useState('loop');
  const [lead, setLead] = useState(STYLES[DEFAULT_STYLE].lead);
  const [seed, setSeed] = useState(() => randomSeed());
  const [melodySeed, setMelodySeed] = useState(() => randomSeed());

  // ---- engine + song ----
  const engineRef = useRef(null);
  const [engineReady, setEngineReady] = useState(false);
  const [song, setSong] = useState(null);
  const [cuts, setCuts] = useState(() => listCuts());
  const [layers, setLayers] = useState([]);
  const [mutedLayers, setMutedLayers] = useState(new Set());
  const [trackMutes, setTrackMutes] = useState({});
  const [isPlaying, setIsPlaying] = useState(false);
  const [loop, setLoop] = useState(true);
  const [position, setPosition] = useState(0);
  const [busy, setBusy] = useState(false);

  // ---- seed recording (humming / voice memo) ----
  const [recordingUrl, setRecordingUrl] = useState(null);
  const [isRecordingSeed, setIsRecordingSeed] = useState(false);
  const mediaRecorderRef = useRef(null);
  const streamRef = useRef(null);
  const chunksRef = useRef([]);

  // ---- perform + publish ----
  const [isTakeRecording, setIsTakeRecording] = useState(false);
  const [showPerform, setShowPerform] = useState(false);
  const [parentJam, setParentJam] = useState(null);
  const [title, setTitle] = useState('');
  const [publishState, setPublishState] = useState(null); // null | 'saving' | 'done' | error

  /* -------------------- Mount: hum seed and/or remix source -------------------- */
  useEffect(() => {
    if (searchParams.get('from') === 'mic') {
      try {
        const dataUrl = sessionStorage.getItem(SMARTMIC_BLOB_KEY);
        if (dataUrl) setRecordingUrl(dataUrl);
      } catch (_) { /* noop */ }
    }
    const remixId = searchParams.get('remix');
    if (remixId) {
      (async () => {
        try {
          const jam = await getJam(remixId);
          if (jam) {
            setParentJam(jam);
            setLayers((jam.layers || []).map(l => ({ ...l, fromRemix: true })));
            setTitle(jam.title ? `${jam.title} (remix)` : '');
            if (jam.theory) {
              if (jam.theory.keyName) setKeyName(jam.theory.keyName);
              if (jam.theory.scaleName) setScaleName(jam.theory.scaleName);
              if (jam.theory.tempo) setTempo(jam.theory.tempo);
              if (jam.theory.lead) setLead(jam.theory.lead);
            }
            if (engineRef.current && jam.theory) engineRef.current.setTheory(jam.theory);
            setShowPerform(true);
          }
        } catch (e) {
          // eslint-disable-next-line no-console
          console.warn('[JamStudio] could not load remix source:', e);
        }
      })();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [searchParams]);

  // Tear down on unmount only — the engine must survive re-renders.
  useEffect(() => () => {
    if (engineRef.current) {
      engineRef.current.dispose();
      engineRef.current = null;
    }
    if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
  }, []);

  // Keep the engine's layer set in sync with ours.
  useEffect(() => {
    if (engineRef.current) {
      engineRef.current.loadLayers(
        layers,
        parentJam ? parentJam.theory : undefined,
        song ? song.duration : undefined,
      );
      mutedLayers.forEach(id => engineRef.current.setLayerMuted(id, true));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [layers, song]);

  /* -------------------- Engine -------------------- */

  const ensureEngine = async () => {
    if (engineRef.current) return engineRef.current;
    setBusy(true);
    try {
      const eng = await createSketchEngine();
      eng.setOnTick(({ elapsed, ended }) => {
        setPosition(elapsed);
        if (ended) setIsPlaying(false);
      });
      eng.setLoop(loop);
      if (parentJam && parentJam.theory) eng.setTheory(parentJam.theory);
      eng.loadLayers(layers, parentJam ? parentJam.theory : undefined);
      engineRef.current = eng;
      setEngineReady(true);
      return eng;
    } finally {
      setBusy(false);
    }
  };

  /* -------------------- Composing -------------------- */

  const compose = async (overrides = {}) => {
    const eng = await ensureEngine();
    const settings = {
      style, keyName, scaleName, tempo, bars, seed, melodySeed, lead, arrangement,
      palette: ['melody', 'chords', 'bass', 'drums', 'arp', 'pad', 'fx'],
      ...overrides,
    };
    const composed = eng.generate(settings);
    setSong(composed);
    // Replace our own generated layers; keep performed takes and remix layers.
    const generated = sketchToLayers(composed);
    setLayers(prev => [...prev.filter(l => l.kind !== 'generated' || l.fromRemix), ...generated]);
    setPosition(0);
    return composed;
  };

  const newMelody = () => {
    const s = randomSeed();
    setMelodySeed(s);
    compose({ melodySeed: s });
  };

  /* ---- saved cuts: keep a take you liked and bring it back exactly ---- */

  const keepCut = () => {
    if (!song) return;
    saveCut(recipeFromSong(song));
    setCuts(listCuts());
  };

  const recallCut = (cut) => {
    setStyle(cut.style);
    setKeyName(cut.keyName);
    setScaleName(cut.scaleName);
    setTempo(cut.tempo);
    setBars(cut.bars);
    setArrangement(cut.arrangement || 'loop');
    setLead(cut.lead);
    setSeed(cut.seed);
    setMelodySeed(cut.melodySeed);
    // Pass the whole recipe as overrides — the state setters above haven't
    // landed yet, and a recall has to reproduce the cut exactly.
    compose(recipeFromSong(cut));
  };

  const forgetCut = (id) => {
    deleteCut(id);
    setCuts(listCuts());
  };

  const savedCurrent = !!song && cuts.some(c =>
    c.seed === song.seed && c.melodySeed === song.melodySeed &&
    c.style === song.style && c.tempo === song.tempo && c.keyName === song.keyName);

  const newArrangement = () => {
    const s = randomSeed();
    setSeed(s);
    compose({ seed: s });
  };

  const pickStyle = (key) => {
    const st = STYLES[key];
    const nextTempo = tempoLocked ? tempo : Math.round((st.tempo[0] + st.tempo[1]) / 2);
    setStyle(key);
    setScaleName(st.scale);
    setLead(st.lead);
    if (!tempoLocked) setTempo(nextTempo);
    if (song) compose({ style: key, scaleName: st.scale, tempo: nextTempo, lead: st.lead });
  };

  const pickLead = (key) => {
    setLead(key);
    if (engineRef.current) engineRef.current.setLead(key);
    if (song) setSong({ ...song, lead: key });
  };

  /* -------------------- Transport -------------------- */

  const playPause = async () => {
    const eng = await ensureEngine();
    if (eng.isPlaying()) {
      eng.stop();
      setIsPlaying(false);
    } else if (layers.length) {
      await eng.playLayers();
      setIsPlaying(true);
    }
  };

  const toggleLoop = () => {
    const next = !loop;
    setLoop(next);
    if (engineRef.current) engineRef.current.setLoop(next);
  };

  /* -------------------- Mixer -------------------- */

  const toggleTrack = (key) => {
    const muted = !trackMutes[key];
    setTrackMutes(prev => ({ ...prev, [key]: muted }));
    if (engineRef.current) engineRef.current.setGroupMuted(key, muted);
  };

  const setTrackVolume = (key, db) => {
    if (engineRef.current) engineRef.current.setGroupVolume(key, db);
  };

  /* -------------------- Take recording -------------------- */

  const startTake = async () => {
    const eng = await ensureEngine();
    eng.startCapture();
    if (layers.length && !eng.isPlaying()) {
      await eng.playLayers();
      setIsPlaying(true);
    }
    setIsTakeRecording(true);
  };

  const stopTake = async () => {
    const eng = engineRef.current;
    if (!eng) return;
    const events = eng.stopCapture();
    setIsTakeRecording(false);
    if (events.length) {
      takeCounter += 1;
      const instr = events[0].instr.replace('perf-', '');
      setLayers(prev => [...prev, {
        id: `take-${Date.now().toString(36)}-${takeCounter}`,
        kind: 'performed',
        label: `take ${takeCounter} · ${instr}`,
        instr: events[0].instr,
        createdBy: currentUser?.uid || 'local',
        events,
      }]);
    }
  };

  const takes = layers.filter(l => l.kind === 'performed');

  const toggleLayerMute = (id) => {
    setMutedLayers(prev => {
      const next = new Set(prev);
      const muted = !next.has(id);
      if (muted) next.add(id); else next.delete(id);
      if (engineRef.current) engineRef.current.setLayerMuted(id, muted);
      return next;
    });
  };
  const deleteLayer = (id) => setLayers(prev => prev.filter(l => l.id !== id));

  /* -------------------- Seed recording -------------------- */

  const startSeedRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        audio: { channelCount: 1, sampleRate: 44100, echoCancellation: true, noiseSuppression: true },
      });
      streamRef.current = stream;
      const rec = new MediaRecorder(stream);
      chunksRef.current = [];
      rec.ondataavailable = (e) => { if (e.data.size > 0) chunksRef.current.push(e.data); };
      rec.onstop = () => {
        const blob = new Blob(chunksRef.current, { type: 'audio/webm' });
        setRecordingUrl(URL.createObjectURL(blob));
        if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
      };
      mediaRecorderRef.current = rec;
      rec.start();
      setIsRecordingSeed(true);
    } catch (e) {
      // eslint-disable-next-line no-console
      console.warn('[JamStudio] seed record failed:', e);
    }
  };
  const stopSeedRecording = () => {
    if (mediaRecorderRef.current && isRecordingSeed) {
      mediaRecorderRef.current.stop();
      setIsRecordingSeed(false);
    }
  };

  /* -------------------- Publish -------------------- */

  const publish = async () => {
    if (!layers.length) return;
    if (!currentUser || currentUser.isAnonymous) {
      navigate(`/login?next=${encodeURIComponent('/sketch')}`);
      return;
    }
    setPublishState('saving');
    try {
      const eng = await ensureEngine();
      await publishJam({
        title: title.trim() || 'untitled jam',
        theory: eng.getTheory(),
        layers,
        user: currentUser,
        parentJam,
      });
      setPublishState('done');
      setTimeout(() => navigate('/jams'), 800);
    } catch (e) {
      setPublishState(e.message || 'Could not publish');
    }
  };

  /* ============================== Render ============================== */

  const duration = song
    ? song.duration
    : (engineReady && layers.length ? engineRef.current.jamDuration() : 1);
  const barSec = song ? song.barSec : (duration / 16);

  return (
    <div
      style={{
        minHeight: '100vh',
        background:
          'radial-gradient(circle at 20% 0%, rgba(127, 119, 221, 0.18), transparent 55%),' +
          'radial-gradient(circle at 80% 100%, rgba(93, 202, 165, 0.10), transparent 60%),' +
          '#0a0a12',
        color: '#e8e8f0',
        fontFamily: '-apple-system, BlinkMacSystemFont, system-ui, sans-serif',
        padding: '1rem',
      }}
    >
      <div style={{ maxWidth: 640, margin: '0 auto' }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <button onClick={() => navigate(-1)} style={linkButtonStyle}>
            <ChevronLeft size={16} /> Back
          </button>
          <button onClick={() => navigate('/jams')} style={outlineButtonStyle}>
            <ListMusic size={14} /> Jam feed
          </button>
        </div>

        <h1 style={{ fontSize: '1.4rem', fontWeight: 600, margin: '0.5rem 0 0.25rem' }}>
          Jam Studio
        </h1>
        <p style={{ color: '#8b8b9a', fontSize: '0.9rem', margin: '0 0 1rem' }}>
          Pick a vibe, write a melody, then keep what you like and reroll the rest.
        </p>

        {parentJam && (
          <div style={remixBannerStyle}>
            <GitBranch size={14} />
            Remixing “{parentJam.title}” by {parentJam.createdBy?.name}
          </div>
        )}

        {/* ---------- VIBE ---------- */}
        <Section title="Vibe">
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(140px, 1fr))', gap: 6 }}>
            {STYLE_KEYS.map(key => {
              const st = STYLES[key];
              const active = style === key;
              return (
                <button
                  key={key}
                  type="button"
                  onClick={() => pickStyle(key)}
                  style={{
                    textAlign: 'left', padding: '10px 12px', borderRadius: 10, cursor: 'pointer',
                    background: active ? '#1a1626' : '#15151e',
                    border: '0.5px solid ' + (active ? '#3C3489' : '#25252e'),
                    color: active ? '#AFA9EC' : '#8b8b9a',
                    fontFamily: 'inherit', transition: 'all 0.15s',
                  }}
                >
                  <div style={{ fontSize: 13, fontWeight: 500 }}>{st.label}</div>
                  <div style={{ fontSize: 10, color: '#5b5b6a', marginTop: 2 }}>{st.blurb}</div>
                </button>
              );
            })}
          </div>
        </Section>

        {/* ---------- KEY / TEMPO / LENGTH ---------- */}
        <Section title="Key & feel">
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, alignItems: 'flex-end' }}>
            <Field label="Key">
              <Select
                value={keyName}
                options={KEYS.map(k => ({ value: k, label: k }))}
                onChange={v => { setKeyName(v); if (song) compose({ keyName: v }); }}
              />
            </Field>
            <Field label="Mode">
              <Select
                value={scaleName}
                options={SCALE_OPTIONS.map(s => ({ value: s, label: SCALE_LABELS[s] }))}
                onChange={v => { setScaleName(v); if (song) compose({ scaleName: v }); }}
              />
            </Field>
            <Field label="Length">
              <Select
                value={arrangement === 'radio' ? 'radio' : `loop:${bars}`}
                options={LENGTHS.map(l => ({ value: l.value, label: l.label }))}
                onChange={v => {
                  const opt = LENGTHS.find(l => l.value === v) || LENGTHS[1];
                  setArrangement(opt.arrangement);
                  setBars(opt.bars);
                  if (song) compose({ arrangement: opt.arrangement, bars: opt.bars });
                }}
              />
            </Field>
          </div>

          <div style={{ marginTop: 12 }}>
            <div style={sliderLabelStyle}>
              <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
                Tempo
                <button
                  type="button"
                  onClick={() => setTempoLocked(v => !v)}
                  title={tempoLocked ? 'Tempo locked — switching vibe keeps it' : 'Tempo follows the vibe you pick'}
                  style={{
                    background: 'transparent', border: 'none', cursor: 'pointer', padding: 0,
                    color: tempoLocked ? '#5DCAA5' : '#4b4b5a', display: 'inline-flex',
                  }}
                >
                  {tempoLocked ? <Lock size={12} /> : <Unlock size={12} />}
                </button>
              </span>
              <span style={{ color: '#AFA9EC', fontVariantNumeric: 'tabular-nums' }}>{tempo} bpm</span>
            </div>
            <input
              type="range" min={TEMPO_MIN} max={TEMPO_MAX} value={tempo}
              onChange={e => setTempo(Number(e.target.value))}
              onMouseUp={() => song && compose({ tempo })}
              onTouchEnd={() => song && compose({ tempo })}
              onKeyUp={() => song && compose({ tempo })}
              style={{ width: '100%', accentColor: '#7F77DD' }}
            />
            <div style={{ fontSize: 10, color: '#5b5b6a', marginTop: 2 }}>
              {STYLES[style].label} sits naturally at {STYLES[style].tempo[0]}–{STYLES[style].tempo[1]}
              {tempoLocked && (tempo < STYLES[style].tempo[0] || tempo > STYLES[style].tempo[1])
                ? ' · you’re running it outside that on purpose'
                : ''}
            </div>
          </div>

          <div style={{ marginTop: 10 }}>
            <div style={{ ...sliderLabelStyle, marginBottom: 6 }}><span>Lead sound</span></div>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
              {LEAD_OPTIONS.map(opt => (
                <Chip key={opt.key} active={lead === opt.key} onClick={() => pickLead(opt.key)}>
                  {opt.label}
                </Chip>
              ))}
            </div>
          </div>
        </Section>

        {/* ---------- MELODY ---------- */}
        <Section title="Melody">
          <MelodyRoll
            melody={song ? song.melody : []}
            chords={song ? song.chords : []}
            sections={song ? song.form : []}
            duration={duration}
            barSec={barSec}
            position={position}
          />

          {song && (
            <div style={metaRowStyle}>
              <span>{song.keyName} {SCALE_LABELS[song.scaleName]}</span>
              <span>{song.tempo} bpm</span>
              <span>{song.bars} bars</span>
              <span>{song.melody.length} notes</span>
            </div>
          )}

          <button
            onClick={newMelody}
            disabled={busy}
            style={{ ...buttonStyle, width: '100%', background: '#534AB7', color: 'white', opacity: busy ? 0.6 : 1, marginTop: 10 }}
          >
            <Sparkles size={16} style={{ marginRight: 6 }} />
            {song ? 'Write a new melody' : 'Write a melody'}
          </button>

          {song && (
            <div style={{ display: 'flex', gap: 6, marginTop: 6 }}>
              <button
                onClick={newArrangement}
                disabled={busy}
                style={{
                  ...buttonStyle, flex: 1,
                  background: '#15151e', color: '#AFA9EC', border: '0.5px solid #3C3489',
                }}
              >
                <Shuffle size={15} style={{ marginRight: 6 }} />
                New arrangement
              </button>
              <button
                onClick={keepCut}
                disabled={savedCurrent}
                title={savedCurrent ? 'Already saved' : 'Save this cut so you can bring it back'}
                style={{
                  ...buttonStyle, flex: 1,
                  background: savedCurrent ? '#0d1f1a' : '#15151e',
                  color: savedCurrent ? '#5DCAA5' : '#8b8b9a',
                  border: '0.5px solid ' + (savedCurrent ? '#1D9E75' : '#25252e'),
                  cursor: savedCurrent ? 'default' : 'pointer',
                }}
              >
                <Star size={15} fill={savedCurrent ? 'currentColor' : 'none'} style={{ marginRight: 6 }} />
                {savedCurrent ? 'Kept' : 'Keep this cut'}
              </button>
            </div>
          )}

          {cuts.length > 0 && (
            <div style={{ marginTop: 10 }}>
              <div style={{ fontSize: 10, color: '#6b6b7a', letterSpacing: 1.5, marginBottom: 6 }}>
                RECALL
              </div>
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
                {cuts.map(cut => {
                  const active = !!song && cut.seed === song.seed && cut.melodySeed === song.melodySeed;
                  return (
                    <span
                      key={cut.id}
                      style={{
                        display: 'inline-flex', alignItems: 'center', gap: 6,
                        fontSize: 11, padding: '5px 6px 5px 10px', borderRadius: 14,
                        background: active ? '#0d1f1a' : '#15151e',
                        border: '0.5px solid ' + (active ? '#1D9E75' : '#25252e'),
                        color: active ? '#5DCAA5' : '#8b8b9a',
                      }}
                    >
                      <button
                        type="button"
                        onClick={() => recallCut(cut)}
                        title="Recall this cut exactly"
                        style={{
                          background: 'transparent', border: 'none', padding: 0,
                          color: 'inherit', cursor: 'pointer', fontFamily: 'inherit', fontSize: 11,
                          fontVariantNumeric: 'tabular-nums',
                        }}
                      >
                        {cut.name || describeCut(cut, STYLES[cut.style]?.label)}
                      </button>
                      <button
                        type="button"
                        onClick={() => forgetCut(cut.id)}
                        title="Forget this cut"
                        style={{
                          background: 'transparent', border: 'none', padding: 0,
                          color: '#4b4b5a', cursor: 'pointer', display: 'inline-flex',
                        }}
                      >
                        <X size={11} />
                      </button>
                    </span>
                  );
                })}
              </div>
            </div>
          )}
        </Section>

        {/* ---------- TRANSPORT + MIXER ---------- */}
        {layers.length > 0 && (
          <Section title="Mix">
            <div style={transportStyle}>
              <IconButton onClick={playPause} title={isPlaying ? 'Pause' : 'Play'} prominent>
                {isPlaying ? <Pause size={18} /> : <Play size={18} />}
              </IconButton>
              <div style={{ flex: 1 }}>
                <ProgressBar pct={duration ? Math.min(1, position / duration) : 0} />
              </div>
              <span style={{ fontSize: 11, color: '#6b6b7a', fontVariantNumeric: 'tabular-nums', minWidth: 62, textAlign: 'right' }}>
                {fmt(position)} / {fmt(duration)}
              </span>
              <button
                onClick={toggleLoop}
                title={loop ? 'Looping' : 'Play once'}
                style={{
                  background: 'transparent', border: 'none', cursor: 'pointer', padding: 4,
                  color: loop ? '#5DCAA5' : '#4b4b5a',
                }}
              >
                <Repeat size={16} />
              </button>
            </div>

            <div style={panelStyle}>
              {MIXER_TRACKS.map(track => {
                const present = layers.some(l => l.instr === track.key);
                if (!present) return null;
                const muted = !!trackMutes[track.key];
                return (
                  <div key={track.key} style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 8 }}>
                    <button
                      onClick={() => toggleTrack(track.key)}
                      title={muted ? 'Unmute' : 'Mute'}
                      style={{
                        background: 'transparent', border: 'none', cursor: 'pointer', padding: 0,
                        color: muted ? '#4b4b5a' : '#AFA9EC', display: 'inline-flex',
                      }}
                    >
                      {muted ? <VolumeX size={14} /> : <Volume2 size={14} />}
                    </button>
                    <span style={{ fontSize: 11, width: 52, color: muted ? '#4b4b5a' : '#8b8b9a' }}>
                      {track.label}
                    </span>
                    <input
                      type="range" min={-30} max={6} defaultValue={0}
                      onChange={e => setTrackVolume(track.key, Number(e.target.value))}
                      style={{ flex: 1, accentColor: muted ? '#4b4b5a' : '#7F77DD' }}
                    />
                  </div>
                );
              })}
            </div>
          </Section>
        )}

        {/* ---------- PLAY OVER IT ---------- */}
        <Section title="Play over it">
          <Disclosure open={showPerform} onToggle={() => setShowPerform(v => !v)} label="Instrument & takes">
            <JamPad
              engine={engineReady ? engineRef.current : null}
              disabled={!engineReady}
              recording={isTakeRecording}
              refreshKey={layers.length}
            />
            {!engineReady && (
              <button
                onClick={ensureEngine}
                style={{ ...buttonStyle, width: '100%', marginTop: 8, background: '#1a1626', color: '#AFA9EC', border: '1px solid #3C3489' }}
              >
                Start the instrument
              </button>
            )}
            {engineReady && (
              <button
                onClick={isTakeRecording ? stopTake : startTake}
                style={{
                  ...buttonStyle, width: '100%', marginTop: 8,
                  background: isTakeRecording ? '#E24B4A' : '#1a0e14',
                  color: isTakeRecording ? 'white' : '#F0999A',
                  border: '2px solid #E24B4A',
                }}
              >
                <Circle size={14} fill="currentColor" style={{ marginRight: 6 }} />
                {isTakeRecording ? 'Stop take' : 'Record a take'}
              </button>
            )}

            {takes.length > 0 && (
              <div style={{ ...panelStyle, marginTop: 8 }}>
                {takes.map(l => {
                  const muted = mutedLayers.has(l.id);
                  return (
                    <div key={l.id} style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6 }}>
                      <button
                        onClick={() => toggleLayerMute(l.id)}
                        style={{
                          fontSize: 11, flex: 1, textAlign: 'left', background: 'transparent',
                          border: 'none', cursor: 'pointer', padding: 0,
                          color: muted ? '#4b4b5a' : '#5DCAA5',
                          textDecoration: muted ? 'line-through' : 'none',
                        }}
                      >
                        {l.label}
                      </button>
                      <button
                        onClick={() => deleteLayer(l.id)}
                        title="Delete take"
                        style={{ background: 'transparent', border: 'none', color: '#4b4b5a', cursor: 'pointer', padding: 2 }}
                      >
                        <Trash2 size={13} />
                      </button>
                    </div>
                  );
                })}
              </div>
            )}

            {/* Hum seed — a reference to write against, kept out of the way. */}
            <div style={{ marginTop: 12 }}>
              {!recordingUrl && !isRecordingSeed && (
                <BigButton onClick={startSeedRecording} icon={<Mic size={18} />}>
                  Record a hum to write against
                </BigButton>
              )}
              {isRecordingSeed && (
                <BigButton onClick={stopSeedRecording} icon={<Square size={18} />} variant="recording">
                  Stop recording
                </BigButton>
              )}
              {recordingUrl && (
                <div>
                  <audio src={recordingUrl} controls style={{ width: '100%' }} />
                  <button
                    onClick={() => {
                      setRecordingUrl(null);
                      try { sessionStorage.removeItem(SMARTMIC_BLOB_KEY); } catch (_) { /* noop */ }
                    }}
                    style={{ ...outlineButtonStyle, marginTop: 8 }}
                  >
                    Clear hum
                  </button>
                </div>
              )}
            </div>
          </Disclosure>
        </Section>

        {/* ---------- PUBLISH ---------- */}
        {layers.length > 0 && (
          <Section title="Share">
            <input
              value={title}
              onChange={e => setTitle(e.target.value)}
              placeholder="Name your jam…"
              style={inputStyle}
            />
            <button
              onClick={publish}
              disabled={publishState === 'saving'}
              style={{
                ...buttonStyle, width: '100%',
                background: '#0d1f1a', color: '#5DCAA5', border: '1px solid #1D9E75',
                opacity: publishState === 'saving' ? 0.6 : 1,
              }}
            >
              <Share2 size={16} style={{ marginRight: 6 }} />
              {publishState === 'saving' ? 'Publishing…'
                : publishState === 'done' ? 'Published!'
                  : parentJam ? 'Publish remix' : 'Publish to jam feed'}
            </button>
            {publishState && publishState !== 'saving' && publishState !== 'done' && (
              <div style={{ marginTop: 8, color: '#fca5a5', fontSize: 12 }}>{publishState}</div>
            )}
          </Section>
        )}
      </div>
    </div>
  );
};

/* ============================== Sub-pieces ============================== */

const fmt = (s) => {
  const total = Math.max(0, Math.round(s || 0));
  return `${Math.floor(total / 60)}:${String(total % 60).padStart(2, '0')}`;
};

const Section = ({ title, children }) => (
  <div style={{ marginTop: 18 }}>
    <div style={{ fontSize: 10, color: '#6b6b7a', letterSpacing: 2, margin: '0 0 8px', textTransform: 'uppercase' }}>
      {title}
    </div>
    {children}
  </div>
);

const Disclosure = ({ open, onToggle, label, children }) => (
  <div>
    <button
      type="button"
      onClick={onToggle}
      style={{
        width: '100%', display: 'flex', alignItems: 'center', gap: 6,
        background: '#15151e', border: '0.5px solid #25252e', borderRadius: 10,
        color: '#8b8b9a', padding: '10px 12px', cursor: 'pointer',
        fontSize: 12, fontFamily: 'inherit',
      }}
    >
      {open ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
      {label}
    </button>
    {open && <div style={{ marginTop: 8 }}>{children}</div>}
  </div>
);

const Field = ({ label, children }) => (
  <label style={{ display: 'flex', flexDirection: 'column', gap: 4, flex: '1 1 90px' }}>
    <span style={{ fontSize: 11, color: '#8b8b9a' }}>{label}</span>
    {children}
  </label>
);

const Select = ({ value, options, onChange }) => (
  <select
    value={value}
    onChange={e => onChange(e.target.value)}
    style={{
      width: '100%', padding: '8px 10px', borderRadius: 8,
      background: '#15151e', border: '0.5px solid #25252e', color: '#e8e8f0',
      fontSize: 13, fontFamily: 'inherit', cursor: 'pointer',
    }}
  >
    {options.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}
  </select>
);

const Chip = ({ active, children, onClick }) => (
  <button
    type="button"
    onClick={onClick}
    style={{
      fontSize: 12, padding: '6px 12px', borderRadius: 16,
      background: active ? '#1a1626' : '#15151e',
      color: active ? '#AFA9EC' : '#8b8b9a',
      border: '0.5px solid ' + (active ? '#3C3489' : '#25252e'),
      cursor: 'pointer', transition: 'all 0.15s', fontFamily: 'inherit',
    }}
  >
    {children}
  </button>
);

const BigButton = ({ children, onClick, icon, variant }) => (
  <button
    onClick={onClick}
    style={{
      width: '100%', padding: '14px',
      background: variant === 'recording' ? '#E24B4A' : '#1a0e14',
      color: variant === 'recording' ? 'white' : '#F0999A',
      border: '2px solid #E24B4A', borderRadius: 12, cursor: 'pointer',
      display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
      gap: 8, fontSize: 14, fontFamily: 'inherit',
    }}
  >
    {icon} {children}
  </button>
);

const IconButton = ({ children, onClick, title, prominent }) => (
  <button
    onClick={onClick}
    title={title}
    style={{
      background: prominent ? '#534AB7' : 'transparent',
      color: prominent ? 'white' : '#AFA9EC',
      border: prominent ? 'none' : '1px solid #3C3489',
      width: prominent ? 40 : 32, height: prominent ? 40 : 32,
      borderRadius: '50%', cursor: 'pointer', flexShrink: 0,
      display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
    }}
  >
    {children}
  </button>
);

const ProgressBar = ({ pct }) => (
  <div style={{ height: 3, background: '#0a0a12', borderRadius: 2, overflow: 'hidden' }}>
    <div
      style={{
        width: `${Math.round(pct * 100)}%`, height: '100%',
        background: 'linear-gradient(90deg, #7F77DD, #5DCAA5)',
        transition: 'width 0.1s linear',
      }}
    />
  </div>
);

const buttonStyle = {
  padding: '14px', borderRadius: 12, fontSize: 14, fontWeight: 500,
  cursor: 'pointer', fontFamily: 'inherit', border: 'none',
  display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
};

const linkButtonStyle = {
  background: 'transparent', border: 'none', color: '#8b8b9a',
  display: 'inline-flex', alignItems: 'center', gap: 4,
  padding: '0.5rem 0', cursor: 'pointer', fontSize: '0.85rem', fontFamily: 'inherit',
};

const outlineButtonStyle = {
  background: 'transparent', border: '1px solid #25252e', color: '#8b8b9a',
  display: 'inline-flex', alignItems: 'center', gap: 6,
  padding: '6px 12px', borderRadius: 8, cursor: 'pointer', fontSize: 12, fontFamily: 'inherit',
};

const panelStyle = {
  background: '#15151e', border: '0.5px solid #25252e', borderRadius: 12, padding: 12,
};

const transportStyle = {
  display: 'flex', alignItems: 'center', gap: 10,
  padding: '10px 14px', background: '#15151e',
  border: '0.5px solid #25252e', borderRadius: 12, marginBottom: 8,
};

const metaRowStyle = {
  display: 'flex', flexWrap: 'wrap', gap: 12, marginTop: 8,
  fontSize: 11, color: '#6b6b7a', fontVariantNumeric: 'tabular-nums',
};

const sliderLabelStyle = {
  display: 'flex', justifyContent: 'space-between',
  fontSize: 11, color: '#8b8b9a', marginBottom: 4,
};

const inputStyle = {
  width: '100%', boxSizing: 'border-box', padding: '10px 12px',
  background: '#15151e', border: '0.5px solid #25252e', borderRadius: 10,
  color: '#e8e8f0', fontSize: 14, marginBottom: 8, fontFamily: 'inherit',
};

const remixBannerStyle = {
  display: 'flex', alignItems: 'center', gap: 8,
  padding: '8px 12px', marginBottom: 8,
  background: '#0d1f1a', border: '1px solid #1D9E75', borderRadius: 10,
  fontSize: 12, color: '#5DCAA5',
};

export default SketchPage;
