import { getCategoryById } from '../../utils/categories'

export default function Badge({ category, size = 'sm' }) {
  const cat = getCategoryById(category)
  const Icon = cat.icon
  const sizeClasses = size === 'sm' ? 'text-xs px-2 py-0.5 gap-1' : 'text-sm px-3 py-1 gap-1.5'

  return (
    <span className={`inline-flex items-center rounded-full font-medium ${cat.color}/15 ${cat.textColor} ${sizeClasses}`}>
      <Icon size={size === 'sm' ? 12 : 14} />
      {cat.label}
    </span>
  )
}
