// src/components/posts/CreatePostPage.jsx
import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { getFirestore, collection, addDoc, serverTimestamp } from 'firebase/firestore';
import { getStorage, ref as storageRef, uploadBytes, getDownloadURL } from 'firebase/storage';
import { getDatabase, ref as dbRef, push as dbPush } from 'firebase/database';
import { AlertCircle, ArrowLeft, Send, Map, Link as LinkIcon, Image, Camera, MapPin } from 'lucide-react';
import './CreatePostPage.css';

const CreatePostPage = () => {
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [topic, setTopic] = useState('');
  const [location, setLocation] = useState('');
  const [url, setUrl] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState(null);
  
  // Location detection states
  const [isDetectingLocation, setIsDetectingLocation] = useState(false);
  const [locationError, setLocationError] = useState(null);
  const [coordinates, setCoordinates] = useState(null);
  
  // Photo upload states
  const [photo, setPhoto] = useState(null);
  const [photoPreview, setPhotoPreview] = useState(null);
  const [isUploading, setIsUploading] = useState(false);
  const fileInputRef = useRef(null);
  const cameraInputRef = useRef(null);
  
  const navigate = useNavigate();
  const { currentUser } = useAuth();
  
  // Redirect if not logged in or anonymous
  useEffect(() => {
    if (!currentUser || currentUser.isAnonymous) {
      navigate('/login', { state: { from: '/create-post' } });
    }
  }, [currentUser, navigate]);
  
  // Handle file selection
  const handleFileChange = (e) => {
    const selectedFile = e.target.files[0];
    if (selectedFile) {
      setPhoto(selectedFile);
      
      // Create preview
      const reader = new FileReader();
      reader.onloadend = () => {
        setPhotoPreview(reader.result);
      };
      reader.readAsDataURL(selectedFile);
    }
  };
  
  // Handle camera capture
  const handleCameraCapture = (e) => {
    const capturedFile = e.target.files[0];
    if (capturedFile) {
      setPhoto(capturedFile);
      
      // Create preview
      const reader = new FileReader();
      reader.onloadend = () => {
        setPhotoPreview(reader.result);
      };
      reader.readAsDataURL(capturedFile);
    }
  };
  
  // Open file picker
  const handleUploadClick = () => {
    fileInputRef.current.click();
  };
  
  // Open camera
  const handleCameraClick = () => {
    cameraInputRef.current.click();
  };
  
  // Remove photo
  const handleRemovePhoto = () => {
    setPhoto(null);
    setPhotoPreview(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
    if (cameraInputRef.current) {
      cameraInputRef.current.value = '';
    }
  };
  
  // Detect user's location
  const handleDetectLocation = () => {
    setIsDetectingLocation(true);
    setLocationError(null);
    
    if (!navigator.geolocation) {
      setLocationError('Geolocation is not supported by your browser');
      setIsDetectingLocation(false);
      return;
    }
    
    navigator.geolocation.getCurrentPosition(
      async (position) => {
        try {
          const { latitude, longitude } = position.coords;
          setCoordinates({ latitude, longitude });
          
          // Try to get a readable address using reverse geocoding
          try {
            const response = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}&zoom=18&addressdetails=1`);
            const data = await response.json();
            
            if (data && data.display_name) {
              // Create a simplified location string
              let locationString = '';
              
              // Prioritize city, state, country format if available
              if (data.address) {
                const address = data.address;
                const parts = [];
                
                if (address.city || address.town || address.village) {
                  parts.push(address.city || address.town || address.village);
                }
                
                if (address.state || address.county) {
                  parts.push(address.state || address.county);
                }
                
                if (address.country) {
                  parts.push(address.country);
                }
                
                locationString = parts.join(', ');
              }
              
              // Fallback to display_name if we couldn't parse it nicely
              if (!locationString) {
                locationString = data.display_name;
              }
              
              setLocation(locationString);
            } else {
              // Just use coordinates if we can't get an address
              setLocation(`${latitude.toFixed(6)}, ${longitude.toFixed(6)}`);
            }
          } catch (error) {
            // If geocoding fails, just use the coordinates
            console.error('Geocoding error:', error);
            setLocation(`${latitude.toFixed(6)}, ${longitude.toFixed(6)}`);
          }
        } catch (error) {
          console.error('Location error:', error);
          setLocationError('Failed to process location data');
        } finally {
          setIsDetectingLocation(false);
        }
      },
      (error) => {
        console.error('Geolocation error:', error);
        switch(error.code) {
          case error.PERMISSION_DENIED:
            setLocationError('Location permission denied');
            break;
          case error.POSITION_UNAVAILABLE:
            setLocationError('Location information unavailable');
            break;
          case error.TIMEOUT:
            setLocationError('Location request timed out');
            break;
          default:
            setLocationError('An unknown error occurred');
        }
        setIsDetectingLocation(false);
      },
      { 
        enableHighAccuracy: true,
        timeout: 10000,
        maximumAge: 0
      }
    );
  };
  
  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!title.trim()) {
      setError('Post title is required');
      return;
    }
    
    if (!content.trim()) {
      setError('Post content is required');
      return;
    }
    
    try {
      setIsSubmitting(true);
      setError(null);
      
      let photoURL = null;
      let thumbnailURL = null;
      
      // Upload photo if one is selected
      if (photo) {
        setIsUploading(true);
        const storage = getStorage();
        const timestamp = Date.now();
        
        // Use the proper path according to storage rules
        const filename = `posts/${currentUser.uid}/${timestamp}_${photo.name.replace(/[^a-zA-Z0-9.-]/g, '_')}`;
        const fileRef = storageRef(storage, filename);
        
        console.log("Uploading photo to:", filename);
        
        try {
          // Upload the file
          const uploadResult = await uploadBytes(fileRef, photo);
          console.log("Upload complete:", uploadResult);
          
          // Get the URL
          photoURL = await getDownloadURL(fileRef);
          console.log("Photo URL:", photoURL);
          
          // For now, use the same URL for thumbnail
          // In a production app, you'd generate an actual thumbnail
          thumbnailURL = photoURL;
        } catch (uploadError) {
          console.error("Error uploading photo:", uploadError);
          setError(`Failed to upload photo: ${uploadError.message}`);
          setIsSubmitting(false);
          setIsUploading(false);
          return;
        }
        
        setIsUploading(false);
      }
      
      // Get Firestore instance
      const db = getFirestore();
      
      // Get current timestamp
      const timestamp = Date.now();
      
      // Create post data structure for Firestore
      const postData = {
        title: title.trim(),
        content: content.trim(),
        topic: topic.trim(),
        authorId: currentUser.uid,
        authorName: currentUser.displayName || 'Anonymous',
        authorPhotoURL: currentUser.photoURL || null,
        createdAt: serverTimestamp(), // Use server timestamp for Firestore
        updatedAt: serverTimestamp(),
        likes: 0,
        views: 0,
        commentCount: 0,
        status: 'published',
        hasPhoto: !!photoURL // Boolean flag to indicate if post has a photo
      };
      
      // Add optional fields if provided
      if (location.trim()) {
        postData.location = location.trim();
        
        // If we have coordinates, add them too
        if (coordinates) {
          postData.coordinates = coordinates;
        }
      }
      
      if (url.trim()) {
        postData.url = url.trim();
      }
      
      if (photoURL) {
        postData.photoURL = photoURL;
        postData.thumbnailURL = thumbnailURL;
      }
      
      console.log("Creating post with data:", postData);
      
      // Save the post to Firestore
      const postsCollection = collection(db, 'posts');
      const newPostRef = await addDoc(postsCollection, postData);
      
      console.log("Post created with ID:", newPostRef.id);
      
      // Create activity for the RTDB timeline
      const rtdb = getDatabase();
      const activitiesRef = dbRef(rtdb, 'activities');
      
      const activityData = {
        type: 'post',
        userId: currentUser.uid,
        userName: currentUser.displayName || 'Anonymous',
        userAvatar: currentUser.photoURL || null,
        postId: newPostRef.id,
        postTitle: title.trim(),
        topicTitle: topic.trim(),
        contentPreview: content.length > 100 ? content.substring(0, 100) + '...' : content,
        timestamp: timestamp,
        hasPhoto: !!photoURL
      };
      
      // Add photo URL to activity if available
      if (photoURL) {
        activityData.photoURL = thumbnailURL;
      }
      
      // Add location if available
      if (location.trim()) {
        activityData.location = location.trim();
      }
      
      console.log("Creating activity with data:", activityData);
      
      // Create the activity in RTDB
      await dbPush(activitiesRef, activityData);
      
      console.log("Activity created successfully");
      
      // Navigate to the new post
      navigate(`/post/${newPostRef.id}`);
      
    } catch (error) {
      console.error('Error creating post:', error);
      setError(`Failed to create post: ${error.message}`);
      setIsSubmitting(false);
    }
  };
  
  const handleCancel = () => {
    navigate(-1); // Go back to previous page
  };
  
  if (!currentUser || currentUser.isAnonymous) {
    return <div className="loading">Redirecting to login...</div>;
  }
  
  return (
    <div className="create-post-page">
      <div className="create-post-container">
        <div className="page-header">
          <button 
            onClick={handleCancel}
            className="back-button"
            title="Go back"
          >
            <ArrowLeft size={20} />
          </button>
          <h1 className="page-title">Create New Post</h1>
        </div>
        
        {error && (
          <div className="error-message">
            <AlertCircle size={18} className="error-icon" />
            {error}
          </div>
        )}
        
        <form onSubmit={handleSubmit} className="create-post-form">
          <div className="form-group">
            <label htmlFor="title">Title*</label>
            <input
              type="text"
              id="title"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="Enter post title"
              required
              disabled={isSubmitting}
              className="form-input"
            />
          </div>
          
          <div className="form-group">
            <label htmlFor="topic">Topic*</label>
            <input
              type="text"
              id="topic"
              value={topic}
              onChange={(e) => setTopic(e.target.value)}
              placeholder="Enter a topic for your post"
              required
              disabled={isSubmitting}
              className="form-input"
            />
          </div>
          
          <div className="form-group">
            <label htmlFor="content">Content*</label>
            <textarea
              id="content"
              value={content}
              onChange={(e) => setContent(e.target.value)}
              placeholder="Write your post content here"
              rows={10}
              required
              disabled={isSubmitting}
              className="form-textarea"
            />
          </div>
          
          {/* Optional fields */}
          <div className="optional-fields">
            <h3>Optional Information</h3>
            
            <div className="form-group">
              <label htmlFor="location" className="flex items-center">
                <Map size={16} className="mr-2" />
                Location
              </label>
              
              <div className="location-input-group">
                <input
                  type="text"
                  id="location"
                  value={location}
                  onChange={(e) => setLocation(e.target.value)}
                  placeholder="Add location (optional)"
                  disabled={isSubmitting || isDetectingLocation}
                  className="form-input"
                />
                
                <button
                  type="button"
                  onClick={handleDetectLocation}
                  disabled={isSubmitting || isDetectingLocation}
                  className="detect-location-button"
                  title="Detect my location"
                >
                  <MapPin size={16} />
                  {isDetectingLocation ? 'Detecting...' : 'Detect'}
                </button>
              </div>
              
              {locationError && (
                <p className="location-error">
                  {locationError}
                </p>
              )}
            </div>
            
            <div className="form-group">
              <label htmlFor="url" className="flex items-center">
                <LinkIcon size={16} className="mr-2" />
                Related URL
              </label>
              <input
                type="text"
                id="url"
                value={url}
                onChange={(e) => setUrl(e.target.value)}
                placeholder="Add a related URL (optional)"
                disabled={isSubmitting}
                className="form-input"
              />
            </div>
            
            {/* Photo upload section */}
            <div className="form-group">
              <label className="flex items-center">
                <Image size={16} className="mr-2" />
                Photo
              </label>
              
              <div className="photo-upload-section">
                {photoPreview ? (
                  <div className="photo-preview-container">
                    <img 
                      src={photoPreview} 
                      alt="Preview" 
                      className="photo-preview" 
                    />
                    <button 
                      type="button" 
                      onClick={handleRemovePhoto}
                      className="remove-photo-button"
                    >
                      Remove
                    </button>
                  </div>
                ) : (
                  <div className="upload-buttons">
                    <button 
                      type="button" 
                      onClick={handleUploadClick}
                      className="photo-button"
                      disabled={isSubmitting}
                    >
                      <Image size={16} className="mr-2" />
                      Upload Photo
                    </button>
                    
                    <button 
                      type="button"
                      onClick={handleCameraClick}
                      className="photo-button"
                      disabled={isSubmitting}
                    >
                      <Camera size={16} className="mr-2" />
                      Take Photo
                    </button>
                  </div>
                )}
                
                {/* Hidden file inputs */}
                <input 
                  type="file"
                  ref={fileInputRef}
                  onChange={handleFileChange}
                  accept="image/*"
                  className="hidden-input"
                />
                
                <input 
                  type="file"
                  ref={cameraInputRef}
                  onChange={handleCameraCapture}
                  accept="image/*"
                  capture="environment"
                  className="hidden-input"
                />
              </div>
            </div>
          </div>
          
          <div className="form-actions">
            <button 
              type="button"
              onClick={handleCancel}
              className="cancel-button"
              disabled={isSubmitting || isUploading || isDetectingLocation}
            >
              Cancel
            </button>
            <button
              type="submit"
              className="submit-button"
              disabled={isSubmitting || isUploading || isDetectingLocation || !title.trim() || !content.trim() || !topic.trim()}
            >
              {isSubmitting || isUploading || isDetectingLocation ? (
                isUploading ? 'Uploading...' : isDetectingLocation ? 'Detecting Location...' : 'Creating...'
              ) : (
                <span className="button-content">
                  <Send size={16} className="button-icon" />
                  Create Post
                </span>
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default CreatePostPage;