// src/components/premium/SubscriptionManager.jsx
import React, { useState } from 'react';
import { useSubscription } from '../../hooks/useSubscription';
import { Link } from 'react-router-dom';
import { Shield, Calendar, CreditCard, AlertCircle, Crown, ExternalLink } from 'lucide-react';
import './SubscriptionManager.css';

const SubscriptionManager = () => {
  const { 
    subscription, 
    loading, 
    isActive, 
    formattedExpiryDate, 
    daysRemaining, 
    refreshSubscription 
  } = useSubscription();
  const [refreshing, setRefreshing] = useState(false);

  const handleRefresh = async () => {
    setRefreshing(true);
    await refreshSubscription();
    setTimeout(() => setRefreshing(false), 1000);
  };

  if (loading) {
    return (
      <div className="subscription-manager loading">
        <div className="loading-spinner"></div>
        <p>Loading subscription details...</p>
      </div>
    );
  }

  if (subscription.error) {
    return (
      <div className="subscription-manager error">
        <AlertCircle className="error-icon" />
        <h3>Error Loading Subscription</h3>
        <p>{subscription.error}</p>
        <button onClick={handleRefresh} className="btn btn-secondary">
          Retry
        </button>
      </div>
    );
  }

  // Active subscription view
  if (isActive) {
    return (
      <div className="subscription-manager active">
        <div className="subscription-header">
          <div className="subscription-icon">
            <Shield className="shield-icon active" />
            <Crown className="crown-overlay" />
          </div>
          <div className="subscription-info">
            <h2>Premium Membership</h2>
            <div className="status-badge active">✓ Active</div>
          </div>
        </div>

        <div className="subscription-details">
          <div className="detail-card">
            <div className="detail-header">
              <CreditCard className="detail-icon" />
              <h3>Plan Details</h3>
            </div>
            <div className="detail-content">
              <div className="detail-row">
                <span className="label">Plan:</span>
                <span className="value">{subscription.plan || 'Premium'}</span>
              </div>
              {formattedExpiryDate && (
                <div className="detail-row">
                  <span className="label">Expires:</span>
                  <span className="value">{formattedExpiryDate}</span>
                </div>
              )}
              {daysRemaining !== null && (
                <div className="detail-row">
                  <span className="label">Days Remaining:</span>
                  <span className={`value ${daysRemaining < 7 ? 'warning' : ''}`}>
                    {daysRemaining} days
                  </span>
                </div>
              )}
            </div>
          </div>

          {subscription.transactions && subscription.transactions.length > 0 && (
            <div className="detail-card">
              <div className="detail-header">
                <Calendar className="detail-icon" />
                <h3>Recent Transactions</h3>
              </div>
              <div className="detail-content">
                {subscription.transactions.slice(-3).map((transaction, index) => (
                  <div key={index} className="transaction-row">
                    <span className="transaction-date">
                      {new Date(transaction.date.seconds ? 
                        transaction.date.seconds * 1000 : 
                        transaction.date
                      ).toLocaleDateString()}
                    </span>
                    <span className="transaction-amount">
                      ${transaction.amount}
                    </span>
                    <span className="transaction-status success">
                      {transaction.status}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        <div className="subscription-actions">
          <button 
            onClick={handleRefresh} 
            className="btn btn-secondary"
            disabled={refreshing}
          >
            {refreshing ? 'Refreshing...' : 'Refresh Status'}
          </button>
          <a 
            href="https://billing.stripe.com/p/login/test_00000000000001" 
            target="_blank" 
            rel="noopener noreferrer"
            className="btn btn-outline"
          >
            <ExternalLink size={16} />
            Manage Billing
          </a>
        </div>

        {daysRemaining !== null && daysRemaining < 7 && (
          <div className="renewal-notice">
            <AlertCircle className="notice-icon" />
            <div className="notice-content">
              <h4>Your subscription expires soon!</h4>
              <p>Renew your premium membership to continue enjoying all features.</p>
              <Link to="/premium-membership" className="btn btn-primary">
                Renew Subscription
              </Link>
            </div>
          </div>
        )}
      </div>
    );
  }

  // No active subscription view
  return (
    <div className="subscription-manager inactive">
      <div className="subscription-header">
        <Shield className="shield-icon inactive" />
        <div className="subscription-info">
          <h2>Premium Membership</h2>
          <div className="status-badge inactive">Not Active</div>
        </div>
      </div>

      <div className="upgrade-prompt">
        <div className="upgrade-content">
          <Crown className="upgrade-icon" />
          <h3>Upgrade to Premium</h3>
          <p>
            Get access to exclusive features, priority support, and an ad-free experience.
          </p>
          <div className="premium-features">
            <div className="feature-item">✨ Premium Badge</div>
            <div className="feature-item">🚀 Priority Support</div>
            <div className="feature-item">🎵 Enhanced Audio Features</div>
            <div className="feature-item">💬 Exclusive Communities</div>
          </div>
          <Link to="/premium-membership" className="btn btn-primary">
            <Crown size={16} />
            Upgrade Now
          </Link>
        </div>
      </div>

      <div className="subscription-actions">
        <button 
          onClick={handleRefresh} 
          className="btn btn-secondary"
          disabled={refreshing}
        >
          {refreshing ? 'Checking...' : 'Check Status'}
        </button>
      </div>
    </div>
  );
};

export default SubscriptionManager;