// src/components/streaming/StreamsPanel.jsx
import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useStreamingLiveKit as useStreaming } from '../../contexts/StreamingContextLiveKit';
import VideoStream from './VideoStream';
import { Users, Video } from 'lucide-react';

const StreamsPanel = ({ roomId, peers, streams, onMaximize }) => {
  const { currentUser } = useAuth();
  const { roomActiveStreamers } = useStreaming();
  const [activeStreams, setActiveStreams] = useState([]);
  const [focusedStream, setFocusedStream] = useState(null);
  
  // Organize streams data
  useEffect(() => {
    if (!streams || !roomActiveStreamers) return;
    
    // Combine stream data with streamer info
    const combinedStreams = Object.entries(streams).map(([userId, stream]) => {
      // Find corresponding streamer info
      const streamer = roomActiveStreamers.find(s => s.userId === userId);
      
      return {
        userId,
        stream,
        isSelf: userId === currentUser?.uid,
        displayName: streamer?.displayName || 'Unknown',
        photoURL: streamer?.photoURL || null,
        hasAudio: streamer?.hasAudio !== false,
        hasVideo: streamer?.hasVideo !== false
      };
    });
    
    // Sort streams - put self first, then by name
    const sortedStreams = combinedStreams.sort((a, b) => {
      if (a.isSelf) return -1;
      if (b.isSelf) return 1;
      return a.displayName.localeCompare(b.displayName);
    });
    
    setActiveStreams(sortedStreams);
    
    // If there's at least one stream and no focused stream, set the first one as focused
    if (sortedStreams.length > 0 && !focusedStream) {
      setFocusedStream(sortedStreams[0].userId);
    }
  }, [streams, roomActiveStreamers, currentUser, focusedStream]);
  
  // Handle setting a stream as focused
  const handleFocusStream = (userId) => {
    setFocusedStream(userId);
    
    // If onMaximize callback is provided, call it with the focused stream
    if (onMaximize) {
      const streamToMaximize = activeStreams.find(s => s.userId === userId);
      onMaximize(streamToMaximize);
    }
  };
  
  if (activeStreams.length === 0) {
    return (
      <div className="streams-panel empty">
        <div className="no-streams-message">
          <Video size={32} />
          <p>No active video streams</p>
          {peers && peers.length > 0 && (
            <div className="peers-connected">
              <Users size={16} />
              <span>{peers.length} peer{peers.length !== 1 ? 's' : ''} connected</span>
            </div>
          )}
        </div>
        
        <style jsx>{`
          .streams-panel {
            background-color: #1f2937;
            border-radius: 8px;
            height: 100%;
            display: flex;
            flex-direction: column;
            overflow: hidden;
          }
          
          .no-streams-message {
            flex-grow: 1;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 12px;
            color: #9ca3af;
            padding: 24px;
            text-align: center;
          }
          
          .peers-connected {
            display: flex;
            align-items: center;
            gap: 6px;
            background-color: #374151;
            padding: 6px 12px;
            border-radius: 16px;
            font-size: 14px;
          }
        `}</style>
      </div>
    );
  }
  
  // Determine if we should use grid or list layout
  const useGridLayout = activeStreams.length <= 4;
  
  return (
    <div className={`streams-panel ${useGridLayout ? 'grid-layout' : 'list-layout'}`}>
      {/* Main Video Display (for list layout) */}
      {!useGridLayout && focusedStream && (
        <div className="focused-stream-container">
          {activeStreams.map(stream => {
            if (stream.userId !== focusedStream) return null;
            
            return (
              <VideoStream
                key={stream.userId}
                stream={stream.stream}
                isSelf={stream.isSelf}
                displayName={stream.displayName}
                photoURL={stream.photoURL}
                hasAudio={stream.hasAudio}
                hasVideo={stream.hasVideo}
                onToggleAudio={stream.isSelf ? (enabled) => handleToggleAudio(stream.userId, enabled) : undefined}
                onToggleVideo={stream.isSelf ? (enabled) => handleToggleVideo(stream.userId, enabled) : undefined}
              />
            );
          })}
        </div>
      )}
      
      {/* Thumbnails Grid/List */}
      <div className={`streams-${useGridLayout ? 'grid' : 'list'}`}>
        {activeStreams.map(stream => {
          // For grid layout, show all streams
          // For list layout, only show thumbnails for non-focused streams
          if (!useGridLayout && stream.userId === focusedStream) return null;
          
          return (
            <div 
              key={stream.userId} 
              className={`stream-item ${stream.isSelf ? 'self-stream' : ''}`}
              onClick={() => !useGridLayout && handleFocusStream(stream.userId)}
            >
              <VideoStream
                stream={stream.stream}
                isSelf={stream.isSelf}
                displayName={stream.displayName}
                photoURL={stream.photoURL}
                hasAudio={stream.hasAudio}
                hasVideo={stream.hasVideo}
                onToggleAudio={stream.isSelf ? (enabled) => handleToggleAudio(stream.userId, enabled) : undefined}
                onToggleVideo={stream.isSelf ? (enabled) => handleToggleVideo(stream.userId, enabled) : undefined}
                minimized={!useGridLayout}
                onExpand={() => !useGridLayout && handleFocusStream(stream.userId)}
              />
            </div>
          );
        })}
      </div>
      
      <style jsx>{`
        .streams-panel {
          background-color: #1f2937;
          border-radius: 8px;
          height: 100%;
          display: flex;
          flex-direction: column;
          overflow: hidden;
        }
        
        .streams-panel.grid-layout {
          padding: 8px;
          gap: 8px;
        }
        
        .streams-panel.list-layout {
          display: flex;
          flex-direction: column;
        }
        
        .focused-stream-container {
          flex-grow: 1;
          margin-bottom: 8px;
        }
        
        .streams-grid {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
          grid-auto-rows: 1fr;
          gap: 8px;
          max-height: 100%;
        }
        
        .streams-list {
          display: flex;
          gap: 8px;
          padding: 8px;
          overflow-x: auto;
          background-color: rgba(0, 0, 0, 0.2);
        }
        
        .stream-item {
          position: relative;
        }
        
        .stream-item.self-stream {
          order: -1;
        }
      `}</style>
    </div>
  );
};

export default StreamsPanel;