/**
 * ReplayService.js - Main video replay orchestrator for TalkStudio.space
 * Path: C:\Users\Tom\Documents\GitHub\presence-react3\presence-react\src\services\recording\ReplayService.js
 * 
 * Handles static video replay from Firebase Storage with quality selection
 * and event management for the Watch-Replays system.
 */

import { getStorage, ref, getDownloadURL, listAll, getMetadata } from 'firebase/storage';
import { getFirestore, collection, doc, getDoc, getDocs, query, orderBy, where, limit, setDoc } from 'firebase/firestore';
import { storage, db } from '../../firebase';

console.log('🚨🚨🚨 ReplayService.js LOADED - THIS IS THE UPDATED VERSION WITH DEBUG LOGGING 🚨🚨🚨');

class ReplayService {
  constructor() {
    this.storage = storage || getStorage();
    this.db = db || getFirestore();
    this.currentEvent = null;
    this.availableQualities = [];
    this.eventCache = new Map();
    this.videoCache = new Map();
    
    // Event listeners - Initialize with default functions
    this.onEventLoaded = () => {};
    this.onQualitiesChanged = () => {};
    this.onError = (error) => console.error('ReplayService Error:', error);
    this.onLoadingStateChange = () => {};
    
    // Loading states
    this.isLoading = false;
    this.loadingProgress = 0;
  }

  /**
   * Initialize the replay service
   */
  async initialize(callbacks = {}) {
    try {
      this.onEventLoaded = callbacks.onEventLoaded || (() => {});
      this.onQualitiesChanged = callbacks.onQualitiesChanged || (() => {});
      this.onError = callbacks.onError || ((error) => console.error('ReplayService Error:', error));
      this.onLoadingStateChange = callbacks.onLoadingStateChange || (() => {});
      
      console.log('✅ ReplayService initialized successfully');
      return true;
    } catch (error) {
      if (this.onError && typeof this.onError === 'function') {
        if (this.onError && typeof this.onError === 'function') {
        this.onError(error);
      }
      }
      return false;
    }
  }

  /**
   * Get all available replay events
   * @param {Object} options - Query options
   * @returns {Promise<Array>} Array of event objects
   */
  async getReplayEvents(options = {}) {
    try {
      this.setLoadingState(true, 0);
      
      const {
        limit: queryLimit = 50,
        orderBy: orderField = 'createdAt',
        orderDirection = 'desc',
        startAfter = null,
        filters = {}
      } = options;

      // Check cache first
      const cacheKey = JSON.stringify({ queryLimit, orderField, orderDirection, filters });
      if (this.eventCache.has(cacheKey)) {
        this.setLoadingState(false, 100);
        return this.eventCache.get(cacheKey);
      }

      // Query Firestore for events
      const eventsRef = collection(this.db, 'replayEvents');
      let eventsQuery = query(
        eventsRef,
        orderBy(orderField, orderDirection),
        limit(queryLimit)
      );

      // Apply filters
      Object.entries(filters).forEach(([field, value]) => {
        eventsQuery = query(eventsQuery, where(field, '==', value));
      });

      this.setLoadingState(true, 30);

      const snapshot = await getDocs(eventsQuery);
      const events = [];

      this.setLoadingState(true, 60);

      snapshot.forEach((doc) => {
        const eventData = doc.data();
        events.push({
          id: doc.id,
          ...eventData,
          createdAt: eventData.createdAt?.toDate() || new Date(),
          updatedAt: eventData.updatedAt?.toDate() || new Date()
        });
      });

      // Check Firebase Storage for additional metadata
      await this.enrichEventsWithStorageData(events);

      this.setLoadingState(true, 90);

      // Cache the results
      this.eventCache.set(cacheKey, events);

      this.setLoadingState(false, 100);
      return events;

    } catch (error) {
      this.setLoadingState(false, 0);
      if (this.onError && typeof this.onError === 'function') {
        this.onError(error);
      }
      return [];
    }
  }

  /**
   * Load a specific replay event
   * @param {string} eventId - The event ID to load
   * @returns {Promise<Object>} Event object with video data
   */
  async loadReplayEvent(eventId) {
    try {
      console.log('🎥 ReplayService: Loading event', eventId);
      this.setLoadingState(true, 0);

      // Check cache first
      if (this.eventCache.has(eventId)) {
        console.log('🎥 ReplayService: Found in cache');
        const cachedEvent = this.eventCache.get(eventId);
        this.currentEvent = cachedEvent;
        if (this.onEventLoaded && typeof this.onEventLoaded === 'function') {
        this.onEventLoaded(cachedEvent);
      }
        this.setLoadingState(false, 100);
        return cachedEvent;
      }

      this.setLoadingState(true, 20);

      // Try to get event metadata from Firestore
      let eventData = null;
      try {
        console.log('🎥 ReplayService: Checking Firestore for event metadata...');
        const eventDoc = await getDoc(doc(this.db, 'replayEvents', eventId));
        if (eventDoc.exists()) {
          console.log('🎥 ReplayService: Found event in Firestore');
          eventData = eventDoc.data();
        } else {
          console.log('🎥 ReplayService: Event not in Firestore, using fallback data');
        }
      } catch (firestoreError) {
        console.log('🎥 ReplayService: Firestore error, using fallback:', firestoreError.message);
      }

      // If no Firestore data, create fallback
      if (!eventData) {
        console.log('🎥 ReplayService: Creating fallback event data');
        eventData = {
          title: `Event ${eventId}`,
          description: 'Recorded event',
          createdAt: new Date(),
          updatedAt: new Date(),
          viewCount: 0
        };
      }

      this.setLoadingState(true, 40);

      // Get available video qualities from Firebase Storage
      console.log('🎥 ReplayService: Getting video data...');
      const videoData = await this.getEventVideoData(eventId);
      console.log('🎥 ReplayService: Video data received:', videoData);
      this.setLoadingState(true, 70);

      const event = {
        id: eventId,
        ...eventData,
        videos: videoData,
        createdAt: eventData.createdAt?.toDate ? eventData.createdAt.toDate() : eventData.createdAt,
        updatedAt: eventData.updatedAt?.toDate ? eventData.updatedAt.toDate() : eventData.updatedAt
      };

      // Update available qualities
      this.availableQualities = Object.keys(videoData.combined || {});
      console.log('🎥 ReplayService: Available qualities:', this.availableQualities);
      
      if (this.onQualitiesChanged && typeof this.onQualitiesChanged === 'function') {
        this.onQualitiesChanged(this.availableQualities);
      }

      this.setLoadingState(true, 90);

      // Cache the event
      this.eventCache.set(eventId, event);
      this.currentEvent = event;

      if (this.onEventLoaded && typeof this.onEventLoaded === 'function') {
        this.onEventLoaded(event);
      }
      this.setLoadingState(false, 100);

      console.log('🎥 ReplayService: Event loaded successfully:', event);
      return event;

    } catch (error) {
      console.error('🎥 ReplayService: Error loading event:', error);
      this.setLoadingState(false, 0);
      if (this.onError && typeof this.onError === 'function') {
        this.onError(error);
      }
      return null;
    }
  }

  /**
   * Get video data for a specific event from Firebase Storage
   * @param {string} eventId - The event ID
   * @returns {Promise<Object>} Video data structure
   */
  async getEventVideoData(eventId) {
    try {
      console.log('🎥 ReplayService.getEventVideoData: Getting video data for', eventId);
      
      // Use direct Google Cloud Storage URL for finished events
      const bucketName = 'talkstudio-fb.appspot.com';
      const baseUrl = `https://storage.googleapis.com/${bucketName}`;
      
      const videoData = {
        combined: {},
        individual: {}
      };

      // For finished events, use the direct cloud storage URL pattern
      // Pattern: finished-events/eventId/eventId.mp4
      const finishedEventUrl = `${baseUrl}/finished-events/${eventId}/${eventId}.mp4`;
      console.log('🎥 ReplayService: Direct video URL:', finishedEventUrl);
      
      // Skip HEAD request - just assume the video exists and let the player handle errors
      // This avoids CORS issues with HEAD requests
      console.log('🎥 ReplayService: Using direct URL for all qualities');
      
      // Add the URL for all common qualities
      const qualities = ['standard', 'hd', '720p', '1080p', '480p'];
      for (const quality of qualities) {
        videoData.combined[quality] = {
          url: finishedEventUrl,
          metadata: null,
          size: 0, // Unknown size
          format: 'mp4'
        };
      }
      
      console.log('🎥 ReplayService: Video data prepared:', videoData);
      return videoData;

      // Fall back to the original recordings path if finished event doesn't exist
      const eventPath = `recordings/${eventId}`;
      const eventRef = ref(this.storage, eventPath);

      // List all items in the event directory
      const eventList = await listAll(eventRef);

      // Process combined videos (main replay videos)
      const combinedRef = ref(this.storage, `${eventPath}/combined`);
      try {
        const combinedList = await listAll(combinedRef);
        
        for (const qualityFolder of combinedList.prefixes) {
          const qualityName = qualityFolder.name;
          const qualityRef = ref(this.storage, `${eventPath}/combined/${qualityName}`);
          const qualityList = await listAll(qualityRef);

          // Look for video file and metadata
          const videoFile = qualityList.items.find(item => 
            item.name.endsWith('.mp4') || item.name.endsWith('.webm')
          );
          const metadataFile = qualityList.items.find(item => 
            item.name === 'metadata.json'
          );

          if (videoFile) {
            videoData.combined[qualityName] = {
              url: await getDownloadURL(videoFile),
              metadata: metadataFile ? await this.getVideoMetadata(metadataFile) : null,
              size: await this.getFileSize(videoFile),
              format: this.getFileFormat(videoFile.name)
            };
          }
        }
      } catch (error) {
        console.warn('No combined videos found for event:', eventId);
      }

      // Process individual videos (individual user perspectives)
      const individualRef = ref(this.storage, `${eventPath}/individual`);
      try {
        const individualList = await listAll(individualRef);
        
        for (const userFolder of individualList.prefixes) {
          const userId = userFolder.name;
          const userRef = ref(this.storage, `${eventPath}/individual/${userId}`);
          const userList = await listAll(userRef);

          const videoFile = userList.items.find(item => 
            item.name.endsWith('.mp4') || item.name.endsWith('.webm')
          );

          if (videoFile) {
            videoData.individual[userId] = {
              url: await getDownloadURL(videoFile),
              size: await this.getFileSize(videoFile),
              format: this.getFileFormat(videoFile.name)
            };
          }
        }
      } catch (error) {
        console.warn('No individual videos found for event:', eventId);
      }

      return videoData;

    } catch (error) {
      if (this.onError && typeof this.onError === 'function') {
        this.onError(error);
      }
      return { combined: {}, individual: {} };
    }
  }

  /**
   * Get video URL for specific quality
   * @param {string} eventId - The event ID
   * @param {string} quality - The quality level (e.g., 'standard', 'hd')
   * @returns {Promise<string>} Video URL
   */
  async getVideoUrl(eventId, quality = 'standard') {
    try {
      // Check cache first
      const cacheKey = `${eventId}-${quality}`;
      if (this.videoCache.has(cacheKey)) {
        return this.videoCache.get(cacheKey);
      }

      // Use direct Google Cloud Storage URL for finished events
      const bucketName = 'talkstudio-fb.appspot.com';
      const baseUrl = `https://storage.googleapis.com/${bucketName}`;
      
      // All qualities use the same URL (the video is already high quality)
      const videoUrl = `${baseUrl}/finished-events/${eventId}/${eventId}.mp4`;

      // Check if the URL exists
      try {
        const response = await fetch(videoUrl, { method: 'HEAD' });
        if (response.ok) {
          this.videoCache.set(cacheKey, videoUrl);
          return videoUrl;
        }
      } catch (error) {
        console.log(`Direct cloud storage URL not found for ${eventId} with quality ${quality}`);
      }

      // If current event is loaded and matches, try the fallback URLs
      if (this.currentEvent && this.currentEvent.id === eventId) {
        const fallbackUrl = this.currentEvent.videos?.combined?.[quality]?.url;
        if (fallbackUrl) {
          this.videoCache.set(cacheKey, fallbackUrl);
          return fallbackUrl;
        }
      }

      // Load event data to get video URL
      const event = await this.loadReplayEvent(eventId);
      const fallbackUrl = event?.videos?.combined?.[quality]?.url;

      if (fallbackUrl) {
        this.videoCache.set(cacheKey, fallbackUrl);
        return fallbackUrl;
      }

      throw new Error(`Video not found for event ${eventId} with quality ${quality}`);

    } catch (error) {
      if (this.onError && typeof this.onError === 'function') {
        this.onError(error);
      }
      return null;
    }
  }

  /**
   * Get available qualities for current event
   * @returns {Array<string>} Array of quality names
   */
  getAvailableQualities() {
    return this.availableQualities;
  }

  /**
   * Search replay events
   * @param {string} searchTerm - Search term
   * @param {Object} options - Search options
   * @returns {Promise<Array>} Array of matching events
   */
  async searchReplayEvents(searchTerm, options = {}) {
    try {
      this.setLoadingState(true, 0);

      const {
        limit: queryLimit = 20,
        filters = {}
      } = options;

      // For now, we'll do a simple client-side search
      // In production, you might want to use Algolia or similar
      const allEvents = await this.getReplayEvents({ limit: 100 });
      
      this.setLoadingState(true, 50);

      const searchResults = allEvents.filter(event => {
        const searchInTitle = event.title?.toLowerCase().includes(searchTerm.toLowerCase());
        const searchInDescription = event.description?.toLowerCase().includes(searchTerm.toLowerCase());
        const searchInTags = event.tags?.some(tag => 
          tag.toLowerCase().includes(searchTerm.toLowerCase())
        );

        return searchInTitle || searchInDescription || searchInTags;
      }).slice(0, queryLimit);

      this.setLoadingState(false, 100);
      return searchResults;

    } catch (error) {
      this.setLoadingState(false, 0);
      if (this.onError && typeof this.onError === 'function') {
        this.onError(error);
      }
      return [];
    }
  }

  /**
   * Get recent replay events
   * @param {number} limit - Number of events to return
   * @returns {Promise<Array>} Array of recent events
   */
  async getRecentReplays(limit = 10) {
    return this.getReplayEvents({
      limit,
      orderBy: 'createdAt',
      orderDirection: 'desc'
    });
  }

  /**
   * Get popular replay events
   * @param {number} limit - Number of events to return
   * @returns {Promise<Array>} Array of popular events
   */
  async getPopularReplays(limit = 10) {
    return this.getReplayEvents({
      limit,
      orderBy: 'viewCount',
      orderDirection: 'desc'
    });
  }

  /**
   * Increment view count for an event
   * @param {string} eventId - The event ID
   */
  async incrementViewCount(eventId) {
    try {
      // You might want to implement this server-side to avoid race conditions
      const eventRef = doc(this.db, 'replayEvents', eventId);
      const eventDoc = await getDoc(eventRef);
      
      if (eventDoc.exists()) {
        const currentCount = eventDoc.data().viewCount || 0;
        await setDoc(eventRef, { 
          viewCount: currentCount + 1,
          lastViewed: new Date()
        }, { merge: true });
      }
    } catch (error) {
      // Don't throw error for view count updates
      console.warn('Failed to increment view count:', error);
    }
  }

  // Helper methods

  /**
   * Enrich events with storage data
   * @param {Array} events - Array of events to enrich
   */
  async enrichEventsWithStorageData(events) {
    // This could be used to add thumbnail URLs, duration, etc.
    // For now, we'll just ensure all events have basic structure
    events.forEach(event => {
      if (!event.thumbnailUrl) {
        event.thumbnailUrl = `/api/thumbnail/${event.id}`;
      }
      if (!event.duration) {
        event.duration = 0; // Will be populated from video metadata
      }
    });
  }

  /**
   * Get video metadata from storage
   * @param {Object} metadataFile - Firebase storage reference
   * @returns {Promise<Object>} Metadata object
   */
  async getVideoMetadata(metadataFile) {
    try {
      const url = await getDownloadURL(metadataFile);
      const response = await fetch(url);
      const metadata = await response.json();
      return metadata;
    } catch (error) {
      console.warn('Failed to load video metadata:', error);
      return null;
    }
  }

  /**
   * Get file size from storage reference
   * @param {Object} fileRef - Firebase storage reference
   * @returns {Promise<number>} File size in bytes
   */
  async getFileSize(fileRef) {
    try {
      const metadata = await getMetadata(fileRef);
      return metadata.size;
    } catch (error) {
      console.warn('Failed to get file size:', error);
      return 0;
    }
  }

  /**
   * Get file format from filename
   * @param {string} filename - The filename
   * @returns {string} File format
   */
  getFileFormat(filename) {
    const extension = filename.split('.').pop().toLowerCase();
    return extension;
  }

  /**
   * Set loading state and notify listeners
   * @param {boolean} loading - Loading state
   * @param {number} progress - Progress percentage (0-100)
   */
  setLoadingState(loading, progress = 0) {
    this.isLoading = loading;
    this.loadingProgress = progress;
    if (this.onLoadingStateChange && typeof this.onLoadingStateChange === 'function') {
      this.onLoadingStateChange(loading, progress);
    }
  }

  /**
   * Clear all caches
   */
  clearCache() {
    this.eventCache.clear();
    this.videoCache.clear();
    console.log('ReplayService cache cleared');
  }

  /**
   * Get cache statistics
   * @returns {Object} Cache statistics
   */
  getCacheStats() {
    return {
      eventCacheSize: this.eventCache.size,
      videoCacheSize: this.videoCache.size,
      currentEvent: this.currentEvent?.id || null,
      availableQualities: this.availableQualities
    };
  }

  /**
   * Cleanup service resources
   */
  cleanup() {
    this.clearCache();
    this.currentEvent = null;
    this.availableQualities = [];
    // Reset to default functions instead of null
    this.onEventLoaded = () => {};
    this.onQualitiesChanged = () => {};
    this.onError = (error) => console.error('ReplayService Error:', error);
    this.onLoadingStateChange = () => {};
  }
}

// Export singleton instance
const replayService = new ReplayService();
export default replayService;

// Also export the class for testing
export { ReplayService };
