// src/components/premium/SubscriptionSuccess.jsx
import React, { useState, useEffect } from 'react';
import { useLocation, useNavigate, useSearchParams } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { useSubscription } from '../../hooks/useSubscription';
import { CheckCircle, Crown, Home, Settings, Sparkles, User, Copy } from 'lucide-react';
import './SubscriptionSuccess.css';

const SubscriptionSuccess = () => {
  const [status, setStatus] = useState('loading');
  const [sessionInfo, setSessionInfo] = useState(null);
  const [error, setError] = useState(null);
  const [debugInfo, setDebugInfo] = useState(null);
  const location = useLocation();
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { currentUser } = useAuth();
  const { updateSubscription, refreshSubscription, subscription } = useSubscription();

  // Copy to clipboard function
  const copyToClipboard = (text) => {
    navigator.clipboard.writeText(text).then(() => {
      alert('Copied to clipboard!');
    });
  };

  useEffect(() => {
    const processSuccess = async () => {
      try {
        // Get session ID from URL query parameters
        const sessionId = searchParams.get('session_id');
        const paymentIntent = searchParams.get('payment_intent');
        const amount = searchParams.get('amount');
        // `plan` is set by the membership page's checkout (monthly | yearly) and
        // decides how long the entitlement runs. Anything unrecognised — e.g. an
        // older Buy Button link that never sent one — falls back to monthly.
        const planId = searchParams.get('plan') === 'yearly' ? 'yearly' : 'monthly';
        const redirectStatus = searchParams.get('redirect_status');

        if (redirectStatus && redirectStatus !== 'succeeded' && redirectStatus !== 'processing') {
          setStatus('error');
          setError(`Payment was not completed (${redirectStatus}). You have not been charged.`);
          return;
        }

        if (!sessionId && !paymentIntent) {
          setStatus('error');
          setError('No payment information found in URL');
          return;
        }
        
        if (!currentUser) {
          setStatus('error');
          setError('You must be logged in to view subscription details');
          return;
        }

        // Store session info
        setSessionInfo({
          sessionId,
          paymentIntent,
          amount: amount ? parseFloat(amount) : 9.99
        });

        // Collect debug information
        const debug = {
          userId: currentUser.uid,
          userEmail: currentUser.email,
          sessionId,
          paymentIntent,
          amount: amount ? parseFloat(amount) : 9.99,
          hostname: window.location.hostname,
          timestamp: new Date().toISOString(),
          subscriptionBefore: subscription
        };
        
        console.log('🐛 Debug Info - Before Update:', debug);
        setDebugInfo(debug);

        // Update subscription status in database
        // This simulates what would happen from a webhook
        const subscriptionData = {
          plan: planId === 'yearly' ? 'Premium Yearly' : 'Premium',
          amount: amount ? parseFloat(amount) : (planId === 'yearly' ? 99.99 : 9.99),
          currency: 'usd',
          durationDays: planId === 'yearly' ? 365 : 30,
          stripePaymentIntentId: paymentIntent,
          transactionId: paymentIntent || sessionId || `tx_${Date.now()}`,
          description: `TalkStudio Premium (${planId}) purchase`
        };

        const result = await updateSubscription(subscriptionData);
        
        console.log('🐛 Debug Info - Update Result:', result);
        setDebugInfo(prev => ({ ...prev, updateResult: result }));
        
        if (result.success) {
          setStatus('success');
          // Refresh to get latest data
          setTimeout(() => {
            refreshSubscription();
          }, 1000);
        } else {
          throw new Error(result.error || 'Failed to update subscription');
        }
        
        // Clean up URL parameters
        navigate('/subscription-success', { replace: true });
        
      } catch (error) {
        console.error('Error processing subscription success:', error);
        setStatus('error');
        setError(error.message || 'An error occurred processing your subscription');
      }
    };
    
    processSuccess();
  }, [location, currentUser, navigate, searchParams, updateSubscription, refreshSubscription]);

  if (status === 'loading') {
    return (
      <div className="subscription-success loading">
        <div className="loading-content">
          <div className="loading-spinner"></div>
          <h2>Processing your subscription...</h2>
          <p>Please wait while we activate your premium membership.</p>
        </div>
      </div>
    );
  }

  if (status === 'error') {
    return (
      <div className="subscription-success error">
        <div className="error-content">
          <div className="error-icon">⚠️</div>
          <h2>Subscription Error</h2>
          <p>{error}</p>
          <div className="error-actions">
            <button 
              onClick={() => navigate('/premium-membership')}
              className="btn btn-primary"
            >
              Back to Premium Membership
            </button>
            <button 
              onClick={() => navigate('/settings')}
              className="btn btn-secondary"
            >
              Check Account Settings
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Success state
  return (
    <div className="subscription-success">
      <div className="success-container">
        {/* Success Header */}
        <div className="success-header">
          <div className="success-icon-container">
            <CheckCircle className="success-icon" />
            <Sparkles className="sparkle-1" />
            <Sparkles className="sparkle-2" />
            <Crown className="crown-icon" />
          </div>
          <h1>Welcome to Premium!</h1>
          <p className="success-subtitle">
            Your premium membership has been successfully activated.
          </p>
        </div>

        {/* Membership Details */}
        <div className="membership-details">
          <h2>🎉 You're now a Premium Member!</h2>
          <div className="details-grid">
            <div className="detail-item">
              <strong>Plan:</strong> Premium Membership
            </div>
            {sessionInfo?.amount && (
              <div className="detail-item">
                <strong>Amount:</strong> ${sessionInfo.amount}
              </div>
            )}
            <div className="detail-item">
              <strong>Duration:</strong> 30 days
            </div>
            <div className="detail-item">
              <strong>Status:</strong> <span className="active-status">✓ Active</span>
            </div>
          </div>
        </div>

        {/* Premium Features */}
        <div className="premium-features">
          <h3>Your Premium Features Are Now Active</h3>
          <div className="features-grid">
            <div className="feature-card">
              <div className="feature-icon">👑</div>
              <h4>Premium Badge</h4>
              <p>Show off your premium status</p>
            </div>
            <div className="feature-card">
              <div className="feature-icon">🚀</div>
              <h4>Priority Support</h4>
              <p>Get faster help when you need it</p>
            </div>
            <div className="feature-card">
              <div className="feature-icon">💬</div>
              <h4>Exclusive Access</h4>
              <p>Premium-only communities</p>
            </div>
            <div className="feature-card">
              <div className="feature-icon">🎵</div>
              <h4>Enhanced Audio</h4>
              <p>Advanced audio features</p>
            </div>
          </div>
        </div>

        {/* Next Steps */}
        <div className="next-steps">
          <h3>What's Next?</h3>
          <div className="steps-list">
            <div className="step-item">
              <div className="step-number">1</div>
              <div className="step-content">
                <h4>Explore Premium Features</h4>
                <p>Start using your new premium features right away</p>
              </div>
            </div>
            <div className="step-item">
              <div className="step-number">2</div>
              <div className="step-content">
                <h4>Join Premium Communities</h4>
                <p>Access exclusive chat rooms and discussions</p>
              </div>
            </div>
            <div className="step-item">
              <div className="step-number">3</div>
              <div className="step-content">
                <h4>Manage Your Subscription</h4>
                <p>View details and manage billing in your settings</p>
              </div>
            </div>
          </div>
        </div>

        {/* Action Buttons */}
        <div className="success-actions">
          <button 
            onClick={() => navigate('/')}
            className="btn btn-primary"
          >
            <Home size={16} />
            Start Using Premium
          </button>
          <button 
            onClick={() => navigate('/settings')}
            className="btn btn-secondary"
          >
            <Settings size={16} />
            Manage Subscription
          </button>
        </div>

        {/* Receipt Info */}
        {sessionInfo && (
          <div className="receipt-info">
            <p>
              <strong>Receipt:</strong> A confirmation email has been sent to your registered email address.
            </p>
            {sessionInfo.sessionId && (
              <p className="session-id">
                <strong>Transaction ID:</strong> {sessionInfo.sessionId}
              </p>
            )}
          </div>
        )}

        {/* Debug Information - Development Mode Only */}
        {(debugInfo && (window.location.hostname.includes('localhost') || process.env.NODE_ENV === 'development')) && (
          <div className="debug-panel">
            <h3>🐛 Debug Information (Development Only)</h3>
            <div className="debug-grid">
              <div className="debug-item">
                <strong>User ID:</strong>
                <div className="debug-value">
                  <code>{debugInfo.userId}</code>
                  <button onClick={() => copyToClipboard(debugInfo.userId)} className="copy-btn">
                    <Copy size={12} />
                  </button>
                </div>
              </div>
              <div className="debug-item">
                <strong>User Email:</strong>
                <code>{debugInfo.userEmail}</code>
              </div>
              <div className="debug-item">
                <strong>Session ID:</strong>
                <code>{debugInfo.sessionId || 'None'}</code>
              </div>
              <div className="debug-item">
                <strong>Payment Intent:</strong>
                <code>{debugInfo.paymentIntent || 'None'}</code>
              </div>
              <div className="debug-item">
                <strong>Amount:</strong>
                <code>${debugInfo.amount}</code>
              </div>
              <div className="debug-item">
                <strong>Environment:</strong>
                <code>{debugInfo.hostname}</code>
              </div>
              <div className="debug-item">
                <strong>Timestamp:</strong>
                <code>{debugInfo.timestamp}</code>
              </div>
              {debugInfo.updateResult && (
                <div className="debug-item">
                  <strong>Update Result:</strong>
                  <code className={debugInfo.updateResult.success ? 'success' : 'error'}>
                    {debugInfo.updateResult.success ? '✅ Success' : '❌ Failed'}
                  </code>
                </div>
              )}
              {debugInfo.subscriptionBefore && (
                <div className="debug-item full-width">
                  <strong>Subscription Before:</strong>
                  <pre className="subscription-debug">
                    {JSON.stringify(debugInfo.subscriptionBefore, null, 2)}
                  </pre>
                </div>
              )}
              <div className="debug-item full-width">
                <strong>Current Subscription:</strong>
                <pre className="subscription-debug">
                  {JSON.stringify(subscription, null, 2)}
                </pre>
              </div>
            </div>
            <div className="debug-actions">
              <button 
                onClick={() => copyToClipboard(JSON.stringify(debugInfo, null, 2))} 
                className="btn btn-secondary"
              >
                <Copy size={16} />
                Copy All Debug Info
              </button>
              <button 
                onClick={() => {
                  console.log('🔍 Full Debug Object:', debugInfo);
                  console.log('🔍 Current Subscription:', subscription);
                  console.log('🔍 Current User:', currentUser);
                }} 
                className="btn btn-secondary"
              >
                Log to Console
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default SubscriptionSuccess;