import { useState, useEffect, useCallback } from 'react';

// Constants for fingerprinting
const FINGERPRINT_SIZE = 256;
const FREQ_BANDS = 33;
const TIME_WINDOWS = 64;

export const useAudioDetectionFixed = () => {
  const [isReady, setIsReady] = useState(false);
  
  const initializeAudio = useCallback(() => {
    setIsReady(true);
  }, []);
  
  // Main processing function
  const processAudioData = useCallback(async (audioBlob, audioContext) => {
    if (!audioBlob || !audioContext) {
      throw new Error('Audio blob or context is null');
    }
    
    try {
      const arrayBuffer = await audioBlob.arrayBuffer();
      const audioBuffer = await audioContext.decodeAudioData(arrayBuffer);
      
      // Generate unique fingerprint
      const fingerprint = await createUniqueFingerprint(audioBuffer);
      
      console.log('Fingerprint created:', fingerprint.slice(0, 10));
      
      return fingerprint;
    } catch (error) {
      console.error('Error processing audio:', error);
      throw error;
    }
  }, []);
  
  // Create a truly unique fingerprint
  const createUniqueFingerprint = async (audioBuffer) => {
    const channelData = audioBuffer.getChannelData(0);
    const sampleRate = audioBuffer.sampleRate;
    
    // Use smaller windows for more temporal resolution
    const windowSize = 2048;
    const hopSize = 512;
    const numWindows = Math.floor((channelData.length - windowSize) / hopSize);
    
    // Create time-frequency matrix
    const spectrograms = [];
    
    for (let i = 0; i < numWindows && i < TIME_WINDOWS; i++) {
      const start = i * hopSize;
      const window = channelData.slice(start, start + windowSize);
      
      // Apply window function
      const windowedData = applyWindow(window);
      
      // Get frequency bands
      const bands = getFrequencyBands(windowedData, sampleRate);
      spectrograms.push(bands);
    }
    
    // Convert to fingerprint using local energy differences
    const fingerprint = [];
    
    // Compare adjacent time-frequency bins
    for (let t = 0; t < spectrograms.length - 1; t++) {
      for (let f = 0; f < FREQ_BANDS - 1; f++) {
        // Time difference
        const timeDiff = spectrograms[t + 1][f] - spectrograms[t][f];
        // Frequency difference  
        const freqDiff = spectrograms[t][f + 1] - spectrograms[t][f];
        
        // Create 2-bit hash for this position
        const hash = ((timeDiff > 0 ? 1 : 0) << 1) | (freqDiff > 0 ? 1 : 0);
        fingerprint.push(hash);
      }
    }
    
    // Ensure fixed size
    while (fingerprint.length < FINGERPRINT_SIZE) {
      fingerprint.push(0);
    }
    
    return fingerprint.slice(0, FINGERPRINT_SIZE);
  };
  
  // Apply Hann window
  const applyWindow = (data) => {
    const result = new Float32Array(data.length);
    for (let i = 0; i < data.length; i++) {
      const window = 0.5 - 0.5 * Math.cos(2 * Math.PI * i / (data.length - 1));
      result[i] = data[i] * window;
    }
    return result;
  };
  
  // Get frequency bands using simple DFT
  const getFrequencyBands = (data, sampleRate) => {
    const bands = new Float32Array(FREQ_BANDS);
    const fftSize = data.length;
    const binWidth = sampleRate / fftSize;
    
    // Define logarithmic frequency bands
    const minFreq = 80;
    const maxFreq = 8000;
    const logMin = Math.log(minFreq);
    const logMax = Math.log(maxFreq);
    
    for (let bandIdx = 0; bandIdx < FREQ_BANDS; bandIdx++) {
      // Calculate frequency range for this band
      const logFreqStart = logMin + (bandIdx / FREQ_BANDS) * (logMax - logMin);
      const logFreqEnd = logMin + ((bandIdx + 1) / FREQ_BANDS) * (logMax - logMin);
      
      const freqStart = Math.exp(logFreqStart);
      const freqEnd = Math.exp(logFreqEnd);
      
      const binStart = Math.floor(freqStart / binWidth);
      const binEnd = Math.ceil(freqEnd / binWidth);
      
      // Calculate energy in this band
      let energy = 0;
      for (let bin = binStart; bin <= binEnd && bin < fftSize / 2; bin++) {
        // Simple DFT for this bin
        let real = 0, imag = 0;
        const freq = bin * binWidth;
        
        for (let n = 0; n < data.length; n++) {
          const angle = -2 * Math.PI * freq * n / sampleRate;
          real += data[n] * Math.cos(angle);
          imag += data[n] * Math.sin(angle);
        }
        
        energy += Math.sqrt(real * real + imag * imag);
      }
      
      bands[bandIdx] = Math.log(1 + energy);
    }
    
    return bands;
  };
  
  // Calculate similarity between fingerprints  
  const calculateSimilarity = (fp1, fp2) => {
    if (!fp1 || !fp2 || fp1.length !== fp2.length) {
      return 0;
    }
    
    // Count matching values
    let matches = 0;
    for (let i = 0; i < fp1.length; i++) {
      if (fp1[i] === fp2[i]) {
        matches++;
      }
    }
    
    const similarity = matches / fp1.length;
    console.log(`Similarity: ${(similarity * 100).toFixed(2)}% (${matches}/${fp1.length} values match)`);
    
    return similarity;
  };
  
  // Create random fingerprint
  const createFallbackFingerprint = () => {
    const fingerprint = [];
    for (let i = 0; i < FINGERPRINT_SIZE; i++) {
      fingerprint.push(Math.floor(Math.random() * 4)); // 2-bit values
    }
    return fingerprint;
  };
  
  // Test function
  const testFingerprint = async () => {
    try {
      const audioContext = new (window.AudioContext || window.webkitAudioContext)();
      const sampleRate = 44100;
      const duration = 2;
      
      // Create three test signals with different characteristics
      const createSignal = (frequency, harmonics = []) => {
        const length = sampleRate * duration;
        const buffer = audioContext.createBuffer(1, length, sampleRate);
        const data = buffer.getChannelData(0);
        
        for (let i = 0; i < length; i++) {
          const t = i / sampleRate;
          let sample = Math.sin(2 * Math.PI * frequency * t);
          
          // Add harmonics
          harmonics.forEach((harmonic, idx) => {
            sample += harmonic * Math.sin(2 * Math.PI * frequency * (idx + 2) * t);
          });
          
          data[i] = sample / (1 + harmonics.length);
        }
        
        return buffer;
      };
      
      // Different audio signals
      const buffer1 = createSignal(440, [0.3, 0.1]); // A4 with harmonics
      const buffer2 = createSignal(523.25, [0.5, 0.2, 0.1]); // C5 with different harmonics
      const buffer3 = createSignal(440, [0.3, 0.1]); // Same as buffer1
      
      const fp1 = await createUniqueFingerprint(buffer1);
      const fp2 = await createUniqueFingerprint(buffer2);
      const fp3 = await createUniqueFingerprint(buffer3);
      
      // Show more diverse fingerprint samples
      console.log('FP1:', fp1.slice(0, 20));
      console.log('FP2:', fp2.slice(0, 20));
      console.log('FP3:', fp3.slice(0, 20));
      
      const selfSimilarity = calculateSimilarity(fp1, fp1);
      const differentSimilarity = calculateSimilarity(fp1, fp2);
      const sameSimilarity = calculateSimilarity(fp1, fp3);
      
      audioContext.close();
      
      return {
        selfSimilarity,
        differentSimilarity,
        sameSimilarity,
        fingerprints: {
          fp1: fp1.slice(0, 20),
          fp2: fp2.slice(0, 20),
          fp3: fp3.slice(0, 20)
        }
      };
    } catch (error) {
      console.error('Test failed:', error);
      return null;
    }
  };
  
  useEffect(() => {
    initializeAudio();
  }, [initializeAudio]);
  
  return {
    isReady,
    processAudioData,
    calculateSimilarity,
    createFallbackFingerprint,
    testFingerprint
  };
};