// EventLiveStatusManager - Comprehensive live status tracking with activity monitoring
// Path: C:\Users\Tom\Documents\GitHub\presence-react3\presence-react\src\services\events\EventLiveStatusManager.js

import { getFirestore, doc, updateDoc, collection, query, where, getDocs, getDoc, onSnapshot, serverTimestamp } from 'firebase/firestore';
import { getDatabase, ref, set, get, update, onDisconnect, serverTimestamp as rtdbServerTimestamp } from 'firebase/database';

class EventLiveStatusManager {
  constructor() {
    this.activityTrackers = new Map(); // eventId -> tracker
    this.statusListeners = new Map(); // eventId -> unsubscribe function
    this.cleanupInterval = null;
    this.ACTIVITY_GRACE_PERIOD = 30 * 60 * 1000; // 30 minutes in milliseconds
    this.CLEANUP_INTERVAL = 5 * 60 * 1000; // Check every 5 minutes
    
    // Start background cleanup
    this.startBackgroundCleanup();
  }

  /**
   * Start tracking activity for an event
   * @param {string} eventId - Event ID
   * @param {string} streamerId - ID of the person streaming
   * @param {Object} options - Configuration options
   */
  async startActivityTracking(eventId, streamerId, options = {}) {
    const {
      maxDuration = null, // Maximum duration in minutes (null = no limit)
      graceMinutes = 30   // Grace period for inactivity
    } = options;

    console.log(`🟢 Starting activity tracking for event ${eventId}`, {
      streamerId,
      maxDuration,
      graceMinutes
    });

    try {
      const db = getFirestore();
      const rtdb = getDatabase();
      const now = Date.now();
      
      // Calculate end time if duration is specified
      const endTime = maxDuration ? now + (maxDuration * 60 * 1000) : null;
      
      // Update event status in Firestore
      const eventRef = doc(db, 'events', eventId);
      await updateDoc(eventRef, {
        status: 'live',
        actualStartTime: now,
        streamStartTime: now,
        lastActivityTime: now,
        streamerId: streamerId,
        streamEndTime: endTime,
        activityGracePeriod: graceMinutes * 60 * 1000,
        updatedAt: serverTimestamp()
      });

      // Set up real-time activity tracking in RTDB
      const activityRef = ref(rtdb, `eventActivity/${eventId}`);
      const activityData = {
        eventId,
        streamerId,
        status: 'live',
        startTime: now,
        lastHeartbeat: now,
        endTime: endTime,
        gracePeriod: graceMinutes * 60 * 1000,
        isActive: true,
        viewerCount: 0,
        streamQuality: 'good'
      };

      await set(activityRef, activityData);

      // Set up auto-cleanup on disconnect
      onDisconnect(activityRef).update({
        isActive: false,
        lastHeartbeat: rtdbServerTimestamp(),
        disconnectedAt: rtdbServerTimestamp()
      });

      // Start heartbeat tracking
      this.startHeartbeat(eventId, streamerId);

      console.log(`✅ Activity tracking started for event ${eventId}`);
      return { success: true, endTime };

    } catch (error) {
      console.error(`❌ Failed to start activity tracking for event ${eventId}:`, error);
      throw error;
    }
  }

  /**
   * Update activity heartbeat for an event
   * @param {string} eventId - Event ID
   * @param {Object} activityData - Activity data (viewer count, stream quality, etc.)
   */
  async updateActivity(eventId, activityData = {}) {
    try {
      const rtdb = getDatabase();
      const now = Date.now();
      
      const activityRef = ref(rtdb, `eventActivity/${eventId}`);
      const updateData = {
        lastHeartbeat: now,
        ...activityData,
        isActive: true
      };

      await update(activityRef, updateData);

      // Also update Firestore for persistent storage
      const db = getFirestore();
      const eventRef = doc(db, 'events', eventId);
      await updateDoc(eventRef, {
        lastActivityTime: now,
        viewerCount: activityData.viewerCount || 0,
        updatedAt: serverTimestamp()
      });

      console.log(`💓 Activity updated for event ${eventId}`, activityData);

    } catch (error) {
      console.error(`❌ Failed to update activity for event ${eventId}:`, error);
    }
  }

  /**
   * Stop activity tracking and set event to ended
   * @param {string} eventId - Event ID
   * @param {string} reason - Reason for stopping ('manual', 'expired', 'inactive')
   */
  async stopActivityTracking(eventId, reason = 'manual') {
    console.log(`🔴 Stopping activity tracking for event ${eventId}`, { reason });

    try {
      const db = getFirestore();
      const rtdb = getDatabase();
      const now = Date.now();

      // Update event status in Firestore
      const eventRef = doc(db, 'events', eventId);
      await updateDoc(eventRef, {
        status: 'ended',
        actualEndTime: now,
        endReason: reason,
        lastActivityTime: now,
        updatedAt: serverTimestamp()
      });

      // Update activity tracking in RTDB
      const activityRef = ref(rtdb, `eventActivity/${eventId}`);
      await update(activityRef, {
        status: 'ended',
        endTime: now,
        endReason: reason,
        isActive: false,
        lastHeartbeat: now
      });

      // Stop heartbeat if running
      this.stopHeartbeat(eventId);

      console.log(`✅ Activity tracking stopped for event ${eventId}`);

    } catch (error) {
      console.error(`❌ Failed to stop activity tracking for event ${eventId}:`, error);
      throw error;
    }
  }

  /**
   * Check if an event is actually live (has recent activity)
   * @param {string} eventId - Event ID
   * @returns {Promise<Object>} Live status and details
   */
  async checkEventLiveStatus(eventId) {
    try {
      const db = getFirestore();
      const rtdb = getDatabase();
      const now = Date.now();

      // Get event data from Firestore
      const eventRef = doc(db, 'events', eventId);
      const eventDoc = await getDoc(eventRef);
      
      if (!eventDoc.exists()) {
        return { 
          isLive: false, 
          reason: 'not_found',
          status: 'not_found'
        };
      }

      const eventData = eventDoc.data();
      
      // Check basic status
      if (eventData.status !== 'live') {
        return {
          isLive: false,
          reason: 'not_scheduled_live',
          status: eventData.status,
          eventData
        };
      }

      // Check activity data from RTDB
      let activitySnapshot;
      try {
        const activityRef = ref(rtdb, `eventActivity/${eventId}`);
        activitySnapshot = await get(activityRef);
      } catch (rtdbError) {
        // Handle permission denied or other RTDB errors
        console.log(`⚠️ Could not access RTDB activity data for event ${eventId}:`, rtdbError.message);
        
        // If we can't access RTDB, check if event is stale based on Firestore data alone
        const lastActivity = eventData.lastActivityTime || eventData.streamStartTime || 0;
        const timeSinceActivity = now - lastActivity;
        const gracePeriod = eventData.activityGracePeriod || this.ACTIVITY_GRACE_PERIOD;
        
        if (timeSinceActivity > gracePeriod) {
          return {
            isLive: false,
            reason: 'inactive_based_on_firestore',
            status: 'stale',
            shouldCleanup: true,
            eventData,
            rtdbError: rtdbError.message
          };
        }
        
        // If recent activity in Firestore, assume it's live
        return {
          isLive: true,
          reason: 'active_firestore_only',
          status: 'live',
          timeSinceLastActivity: timeSinceActivity,
          gracePeriod,
          eventData,
          rtdbError: rtdbError.message
        };
      }
      
      if (!activitySnapshot.exists()) {
        // No activity data but marked as live - probably stale
        return {
          isLive: false,
          reason: 'no_activity_data',
          status: 'stale',
          shouldCleanup: true,
          eventData
        };
      }

      const activityData = activitySnapshot.val();
      const lastHeartbeat = activityData.lastHeartbeat || 0;
      const timeSinceLastActivity = now - lastHeartbeat;
      const gracePeriod = eventData.activityGracePeriod || this.ACTIVITY_GRACE_PERIOD;

      // Check if activity is within grace period
      if (timeSinceLastActivity > gracePeriod) {
        return {
          isLive: false,
          reason: 'inactive_too_long',
          status: 'inactive',
          timeSinceLastActivity,
          gracePeriod,
          shouldCleanup: true,
          eventData,
          activityData
        };
      }

      // Check if event has expired (past end time)
      if (eventData.streamEndTime && now > eventData.streamEndTime) {
        return {
          isLive: false,
          reason: 'expired',
          status: 'expired',
          shouldCleanup: true,
          eventData,
          activityData
        };
      }

      // Event is actually live!
      return {
        isLive: true,
        reason: 'active',
        status: 'live',
        timeSinceLastActivity,
        gracePeriod,
        eventData,
        activityData
      };

    } catch (error) {
      // Don't log permission errors as failures
      if (error.message && error.message.includes('Permission denied')) {
        console.log(`🔒 Permission denied checking event ${eventId} - using Firestore data only`);
      } else {
        console.error(`❌ Failed to check live status for event ${eventId}:`, error);
      }
      return {
        isLive: false,
        reason: 'error',
        status: 'error',
        error: error.message
      };
    }
  }

  /**
   * Get all actually live events (filtering out inactive ones)
   * @returns {Promise<Array>} Array of live event IDs with status
   */
  async getActuallyLiveEvents() {
    try {
      const db = getFirestore();
      
      // Get all events marked as 'live'
      const eventsQuery = query(
        collection(db, 'events'),
        where('status', '==', 'live')
      );
      
      const eventsSnapshot = await getDocs(eventsQuery);
      const liveEvents = [];
      const staleEvents = [];

      // Check each event's actual activity
      for (const doc of eventsSnapshot.docs) {
        const eventId = doc.id;
        const liveStatus = await this.checkEventLiveStatus(eventId);
        
        if (liveStatus.isLive) {
          liveEvents.push({
            eventId,
            ...liveStatus
          });
        } else if (liveStatus.shouldCleanup) {
          staleEvents.push({
            eventId,
            ...liveStatus
          });
        }
      }

      console.log(`📊 Live events check:`, {
        totalMarkedLive: eventsSnapshot.docs.length,
        actuallyLive: liveEvents.length,
        staleToCleanup: staleEvents.length
      });

      // Auto-cleanup stale events
      for (const staleEvent of staleEvents) {
        await this.stopActivityTracking(staleEvent.eventId, staleEvent.reason);
      }

      return liveEvents;

    } catch (error) {
      console.error('❌ Failed to get actually live events:', error);
      return [];
    }
  }

  /**
   * Start heartbeat for an event
   * @param {string} eventId - Event ID
   * @param {string} streamerId - Streamer ID
   */
  startHeartbeat(eventId, streamerId) {
    // Stop existing heartbeat if any
    this.stopHeartbeat(eventId);

    const heartbeatInterval = setInterval(async () => {
      try {
        await this.updateActivity(eventId, {
          streamerId,
          heartbeatTime: Date.now()
        });
      } catch (error) {
        console.error(`❌ Heartbeat failed for event ${eventId}:`, error);
        this.stopHeartbeat(eventId);
      }
    }, 30000); // Heartbeat every 30 seconds

    this.activityTrackers.set(eventId, heartbeatInterval);
    console.log(`💓 Heartbeat started for event ${eventId}`);
  }

  /**
   * Stop heartbeat for an event
   * @param {string} eventId - Event ID
   */
  stopHeartbeat(eventId) {
    const heartbeatInterval = this.activityTrackers.get(eventId);
    if (heartbeatInterval) {
      clearInterval(heartbeatInterval);
      this.activityTrackers.delete(eventId);
      console.log(`💓 Heartbeat stopped for event ${eventId}`);
    }
  }

  /**
   * Start background cleanup process
   */
  startBackgroundCleanup() {
    if (this.cleanupInterval) {
      clearInterval(this.cleanupInterval);
    }

    this.cleanupInterval = setInterval(async () => {
      try {
        console.log('🧹 Running background cleanup of stale live events...');
        await this.getActuallyLiveEvents(); // This automatically cleans up stale events
      } catch (error) {
        console.error('❌ Background cleanup failed:', error);
      }
    }, this.CLEANUP_INTERVAL);

    console.log('🧹 Background cleanup started (every 5 minutes)');
  }

  /**
   * Stop background cleanup
   */
  stopBackgroundCleanup() {
    if (this.cleanupInterval) {
      clearInterval(this.cleanupInterval);
      this.cleanupInterval = null;
      console.log('🧹 Background cleanup stopped');
    }
  }

  /**
   * Manually trigger cleanup of all stale events
   */
  async cleanupStaleEvents() {
    console.log('🧹 Manual cleanup of stale events...');
    const liveEvents = await this.getActuallyLiveEvents();
    return liveEvents;
  }

  /**
   * Set event expiration time
   * @param {string} eventId - Event ID
   * @param {number} durationMinutes - Duration in minutes from now
   */
  async setEventExpiration(eventId, durationMinutes) {
    try {
      const db = getFirestore();
      const rtdb = getDatabase();
      const endTime = Date.now() + (durationMinutes * 60 * 1000);

      // Update Firestore
      const eventRef = doc(db, 'events', eventId);
      await updateDoc(eventRef, {
        streamEndTime: endTime,
        updatedAt: serverTimestamp()
      });

      // Update RTDB activity
      const activityRef = ref(rtdb, `eventActivity/${eventId}`);
      await update(activityRef, {
        endTime: endTime
      });

      console.log(`⏰ Event ${eventId} will expire in ${durationMinutes} minutes`);

    } catch (error) {
      console.error(`❌ Failed to set expiration for event ${eventId}:`, error);
      throw error;
    }
  }

  /**
   * Cleanup - stop all trackers
   */
  cleanup() {
    // Stop all heartbeats
    for (const [eventId, interval] of this.activityTrackers) {
      clearInterval(interval);
    }
    this.activityTrackers.clear();

    // Stop background cleanup
    this.stopBackgroundCleanup();

    // Stop all listeners
    for (const [eventId, unsubscribe] of this.statusListeners) {
      unsubscribe();
    }
    this.statusListeners.clear();

    console.log('🧹 EventLiveStatusManager cleanup completed');
  }
}

// Export singleton instance
export const eventLiveStatusManager = new EventLiveStatusManager();
export default eventLiveStatusManager;

// Make available globally for debugging
if (typeof window !== 'undefined') {
  window.eventLiveStatusManager = eventLiveStatusManager;
}