import { useEffect, useMemo, useState } from 'react'
import { Activity, BarChart3, Users, Flame, TrendingUp, TrendingDown } from 'lucide-react'
import { usePredictions } from '../contexts/PredictionContext'
import { useLiveData } from '../contexts/LiveDataContext'
import Card from '../components/common/Card'
import FilterBar from '../components/common/FilterBar'
import SearchBar from '../components/common/SearchBar'
import LiveIndicator from '../components/common/LiveIndicator'
import MyMarketsSelector from '../components/common/MyMarketsSelector'
import PredictionHero from '../components/predictions/PredictionHero'
import PredictionList from '../components/predictions/PredictionList'
import CategoryBreakdown from '../components/charts/CategoryBreakdown'
import {
  getUserMarkets,
  predictionMatchesMarkets,
  deriveMarketTags,
} from '../utils/markets'

function StatCard({ icon: Icon, label, value, color, delta, hint }) {
  // delta: signed number rendered as a small colored movement chip next to
  // the value. `0` is intentionally shown as flat (no chip) since a metric
  // that isn't moving shouldn't fake a direction.
  const showDelta = typeof delta === 'number' && delta !== 0
  const DeltaIcon = delta > 0 ? TrendingUp : TrendingDown
  return (
    <Card className="p-4 flex items-center gap-3" hover={false}>
      <div className={`w-10 h-10 rounded-lg ${color}/15 flex items-center justify-center shrink-0`}>
        <Icon size={20} className={color.replace('bg-', 'text-')} />
      </div>
      <div className="min-w-0" title={hint || undefined}>
        <div className="flex items-baseline gap-1.5">
          <p className="font-mono text-xl font-bold text-gray-100">{value}</p>
          {showDelta && (
            <span className={`inline-flex items-center gap-0.5 text-xs font-mono font-semibold ${delta > 0 ? 'text-emerald-400' : 'text-red-400'}`}>
              <DeltaIcon size={12} />
              {delta > 0 ? '+' : ''}{delta}
            </span>
          )}
        </div>
        <p className="text-xs text-gray-500 truncate">{label}</p>
      </div>
    </Card>
  )
}

export default function Dashboard() {
  const { predictions, allPredictions, loading, filters, setCategory, setSort, setSearch } = usePredictions()
  const { runScan, scanning, lastScan, sources, newsArticles, rssItems, scanCount } = useLiveData()

  // User's markets — re-read on storage/custom event so the Dashboard updates
  // immediately when MyMarketsSelector toggles something.
  const [userMarkets, setUserMarketsState] = useState(() => getUserMarkets())
  useEffect(() => {
    const sync = () => setUserMarketsState(getUserMarkets())
    window.addEventListener('predict:user-markets-changed', sync)
    window.addEventListener('storage', sync)
    return () => {
      window.removeEventListener('predict:user-markets-changed', sync)
      window.removeEventListener('storage', sync)
    }
  }, [])

  // Filter: when user has picked markets, scope the list to predictions that
  // touch those markets (national predictions always pass through).
  const marketFilteredAll = useMemo(
    () => allPredictions.filter(p => predictionMatchesMarkets(p, userMarkets)),
    [allPredictions, userMarkets]
  )
  const marketFilteredVisible = useMemo(
    () => predictions.filter(p => predictionMatchesMarkets(p, userMarkets)),
    [predictions, userMarkets]
  )

  // Auto-scan disabled. Legacy NewsAPI/RSS scanning was tuned for current-
  // events predictions and hit flaky public CORS proxies. Music signal
  // intelligence will come from chart/streaming feeds (Billboard, Spotify
  // Charts, Chartmetric) in Pass 2. Manual "Refresh" button still triggers a
  // scan if a user wants to test the legacy pipeline.
  // (was: runScan(allPredictions) on first load)

  const activePreds = marketFilteredAll.filter(p => p.status === 'active')
  const liveSourceCount = newsArticles.length + rssItems.length

  // Metrics derived from the (scene-scoped) prediction set. These recompute
  // whenever predictions stream in, votes land, or the user changes scenes —
  // so the stat bar reflects the live board rather than a fixed snapshot.
  const trendPrior = p => {
    const td = Array.isArray(p.trendData) ? p.trendData : []
    return td.length >= 2 ? td[td.length - 2] : p.outcomes[0].probability
  }
  const confNow = activePreds.length
    ? activePreds.reduce((sum, p) => sum + p.outcomes[0].probability, 0) / activePreds.length
    : 0
  const confPrior = activePreds.length
    ? activePreds.reduce((sum, p) => sum + trendPrior(p), 0) / activePreds.length
    : 0
  const avgConfidence = Math.round(confNow)
  const confDelta = Math.round(confNow - confPrior)

  // Top mover: the active market with the largest confidence swing across its
  // trend window — the "biggest story right now" for a markets terminal.
  const topMover = activePreds.reduce((best, p) => {
    const td = Array.isArray(p.trendData) ? p.trendData : []
    const change = td.length >= 2 ? td[td.length - 1] - td[0] : 0
    return Math.abs(change) > Math.abs(best.change) ? { p, change } : best
  }, { p: null, change: 0 })

  return (
    <div className="space-y-6">
      <div className="flex items-start justify-between flex-wrap gap-3">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">Dashboard</h1>
          <p className="text-sm text-gray-500 mt-1">Real-time forecasting across music, charts, and culture</p>
        </div>
        <LiveIndicator
          scanning={scanning}
          sources={sources}
          lastScan={lastScan}
          onScan={() => runScan(allPredictions)}
        />
      </div>

      {/* Interest-based personalization: predictions filter by the user's
          selected scenes (localStorage for Pass 1). */}
      <MyMarketsSelector />

      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
        <StatCard icon={Activity} label="Active Predictions" value={activePreds.length} color="bg-blue-500" />
        <StatCard icon={BarChart3} label="Avg Confidence" value={`${avgConfidence}%`} delta={confDelta} color="bg-emerald-500" />
        <StatCard
          icon={Flame}
          label={topMover.p ? `Top Mover · ${topMover.p.title}` : 'Top Mover'}
          hint={topMover.p ? topMover.p.title : undefined}
          value={topMover.p ? `${topMover.change > 0 ? '+' : ''}${topMover.change}%` : '—'}
          color="bg-violet-500"
        />
        <StatCard icon={Users} label="Total Votes" value={marketFilteredAll.reduce((s, p) => s + p.communityVotes.agree + p.communityVotes.disagree, 0).toLocaleString()} color="bg-amber-500" />
      </div>

      <PredictionHero predictions={marketFilteredAll} />

      <div className="md:hidden">
        <SearchBar value={filters.search} onChange={setSearch} />
      </div>

      <FilterBar
        activeCategory={filters.category}
        sortBy={filters.sort}
        onCategoryChange={setCategory}
        onSortChange={setSort}
      />

      <div className="flex gap-6">
        <div className="flex-1 min-w-0">
          {userMarkets.length > 0 && marketFilteredVisible.length === 0 && !loading && (
            <div className="p-4 rounded-lg bg-amber-500/10 border border-amber-500/30 text-amber-200 text-sm mb-4">
              No predictions match your selected scenes yet. Try adding more scenes above, or clear your selection to see everything.
            </div>
          )}
          <PredictionList predictions={marketFilteredVisible} loading={loading} />
        </div>
        <div className="hidden xl:block w-64 shrink-0 space-y-4">
          <Card className="p-4" hover={false}>
            <h3 className="text-sm font-semibold text-gray-300 mb-3">Category Distribution</h3>
            <CategoryBreakdown predictions={marketFilteredAll} />
          </Card>
          <Card className="p-4" hover={false}>
            <h3 className="text-sm font-semibold text-gray-300 mb-3">Quick Stats</h3>
            <div className="space-y-3 text-sm">
              <div className="flex justify-between">
                <span className="text-gray-500">High confidence</span>
                <span className="font-mono text-emerald-400">{marketFilteredAll.filter(p => p.outcomes[0].probability >= 70).length}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-500">Trending up</span>
                <span className="font-mono text-emerald-400">{marketFilteredAll.filter(p => p.outcomes[0].trend === 'up').length}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-500">Trending down</span>
                <span className="font-mono text-red-400">{marketFilteredAll.filter(p => p.outcomes[0].trend === 'down').length}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-500">Community submitted</span>
                <span className="font-mono text-blue-400">{marketFilteredAll.filter(p => p.createdBy?.startsWith('community')).length}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-500">Live articles</span>
                <span className="font-mono text-cyan-400">{liveSourceCount}</span>
              </div>
            </div>
          </Card>
        </div>
      </div>
    </div>
  )
}
