// src/components/SessionManager.jsx
// Component to handle session warnings and notifications for time limits

import React, { useState, useEffect, useCallback } from 'react';
import { useAuth } from '../contexts/AuthContext';
import adManager from '../utils/adManager';
import VideoAdContainer from './ads/VideoAdContainer';

const SessionManager = () => {
  const { currentUser, getRemainingSessionTime } = useAuth();
  const [sessionStatus, setSessionStatus] = useState(null);
  const [showWarning, setShowWarning] = useState(false);
  const [warningMessage, setWarningMessage] = useState('');
  const [showVideoAd, setShowVideoAd] = useState(false);
  const [currentAdType, setCurrentAdType] = useState('video');

  // Memoized session status update function with better error handling
  const updateSessionStatus = useCallback(async (callback) => {
    try {
      if (!currentUser) {
        setSessionStatus(null);
        setShowWarning(false);
        return;
      }

      // Check if getRemainingSessionTime function exists
      if (typeof getRemainingSessionTime !== 'function') {
        console.warn('getRemainingSessionTime is not available');
        return;
      }

      const status = await getRemainingSessionTime();
      setSessionStatus(status);

      // Show warnings based on remaining time
      if (!status.expired && status.remainingTime < 5 * 60 * 1000) { // Less than 5 minutes
        const minutes = Math.floor(status.remainingTime / (60 * 1000));
        const seconds = Math.floor((status.remainingTime % (60 * 1000)) / 1000);
        
        let message = '';
        if (currentUser.isAnonymous) {
          message = `Anonymous session expires in ${minutes}:${seconds.toString().padStart(2, '0')}. Create an account to continue.`;
        } else {
          message = `Session expires in ${minutes}:${seconds.toString().padStart(2, '0')}. Your session will be extended automatically.`;
        }
        
        setWarningMessage(message);
        setShowWarning(true);
      } else {
        setShowWarning(false);
      }

      // Execute callback if provided and is a function
      if (callback && typeof callback === 'function') {
        try {
          callback(status);
        } catch (callbackError) {
          console.error('Error in session status callback:', callbackError);
        }
      }

    } catch (error) {
      console.error('Error updating session status:', error);
      
      // Don't show error to user for session status updates
      // Just log it and continue
    }
  }, [currentUser, getRemainingSessionTime]);

  // Initialize ad manager for anonymous users
  useEffect(() => {
    if (currentUser?.isAnonymous) {
      adManager.initialize();
      adManager.startAnonymousSession();
      
      // Set up ad event listeners
      adManager.on('onShowAd', (adType) => {
        setCurrentAdType(adType);
        setShowVideoAd(true);
      });
      
      adManager.on('onHideAd', () => {
        setShowVideoAd(false);
      });
    } else {
      // Stop ad session for non-anonymous users
      adManager.stopAnonymousSession();
      setShowVideoAd(false);
    }
    
    return () => {
      adManager.off('onShowAd');
      adManager.off('onHideAd');
    };
  }, [currentUser?.isAnonymous]);

  useEffect(() => {
    if (!currentUser) {
      setSessionStatus(null);
      setShowWarning(false);
      return;
    }

    // Initial update
    updateSessionStatus();

    // Set up interval for updates
    const interval = setInterval(() => {
      updateSessionStatus();
    }, 30000); // Every 30 seconds

    // Event listeners with proper error handling
    const handleSessionWarning = (event) => {
      try {
        const { remainingTime, message } = event.detail || {};
        if (message) {
          setWarningMessage(message);
          setShowWarning(true);
        }
      } catch (error) {
        console.error('Error handling session warning event:', error);
      }
    };

    const handleSessionExpired = (event) => {
      try {
        const { wasAnonymous } = event.detail || {};
        if (wasAnonymous) {
          setWarningMessage('Anonymous session expired. Please sign in to continue.');
        } else {
          setWarningMessage('Session expired. Please sign in again.');
        }
        setShowWarning(true);
        setSessionStatus({ expired: true, remainingTime: 0 });
      } catch (error) {
        console.error('Error handling session expired event:', error);
      }
    };

    const handleSessionStatusUpdate = (event) => {
      try {
        const { remainingTime, userType, canJoinEvents, canJoinRooms } = event.detail || {};
        if (remainingTime !== undefined) {
          setSessionStatus({
            remainingTime,
            userType,
            canJoinEvents,
            canJoinRooms,
            expired: false
          });
        }
      } catch (error) {
        console.error('Error handling session status update event:', error);
      }
    };

    // Add event listeners
    window.addEventListener('sessionWarning', handleSessionWarning);
    window.addEventListener('sessionExpired', handleSessionExpired);
    window.addEventListener('sessionStatusUpdate', handleSessionStatusUpdate);

    return () => {
      clearInterval(interval);
      window.removeEventListener('sessionWarning', handleSessionWarning);
      window.removeEventListener('sessionExpired', handleSessionExpired);
      window.removeEventListener('sessionStatusUpdate', handleSessionStatusUpdate);
    };
  }, [currentUser, updateSessionStatus]);

  const formatTime = (milliseconds) => {
    if (!milliseconds || milliseconds < 0) return '0:00';
    
    const minutes = Math.floor(milliseconds / (60 * 1000));
    const seconds = Math.floor((milliseconds % (60 * 1000)) / 1000);
    return `${minutes}:${seconds.toString().padStart(2, '0')}`;
  };

  const handleCreateAccount = () => {
    // Navigate to registration page
    window.location.href = '/signup';
  };

  const handleSignIn = () => {
    // Navigate to login page
    window.location.href = '/login';
  };

  const dismissWarning = () => {
    setShowWarning(false);
  };

  const handleAdComplete = () => {
    adManager.onAdComplete();
  };

  if (!currentUser || !sessionStatus) {
    return null;
  }

  return (
    <>
      {/* Video Ad Container */}
      <VideoAdContainer 
        isVisible={showVideoAd} 
        onAdComplete={handleAdComplete}
        adType={currentAdType}
      />


    </>
  );
};

export default SessionManager;