// src/components/premium/StripeBuyButton.jsx
import React, { useEffect, useState } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { detectEnvironment } from '../../utils/environmentDetection';

const StripeBuyButton = ({ 
  planType = 'monthly', // 'monthly' or 'yearly'
  onSuccess,
  onCancel,
  className = '',
  disabled = false 
}) => {
  const { currentUser } = useAuth();
  const [isLoaded, setIsLoaded] = useState(false);
  const [error, setError] = useState(null);
  const [currentEnv, setCurrentEnv] = useState('dev');

  // Environment detection and configuration
  useEffect(() => {
    const detectedEnv = detectEnvironment();
    setCurrentEnv(detectedEnv);
    
    console.log('StripeBuyButton initialized for environment:', detectedEnv);
  }, []);

  // Environment-specific configurations with correct IDs
  const getEnvironmentConfig = () => {
    switch (currentEnv) {
      case 'dev':
        return {
          name: 'Development',
          stripePublicKey: 'pk_test_REDACTED',
          buyButtonIds: {
            monthly: 'buy_btn_1RRlzKD1B8Z9nCzcoB0Gc0de', // DEV Monthly
            yearly: 'buy_btn_1RTav7D1B8Z9nCzcUUzP6edL'   // DEV Yearly (corrected)
          },
          showPaymentButtons: true,
          environment: 'sandbox'
        };
      case 'test':
        return {
          name: 'Testing',
          stripePublicKey: 'pk_test_REDACTED',
          buyButtonIds: {
            monthly: 'buy_btn_1RRlpSDfOv6NEd1s4gZKZQiu', // TEST Monthly
            yearly: 'buy_btn_1RTaiRDfOv6NEd1s6wl2cXj3'   // TEST Yearly (corrected)
          },
          showPaymentButtons: true,
          environment: 'test_sandbox'
        };
      case 'prod':
      default:
        return {
          name: 'Production',
          stripePublicKey: 'pk_live_REDACTED',
          buyButtonIds: {
            monthly: 'buy_btn_1RRluSDfOv6NEd1s36tcwrND', // PROD Monthly (corrected)
            yearly: 'buy_btn_1RRzCWDfOv6NEd1sF7FcPCZB'   // PROD Yearly (corrected)

          },
          showPaymentButtons: true,
          environment: 'production'
        };
    }
  };

  // Load Stripe Buy Button script (only in dev/test)
  useEffect(() => {
    const config = getEnvironmentConfig();
    
    if (!config.showPaymentButtons) {
      setIsLoaded(true);
      return;
    }

    const loadStripeScript = () => {
      return new Promise((resolve, reject) => {
        // Check if script is already loaded
        if (document.querySelector('script[src="https://js.stripe.com/v3/buy-button.js"]')) {
          setIsLoaded(true);
          resolve();
          return;
        }

        const script = document.createElement('script');
        script.src = 'https://js.stripe.com/v3/buy-button.js';
        script.async = true;
        script.onload = () => {
          setIsLoaded(true);
          resolve();
        };
        script.onerror = () => {
          setError('Failed to load Stripe Buy Button script');
          reject(new Error('Failed to load Stripe script'));
        };

        document.head.appendChild(script);
      });
    };

    loadStripeScript().catch(err => {
      console.error('Error loading Stripe script:', err);
      setError(err.message);
    });
  }, [currentEnv]);

  // Handle Stripe events (only in dev/test)
  useEffect(() => {
    const config = getEnvironmentConfig();
    
    if (!config.showPaymentButtons || !isLoaded) return;

    const handleStripeEvents = () => {
      // Listen for successful payments
      window.addEventListener('stripe_buy_button_success', (event) => {
        console.log('Stripe payment successful:', event.detail);
        if (onSuccess) {
          onSuccess({
            ...event.detail,
            environment: currentEnv,
            stripeEnvironment: config.environment
          });
        }
      });

      // Listen for cancelled payments
      window.addEventListener('stripe_buy_button_cancel', (event) => {
        console.log('Stripe payment cancelled:', event.detail);
        if (onCancel) {
          onCancel({
            ...event.detail,
            environment: currentEnv,
            stripeEnvironment: config.environment
          });
        }
      });
    };

    handleStripeEvents();

    return () => {
      window.removeEventListener('stripe_buy_button_success', () => {});
      window.removeEventListener('stripe_buy_button_cancel', () => {});
    };
  }, [isLoaded, currentEnv, onSuccess, onCancel]);

  const config = getEnvironmentConfig();

  const planDetails = {
    monthly: {
      name: 'Monthly Plan',
      price: '$9.99/month',
      description: 'Full access to all premium features'
    },
    yearly: {
      name: 'Yearly Plan', 
      price: '$99.99/year',
      description: 'Save $19.89 compared to monthly'
    }
  };

  const handleContactSales = () => {
    const subject = `Premium Membership Inquiry - ${planDetails[planType].name}`;
    const body = `I am interested in the ${planDetails[planType].name} (${planDetails[planType].price}).`;
    window.location.href = `mailto:sales@talkstudio.space?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
  };

  if (!currentUser) {
    return (
      <div className={`stripe-buy-button-auth-required ${className}`}>
        <p className="text-center text-gray-600 mb-4">Please log in to purchase premium membership.</p>
        <button 
          onClick={() => window.location.href = '/login'}
          className="w-full bg-gray-500 hover:bg-gray-600 text-white font-semibold py-3 px-6 rounded-lg transition-colors"
        >
          Log In to Continue
        </button>
      </div>
    );
  }

  // Show Contact Sales button in production
  if (!config.showPaymentButtons) {
    return (
      <div className={`stripe-buy-button-container ${className}`}>
        <button
          onClick={handleContactSales}
          disabled={disabled}
          className={`w-full bg-blue-600 hover:bg-blue-700 disabled:bg-gray-400 text-white font-semibold py-3 px-6 rounded-lg transition-colors ${disabled ? 'cursor-not-allowed' : 'cursor-pointer'}`}
        >
          Contact Sales for {planDetails[planType].name}
        </button>
        
        <div className="text-center mt-2">
          <small className="text-gray-500">
            {planDetails[planType].price} • {planDetails[planType].description}
          </small>
        </div>
      </div>
    );
  }

  // Show error state
  if (error) {
    return (
      <div className={`stripe-buy-button-error ${className}`}>
        <p className="text-red-600 mb-2">Error loading payment system: {error}</p>
        <button 
          onClick={() => window.location.reload()} 
          className="w-full bg-gray-500 hover:bg-gray-600 text-white font-semibold py-2 px-4 rounded transition-colors"
        >
          Retry
        </button>
      </div>
    );
  }

  // Show loading state
  if (!isLoaded) {
    return (
      <div className={`stripe-buy-button-loading ${className}`}>
        <div className="flex items-center justify-center py-4">
          <div className="animate-spin rounded-full h-6 w-6 border-t-2 border-b-2 border-blue-500 mr-3"></div>
          <p className="text-gray-600">Loading payment system...</p>
        </div>
      </div>
    );
  }

  // Show Stripe Buy Button (dev/test/prod environments)
  return (
    <div className={`stripe-buy-button-container ${className}`}>
      {/* Environment indicator for development/testing */}
      {currentEnv !== 'prod' && (
        <div className="environment-indicator mb-2">
          <small className="text-blue-600">
            🧪 {config.name.toUpperCase()} MODE ({config.environment}) - {window.location.hostname}
          </small>
        </div>
      )}
      
      {/* Wrapper to ensure consistent styling across environments */}
      <div className="stripe-button-wrapper" style={{
        width: '100%',
        minHeight: '50px',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'stretch'
      }}>
        <stripe-buy-button
          buy-button-id={config.buyButtonIds[planType]}
          publishable-key={config.stripePublicKey}
          customer-email={currentUser.email}
          disabled={disabled}
        />
      </div>
      
      {/* Debug info for development */}
      {currentEnv === 'dev' && (
        <div className="debug-info mt-2" style={{ fontSize: '12px', color: '#666' }}>
          <details>
            <summary>Debug Info</summary>
            <pre style={{ fontSize: '10px', background: '#f5f5f5', padding: '8px', borderRadius: '4px' }}>
              {JSON.stringify({
                environment: currentEnv,
                stripeEnvironment: config.environment,
                hostname: window.location.hostname,
                planType: planType,
                buyButtonId: config.buyButtonIds[planType],
                publishableKey: config.stripePublicKey?.substring(0, 20) + '...',
                userEmail: currentUser?.email
              }, null, 2)}
            </pre>
          </details>
        </div>
      )}
    </div>
  );
};

export default StripeBuyButton;