// src/components/audio/SmartMic.jsx
//
// One mic, three branches running in parallel.
//
// On tap:
//   1) Start MediaRecorder capturing audio for ~8 seconds (with early-stop)
//   2) Concurrently launch:
//        a) Web Speech API (useSpeechSearch) — transcribes any speech it hears
//        b) AudioMatchingService.findMatchingRoom — fingerprint room match
//        c) (after recording stops) prepare blob for dream-sketch fallback
//
// First confident branch wins:
//   - Speech (confidence ≥ 0.5)        → navigate /search?q=<transcript>
//   - Match (similarity ≥ threshold)   → navigate /room/<roomId>
//   - Neither confident                → stash blob, navigate /sketch?from=mic
//
// Replaces AudioMatcherImproved on the home page.

import React, { useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Mic, Square, Loader, Search, MessageCircle, Sparkles } from 'lucide-react';

import { useSpeechSearch } from '../../hooks/useSpeechSearch';
import { useAudioDetectionFixed } from '../../hooks/useAudioDetectionFixed';
import { AudioMatchingService } from '../../services/AudioMatchingService';
import { useAuth } from '../../contexts/AuthContext';
import { getDb, getRtdb } from '../../firebase';

import { SMARTMIC_BLOB_KEY } from '../../pages/SketchPage';

const CAPTURE_MS = 8000;

const SmartMic = () => {
  const navigate = useNavigate();
  const { currentUser } = useAuth();
  const speech = useSpeechSearch({ timeoutMs: CAPTURE_MS });
  const audioDetection = useAudioDetectionFixed();

  const [phase, setPhase] = useState('idle'); // idle | listening | resolving
  const [error, setError] = useState(null);

  const mediaRecorderRef = useRef(null);
  const streamRef = useRef(null);
  const chunksRef = useRef([]);
  const matchingServiceRef = useRef(null);

  const getMatchingService = () => {
    if (!matchingServiceRef.current) {
      matchingServiceRef.current = new AudioMatchingService(getDb(), getRtdb());
    }
    return matchingServiceRef.current;
  };

  const reset = () => {
    setPhase('idle');
    setError(null);
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(t => t.stop());
      streamRef.current = null;
    }
  };

  const blobToDataUrl = (blob) =>
    new Promise((resolve, reject) => {
      const r = new FileReader();
      r.onerror = reject;
      r.onloadend = () => resolve(r.result);
      r.readAsDataURL(blob);
    });

  const stashRecordingForSketch = async (blob) => {
    try {
      const dataUrl = await blobToDataUrl(blob);
      sessionStorage.setItem(SMARTMIC_BLOB_KEY, dataUrl);
    } catch (e) {
      // Most likely sessionStorage quota — sketch page just won't preload audio
      // eslint-disable-next-line no-console
      console.warn('[SmartMic] could not stash recording:', e);
    }
  };

  const listen = async () => {
    setError(null);
    setPhase('listening');

    // (a) Kick off speech recognition immediately (it owns its own mic stream).
    const speechPromise = speech.supported
      ? speech.start().catch(() => null)
      : Promise.resolve(null);

    // (b) Start MediaRecorder for the fingerprint + fallback blob.
    let recordedBlob = null;
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          channelCount: 1,
          sampleRate: 44100,
          echoCancellation: true,
          noiseSuppression: true,
        },
      });
      streamRef.current = stream;
      const rec = new MediaRecorder(stream);
      mediaRecorderRef.current = rec;
      chunksRef.current = [];

      const recDone = new Promise((resolve) => {
        rec.ondataavailable = (e) => { if (e.data.size > 0) chunksRef.current.push(e.data); };
        rec.onstop = () => {
          recordedBlob = new Blob(chunksRef.current, { type: 'audio/webm' });
          stream.getTracks().forEach(t => t.stop());
          resolve(recordedBlob);
        };
      });

      rec.start();
      const stopTimer = setTimeout(() => {
        if (rec.state === 'recording') rec.stop();
      }, CAPTURE_MS);

      const blob = await recDone;
      clearTimeout(stopTimer);

      // (c) Start fingerprint match in parallel; speech may have already resolved.
      setPhase('resolving');

      const matchPromise = (async () => {
        try {
          const ctx = new (window.AudioContext || window.webkitAudioContext)();
          const fingerprint = await audioDetection.processAudioData(blob, ctx);
          ctx.close();
          const matchingService = getMatchingService();
          const room = await matchingService.findMatchingRoom(
            fingerprint,
            currentUser?.uid,
          );
          return { room, fingerprint };
        } catch (e) {
          // eslint-disable-next-line no-console
          console.warn('[SmartMic] fingerprint branch failed:', e);
          return null;
        }
      })();

      // ---------- Race: whichever resolves first with a confident result wins ----------
      // We don't use Promise.race because we want to wait for BOTH to settle
      // before falling back to sketch — speech may finish first with null while
      // fingerprint is still going, etc.
      const [speechResult, matchResult] = await Promise.all([speechPromise, matchPromise]);

      if (speechResult && speechResult.transcript) {
        navigate(`/search?q=${encodeURIComponent(speechResult.transcript)}`);
        reset();
        return;
      }
      if (matchResult && matchResult.room && matchResult.room.roomId) {
        navigate(`/room/${matchResult.room.roomId}`);
        reset();
        return;
      }

      // ---------- Fallback: send the blob to the sketch page ----------
      if (blob) await stashRecordingForSketch(blob);
      navigate('/sketch?from=mic');
      reset();
    } catch (e) {
      // eslint-disable-next-line no-console
      console.error('[SmartMic] error:', e);
      setError(e.message || 'Could not access microphone.');
      reset();
    }
  };

  const cancel = () => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state === 'recording') {
      mediaRecorderRef.current.stop();
    }
    speech.stop();
    reset();
  };

  // -------------------- Render --------------------
  return (
    <div style={{ padding: '1.25rem 1rem 1.5rem', textAlign: 'center' }}>
      <div
        style={{
          margin: '0 auto',
          width: 140,
          height: 140,
          borderRadius: '50%',
          background: phase === 'idle'
            ? 'radial-gradient(circle at 30% 30%, #8b5cf6, #4f46e5)'
            : phase === 'listening'
              ? 'radial-gradient(circle at 30% 30%, #ec4899, #be185d)'
              : 'radial-gradient(circle at 30% 30%, #06b6d4, #0e7490)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          color: 'white',
          cursor: phase === 'idle' ? 'pointer' : 'default',
          boxShadow: phase === 'listening' ? '0 0 0 0 rgba(236,72,153,0.6)' : '0 6px 20px rgba(99,102,241,0.35)',
          animation: phase !== 'idle' ? 'smartmic-pulse 1.6s ease-in-out infinite' : 'none',
          transition: 'background 0.3s',
        }}
        onClick={phase === 'idle' ? listen : undefined}
        role="button"
        aria-label={phase === 'idle' ? 'Tap to listen' : 'Listening…'}
      >
        {phase === 'idle' && <Mic size={48} />}
        {phase === 'listening' && <Square size={36} fill="white" />}
        {phase === 'resolving' && <Loader size={42} className="smartmic-spin" />}
      </div>

      <div style={{ marginTop: 14, fontSize: 13, color: '#a5b4fc', letterSpacing: '0.08em', textTransform: 'uppercase' }}>
        {phase === 'idle' && 'Tap to listen'}
        {phase === 'listening' && 'Listening…'}
        {phase === 'resolving' && 'Finding the conversation…'}
      </div>

      {phase === 'listening' && (
        <button
          onClick={cancel}
          style={{
            marginTop: 12,
            background: 'transparent',
            border: '1px solid rgba(255,255,255,0.18)',
            color: '#cbd5e1',
            padding: '6px 12px',
            borderRadius: 6,
            cursor: 'pointer',
            fontSize: 12,
          }}
        >
          Cancel
        </button>
      )}

      {error && (
        <div style={{ marginTop: 12, color: '#fca5a5', fontSize: 13 }}>{error}</div>
      )}

      <div style={{ marginTop: 18, display: 'grid', gap: 6, fontSize: 11, color: '#64748b' }}>
        <Hint icon={<Search size={12} />} label="Speak — search rooms, artists, streams" />
        <Hint icon={<MessageCircle size={12} />} label="Play something — match into a live conversation" />
        <Hint icon={<Sparkles size={12} />} label="Hum — start a jam, play over it, share it" />
      </div>

      <style>{`
        @keyframes smartmic-pulse {
          0%, 100% { box-shadow: 0 0 0 0 rgba(236, 72, 153, 0.45); }
          50%      { box-shadow: 0 0 0 18px rgba(236, 72, 153, 0); }
        }
        .smartmic-spin { animation: smartmic-spin 1s linear infinite; }
        @keyframes smartmic-spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
      `}</style>
    </div>
  );
};

const Hint = ({ icon, label }) => (
  <div style={{ display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6 }}>
    {icon} {label}
  </div>
);

export default SmartMic;
