import React, { useState, useEffect } from 'react';
import { useFirebaseTraceManager, generateFirebaseRules } from './FirebaseTraceManager';
import { saveGeneratedRules } from '../../services/FirebaseTracerService';
import { useAuth } from '../../contexts/AuthContext';
import { getFirebaseModule } from '../../utils/firebaseTracingToggle';
import FirebaseTraceTest from '../../utils/FirebaseTraceDirectTest';
import './TraceCommand.css';

const TraceCommand = ({ onPathsGenerated }) => {
  const [isTracing, setIsTracing] = useState(false);
  const [tracedPaths, setTracedPaths] = useState([]);
  const { currentUser } = useAuth();
  const [isTestingFirebase, setIsTestingFirebase] = useState(false);
  const [isDebugging, setIsDebugging] = useState(false);
  const [testResults, setTestResults] = useState(null);
  const [ruleTemplates, setRuleTemplates] = useState({
    database: {
      read: "auth != null",
      write: "auth != null"
    },
    firestore: {
      read: "request.auth != null",
      write: "request.auth != null"
    }
  });

  // Get tracing manager functions
  const traceManager = useFirebaseTraceManager();

  useEffect(() => {
    // Check if tracing was already active (e.g. from a previous session)
    if (traceManager.isTracing()) {
      setIsTracing(true);
      const currentPaths = traceManager.getTracedPaths();
      if (currentPaths.length > 0) {
        setTracedPaths(currentPaths);
      }
    }
  }, []);

  const startTracing = () => {
    traceManager.startTracing();
    setIsTracing(true);
    setTracedPaths([]);
  };

  const stopTracing = () => {
    const paths = traceManager.stopTracing();
    setIsTracing(false);
    setTracedPaths(paths);
  };

  const handleRuleTemplateChange = (dbType, ruleType, value) => {
    setRuleTemplates(prev => ({
      ...prev,
      [dbType]: {
        ...prev[dbType],
        [ruleType]: value
      }
    }));
  };

  const generateRulesFile = async () => {
    const rules = generateFirebaseRules(tracedPaths, ruleTemplates);
    
    // Download the rules files
    downloadRules('database-rules.json', rules.database);
    downloadRules('firestore-rules.rules', rules.firestore);
    
    // Save the generated rules to the audit system if a callback was provided
    if (onPathsGenerated) {
      onPathsGenerated(tracedPaths, rules);
    }
    
    // If currentUser exists, save the rules to the database
    if (currentUser) {
      try {
        await saveGeneratedRules(currentUser.uid, rules);
      } catch (error) {
        console.error('Error saving generated rules:', error);
      }
    }
  };

  const downloadRules = (filename, content) => {
    const element = document.createElement('a');
    const file = new Blob([content], {type: 'text/plain'});
    element.href = URL.createObjectURL(file);
    element.download = filename;
    document.body.appendChild(element);
    element.click();
    document.body.removeChild(element);
  };

  // Function to test Firebase operations with tracing enabled
  const testFirebaseOperations = async () => {
    if (!isTracing) {
      alert('Please start tracing first');
      return;
    }
    
    setIsTestingFirebase(true);
    setTestResults(null);
    
    try {
      console.log('Starting Firebase operations test...');
      
      // Dynamically import Firebase from traced module
      const firebase = await getFirebaseModule();
      console.log('Firebase module loaded:', firebase);
      
      // Get references to Firestore
      const { db } = firebase;
      const { collection, doc, getDoc, getDocs, query, where } = firebase;
      
      // Test operations
      try {
        // Test Firestore collection access
        console.log('Testing Firestore collection access...');
        const usersCollection = collection(db, 'users');
        const usersSnapshot = await getDocs(usersCollection);
        console.log(`Found ${usersSnapshot.size} users`);
        
        // Test Firestore document access
        console.log('Testing Firestore document access...');
        const configDoc = doc(db, 'settings', 'app_config');
        const configSnapshot = await getDoc(configDoc);
        console.log('Config exists:', configSnapshot.exists());
        
        // Test Firestore query
        console.log('Testing Firestore query...');
        const activeQuery = query(usersCollection, where('active', '==', true));
        const activeSnapshot = await getDocs(activeQuery);
        console.log(`Found ${activeSnapshot.size} active users`);
        
        setTestResults({
          success: true,
          message: 'Firebase operations completed successfully',
          users: usersSnapshot.size,
          configExists: configSnapshot.exists(),
          activeUsers: activeSnapshot.size
        });
      } catch (firestoreError) {
        console.error('Firestore operations failed:', firestoreError);
      }
      
      // Try Realtime Database if Firestore failed
      try {
        // Test Realtime DB access
        console.log('Testing Realtime Database access...');
        const { rtdb } = firebase;
        const { ref, get, onValue } = firebase;
        
        const statusRef = ref(rtdb, 'status');
        const statusSnapshot = await get(statusRef);
        console.log('Status exists:', statusSnapshot.exists());
        
        const usersRef = ref(rtdb, 'users');
        const usersSnapshot = await get(usersRef);
        console.log('Users exists:', usersSnapshot.exists());
        
        setTestResults(prev => ({
          ...prev,
          rtdb: {
            success: true,
            statusExists: statusSnapshot.exists(),
            usersExists: usersSnapshot.exists()
          }
        }));
      } catch (rtdbError) {
        console.error('Realtime Database operations failed:', rtdbError);
        setTestResults(prev => ({
          ...prev,
          rtdb: {
            success: false,
            error: rtdbError.message
          }
        }));
      }
      
      // Get the traced paths
      const paths = traceManager.getTracedPaths();
      console.log('Final traced paths:', paths);
      setTracedPaths(paths);
    } catch (error) {
      console.error('Error during Firebase test:', error);
      setTestResults({
        success: false,
        error: error.message
      });
    } finally {
      setIsTestingFirebase(false);
    }
  };

  // Run advanced debug tests
  const runDebugTests = async () => {
    if (!isTracing) {
      alert('Please start tracing first');
      return;
    }
    
    setIsDebugging(true);
    
    try {
      // Run the test suite
      const results = await FirebaseTraceTest.runTest();
      
      // Update the traced paths
      const paths = traceManager.getTracedPaths();
      setTracedPaths(paths);
      
      // Show a summary notification
      if (results.allPassed) {
        alert('All trace tests passed! The path tracer is working correctly.');
      } else {
        alert('Some trace tests failed. Check the browser console for details.');
      }
    } catch (error) {
      console.error('Error during debug tests:', error);
      alert(`Error during debug tests: ${error.message}`);
    } finally {
      setIsDebugging(false);
    }
  };

  return (
    <div className="trace-command-container">
      <h2>Firebase Path Tracer</h2>
      <p>Track which Firebase paths your application accesses and generate security rules based on actual usage.</p>
      
      <div className="trace-controls">
        {!isTracing ? (
          <button onClick={startTracing} className="start-trace-btn">Start Tracing</button>
        ) : (
          <button onClick={stopTracing} className="stop-trace-btn">Stop Tracing</button>
        )}
        
        {isTracing && (
          <>
            <button 
              onClick={testFirebaseOperations}
              disabled={isTestingFirebase}
              className="test-firebase-btn"
            >
              {isTestingFirebase ? 'Testing...' : 'Test Firebase Access'}
            </button>
            
            <button
              onClick={runDebugTests}
              disabled={isDebugging}
              className="debug-btn"
            >
              {isDebugging ? 'Debugging...' : 'Run Advanced Tests'}
            </button>
          </>
        )}
        
        {tracedPaths.length > 0 && (
          <button onClick={generateRulesFile} className="generate-rules-btn">Generate Rules Files</button>
        )}
      </div>
      
      {isTracing && (
        <div className="tracing-indicator">
          <span className="pulse"></span> Tracing active - use your application to track Firebase path access
        </div>
      )}
      
      {testResults && (
        <div className="test-results-container">
          <h3>Firebase Test Results</h3>
          <div className={`test-status ${testResults.success ? 'success' : 'error'}`}>
            <span className="status-icon">{testResults.success ? '✓' : '✗'}</span>
            <span>{testResults.message || (testResults.success ? 'Test completed successfully' : 'Test failed')}</span>
          </div>
          
          <div className="test-details">
            <pre>{JSON.stringify(testResults, null, 2)}</pre>
          </div>
        </div>
      )}
      
      {tracedPaths.length > 0 && (
        <>
          <div className="rule-templates">
            <h3>Rule Templates</h3>
            <div className="template-section">
              <h4>Realtime Database</h4>
              <div className="template-input">
                <label>Read Rule:</label>
                <input 
                  type="text" 
                  value={ruleTemplates.database.read} 
                  onChange={(e) => handleRuleTemplateChange('database', 'read', e.target.value)}
                />
              </div>
              <div className="template-input">
                <label>Write Rule:</label>
                <input 
                  type="text" 
                  value={ruleTemplates.database.write} 
                  onChange={(e) => handleRuleTemplateChange('database', 'write', e.target.value)}
                />
              </div>
            </div>
            
            <div className="template-section">
              <h4>Firestore</h4>
              <div className="template-input">
                <label>Read Rule:</label>
                <input 
                  type="text" 
                  value={ruleTemplates.firestore.read} 
                  onChange={(e) => handleRuleTemplateChange('firestore', 'read', e.target.value)}
                />
              </div>
              <div className="template-input">
                <label>Write Rule:</label>
                <input 
                  type="text" 
                  value={ruleTemplates.firestore.write} 
                  onChange={(e) => handleRuleTemplateChange('firestore', 'write', e.target.value)}
                />
              </div>
            </div>
          </div>
          
          <div className="traced-paths-container">
            <h3>Traced Paths ({tracedPaths.length})</h3>
            <ul className="path-list">
              {tracedPaths.map((path, index) => (
                <li key={index}>{path}</li>
              ))}
            </ul>
          </div>
        </>
      )}
    </div>
  );
};

export default TraceCommand;