import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { getFirestore, collection, getDocs, query, limit, orderBy, getDoc, doc } from 'firebase/firestore';
import {
  Users,
  MessageSquare,
  Settings,
  Bell,
  AlertTriangle,
  Music,
  Image,
  Activity,
  Database,
  Bot,
  Shield,
  Crown
} from 'lucide-react';

import './AdminDashboard.css';

const AdminDashboard = () => {
  const { currentUser } = useAuth();
  const [stats, setStats] = useState({
    totalUsers: 0,
    totalRooms: 0,
    premiumUsers: 0,
    recentReports: 0,
    activeStreams: 0,
    systemStatus: 'Operational'
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchStats = async () => {
      setLoading(true);
      const db = getFirestore();
      
      try {
        // Fetch total users count
        const usersQuery = query(collection(db, 'users'), limit(1000));
        const usersSnapshot = await getDocs(usersQuery);
        const totalUsers = usersSnapshot.size;
        
        // Count premium users
        let premiumCount = 0;
        usersSnapshot.forEach(doc => {
          const userData = doc.data();
          if (userData.isPremium === true) {
            premiumCount++;
          }
        });
        
        // Fetch rooms count
        const roomsQuery = query(collection(db, 'rooms'), limit(1000));
        const roomsSnapshot = await getDocs(roomsQuery);
        const totalRooms = roomsSnapshot.size;
        
        // Fetch recent reports count
        const reportsQuery = query(
          collection(db, 'reports'), 
          orderBy('createdAt', 'desc'), 
          limit(100)
        );
        const reportsSnapshot = await getDocs(reportsQuery);
        const recentReports = reportsSnapshot.size;
        
        // Check active streams
        const streamsDoc = await getDoc(doc(db, 'streams', 'currentStream'));
        const activeStreams = streamsDoc.exists() && streamsDoc.data().isLive ? 1 : 0;
        
        // Check system status
        const configDoc = await getDoc(doc(db, 'system', 'config'));
        let systemStatus = 'Operational';
        if (configDoc.exists()) {
          const config = configDoc.data();
          if (config.maintenance && config.maintenance.enabled) {
            systemStatus = 'Maintenance Mode';
          } else if (config.issues && config.issues.length > 0) {
            systemStatus = 'Issues Detected';
          }
        }
        
        setStats({
          totalUsers,
          totalRooms,
          premiumUsers: premiumCount,
          recentReports,
          activeStreams,
          systemStatus
        });
      } catch (error) {
        console.error('Error fetching admin stats:', error);
      } finally {
        setLoading(false);
      }
    };
    
    fetchStats();
  }, []);

  const getStatusClass = (status) => {
    switch (status) {
      case 'Operational':
        return 'status-operational';
      case 'Maintenance Mode':
        return 'status-maintenance';
      case 'Issues Detected':
        return 'status-issues';
      default:
        return '';
    }
  };

  const adminModules = [
    {
      name: 'User Management',
      description: 'View and manage all registered users',
      icon: <Users />,
      link: '/admin/users'
    },
    {
      name: 'Subscription Management',
      description: 'Manage user subscriptions and premium access',
      icon: <Crown />,
      link: '/admin/subscriptions'
    },
    {
      name: 'Admin Roles',
      description: 'Manage admin permissions and privileges',
      icon: <Shield />,
      link: '/admin/users/roles'
    },
    {
      name: 'Content Moderation',
      description: 'Review and moderate user content and reports',
      icon: <AlertTriangle />,
      link: '/admin/moderation'
    },
    {
      name: 'Bot Configuration',
      description: 'Manage moderation bots and automated messages',
      icon: <Bot />,
      link: '/admin/bot-management'
    },
    {
      name: 'Background Manager',
      description: 'Manage room backgrounds and assets',
      icon: <Image />,
      link: '/admin/background-manager'
    },
    {
      name: 'Audio Detection',
      description: 'Configure audio detection and matching',
      icon: <Music />,
      link: '/admin/audio-detection'
    },
    {
      name: 'Announcements',
      description: 'Create and manage system announcements',
      icon: <Bell />,
      link: '/admin/announcements'
    },
    {
      name: 'System Settings',
      description: 'Adjust global system settings',
      icon: <Settings />,
      link: '/admin/settings'
    },
    {
      name: 'Stream Management',
      description: 'Monitor and manage active streams',
      icon: <Activity />,
      link: '/admin/streams'
    }
  ];

  return (
    <div className="admin-dashboard">
      <header className="admin-header">
        <div className="admin-title">
          <Shield className="admin-icon" />
          <h1>Admin Dashboard</h1>
        </div>
        <div className="admin-user">
          Logged in as: <strong>{currentUser?.displayName || currentUser?.email}</strong>
        </div>
      </header>

      <div className="admin-stats-container">
        <h2>System Overview</h2>
        {loading ? (
          <div className="loading-spinner"></div>
        ) : (
          <div className="admin-stats">
            <div className="stat-card">
              <div className="stat-icon"><Users /></div>
              <div className="stat-value">{stats.totalUsers}</div>
              <div className="stat-label">Total Users</div>
            </div>
            <div className="stat-card">
              <div className="stat-icon"><MessageSquare /></div>
              <div className="stat-value">{stats.totalRooms}</div>
              <div className="stat-label">Total Rooms</div>
            </div>
            <div className="stat-card">
              <div className="stat-icon"><Users /></div>
              <div className="stat-value">{stats.premiumUsers}</div>
              <div className="stat-label">Premium Users</div>
            </div>
            <div className="stat-card">
              <div className="stat-icon"><AlertTriangle /></div>
              <div className="stat-value">{stats.recentReports}</div>
              <div className="stat-label">Recent Reports</div>
            </div>
            <div className="stat-card">
              <div className="stat-icon"><Activity /></div>
              <div className="stat-value">{stats.activeStreams}</div>
              <div className="stat-label">Active Streams</div>
            </div>
            <div className="stat-card">
              <div className="stat-icon"><Database /></div>
              <div className={`stat-value ${getStatusClass(stats.systemStatus)}`}>
                {stats.systemStatus}
              </div>
              <div className="stat-label">System Status</div>
            </div>
          </div>
        )}
      </div>

      <div className="admin-modules">
        <h2>Admin Modules</h2>
        <div className="module-grid">
          {adminModules.map((module, index) => (
            <Link to={module.link} className="module-card" key={index}>
              <div className="module-icon">{module.icon}</div>
              <h3 className="module-name">{module.name}</h3>
              <p className="module-description">{module.description}</p>
            </Link>
          ))}
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;
