import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { 
  MessageSquare, 
  Plus,
  Save, 
  Trash, 
  ChevronLeft, 
  Edit, 
  Check, 
  X, 
  RefreshCw,
  Play,
  TestTube
} from 'lucide-react';

import TestBotInteraction from './TestBotInteraction';

// Import the BotMessageService
import { BotMessageService } from '../services/BotMessageService.js';
import { rtdb } from '../firebase';
import { ref, get } from 'firebase/database';

import './BotMessageConfig.css';

/**
 * Admin component for managing bot message templates
 */
const BotMessageConfig = () => {
  const { roomId } = useParams();
  const navigate = useNavigate();
  
  const [templates, setTemplates] = useState({});
  const [loading, setLoading] = useState(true);
  const [messageType, setMessageType] = useState('welcome');
  const [selectedVariant, setSelectedVariant] = useState('default');
  const [editMode, setEditMode] = useState(false);
  const [editContent, setEditContent] = useState('');
  const [originalContent, setOriginalContent] = useState('');
  const [newVariantName, setNewVariantName] = useState('');
  const [isAddingVariant, setIsAddingVariant] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(null);
  const [previewVariables, setPreviewVariables] = useState({ roomName: 'Example Room' });
  const [room, setRoom] = useState(null);
  const [roomConfig, setRoomConfig] = useState({});
  
  useEffect(() => {
    loadTemplates();
    
    if (roomId) {
      loadRoomDetails();
    }
  }, [roomId]);
  
  const loadTemplates = async () => {
    setLoading(true);
    try {
      const templates = BotMessageService.getAllTemplates();
      setTemplates(templates);
      
      // Select first available type and variant
      if (Object.keys(templates).length > 0) {
        const firstType = Object.keys(templates)[0];
        setMessageType(firstType);
        
        if (templates[firstType] && Object.keys(templates[firstType]).length > 0) {
          setSelectedVariant('default');
          setEditContent(templates[firstType]['default'] || '');
          setOriginalContent(templates[firstType]['default'] || '');
        }
      }
      
      setLoading(false);
    } catch (error) {
      console.error('Error loading templates:', error);
      setError('Failed to load message templates');
      setLoading(false);
    }
  };
  
  const loadRoomDetails = async () => {
    try {
      const roomRef = ref(rtdb, `chats/public/${roomId}`);
      const snapshot = await get(roomRef);
      
      if (snapshot.exists()) {
        const roomData = snapshot.val();
        setRoom(roomData);
        
        // Set preview variables from room data
        setPreviewVariables({
          roomName: roomData.name || 'Chat Room'
        });
        
        // Load room bot configuration
        const roomBotConfig = roomData.botConfig || {};
        setRoomConfig(roomBotConfig);
      } else {
        setError('Room not found');
      }
    } catch (error) {
      console.error('Error loading room details:', error);
      setError('Failed to load room details');
    }
  };
  
  const handleSelectMessageType = (type) => {
    setMessageType(type);
    setSelectedVariant('default');
    setEditMode(false);
    
    if (templates[type] && templates[type]['default']) {
      setEditContent(templates[type]['default']);
      setOriginalContent(templates[type]['default']);
    }
  };
  
  const handleSelectVariant = (variant) => {
    setSelectedVariant(variant);
    setEditMode(false);
    
    if (templates[messageType] && templates[messageType][variant]) {
      setEditContent(templates[messageType][variant]);
      setOriginalContent(templates[messageType][variant]);
    }
  };
  
  const handleStartEdit = () => {
    setEditMode(true);
  };
  
  const handleCancelEdit = () => {
    setEditMode(false);
    setEditContent(originalContent);
  };
  
  const handleSaveTemplate = async () => {
    try {
      setSaving(true);
      await BotMessageService.saveMessageTemplate(messageType, selectedVariant, editContent);
      
      // Update local state
      setTemplates(prev => ({
        ...prev,
        [messageType]: {
          ...prev[messageType],
          [selectedVariant]: editContent
        }
      }));
      
      setOriginalContent(editContent);
      setEditMode(false);
      setSaving(false);
    } catch (error) {
      console.error('Error saving template:', error);
      setError('Failed to save template');
      setSaving(false);
    }
  };
  
  const handleDeleteVariant = async () => {
    // Can't delete default variant
    if (selectedVariant === 'default') {
      setError('Cannot delete the default variant');
      return;
    }
    
    if (!window.confirm(`Are you sure you want to delete the "${selectedVariant}" variant?`)) {
      return;
    }
    
    try {
      setSaving(true);
      await BotMessageService.deleteMessageTemplate(messageType, selectedVariant);
      
      // Update local state
      const updatedTemplates = { ...templates };
      delete updatedTemplates[messageType][selectedVariant];
      setTemplates(updatedTemplates);
      
      // Select default variant
      setSelectedVariant('default');
      setEditContent(templates[messageType]['default']);
      setOriginalContent(templates[messageType]['default']);
      
      setSaving(false);
    } catch (error) {
      console.error('Error deleting variant:', error);
      setError('Failed to delete variant');
      setSaving(false);
    }
  };
  
  const handleAddVariant = () => {
    setIsAddingVariant(true);
    setNewVariantName('');
  };
  
  const handleCreateVariant = async () => {
    if (!newVariantName.trim()) {
      setError('Variant name cannot be empty');
      return;
    }
    
    // Check if variant already exists
    if (templates[messageType][newVariantName]) {
      setError(`Variant "${newVariantName}" already exists`);
      return;
    }
    
    try {
      setSaving(true);
      // Create new variant with same content as default
      const defaultContent = templates[messageType]['default'];
      await BotMessageService.saveMessageTemplate(messageType, newVariantName, defaultContent);
      
      // Update local state
      setTemplates(prev => ({
        ...prev,
        [messageType]: {
          ...prev[messageType],
          [newVariantName]: defaultContent
        }
      }));
      
      // Select new variant
      setSelectedVariant(newVariantName);
      setEditContent(defaultContent);
      setOriginalContent(defaultContent);
      
      setIsAddingVariant(false);
      setSaving(false);
    } catch (error) {
      console.error('Error creating variant:', error);
      setError('Failed to create variant');
      setSaving(false);
    }
  };
  
  const handleCancelAddVariant = () => {
    setIsAddingVariant(false);
  };
  
  const getPreviewMessage = () => {
    if (!templates[messageType] || !templates[messageType][selectedVariant]) {
      return 'No template selected';
    }
    
    let content = templates[messageType][selectedVariant];
    
    // Replace variables in the content
    Object.keys(previewVariables).forEach(key => {
      const regex = new RegExp(`\\{${key}\\}`, 'g');
      content = content.replace(regex, previewVariables[key]);
    });
    
    return content;
  };
  
  const handleApplyToRoom = async () => {
    if (!roomId) return;
    
    try {
      setSaving(true);
      
      // Get the current configuration
      const updatedConfig = { ...roomConfig };
      
      // Update based on message type
      switch (messageType) {
        case 'welcome':
          updatedConfig.welcomeVariant = selectedVariant;
          break;
        case 'warning':
          updatedConfig.defaultWarningVariant = selectedVariant;
          break;
        case 'moderation':
          updatedConfig.defaultModerationVariant = selectedVariant;
          break;
      }
      
      // Save to the room
      await BotMessageService.configureRoomTemplates(roomId, updatedConfig);
      
      // Update local state
      setRoomConfig(updatedConfig);
      
      setSaving(false);
    } catch (error) {
      console.error('Error applying template to room:', error);
      setError('Failed to apply template to room');
      setSaving(false);
    }
  };
  
  const handleRefresh = () => {
    loadTemplates();
    if (roomId) {
      loadRoomDetails();
    }
  };
  
  const handleBack = () => {
    if (roomId) {
      navigate('/admin/bot-management');
    } else {
      navigate('/admin');
    }
  };
  
  // Get the currently selected template variant for the room
  const getSelectedRoomVariant = () => {
    if (!roomConfig) return 'default';
    
    switch (messageType) {
      case 'welcome':
        return roomConfig.welcomeVariant || 'default';
      case 'warning':
        return roomConfig.defaultWarningVariant || 'default';
      case 'moderation':
        return roomConfig.defaultModerationVariant || 'default';
      default:
        return 'default';
    }
  };
  
  // Check if the current variant is applied to the room
  const isVariantAppliedToRoom = () => {
    if (!roomId) return false;
    return getSelectedRoomVariant() === selectedVariant;
  };
  
  const messageTypeLabels = {
    welcome: 'Welcome Messages',
    warning: 'Warning Messages',
    moderation: 'Moderation Messages'
  };

  return (
    <div className="bot-message-config">
      <div className="header-section">
        <button className="back-button" onClick={handleBack}>
          <ChevronLeft size={16} />
          <span>Back</span>
        </button>
        
        <h1 className="main-title">
          <MessageSquare className="icon" />
          {roomId ? `Bot Messages for ${room?.name || 'Room'}` : 'Bot Message Templates'}
        </h1>
        
        <button className="refresh-button" onClick={handleRefresh} disabled={loading || saving}>
          <RefreshCw size={16} />
          <span>Refresh</span>
        </button>
      </div>
      
      {error && (
        <div className="error-message">
          <span>{error}</span>
          <button onClick={() => setError(null)}>Dismiss</button>
        </div>
      )}
      
      {loading ? (
        <div className="loading-state">
          <RefreshCw className="spin-animation" />
          <span>Loading templates...</span>
        </div>
      ) : (
        <div className="content-grid">
          <div className="sidebar">
            <div className="message-types">
              <h2>Message Types</h2>
              <ul>
                {Object.keys(templates).map(type => (
                  <li 
                    key={type} 
                    className={messageType === type ? 'active' : ''}
                    onClick={() => handleSelectMessageType(type)}
                  >
                    {messageTypeLabels[type] || type}
                  </li>
                ))}
              </ul>
            </div>
            
            <div className="variants-section">
              <div className="variants-header">
                <h2>Variants</h2>
                <button 
                  className="add-variant-button"
                  onClick={handleAddVariant}
                  disabled={isAddingVariant || saving}
                >
                  <Plus size={16} />
                </button>
              </div>
              
              {isAddingVariant ? (
                <div className="add-variant-form">
                  <input
                    type="text"
                    value={newVariantName}
                    onChange={(e) => setNewVariantName(e.target.value)}
                    placeholder="Variant name"
                    disabled={saving}
                  />
                  <div className="add-variant-actions">
                    <button onClick={handleCreateVariant} disabled={!newVariantName.trim() || saving}>
                      <Check size={16} />
                    </button>
                    <button onClick={handleCancelAddVariant} disabled={saving}>
                      <X size={16} />
                    </button>
                  </div>
                </div>
              ) : (
                <ul className="variants-list">
                  {templates[messageType] && Object.keys(templates[messageType]).map(variant => (
                    <li 
                      key={variant} 
                      className={selectedVariant === variant ? 'active' : ''}
                      onClick={() => handleSelectVariant(variant)}
                    >
                      {variant}
                      {roomId && getSelectedRoomVariant() === variant && (
                        <span className="applied-badge">Applied</span>
                      )}
                    </li>
                  ))}
                </ul>
              )}
            </div>
          </div>
          
          <div className="main-content">
            <div className="template-editor">
              <div className="editor-header">
                <h2>
                  {messageTypeLabels[messageType] || messageType}: {selectedVariant}
                </h2>
                
                <div className="editor-actions">
                  {!editMode && (
                    <button 
                      className="edit-button"
                      onClick={handleStartEdit}
                      disabled={saving}
                    >
                      <Edit size={16} />
                      <span>Edit</span>
                    </button>
                  )}
                  
                  {editMode && (
                    <>
                      <button 
                        className="save-button"
                        onClick={handleSaveTemplate}
                        disabled={saving}
                      >
                        <Save size={16} />
                        <span>Save</span>
                      </button>
                      
                      <button 
                        className="cancel-button"
                        onClick={handleCancelEdit}
                        disabled={saving}
                      >
                        <X size={16} />
                        <span>Cancel</span>
                      </button>
                    </>
                  )}
                  
                  {!editMode && selectedVariant !== 'default' && (
                    <button 
                      className="delete-button"
                      onClick={handleDeleteVariant}
                      disabled={saving}
                    >
                      <Trash size={16} />
                      <span>Delete</span>
                    </button>
                  )}
                </div>
              </div>
              
              {editMode ? (
                <textarea
                  className="template-textarea"
                  value={editContent}
                  onChange={(e) => setEditContent(e.target.value)}
                  placeholder="Enter message template..."
                  disabled={saving}
                />
              ) : (
                <div className="template-display">
                  {templates[messageType] && templates[messageType][selectedVariant]}
                </div>
              )}
              
              <div className="variables-help">
                <h3>Available Variables</h3>
                <p>
                  Use <code>{'{roomName}'}</code> to insert the name of the room.
                </p>
              </div>
            </div>
            
            <div className="preview-section">
              <h2>Preview</h2>
              
              <div className="variable-inputs">
                <div className="input-group">
                  <label>Room Name:</label>
                  <input
                    type="text"
                    value={previewVariables.roomName}
                    onChange={(e) => setPreviewVariables({ ...previewVariables, roomName: e.target.value })}
                    placeholder="Room Name"
                  />
                </div>
              </div>
              
              <div className="preview-container">
                <div className="message bot-message">
                  <div className="message-sender">Moderation Bot</div>
                  <div className="message-content">{getPreviewMessage()}</div>
                </div>
              </div>
              
              {roomId && (
                <div className="apply-to-room">
                  <button 
                    className={`apply-button ${isVariantAppliedToRoom() ? 'applied' : ''}`}
                    onClick={handleApplyToRoom}
                    disabled={saving || isVariantAppliedToRoom()}
                  >
                    {isVariantAppliedToRoom() ? (
                      <>
                        <Check size={16} />
                        <span>Applied to Room</span>
                      </>
                    ) : (
                      <>
                        <Play size={16} />
                        <span>Apply to Room</span>
                      </>
                    )}
                  </button>
                </div>
              )}
            </div>
          </div>
          
          {/* Add the TestBotInteraction component after the main content */}
          {roomId && !loading && (
            <TestBotInteraction roomId={roomId} />
          )}
        </div>
      )}
    </div>
  );
};

export default BotMessageConfig;