// src/predict/services/firebaseStorage.js
//
// Firebase Realtime Database (RTDB) backing for Predict.
// Mirrors the API of the legacy localStorage-based storageService.js so
// callers can swap with no surface changes.
//
// Schema:
//   predictions/{id}                — full prediction document
//   predict_meta/seedVersion        — string; bumped when mock data changes
//   predict_meta/seededAt            — timestamp of last seed
//
// Why RTDB and not Firestore?
//   TalkStudio's existing CategoryService / TopicService / IdeaService all
//   use RTDB (see src/services/CategoryService.js). Mirroring keeps the
//   code consistent and uses infrastructure that's already proven in this
//   codebase. Firestore is also initialized in firebase.js if we need it
//   later (e.g. for full-text search or compound queries).

import {
  ref,
  push,
  set,
  get,
  update,
  remove,
  onValue,
  query,
  orderByChild,
  serverTimestamp,
} from 'firebase/database';
import { rtdb } from '../../firebase';
import { mockPredictions, mockUsers } from '../utils/mockData';

const SEED_VERSION = 'dealmaker-2026-04-v1';
const PATHS = {
  predictions: 'predictions',
  meta:        'predict_meta',
  users:       'predict_users',
};

// In-memory cache so synchronous accessors (used by some legacy callers)
// have something to return while the snapshot is loading.
let predictionsCache = [];
let cacheReady = false;
const cacheListeners = new Set();

/**
 * Subscribe once at module load so the cache stays warm and any
 * components that call `getPredictionsSync()` get fresh data on subsequent
 * renders even if they don't subscribe themselves.
 */
let bootSubscriptionInstalled = false;
function installBootSubscription() {
  if (bootSubscriptionInstalled || !rtdb) return;
  bootSubscriptionInstalled = true;
  const predRef = ref(rtdb, PATHS.predictions);
  onValue(
    predRef,
    (snap) => {
      const arr = [];
      if (snap.exists()) {
        const data = snap.val();
        Object.entries(data).forEach(([id, value]) => {
          if (value && value.deleted !== true) {
            arr.push({ id, ...value });
          }
        });
      }
      // If the predictions path is reachable but empty (e.g. no admin has
      // run the seed yet), surface mock predictions locally so the UI isn't
      // blank. We do NOT write to RTDB here — only an admin can do that.
      // Once an admin successfully seeds, this branch stops firing.
      if (arr.length === 0) {
        console.info('[predict] predictions path empty in RTDB — showing local mock data. ' +
          'Run seedPredictionsIfNeeded() from an admin account to publish.');
        predictionsCache = mockPredictions;
        cacheReady = true;
        cacheListeners.forEach(fn => fn(mockPredictions));
        return;
      }
      // Newest first
      arr.sort((a, b) => (new Date(b.createdAt || 0) - new Date(a.createdAt || 0)));
      predictionsCache = arr;
      cacheReady = true;
      cacheListeners.forEach(fn => {
        try { fn(arr); } catch (e) { console.error('[predict] cache listener error:', e); }
      });
    },
    (err) => {
      // Common in Pass 1 dev: Firebase RTDB security rules deny reads on
      // the new `predictions` path. We fall back to mock data so the UI
      // still renders. Pass 2 deploys updated database.rules.json — see
      // INTEGRATION_PASS_2.md "Predict on Firebase" section.
      console.warn(
        '[predict] RTDB read denied/failed — using local mock data. ' +
        'For multi-user predictions, deploy the updated database.rules.json. ' +
        'Underlying error:', err?.message
      );
      predictionsCache = mockPredictions;
      cacheReady = true;
      cacheListeners.forEach(fn => fn(mockPredictions));
    }
  );
}

// Try to install on import; firebase.js initializes RTDB lazily so this is safe.
try { installBootSubscription(); } catch (e) { console.warn('[predict] boot subscribe deferred:', e?.message); }

// Expose an admin debug handle on window so you can introspect from the
// browser console in production (where bundled module imports don't work
// like dev-server `import('/src/...')` does).
//
// Usage in DevTools:
//   window.__predict.uid()        → your auth UID
//   window.__predict.cache()      → current in-memory predictions cache
//   window.__predict.seed()       → force-run the seed (admin only)
//   window.__predict.checkAdmin() → reports if you're in /admins/{uid}
if (typeof window !== 'undefined') {
  window.__predict = {
    cache: () => predictionsCache,
    seed: () => seedPredictionsIfNeeded(),
    async uid() {
      try {
        const auth = (await import('../../firebase')).auth;
        return auth?.currentUser?.uid ?? null;
      } catch { return null; }
    },
    async checkAdmin() {
      try {
        const fb = await import('../../firebase');
        const dbMod = await import('firebase/database');
        const uid = fb.auth?.currentUser?.uid;
        if (!uid) return { uid: null, admin: false, reason: 'not signed in' };
        const snap = await dbMod.get(dbMod.ref(fb.rtdb, `admins/${uid}`));
        return { uid, admin: snap.val() === true, value: snap.val() };
      } catch (e) {
        return { error: e.message };
      }
    },
  };
}

/**
 * Seed mockPredictions into RTDB if the seed version has changed (or never set).
 * Idempotent: writes a meta record so subsequent loads skip work.
 * Pass 1: any client may seed (no auth check). Pass 2 will gate this to admin
 * via security rules.
 */
export async function seedPredictionsIfNeeded() {
  if (!rtdb) return { seeded: false, reason: 'rtdb-unavailable' };
  try {
    const metaSnap = await get(ref(rtdb, `${PATHS.meta}/seedVersion`));
    const currentVersion = metaSnap.exists() ? metaSnap.val() : null;
    if (currentVersion === SEED_VERSION) {
      return { seeded: false, reason: 'already-current', version: currentVersion };
    }

    // Write all mock predictions in one update for atomicity.
    const updates = {};
    for (const p of mockPredictions) {
      updates[`${PATHS.predictions}/${p.id}`] = p;
    }
    updates[`${PATHS.meta}/seedVersion`] = SEED_VERSION;
    updates[`${PATHS.meta}/seededAt`] = serverTimestamp();
    // Mock users (leaderboard) — small, also seeded.
    updates[`${PATHS.users}`] = mockUsers.reduce((acc, u) => {
      acc[u.id] = u;
      return acc;
    }, {});

    await update(ref(rtdb), updates);
    console.log(`[predict] Seeded ${mockPredictions.length} predictions to RTDB (version ${SEED_VERSION})`);
    return { seeded: true, count: mockPredictions.length, version: SEED_VERSION };
  } catch (e) {
    console.error('[predict] seed failed:', e);
    return { seeded: false, reason: 'error', error: e.message };
  }
}

// Auto-seed on first load. Best effort; failures are tolerable (read path
// falls through to mock data).
seedPredictionsIfNeeded().then((r) => {
  if (r.seeded) console.log(`[predict] Initial seed complete:`, r);
});

/** Synchronous read of cached predictions. Empty array until cache warms. */
export function getPredictionsSync() {
  if (!cacheReady) return mockPredictions;
  return predictionsCache;
}

/** Subscribe to live updates. Returns an unsubscribe fn. */
export function subscribePredictions(callback) {
  if (cacheReady) {
    // Fire immediately so the consumer doesn't wait a tick for first paint.
    try { callback(predictionsCache); } catch (e) { console.error(e); }
  }
  cacheListeners.add(callback);
  // Ensure boot subscription exists (no-op if already installed)
  installBootSubscription();
  return () => cacheListeners.delete(callback);
}

const firebaseStorage = {
  /** Promise-based fetch (legacy compat). */
  async getPredictions() {
    if (cacheReady) return predictionsCache;
    if (!rtdb) return mockPredictions;
    try {
      const snap = await get(ref(rtdb, PATHS.predictions));
      const arr = [];
      if (snap.exists()) {
        Object.entries(snap.val()).forEach(([id, v]) => {
          if (v && v.deleted !== true) arr.push({ id, ...v });
        });
      }
      arr.sort((a, b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0));
      return arr;
    } catch (e) {
      console.warn('[predict] getPredictions fallback:', e?.message);
      return mockPredictions;
    }
  },

  async getPrediction(id) {
    if (!rtdb) return mockPredictions.find(p => p.id === id) || null;
    try {
      const snap = await get(ref(rtdb, `${PATHS.predictions}/${id}`));
      if (!snap.exists()) return null;
      const v = snap.val();
      if (v.deleted) return null;
      return { id, ...v };
    } catch (e) {
      console.warn('[predict] getPrediction fallback:', e?.message);
      return mockPredictions.find(p => p.id === id) || null;
    }
  },

  /** Create or replace a prediction. Returns the saved record. */
  async savePrediction(prediction) {
    if (!rtdb) throw new Error('Firebase not initialized');
    if (!prediction?.id) {
      // Allocate a server-side id via push().
      const newRef = push(ref(rtdb, PATHS.predictions));
      const id = newRef.key;
      const record = { ...prediction, id, createdAt: prediction.createdAt || new Date().toISOString() };
      await set(newRef, record);
      return record;
    }
    await set(ref(rtdb, `${PATHS.predictions}/${prediction.id}`), prediction);
    return prediction;
  },

  /** Soft delete (sets deleted=true so we can recover). */
  async deletePrediction(id) {
    if (!rtdb) throw new Error('Firebase not initialized');
    await update(ref(rtdb, `${PATHS.predictions}/${id}`), { deleted: true, deletedAt: serverTimestamp() });
    return true;
  },

  /** Hard delete (admin only — security rules enforce in Pass 2). */
  async hardDeletePrediction(id) {
    if (!rtdb) throw new Error('Firebase not initialized');
    await remove(ref(rtdb, `${PATHS.predictions}/${id}`));
    return true;
  },

  /** Update a single field path (e.g. communityVotes counters). */
  async updatePredictionFields(id, partialUpdates) {
    if (!rtdb) throw new Error('Firebase not initialized');
    await update(ref(rtdb, `${PATHS.predictions}/${id}`), partialUpdates);
  },

  // Re-exports for ergonomics
  subscribePredictions,
  getPredictionsSync,
  seedPredictionsIfNeeded,
};

export default firebaseStorage;
