// src/components/auth/UsernamePrompt.jsx
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import './UsernamePrompt.css';

const UsernamePrompt = () => {
  const { pendingUserData, completeGoogleSignup, checkUsernameAvailability } = useAuth();
  const [username, setUsername] = useState('');
  const [error, setError] = useState('');
  const [isChecking, setIsChecking] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const navigate = useNavigate();

  // Initialize with default username from pending data
  useEffect(() => {
    if (pendingUserData && pendingUserData.defaultUsername) {
      setUsername(pendingUserData.defaultUsername);
      validateUsername(pendingUserData.defaultUsername);
    }
  }, [pendingUserData]);

  // Handle username input validation
  const validateUsername = async (value) => {
    if (!value) {
      setError('Username is required');
      return false;
    }

    if (value.length < 3) {
      setError('Username must be at least 3 characters');
      return false;
    }

    // Basic regex validation
    const regex = /^[a-zA-Z0-9_]+$/;
    if (!regex.test(value)) {
      setError('Username can only contain letters, numbers, and underscores');
      return false;
    }

    // Check availability
    setIsChecking(true);
    try {
      const result = await checkUsernameAvailability(value);
      setIsChecking(false);
      
      if (!result.available) {
        setError(result.reason || 'This username is already taken');
        return false;
      }
      
      setError('');
      return true;
    } catch (error) {
      setIsChecking(false);
      setError('Error checking username availability');
      return false;
    }
  };

  // Handle username change
  const handleUsernameChange = (e) => {
    const value = e.target.value;
    setUsername(value);
    validateUsername(value);
  };

  // Handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (isChecking || isSubmitting) return;
    
    const isValid = await validateUsername(username);
    if (!isValid) return;
    
    setIsSubmitting(true);
    
    try {
      await completeGoogleSignup(username);
      navigate('/'); // Redirect to home page after successful setup
    } catch (error) {
      setError('Failed to complete signup: ' + error.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  // If no pending data, redirect to login
  if (!pendingUserData) {
    navigate('/login');
    return null;
  }

  return (
    <div className="username-prompt-container">
      <div className="username-prompt-card">
        <h2>Set Your Username</h2>
        <p className="prompt-intro">
          Please choose a username for your account. This will be used to mention you in conversations and for your profile URL.
        </p>
        
        {pendingUserData.photoURL && (
          <div className="user-avatar">
            <img src={pendingUserData.photoURL} alt="Profile" />
          </div>
        )}
        
        <div className="user-info">
          <div className="display-name">{pendingUserData.displayName || 'New User'}</div>
          {pendingUserData.email && <div className="email">{pendingUserData.email}</div>}
        </div>
        
        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label htmlFor="username">Username</label>
            <div className="input-wrapper">
              <span className="input-prefix">@</span>
              <input
                type="text"
                id="username"
                value={username}
                onChange={handleUsernameChange}
                placeholder="Choose a username"
                disabled={isSubmitting}
                autoFocus
              />
            </div>
            
            {isChecking && <div className="checking-message">Checking availability...</div>}
            {error && <div className="error-message">{error}</div>}
            
            <p className="username-help">
              Usernames can only contain letters, numbers, and underscores.
              Must be at least 3 characters.
            </p>
          </div>
          
          <div className="form-actions">
            <button 
              type="submit" 
              className="submit-button"
              disabled={!!error || isChecking || isSubmitting}
            >
              {isSubmitting ? 'Setting up...' : 'Continue'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default UsernamePrompt;