import React, { useState, useEffect } from 'react';
import { Shield, Check, X, AlertTriangle, RefreshCw, MessageSquare, TestTube } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import TestBotInteraction from './TestBotInteraction';

// Import the existing Firebase RTDB instance from your firebase.js file
import { rtdb } from '../firebase';
import { ref, onValue, set, update, push, serverTimestamp, remove } from 'firebase/database';

// Import the BotMessageService
import { BotMessageService } from '../services/BotMessageService.js';

const ModerationBot = () => {
  const [rooms, setRooms] = useState([]);
  const [loading, setLoading] = useState(true);
  const [processing, setProcessing] = useState(false);
  const [results, setResults] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [filter, setFilter] = useState('all'); // 'all', 'bot', 'no-bot', 'vip'
  const [selectedRooms, setSelectedRooms] = useState([]);
  const [selectAll, setSelectAll] = useState(false);
  const [error, setError] = useState(null);
  const [activeTab, setActiveTab] = useState('rooms'); // 'rooms' or 'test'
  const [selectedRoomForTest, setSelectedRoomForTest] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    fetchRooms();
  }, []);

  const fetchRooms = async () => {
    setLoading(true);
    setError(null);
    
    try {
      console.log('Fetching rooms from Realtime Database...');
      
      // Reference to all chat rooms - UPDATED PATH to match the database structure
      const roomsRef = ref(rtdb, 'chats/public');
      
      // Listen for all rooms
      onValue(roomsRef, (snapshot) => {
        try {
          const roomsData = snapshot.val() || {};
          console.log('Rooms data:', roomsData);
          
          const roomsArray = [];
          
          // Convert object to array
          Object.keys(roomsData).forEach(roomId => {
            const roomData = roomsData[roomId];
            
            console.log(`Processing room: ${roomId}`, roomData);
            
            // Check if the room is VIP
            const isVIP = roomData.isVIP || roomData.type === 'VIP' || roomData.type === 'type' === 'vip';
            
            // Check if bot is in participants
            const participants = roomData.participants || {};
            const participantsArray = Array.isArray(participants) 
              ? participants 
              : Object.keys(participants).filter(key => participants[key] === true);
            
            const hasBotParticipant = participantsArray.includes('MODERATION_BOT');
            
            // Check if bot has made announcements - now check in botMessages path
            let hasBotAnnounced = false;
            
            // Check in regular messages first (for backward compatibility)
            const messages = roomData.messages || {};
            hasBotAnnounced = Object.values(messages).some(msg => 
              msg && msg.sender === 'MODERATION_BOT' && msg.type === 'ANNOUNCEMENT'
            );
            
            // If not found in regular messages, check in botMessages
            if (!hasBotAnnounced && roomData.botMessages) {
              hasBotAnnounced = Object.keys(roomData.botMessages).length > 0;
            }

            // Get bot message configuration if available
            const botConfig = roomData.botConfig || {};
            
            roomsArray.push({
              id: roomId,
              name: roomData.name || 'Unnamed Room',
              isVIP,
              hasBotParticipant,
              hasBotAnnounced,
              participants: participantsArray,
              botConfig,
              createdAt: roomData.createdAt ? new Date(roomData.createdAt) : null,
              updatedAt: roomData.updatedAt ? new Date(roomData.updatedAt) : null,
            });
          });
          
          console.log(`Processed ${roomsArray.length} rooms`);
          setRooms(roomsArray);
          setLoading(false);
        } catch (err) {
          console.error('Error processing rooms data:', err);
          setError('Failed to process rooms data: ' + err.message);
          setLoading(false);
        }
      }, (err) => {
        console.error('Error fetching rooms:', err);
        setError('Failed to fetch rooms: ' + err.message);
        setLoading(false);
      });
    } catch (err) {
      console.error('Error setting up rooms listener:', err);
      setError('Failed to set up rooms listener: ' + err.message);
      setLoading(false);
    }
  };

  const addBotToRoom = async (roomId, roomName) => {
    try {
      // Add bot to participants - UPDATED PATH
      const roomRef = ref(rtdb, `chats/public/${roomId}`);
      
      // Check if participants is an array or object
      const participantsRef = ref(rtdb, `chats/public/${roomId}/participants`);
      
      // Get current participants
      const participantsSnapshot = await new Promise((resolve) => {
        onValue(participantsRef, resolve, { onlyOnce: true });
      });
      
      const participants = participantsSnapshot.val();
      
      if (Array.isArray(participants)) {
        // If array, push to array if not already there
        if (!participants.includes('MODERATION_BOT')) {
          await set(participantsRef, [...participants, 'MODERATION_BOT']);
        }
      } else {
        // If object with boolean values or null/undefined
        await set(ref(rtdb, `chats/public/${roomId}/participants/MODERATION_BOT`), true);
      }
      
      // Update timestamp
      await update(roomRef, {
        updatedAt: serverTimestamp()
      });
      
      // Get appropriate welcome message using BotMessageService
      const welcomeMessage = await BotMessageService.getWelcomeMessage(roomId, roomName);
      
      // Add bot announcement message - now use botMessages path
      const message = {
        sender: 'MODERATION_BOT',
        senderName: 'Moderation Bot',
        content: welcomeMessage,
        timestamp: serverTimestamp(),
        type: 'ANNOUNCEMENT',
        isSystemMessage: true,
      };
      
      // Push new message to botMessages path - UPDATED PATH
      const botMessagesRef = ref(rtdb, `chats/public/${roomId}/botMessages`);
      await push(botMessagesRef, message);
      
      // Also add to the regular messages path for user visibility
      try {
        // For user messages, we need to conform to the validation rules
        const userMessage = {
          userId: 'MODERATION_BOT', // Use userId instead of sender
          text: message.content, // Use text instead of content
          timestamp: serverTimestamp(),
          senderName: 'Moderation Bot', // Keep this for display purposes
          isSystemMessage: true,
          type: 'ANNOUNCEMENT' // Keep type for filtering
        };
        
        const messagesRef = ref(rtdb, `chats/public/${roomId}/messages`);
        await push(messagesRef, userMessage);
      } catch (msgError) {
        console.warn('Could not add to regular messages, but bot message was added', msgError);
        // Continue even if this fails - the bot message is still in botMessages
      }
      
      return true;
    } catch (error) {
      console.error(`Error adding bot to room ${roomId}:`, error);
      throw error;
    }
  };
  
  const removeBotFromRoom = async (roomId) => {
    try {
      // UPDATED PATH
      const roomRef = ref(rtdb, `chats/public/${roomId}`);
      
      // Check if participants is an array or object
      const participantsRef = ref(rtdb, `chats/public/${roomId}/participants`);
      
      // Get current participants
      const participantsSnapshot = await new Promise((resolve) => {
        onValue(participantsRef, resolve, { onlyOnce: true });
      });
      
      const participants = participantsSnapshot.val();
      
      if (Array.isArray(participants)) {
        // If array, filter out bot
        const updatedParticipants = participants.filter(p => p !== 'MODERATION_BOT');
        await set(participantsRef, updatedParticipants);
      } else {
        // If object with boolean values or null/undefined
        await remove(ref(rtdb, `chats/public/${roomId}/participants/MODERATION_BOT`));
      }
      
      // Update timestamp
      await update(roomRef, {
        updatedAt: serverTimestamp()
      });
      
      // Remove bot messages from both locations
      
      // 1. Remove from botMessages path
      const botMessagesRef = ref(rtdb, `chats/public/${roomId}/botMessages`);
      await remove(botMessagesRef);
      
      // 2. Find and remove bot announcement messages from regular messages
      const messagesRef = ref(rtdb, `chats/public/${roomId}/messages`);
      
      // Get all messages
      const messagesSnapshot = await new Promise((resolve) => {
        onValue(messagesRef, resolve, { onlyOnce: true });
      });
      
      const messages = messagesSnapshot.val() || {};
      
      // Find bot announcement messages - check both sender and userId
      const botAnnouncementMessages = Object.keys(messages).filter(messageId => {
        const message = messages[messageId];
        return (message && 
                ((message.sender === 'MODERATION_BOT' && message.type === 'ANNOUNCEMENT') ||
                 (message.userId === 'MODERATION_BOT' && message.type === 'ANNOUNCEMENT')));
      });
      
      // Remove each bot announcement message
      const updates = {};
      botAnnouncementMessages.forEach(messageId => {
        updates[`chats/public/${roomId}/messages/${messageId}`] = null;
      });
      
      if (Object.keys(updates).length > 0) {
        await update(ref(rtdb), updates);
      }
      
      return true;
    } catch (error) {
      console.error(`Error removing bot from room ${roomId}:`, error);
      throw error;
    }
  };

  const handleAddBotToSelectedRooms = async () => {
    if (selectedRooms.length === 0) {
      alert('Please select at least one room');
      return;
    }

    setProcessing(true);
    setResults({ success: 0, skipped: 0, failed: 0, details: [] });
    
    const newResults = { success: 0, skipped: 0, failed: 0, details: [] };
    
    for (const roomId of selectedRooms) {
      const room = rooms.find(r => r.id === roomId);
      
      if (!room) {
        newResults.failed++;
        newResults.details.push({ id: roomId, status: 'failed', message: 'Room not found' });
        continue;
      }
      
      // Skip VIP rooms
      if (room.isVIP) {
        newResults.skipped++;
        newResults.details.push({ id: roomId, status: 'skipped', message: 'VIP room' });
        continue;
      }
      
      // Skip rooms with bot already
      if (room.hasBotAnnounced) {
        newResults.skipped++;
        newResults.details.push({ id: roomId, status: 'skipped', message: 'Bot already in room' });
        continue;
      }
      
      try {
        await addBotToRoom(roomId, room.name);
        newResults.success++;
        newResults.details.push({ id: roomId, status: 'success', message: 'Bot added successfully' });
        
        // Update local state
        setRooms(prev => prev.map(r => 
          r.id === roomId ? { ...r, hasBotParticipant: true, hasBotAnnounced: true } : r
        ));
      } catch (error) {
        console.error(`Error adding bot to room ${roomId}:`, error);
        newResults.failed++;
        newResults.details.push({ id: roomId, status: 'failed', message: error.message });
      }
      
      // Update results as we go
      setResults({...newResults});
    }
    
    setProcessing(false);
    setSelectedRooms([]);
    setSelectAll(false);
  };

  const handleRemoveBotFromSelectedRooms = async () => {
    if (selectedRooms.length === 0) {
      alert('Please select at least one room');
      return;
    }

    setProcessing(true);
    setResults({ success: 0, skipped: 0, failed: 0, details: [] });
    
    const newResults = { success: 0, skipped: 0, failed: 0, details: [] };
    
    for (const roomId of selectedRooms) {
      const room = rooms.find(r => r.id === roomId);
      
      if (!room) {
        newResults.failed++;
        newResults.details.push({ id: roomId, status: 'failed', message: 'Room not found' });
        continue;
      }
      
      // Skip VIP rooms
      if (room.isVIP) {
        newResults.skipped++;
        newResults.details.push({ id: roomId, status: 'skipped', message: 'VIP room' });
        continue;
      }
      
      try {
        await removeBotFromRoom(roomId);
        newResults.success++;
        newResults.details.push({ id: roomId, status: 'success', message: 'Bot removed successfully' });
        
        // Update local state
        setRooms(prev => prev.map(r => 
          r.id === roomId ? { ...r, hasBotParticipant: false, hasBotAnnounced: false } : r
        ));
      } catch (error) {
        console.error(`Error removing bot from room ${roomId}:`, error);
        newResults.failed++;
        newResults.details.push({ id: roomId, status: 'failed', message: error.message });
      }
      
      // Update results as we go
      setResults({...newResults});
    }
    
    setProcessing(false);
    setSelectedRooms([]);
    setSelectAll(false);
  };

  const handleRefresh = () => {
    fetchRooms();
    setResults(null);
  };

  const handleSelectAll = (e) => {
    const checked = e.target.checked;
    setSelectAll(checked);
    
    if (checked) {
      // Select all rooms that match the current filter
      const filteredRoomIds = filteredRooms.map(room => room.id);
      setSelectedRooms(filteredRoomIds);
    } else {
      setSelectedRooms([]);
    }
  };

  const handleSelectRoom = (roomId) => {
    setSelectedRooms(prev => {
      if (prev.includes(roomId)) {
        return prev.filter(id => id !== roomId);
      } else {
        return [...prev, roomId];
      }
    });
  };

  const filteredRooms = rooms.filter(room => {
    // First filter by search term
    if (searchTerm && !room.name.toLowerCase().includes(searchTerm.toLowerCase()) && !room.id.includes(searchTerm)) {
      return false;
    }
    
    // Then filter by bot status
    switch (filter) {
      case 'bot':
        return room.hasBotAnnounced;
      case 'no-bot':
        return !room.hasBotAnnounced && !room.isVIP;
      case 'vip':
        return room.isVIP;
      default:
        return true;
    }
  });

  const getBotConfigStatus = (room) => {
    if (!room.hasBotAnnounced) return '';
    
    if (room.botConfig && Object.keys(room.botConfig).length > 0) {
      return 'Custom';
    }
    return 'Default';
  };

  return (
    <div className="w-full">
      <div className="flex items-center mb-4">
        <Shield className="text-indigo-600 mr-2" size={24} />
        <h2 className="text-xl font-bold">Moderation Bot Management</h2>
      </div>
      
      <p className="mb-6 text-gray-600">
        The moderation bot automatically monitors chat rooms for inappropriate content and helps maintain a positive environment.
        VIP rooms are exempt from moderation.
      </p>
      
      <div className="flex justify-between mb-6">
        <div className="inline-flex rounded-md shadow-sm" role="group">
          <button
            type="button"
            onClick={() => setActiveTab('rooms')}
            className={`px-4 py-2 text-sm font-medium ${activeTab === 'rooms' 
              ? 'bg-indigo-600 text-white hover:bg-indigo-700' 
              : 'bg-white text-gray-700 hover:bg-gray-50'} 
              border border-gray-200 rounded-l-lg focus:z-10 focus:ring-2 focus:ring-indigo-500 focus:text-indigo-600`}
          >
            <Shield className="inline-block mr-2" size={16} />
            Manage Rooms
          </button>
          <button
            type="button"
            onClick={() => setActiveTab('test')}
            className={`px-4 py-2 text-sm font-medium ${activeTab === 'test' 
              ? 'bg-indigo-600 text-white hover:bg-indigo-700' 
              : 'bg-white text-gray-700 hover:bg-gray-50'} 
              border border-gray-200 rounded-r-lg focus:z-10 focus:ring-2 focus:ring-indigo-500 focus:text-indigo-600`}
          >
            <TestTube className="inline-block mr-2" size={16} />
            Test Bot
          </button>
        </div>
      </div>
      
      {activeTab === 'rooms' && (
        <>
        <div className="flex flex-col lg:flex-row justify-between gap-4 mb-6">
          <div className="flex flex-wrap gap-2">
          <div className="relative">
            <input
              type="text"
              placeholder="Search rooms..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="px-4 py-2 border rounded-md w-full focus:outline-none focus:ring-2 focus:ring-indigo-500"
            />
          </div>
          
          <select 
            value={filter} 
            onChange={(e) => setFilter(e.target.value)}
            className="px-4 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
          >
            <option value="all">All Rooms</option>
            <option value="bot">With Bot</option>
            <option value="no-bot">Without Bot</option>
            <option value="vip">VIP Rooms</option>
          </select>
          
          <button 
            onClick={handleRefresh} 
            disabled={loading || processing}
            className="flex items-center px-4 py-2 bg-gray-100 text-gray-700 rounded-md hover:bg-gray-200 focus:outline-none"
          >
            <RefreshCw className="mr-2" size={16} />
            Refresh
          </button>
        </div>
        
        <div className="flex gap-2">
          <button 
            onClick={handleAddBotToSelectedRooms}
            disabled={loading || processing || selectedRooms.length === 0}
            className="flex items-center px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 disabled:bg-gray-300 disabled:cursor-not-allowed focus:outline-none"
          >
            <Check className="mr-2" size={16} />
            Add Bot
          </button>
          
          <button 
            onClick={handleRemoveBotFromSelectedRooms}
            disabled={loading || processing || selectedRooms.length === 0}
            className="flex items-center px-4 py-2 bg-red-600 text-white rounded-md hover:bg-red-700 disabled:bg-gray-300 disabled:cursor-not-allowed focus:outline-none"
          >
            <X className="mr-2" size={16} />
            Remove Bot
          </button>
          
          <a 
            href="/admin/bot-messages"
            onClick={(e) => {
              e.preventDefault();
              navigate('/admin/bot-messages');
            }}
            className="flex items-center px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 focus:outline-none"
          >
            <MessageSquare className="mr-2" size={16} />
            Manage Messages
          </a>
        </div>
      </div>
      
      <div className="text-sm text-gray-600 mb-2">
        {filteredRooms.length} room(s) found, {selectedRooms.length} selected
      </div>
      
      {loading ? (
        <div className="flex justify-center py-8">
          <div className="flex items-center">
            <div className="animate-spin mr-2">
              <RefreshCw size={20} className="text-indigo-600" />
            </div>
            <span>Loading chat rooms...</span>
          </div>
        </div>
      ) : error ? (
        <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-md mb-4">
          <p className="font-medium">Error loading rooms:</p>
          <p>{error}</p>
          <button 
            onClick={handleRefresh}
            className="mt-2 px-4 py-2 bg-white border border-red-300 text-red-700 rounded-md hover:bg-red-50"
          >
            Try Again
          </button>
        </div>
      ) : (
        <div className="bg-white rounded-lg border overflow-hidden shadow-sm">
          {rooms.length === 0 ? (
            <div className="p-8 text-center text-gray-500">
              <p>No chat rooms found. Please check your database connection.</p>
              <button 
                onClick={handleRefresh}
                className="mt-4 px-4 py-2 bg-indigo-100 text-indigo-700 rounded-md hover:bg-indigo-200"
              >
                Refresh
              </button>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                  <tr>
                    <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      <input 
                        type="checkbox" 
                        checked={selectAll}
                        onChange={handleSelectAll}
                        disabled={processing}
                        className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
                      />
                    </th>
                    <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Name
                    </th>
                    <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      ID
                    </th>
                    <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Status
                    </th>
                    <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Bot Config
                    </th>
                    <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Created
                    </th>
                    <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Updated
                    </th>
                    <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Actions
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {filteredRooms.map(room => (
                    <tr key={room.id} className={room.isVIP ? 'bg-yellow-50' : room.hasBotAnnounced ? 'bg-green-50' : ''}>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <input 
                          type="checkbox" 
                          checked={selectedRooms.includes(room.id)}
                          onChange={() => handleSelectRoom(room.id)}
                          disabled={processing}
                          className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
                        />
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <div className="text-sm font-medium text-gray-900">
                          {room.name}
                        </div>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <div className="text-sm text-gray-500">
                          {room.id}
                        </div>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        {room.isVIP ? (
                          <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-yellow-100 text-yellow-800">
                            VIP
                          </span>
                        ) : room.hasBotAnnounced ? (
                          <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-green-100 text-green-800">
                            Bot Active
                          </span>
                        ) : (
                          <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-gray-100 text-gray-800">
                            No Bot
                          </span>
                        )}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        {room.hasBotAnnounced && (
                          <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${
                            getBotConfigStatus(room) === 'Custom' 
                              ? 'bg-purple-100 text-purple-800' 
                              : 'bg-blue-100 text-blue-800'
                          }`}>
                            {getBotConfigStatus(room)}
                          </span>
                        )}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                        {room.createdAt ? room.createdAt.toLocaleString() : 'Unknown'}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                        {room.updatedAt ? room.updatedAt.toLocaleString() : 'Unknown'}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm">
                        {room.hasBotAnnounced && !room.isVIP && (
                          <a 
                            href={`/admin/bot-messages/room/${room.id}`}
                            onClick={(e) => {
                              e.preventDefault();
                              navigate(`/admin/bot-messages/room/${room.id}`);
                            }}
                            className="text-indigo-600 hover:text-indigo-900"
                          >
                            Configure
                          </a>
                        )}
                      </td>
                    </tr>
                  ))}
                  
                  {filteredRooms.length === 0 && (
                    <tr>
                      <td colSpan="8" className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 text-center">
                        No rooms found matching the current filters.
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}
      
      </>
      )}
      
      {activeTab === 'test' && (
        <div className="bg-white rounded-lg border overflow-hidden shadow-sm p-6">
          <h3 className="text-lg font-medium mb-4">Test Bot Functionality</h3>
          
          <div className="mb-4">
            <label className="block text-sm font-medium text-gray-700 mb-2">Select a room to test:</label>
            <select 
              className="mt-1 block w-full py-2 px-3 border border-gray-300 bg-white rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
              value={selectedRoomForTest || ''}
              onChange={(e) => setSelectedRoomForTest(e.target.value)}
            >
              <option value="">-- Select a room --</option>
              {rooms
                .filter(room => room.hasBotAnnounced && !room.isVIP)
                .map(room => (
                  <option key={room.id} value={room.id}>
                    {room.name} ({room.id})
                  </option>
                ))}
            </select>
          </div>
          
          {selectedRoomForTest ? (
            <TestBotInteraction roomId={selectedRoomForTest} />
          ) : (
            <div className="bg-gray-50 rounded-md p-4 text-sm text-gray-600">
              Please select a room with the bot active to test bot functionality.
            </div>
          )}
        </div>
      )}
      
      {activeTab === 'rooms' && results && (
        <div className="mt-6 bg-white rounded-lg border p-4 shadow-sm">
          <h3 className="text-lg font-medium mb-2">Operation Results</h3>
          
          <div className="flex flex-wrap gap-4 mb-4">
            <div className="bg-green-50 text-green-700 px-3 py-2 rounded-md text-sm">
              <span className="font-semibold">Success:</span> {results.success}
            </div>
            <div className="bg-yellow-50 text-yellow-700 px-3 py-2 rounded-md text-sm">
              <span className="font-semibold">Skipped:</span> {results.skipped}
            </div>
            <div className="bg-red-50 text-red-700 px-3 py-2 rounded-md text-sm">
              <span className="font-semibold">Failed:</span> {results.failed}
            </div>
          </div>
          
          {results.details.length > 0 && (
            <div className="border rounded-md overflow-hidden">
              <div className="bg-gray-50 px-4 py-2 font-medium text-sm border-b">
                Details
              </div>
              <div className="divide-y max-h-40 overflow-y-auto">
                {results.details.map((detail, index) => (
                  <div 
                    key={index} 
                    className={`px-4 py-2 text-sm flex items-center
                      ${detail.status === 'success' ? 'text-green-700' : 
                        detail.status === 'skipped' ? 'text-yellow-700' : 'text-red-700'}`}
                  >
                    {detail.status === 'success' ? (
                      <Check size={16} className="mr-2" />
                    ) : detail.status === 'skipped' ? (
                      <AlertTriangle size={16} className="mr-2" />
                    ) : (
                      <X size={16} className="mr-2" />
                    )}
                    <span className="font-medium mr-1">Room {detail.id}:</span> {detail.message}
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default ModerationBot;