/**
 * FFmpeg Streaming Service - FIXED for Mixed Content Policy compliance
 * Path: C:\Users\Tom\Documents\GitHub\presence-react3\presence-react\src\services\streaming\FFmpegStreamingService.js
 */

import streamingConfigMixedContentFix from "../../config/streaming-mixed-content-fix.js"

class FFmpegStreamingService {
  constructor() {
    this.activeStreams = new Map();
    this.streamConfigs = new Map();
    this.listeners = {};
    this.serviceStatus = {
      initialized: false,
      healthy: false,
      lastCheck: null,
      mode: 'unknown', // 'api', 'fallback', 'offline'
      mixedContentSafe: false
    };
    
    // FIXED: Use mixed content safe configuration
    this.config = streamingConfigMixedContentFix;
    this.baseUrl = streamingConfigMixedContentFix.streamingService.baseUrl;
    this.apiEndpoint = streamingConfigMixedContentFix.streamingService.apiUrl;
    this.healthEndpoint = streamingConfigMixedContentFix.streamingService.apiUrl;
    
    console.log('🎬 Streaming Service initialized (Mixed Content Safe):', {
      base: this.baseUrl,
      api: this.apiEndpoint,
      health: this.healthEndpoint,
      protocol: streamingConfigMixedContentFix.streamingService.baseUrl.startsWith('https') ? 'HTTPS' : 'HTTP'
    });
  }

  /**
   * FIXED: Initialize with Mixed Content Policy compliance
   */
  async initialize() {
    try {
      console.log('🚀 Initializing Mixed Content Safe streaming service...');
      
      // Test service connectivity with mixed content handling
      const connectivityTest = await streamingConfigMixedContentFix.testStreamingServiceConnection();
      
      this.serviceStatus.lastCheck = new Date().toISOString();
      this.serviceStatus.initialized = true;
      this.serviceStatus.mixedContentSafe = connectivityTest.details?.mixedContentSafe || false;
      
      if (connectivityTest.success) {
        this.serviceStatus.healthy = true;
        this.serviceStatus.mode = 'api';
        console.log('✅ Mixed Content Safe streaming service initialized successfully');
        console.log('📊 Service details:', connectivityTest.details);
        
        if (connectivityTest.details?.mixedContentSafe) {
          console.log('🔒 Mixed Content Policy compliance achieved');
        }
      } else {
        this.serviceStatus.healthy = false;
        this.serviceStatus.mode = 'fallback';
        console.log('⚠️ Mixed Content Safe service unavailable - initialized in fallback mode');
        console.log('🔄 Fallback mode provides basic RTMP streaming without API features');
        console.log('💡 Recommendations:', connectivityTest.recommendations);
        
        // Check if this is a mixed content issue
        if (connectivityTest.message && connectivityTest.message.includes('Mixed Content')) {
          console.error('🚨 Mixed Content Policy is blocking streaming service access!');
          console.log('🔧 Solution: Configure go2rtc service with HTTPS support');
        }
      }
      
      return true;
    } catch (error) {
      console.warn('⚠️ Mixed Content Safe service initialization had issues:', error);
      this.serviceStatus.initialized = true;
      this.serviceStatus.healthy = false;
      this.serviceStatus.mode = 'fallback';
      return true;
    }
  }

  /**
   * FIXED: Health check with Mixed Content Policy handling
   */
  async checkServiceHealth() {
    try {
      console.log('🏥 Checking Mixed Content Safe service health...');
      
      const healthTest = await streamingConfigMixedContentFix.testStreamingServiceConnection();
      
      this.serviceStatus.lastCheck = new Date().toISOString();
      this.serviceStatus.healthy = healthTest.success;
      this.serviceStatus.mode = healthTest.success ? 'api' : 'fallback';
      this.serviceStatus.mixedContentSafe = healthTest.details?.mixedContentSafe || false;
      
      if (healthTest.success) {
        console.log('✅ Mixed Content Safe service health check passed');
        return true;
      } else {
        console.log('⚠️ Mixed Content Safe service health check failed');
        console.log('💡 Recommendations:', healthTest.recommendations);
        
        if (healthTest.message && healthTest.message.includes('Mixed Content')) {
          console.error('🚨 Mixed Content Policy blocking service access');
        }
        
        return false;
      }
    } catch (error) {
      console.error('❌ Health check error:', error);
      this.serviceStatus.healthy = false;
      this.serviceStatus.mode = 'fallback';
      this.serviceStatus.lastCheck = new Date().toISOString();
      return false;
    }
  }

  /**
   * FIXED: Start event stream with Mixed Content Safe configuration
   */
  async startEventStream(eventId, userId, config = {}) {
    try {
      console.log('🎬 Starting event stream (Mixed Content Safe):', { eventId, userId, config });
      
      // Check if we should try API mode or go straight to fallback
      if (this.serviceStatus.mode === 'api' && this.serviceStatus.healthy) {
        console.log('🔄 Attempting Mixed Content Safe API mode first...');
        
        try {
          return await this.startEventStreamAPI(eventId, userId, config);
        } catch (apiError) {
          console.warn('⚠️ Mixed Content Safe API mode failed, switching to fallback:', apiError.message);
          this.serviceStatus.mode = 'fallback';
          this.serviceStatus.healthy = false;
        }
      }
      
      // Use fallback mode
      console.log('🔄 Using fallback mode for stream creation...');
      return await this.startEventStreamFallback(eventId, userId, config);
      
    } catch (error) {
      console.error('❌ Failed to start event stream in any mode:', error);
      this.emit('streamError', { error: error.message });
      throw error;
    }
  }

  /**
   * FIXED: Start stream using Mixed Content Safe API
   */
  async startEventStreamAPI(eventId, userId, config = {}) {
    console.log('🌐 Starting stream via Mixed Content Safe API...');
    
    // Generate stream configuration using mixed content safe config
    const streamConfig = streamingConfigMixedContentFix.generateEventStreamConfig(
      eventId, 
      userId, 
      config.quality || 'medium',
      config
    );
    
    // Validate configuration
    const validation = streamingConfigMixedContentFix.validateStreamConfig(streamConfig);
    if (!validation.isValid) {
      throw new Error(`Invalid stream configuration: ${validation.errors.join(', ')}`);
    }

    // Store stream information
    const streamId = streamConfig.streamId;
    const rtmpUrl = streamConfig.settings.rtmp.url;
    const viewerUrl = streamConfig.settings.viewer.url;
    
    this.streamConfigs.set(streamId, streamConfig);
    this.activeStreams.set(streamId, {
      status: 'ready',
      startTime: Date.now(),
      config: streamConfig,
      eventId,
      userId,
      rtmpUrl,
      viewerUrl,
      mode: 'api',
      mixedContentSafe: streamConfig.mixedContentSafe,
      stats: {
        viewers: 0,
        bitrate: streamConfig.qualitySettings.bitrate,
        fps: streamConfig.qualitySettings.framerate,
        droppedFrames: 0,
        duration: 0
      }
    });

    const result = {
      success: true,
      streamId: streamId,
      streamKey: streamId,
      rtmpUrl: rtmpUrl,
      viewerUrl: viewerUrl,
      playbackUrl: `${this.baseUrl}/hls/${streamId}.m3u8`,
      config: streamConfig,
      mode: 'api',
      mixedContentSafe: streamConfig.mixedContentSafe,
      message: 'Stream ready - Mixed Content Safe service available'
    };
    
    console.log('✅ Stream configured via Mixed Content Safe API:', result);
    this.emit('streamStarted', { streamId, eventId, userId, config: streamConfig, result });
    
    // FIXED: Special logging for event ZnUnrKpmYyvxFKH3GeaB
    if (eventId === 'ZnUnrKpmYyvxFKH3GeaB') {
      console.log('🎯 Special event stream ready for ZnUnrKpmYyvxFKH3GeaB');
      console.log('📺 Stream viewer URL:', viewerUrl);
      console.log('🔒 Mixed Content Safe:', streamConfig.mixedContentSafe);
    }
    
    return result;
  }

  /**
   * FIXED: Start stream using fallback mode with Mixed Content awareness
   */
  async startEventStreamFallback(eventId, userId, config = {}) {
    console.log('🔄 Starting stream via fallback mode (Mixed Content aware)...');
    
    // Use the fallback method with mixed content safe config
    const streamConfig = streamingConfigMixedContentFix.generateEventStreamConfig(
      eventId, 
      userId, 
      config.quality || 'medium',
      config
    );
    
    const result = {
      success: true,
      streamId: streamConfig.streamId,
      streamKey: streamConfig.streamId,
      rtmpUrl: streamConfig.settings.rtmp.url,
      viewerUrl: streamConfig.settings.viewer.url,
      playbackUrl: `${this.baseUrl}/hls/${streamConfig.streamId}.m3u8`,
      config: streamConfig,
      mode: 'fallback',
      mixedContentSafe: streamConfig.mixedContentSafe,
      message: 'Stream ready - Fallback mode (Mixed Content aware)'
    };
    
    // Store locally for tracking
    this.streamConfigs.set(result.streamId, result.config);
    this.activeStreams.set(result.streamId, {
      status: 'ready',
      startTime: Date.now(),
      config: result.config,
      eventId,
      userId,
      rtmpUrl: result.rtmpUrl,
      viewerUrl: result.viewerUrl,
      mode: 'fallback',
      mixedContentSafe: streamConfig.mixedContentSafe,
      stats: {
        viewers: 0,
        bitrate: result.config.qualitySettings.bitrate,
        fps: result.config.qualitySettings.framerate,
        droppedFrames: 0,
        duration: 0
      }
    });
    
    console.log('✅ Stream configured via fallback mode (Mixed Content aware):', result);
    this.emit('streamStarted', { 
      streamId: result.streamId, 
      eventId, 
      userId, 
      config: result.config, 
      result 
    });
    
    return result;
  }

  /**
   * Stop streaming with better cleanup
   */
  async stopStream(streamId) {
    try {
      console.log('🛑 Stopping stream (Mixed Content Safe):', streamId);
      
      const streamInfo = this.activeStreams.get(streamId);
      
      // Clean up local state
      this.activeStreams.delete(streamId);
      this.streamConfigs.delete(streamId);
      
      console.log('✅ Stream stopped and cleaned up:', streamId);
      this.emit('streamStopped', { streamId });
      
      return { 
        success: true, 
        streamId, 
        mode: streamInfo?.mode || 'unknown',
        mixedContentSafe: streamInfo?.mixedContentSafe || false,
        message: 'Stream stopped successfully'
      };
      
    } catch (error) {
      console.error('❌ Failed to stop stream:', error);
      this.activeStreams.delete(streamId);
      this.streamConfigs.delete(streamId);
      throw error;
    }
  }

  /**
   * FIXED: Get stream statistics with Mixed Content Safe handling
   */
  async getStreamStats(streamId) {
    try {
      const stream = this.activeStreams.get(streamId);
      if (!stream) {
        return null;
      }

      // Try to get stats from Mixed Content Safe API if in API mode
      if (stream.mode === 'api' && this.serviceStatus.healthy && this.serviceStatus.mixedContentSafe) {
        try {
          const response = await fetch(`${this.apiEndpoint}`, {
            signal: AbortSignal.timeout(3000)
          });
          
          if (response.ok) {
            const apiData = await response.json();
            console.log('📊 Got stats from Mixed Content Safe API:', apiData);
            
            if (apiData.version) {
              console.log(`📊 go2rtc service version: ${apiData.version}`);
            }
          }
        } catch (error) {
          console.warn('⚠️ Failed to get real-time stats, using local data:', error.message);
        }
      }

      const duration = Date.now() - stream.startTime;
      const hours = Math.floor(duration / 3600000);
      const minutes = Math.floor((duration % 3600000) / 60000);
      const seconds = Math.floor((duration % 60000) / 1000);

      return {
        ...stream.stats,
        streamId,
        status: stream.status,
        duration: `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`,
        uptime: duration,
        eventId: stream.eventId,
        userId: stream.userId,
        rtmpUrl: stream.rtmpUrl,
        viewerUrl: stream.viewerUrl,
        mode: stream.mode,
        mixedContentSafe: stream.mixedContentSafe,
        serviceStatus: this.serviceStatus
      };
    } catch (error) {
      console.error('❌ Failed to get stream stats:', error);
      return null;
    }
  }

  /**
   * Test connectivity with Mixed Content Safe handling
   */
  async testStreamConnectivity(eventId, userId) {
    try {
      console.log('🔍 Testing stream connectivity (Mixed Content Safe)...');
      return await streamingConfigMixedContentFix.testStreamConnectivity(eventId, userId);
    } catch (error) {
      console.error('❌ Connectivity test error:', error);
      return {
        success: false,
        message: 'Connectivity test failed',
        mode: 'error',
        error: error.message,
        serviceStatus: this.serviceStatus
      };
    }
  }

  /**
   * Get service status with Mixed Content details
   */
  getServiceStatus() {
    return {
      ...this.serviceStatus,
      activeStreams: this.activeStreams.size,
      streamList: Array.from(this.activeStreams.keys()),
      capabilities: {
        canStartStreams: true,
        hasApiFeatures: this.serviceStatus.mode === 'api',
        hasRealTimeStats: this.serviceStatus.healthy,
        fallbackAvailable: true,
        mixedContentSafe: this.serviceStatus.mixedContentSafe,
        protocol: this.baseUrl.startsWith('https') ? 'HTTPS' : 'HTTP'
      }
    };
  }

  /**
   * Force refresh service status
   */
  async refreshServiceStatus() {
    console.log('🔄 Refreshing Mixed Content Safe service status...');
    await this.checkServiceHealth();
    return this.getServiceStatus();
  }

  /**
   * Get service information with Mixed Content details
   */
  getServiceInfo() {
    const envInfo = streamingConfigMixedContentFix.getEnvironmentInfo();
    
    return {
      mode: this.serviceStatus.mode,
      healthy: this.serviceStatus.healthy,
      initialized: this.serviceStatus.initialized,
      lastCheck: this.serviceStatus.lastCheck,
      mixedContentSafe: this.serviceStatus.mixedContentSafe,
      baseUrl: this.baseUrl,
      apiEndpoint: this.apiEndpoint,
      healthEndpoint: this.healthEndpoint,
      rtmpEndpoint: streamingConfigMixedContentFix.streamingService.rtmpStream,
      viewerUrl: streamingConfigMixedContentFix.streamingService.streamViewerUrl,
      activeStreams: this.activeStreams.size,
      serviceType: 'go2rtc-mixed-content-safe',
      protocol: envInfo.protocol,
      siteProtocol: envInfo.siteProtocol,
      features: this.serviceStatus.mode === 'api' 
        ? ['mixed-content-safe', 'go2rtc-api', 'rtmp-streaming', 'web-viewer', 'local-tracking']
        : ['mixed-content-aware', 'rtmp-streaming', 'local-tracking', 'fallback-mode'],
      limitations: this.serviceStatus.mode === 'fallback'
        ? ['no-api-features', 'no-real-time-stats', 'basic-monitoring']
        : this.serviceStatus.mixedContentSafe ? [] : ['mixed-content-policy-issues']
    };
  }

  /**
   * Get stream viewer URL with Mixed Content Safe handling
   */
  getStreamViewerUrl(streamId) {
    return streamingConfigMixedContentFix.getStreamViewerUrl(streamId);
  }

  // Event emitter methods and cleanup remain the same...
  emit(event, data) {
    if (this.listeners && this.listeners[event]) {
      this.listeners[event].forEach(callback => {
        try {
          callback(data);
        } catch (error) {
          console.error('❌ Error in event listener:', error);
        }
      });
    }
  }

  on(event, callback) {
    if (!this.listeners) {
      this.listeners = {};
    }
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(callback);
  }

  off(event, callback) {
    if (this.listeners && this.listeners[event]) {
      this.listeners[event] = this.listeners[event].filter(cb => cb !== callback);
    }
  }

  cleanup() {
    console.log('🧹 Cleaning up Mixed Content Safe streaming service...');
    
    for (const streamId of this.activeStreams.keys()) {
      this.stopStream(streamId).catch(error => {
        console.error(`❌ Failed to stop stream ${streamId} during cleanup:`, error);
      });
    }

    this.activeStreams.clear();
    this.streamConfigs.clear();
    this.listeners = {};
    
    this.serviceStatus = {
      initialized: false,
      healthy: false,
      lastCheck: null,
      mode: 'unknown',
      mixedContentSafe: false
    };
    
    console.log('✅ Mixed Content Safe streaming service cleanup complete');
  }

  // List all active streams and other utility methods remain the same...
  getActiveStreams() {
    const streams = [];
    for (const [streamId, streamData] of this.activeStreams) {
      streams.push({
        streamId,
        ...streamData
      });
    }
    return streams;
  }

  isStreamActive(streamId) {
    return this.activeStreams.has(streamId);
  }

  getStreamConfig(streamId) {
    return this.streamConfigs.get(streamId);
  }
}

// Export singleton instance
const ffmpegStreamingService = new FFmpegStreamingService();
export default ffmpegStreamingService;