// src/components/posts/PostCard.jsx
import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { usePostsContext } from '../../contexts/PostsContext';
import {
  doc,
  updateDoc,
  arrayUnion,
  arrayRemove,
  collection,
  query,
  where,
  orderBy,
  onSnapshot,
  addDoc,
  serverTimestamp,
  increment,
  deleteDoc,
  getDocs
} from 'firebase/firestore';
import { db } from '../../firebase';
import {
  Heart,
  MessageCircle,
  Share2,
  Trash2,
  Music,
  MoreHorizontal,
  Bookmark,
  Flag,
  Copy,
  ExternalLink
} from 'lucide-react';
import CommentSection from './CommentSection';
import VideoPlayer from './VideoPlayer';
import './PostCard.css';

const PostCard = ({ post, onDelete }) => {
  const { currentUser } = useAuth();
  const { subscribeToPost, unsubscribeFromPost, getPostData } = usePostsContext();
  const postData = getPostData(post.id);
  const [likes, setLikes] = useState(postData.likes.length > 0 ? postData.likes : (Array.isArray(post.likes) ? post.likes : []));
  const [commentsCount, setCommentsCount] = useState(postData.commentsCount > 0 ? postData.commentsCount : (post.commentsCount || 0));
  const [showComments, setShowComments] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [error, setError] = useState('');
  const [showOptionsMenu, setShowOptionsMenu] = useState(false);
  const [isLiking, setIsLiking] = useState(false);
  const [shareSuccess, setShareSuccess] = useState(false);

  const isLiked = currentUser && Array.isArray(likes) && likes.includes(currentUser.uid);
  const isOwner = currentUser && post.authorId === currentUser.uid;

  // Subscribe to post updates through context
  useEffect(() => {
    subscribeToPost(post.id);
    return () => unsubscribeFromPost(post.id);
  }, [post.id, subscribeToPost, unsubscribeFromPost]);

  // Update local state when context data changes
  useEffect(() => {
    if (postData.likes.length > 0) {
      setLikes(postData.likes);
    }
    if (postData.commentsCount > 0) {
      setCommentsCount(postData.commentsCount);
    }
  }, [postData]);

  // Close options menu when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (showOptionsMenu && !event.target.closest('.options-menu-container')) {
        setShowOptionsMenu(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showOptionsMenu]);

  const handleLike = async () => {
    if (!currentUser || currentUser.isAnonymous) {
      alert('Please log in to like posts');
      return;
    }

    if (isLiking) return;
    setIsLiking(true);

    try {
      const postRef = doc(db, 'posts', post.id);
      
      if (isLiked) {
        // Unlike
        await updateDoc(postRef, {
          likes: arrayRemove(currentUser.uid),
          likesCount: increment(-1)
        });
      } else {
        // Like
        await updateDoc(postRef, {
          likes: arrayUnion(currentUser.uid),
          likesCount: increment(1)
        });
      }
    } catch (err) {
      console.error('Error updating like:', err);
      setError('Failed to update like');
    } finally {
      setIsLiking(false);
    }
  };

  const handleDelete = async () => {
    if (!isOwner) return;
    
    const confirmDelete = window.confirm('Are you sure you want to delete this post? This action cannot be undone.');
    if (!confirmDelete) return;

    setIsDeleting(true);
    setError('');

    try {
      // Delete all comments first
      const commentsRef = collection(db, 'posts', post.id, 'comments');
      const commentsQuery = query(commentsRef);
      const commentsSnapshot = await getDocs(commentsQuery);
      
      const deletePromises = commentsSnapshot.docs.map(doc => deleteDoc(doc.ref));
      await Promise.all(deletePromises);

      // Then delete the post
      await deleteDoc(doc(db, 'posts', post.id));
      
      if (onDelete) {
        onDelete(post.id);
      }
    } catch (err) {
      console.error('Error deleting post:', err);
      setError('Failed to delete post');
      setIsDeleting(false);
    }
  };

  const handleShare = async () => {
    try {
      const postUrl = `${window.location.origin}/post/${post.id}`;
      await navigator.clipboard.writeText(postUrl);
      setShareSuccess(true);
      setTimeout(() => setShareSuccess(false), 2000);
    } catch (err) {
      console.error('Error sharing post:', err);
      // Fallback for browsers that don't support clipboard API
      prompt('Copy this link:', postUrl);
    }
  };

  const handleReport = () => {
    // Implement report functionality
    alert('Report functionality will be implemented soon');
    setShowOptionsMenu(false);
  };

  const handleBookmark = () => {
    // Implement bookmark functionality
    alert('Bookmark functionality will be implemented soon');
    setShowOptionsMenu(false);
  };

  const formatDate = (timestamp) => {
    if (!timestamp) return '';
    const date = timestamp.toDate ? timestamp.toDate() : new Date(timestamp);
    const now = new Date();
    const diff = now - date;
    
    if (diff < 60000) return 'just now';
    if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
    if (diff < 86400000) return `${Math.floor(diff / 3600000)}h ago`;
    if (diff < 604800000) return `${Math.floor(diff / 86400000)}d ago`;
    
    return date.toLocaleDateString();
  };

  const getProfileUrl = () => {
    if (post.isArtist) {
      return `/artist/${post.authorId}`;
    }
    return `/people/${post.authorId}`;
  };

  return (
    <article className="post-card">
      {/* Post Header */}
      <header className="post-header">
        <Link to={getProfileUrl()} className="author-info">
          <div className="author-avatar">
            {post.authorPhoto ? (
              <img 
                src={post.authorPhoto} 
                alt={post.authorName}
                loading="lazy"
              />
            ) : (
              <div className="avatar-placeholder">
                {post.authorName?.charAt(0)?.toUpperCase() || 'U'}
              </div>
            )}
          </div>
          <div className="author-details">
            <div className="author-name">
              {post.authorName}
              {post.isArtist && (
                <span className="artist-badge" title="Verified Artist">
                  <Music size={12} />
                </span>
              )}
            </div>
            <time className="post-time" dateTime={post.createdAt?.toDate?.()?.toISOString?.()}>
              {formatDate(post.createdAt)}
            </time>
          </div>
        </Link>
        
        {/* Options Menu */}
        <div className="options-menu-container">
          <button
            className="options-button"
            onClick={() => setShowOptionsMenu(!showOptionsMenu)}
            aria-label="Post options"
          >
            <MoreHorizontal size={20} />
          </button>
          
          {showOptionsMenu && (
            <div className="options-menu">
              {isOwner ? (
                <>
                  <button
                    className="menu-item delete-item"
                    onClick={handleDelete}
                    disabled={isDeleting}
                  >
                    <Trash2 size={16} />
                    {isDeleting ? 'Deleting...' : 'Delete post'}
                  </button>
                </>
              ) : (
                <>
                  <button className="menu-item" onClick={handleBookmark}>
                    <Bookmark size={16} />
                    Save post
                  </button>
                  <button className="menu-item" onClick={handleShare}>
                    <Copy size={16} />
                    Copy link
                  </button>
                  <button className="menu-item report-item" onClick={handleReport}>
                    <Flag size={16} />
                    Report post
                  </button>
                </>
              )}
            </div>
          )}
        </div>
      </header>

      {/* Post Content */}
      <div className="post-content">
        {post.content && (
          <div className="post-text">
            <p>{post.content}</p>
          </div>
        )}

        {/* Video content */}
        {post.video && post.video.url && (
          <VideoPlayer video={post.video} />
        )}

        {/* Image content */}
        {post.images && post.images.length > 0 && (
          <div className={`post-images images-${Math.min(post.images.length, 4)}`}>
            {post.images.slice(0, 4).map((image, index) => (
              <div key={index} className="image-container">
                <img
                  src={image}
                  alt={`Post image ${index + 1}`}
                  loading="lazy"
                />
                {post.images.length > 4 && index === 3 && (
                  <div className="more-images-overlay">
                    +{post.images.length - 4} more
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Error Message */}
      {error && (
        <div className="error-message" role="alert">
          {error}
        </div>
      )}

      {/* Share Success Message */}
      {shareSuccess && (
        <div className="success-message" role="status">
          Link copied to clipboard!
        </div>
      )}

      {/* Post Actions */}
      <footer className="post-actions">
        <div className="primary-actions">
          <button
            className={`action-button like-button ${isLiked ? 'liked' : ''}`}
            onClick={handleLike}
            disabled={isLiking}
            aria-label={isLiked ? 'Unlike post' : 'Like post'}
          >
            <Heart size={20} />
            <span className="action-count">{likes.length}</span>
          </button>
          
          <button
            className="action-button comment-button"
            onClick={() => setShowComments(!showComments)}
            aria-label={showComments ? 'Hide comments' : 'Show comments'}
          >
            <MessageCircle size={20} />
            <span className="action-count">{commentsCount}</span>
          </button>
        </div>
        
        <button 
          className="action-button share-button" 
          onClick={handleShare}
          aria-label="Share post"
        >
          <Share2 size={20} />
        </button>
      </footer>

      {/* Comments Section */}
      {showComments && (
        <div className="comments-container">
          <CommentSection 
            postId={post.id} 
            onCommentAdd={() => setCommentsCount(prev => prev + 1)}
            onCommentDelete={() => setCommentsCount(prev => prev - 1)}
          />
        </div>
      )}
    </article>
  );
};

export default PostCard;