// src/components/audio/JamPad.jsx
//
// XY gesture performance surface, Audima-Sway-style:
//   X axis → scale degree, quantized by the engine's theory engine (always in key)
//   Y axis → expression (velocity + filter brightness)
//
// Drag to glide between notes (portamento on glide/bass, retrigger on keys).
// The engine does all sound + capture; this component only translates
// pointer gestures into perfStart/perfMove/perfEnd calls.

import React, { useCallback, useEffect, useRef, useState } from 'react';

import { PAD_DEGREES } from '../../services/sketchEngine';

const INSTRUMENTS = [
  { key: 'glide', label: 'glide' },
  { key: 'keys',  label: 'keys'  },
  { key: 'bass',  label: 'bass'  },
];

const JamPad = ({ engine, disabled, recording, refreshKey }) => {
  const padRef = useRef(null);
  const [instr, setInstr] = useState('glide');
  const [active, setActive] = useState(null); // { degree, note, x, y }
  const [theory, setTheory] = useState(null);

  useEffect(() => {
    if (engine) {
      try { setTheory(engine.getTheory()); } catch (_) { /* noop */ }
    }
  }, [engine, disabled, refreshKey]);

  const coords = useCallback((e) => {
    const rect = padRef.current.getBoundingClientRect();
    const x = (e.clientX - rect.left) / rect.width;
    const y = 1 - (e.clientY - rect.top) / rect.height; // bottom = 0, top = 1
    return { x: Math.max(0, Math.min(1, x)), y: Math.max(0, Math.min(1, y)) };
  }, []);

  const onDown = (e) => {
    if (!engine || disabled) return;
    e.preventDefault();
    padRef.current.setPointerCapture(e.pointerId);
    const { x, y } = coords(e);
    const res = engine.perfStart(instr, x, y);
    if (res) setActive({ ...res, x, y });
  };

  const onMove = (e) => {
    if (!engine || disabled || !active) return;
    const { x, y } = coords(e);
    const res = engine.perfMove(x, y);
    setActive(prev => ({ ...(res || prev), x, y }));
  };

  const onUp = () => {
    if (!engine) return;
    engine.perfEnd();
    setActive(null);
  };

  const degrees = theory ? theory.degrees : [];

  return (
    <div>
      {/* Instrument picker */}
      <div style={{ display: 'flex', gap: 6, marginBottom: 8 }}>
        {INSTRUMENTS.map(opt => (
          <button
            key={opt.key}
            type="button"
            onClick={() => setInstr(opt.key)}
            style={{
              fontSize: 12,
              padding: '6px 12px',
              borderRadius: 16,
              background: instr === opt.key ? '#1a1626' : '#15151e',
              color: instr === opt.key ? '#AFA9EC' : '#8b8b9a',
              border: '0.5px solid ' + (instr === opt.key ? '#3C3489' : '#25252e'),
              cursor: 'pointer',
            }}
          >
            {opt.label}
          </button>
        ))}
        {theory && (
          <span style={{ marginLeft: 'auto', fontSize: 11, color: '#6b6b7a', alignSelf: 'center' }}>
            {theory.keyName} {theory.scaleName}
          </span>
        )}
      </div>

      {/* Pad surface */}
      <div
        ref={padRef}
        onPointerDown={onDown}
        onPointerMove={onMove}
        onPointerUp={onUp}
        onPointerCancel={onUp}
        onPointerLeave={onUp}
        style={{
          position: 'relative',
          height: 180,
          borderRadius: 12,
          border: '0.5px solid ' + (recording ? '#E24B4A' : '#25252e'),
          background: 'linear-gradient(180deg, rgba(127,119,221,0.10), rgba(10,10,18,0.6))',
          touchAction: 'none',
          userSelect: 'none',
          cursor: disabled ? 'not-allowed' : 'crosshair',
          opacity: disabled ? 0.45 : 1,
          overflow: 'hidden',
        }}
      >
        {/* Degree columns */}
        {Array.from({ length: PAD_DEGREES }).map((_, i) => (
          <div
            key={i}
            style={{
              position: 'absolute',
              left: `${(i / PAD_DEGREES) * 100}%`,
              top: 0,
              bottom: 0,
              width: `${100 / PAD_DEGREES}%`,
              borderLeft: i === 0 ? 'none' : '1px solid rgba(255,255,255,0.04)',
              background: active && active.degree === i ? 'rgba(127,119,221,0.22)' : 'transparent',
              transition: 'background 0.08s',
            }}
          >
            {degrees[i] && (
              <span
                style={{
                  position: 'absolute',
                  bottom: 4,
                  left: 0,
                  right: 0,
                  textAlign: 'center',
                  fontSize: 9,
                  color: i % 7 === 0 ? '#AFA9EC' : '#4b4b5a',
                  pointerEvents: 'none',
                }}
              >
                {degrees[i].note.replace(/\d+$/, '')}
              </span>
            )}
          </div>
        ))}

        {/* Active touch dot */}
        {active && (
          <div
            style={{
              position: 'absolute',
              left: `calc(${active.x * 100}% - 14px)`,
              top: `calc(${(1 - active.y) * 100}% - 14px)`,
              width: 28,
              height: 28,
              borderRadius: '50%',
              background: 'radial-gradient(circle at 35% 35%, #AFA9EC, #534AB7)',
              boxShadow: '0 0 18px rgba(127,119,221,0.7)',
              pointerEvents: 'none',
            }}
          />
        )}

        {/* Hints */}
        {!active && (
          <div
            style={{
              position: 'absolute',
              inset: 0,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              color: '#4b4b5a',
              fontSize: 12,
              pointerEvents: 'none',
            }}
          >
            drag to play · ← pitch → · ↑ brighter ↓ softer
          </div>
        )}
      </div>

      {active && (
        <div style={{ marginTop: 6, fontSize: 11, color: '#AFA9EC', fontVariantNumeric: 'tabular-nums' }}>
          {active.note}
        </div>
      )}
    </div>
  );
};

export default JamPad;
