import React, { useState, useEffect, useRef } from 'react';
import { Mic, PauseCircle, PlayCircle, Save, Trash2, Plus, RefreshCw, Info, Music, Search, Volume2 } from 'lucide-react';
import { db } from '../../firebase';
import { 
  collection, 
  getDocs, 
  doc, 
  getDoc, 
  addDoc, 
  updateDoc, 
  deleteDoc, 
  query, 
  where, 
  orderBy 
} from 'firebase/firestore';
import { getDatabase, ref, update, get } from 'firebase/database';
import { useAudioDetection } from '../../hooks/useAudioDetection';
import { useChatRooms } from '../../hooks/useChatRooms';

const AudioDetectionManager = () => {
  // States for audio signatures
  const [signatures, setSignatures] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [activeTab, setActiveTab] = useState('signatures');
  const [stats, setStats] = useState({ totalSignatures: 0, totalRooms: 0, activeSignatures: 0 });
  
  // Use our chat rooms hook with all available options
  const { 
    rooms, 
    loading: roomsLoading, 
    error: roomsError, 
    fetchRooms,
    fetchRoomsFromCollection,
    fetchRoomsFromRTDB
  } = useChatRooms({
    loadOnMount: true,
    collectionName: 'publicChats'
  });
  
  // Track database sources that have been searched
  const [searchedSources, setSearchedSources] = useState([]);
  
  // States for recording
  const [isRecording, setIsRecording] = useState(false);
  const [recordingTime, setRecordingTime] = useState(0);
  const [audioFingerprint, setAudioFingerprint] = useState(null);
  const [recordingStatus, setRecordingStatus] = useState('idle'); // idle, ready, recording, processing, success, error
  const [audioPermissionGranted, setAudioPermissionGranted] = useState(false);
  
  // States for form
  const [selectedRoom, setSelectedRoom] = useState(null);
  const [sourceType, setSourceType] = useState('broadcast');
  const [sourceDescription, setSourceDescription] = useState('');
  
  // References
  const audioContextRef = useRef(null);
  const analyserRef = useRef(null);
  const mediaRecorderRef = useRef(null);
  const recordedChunksRef = useRef([]);
  const canvasRef = useRef(null);
  const animationFrameRef = useRef(null);
  const timerRef = useRef(null);
  
  // Custom hook for audio detection
  const { 
    initializeAudio,
    processAudioData,
    calculateSimilarity
  } = useAudioDetection();
  
  // Load signatures on component mount
  useEffect(() => {
    const fetchSignatures = async () => {
      try {
        setLoading(true);
        // Fetch audio signatures
        const signaturesRef = collection(db, 'audioSignatures');
        const signaturesQuery = query(signaturesRef, orderBy('createdAt', 'desc'));
        const signaturesSnapshot = await getDocs(signaturesQuery);
        
        // Get all signature data
        const signaturesData = signaturesSnapshot.docs.map(doc => ({
          id: doc.id,
          ...doc.data(),
        }));
        
        // For each signature, try to get room source information
        for (const signature of signaturesData) {
          try {
            // First try RTDB
            const rtdb = getDatabase();
            const roomRef = ref(rtdb, `chats/public/${signature.roomId}`);
            const snapshot = await get(roomRef);
            
            if (snapshot.exists()) {
              // Room found in RTDB
              signature.roomSource = 'rtdb';
              signature.roomPath = `chats/public/${signature.roomId}`;
              continue;
            }
            
            // If not in RTDB, check Firestore collections
            const collections = ['publicChats', 'rooms', 'chatRooms'];
            let found = false;
            
            for (const collectionName of collections) {
              try {
                const firestoreRoomRef = doc(db, collectionName, signature.roomId);
                const firestoreSnapshot = await getDoc(firestoreRoomRef);
                
                if (firestoreSnapshot.exists()) {
                  // Room found in Firestore
                  signature.roomSource = 'firestore';
                  signature.roomCollectionName = collectionName;
                  found = true;
                  break;
                }
              } catch (err) {
                console.log(`Error checking ${collectionName} for room ${signature.roomId}:`, err);
              }
            }
            
            if (!found) {
              // Room not found in any source
              signature.roomSource = 'unknown';
            }
          } catch (err) {
            console.error(`Error getting source information for room ${signature.roomId}:`, err);
            signature.roomSource = 'unknown';
          }
        }
        
        console.log(`Loaded ${signaturesData.length} audio signatures`);
        setSignatures(signaturesData);
        setLoading(false);
      } catch (err) {
        console.error('Error fetching signatures:', err);
        setError(`Error fetching signatures: ${err.message}. Check console for details.`);
        setLoading(false);
      }
    };
    
    fetchSignatures();
    
    // Initialize audio context
    initializeAudio();
    
    // Cleanup function
    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
      
      if (timerRef.current) {
        clearInterval(timerRef.current);
      }
      
      if (mediaRecorderRef.current && mediaRecorderRef.current.state === 'recording') {
        mediaRecorderRef.current.stop();
      }
      
      if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
        audioContextRef.current.close();
      }
    };
  }, []);
  
  // Debug room loading issues
  useEffect(() => {
    console.log('Rooms data state:', { 
      roomsCount: rooms?.length || 0,
      roomsLoading,
      roomsError,
      rooms
    });
    
    if (roomsError) {
      console.error('Error loading rooms:', roomsError);
    }
  }, [rooms, roomsLoading, roomsError]);

  // Update stats when rooms or signatures change
  useEffect(() => {
    if (rooms && signatures) {
      setStats({
        totalSignatures: signatures.length,
        totalRooms: rooms.length,
        activeSignatures: signatures.filter(s => s.isActive).length,
        roomsWithSignatures: rooms.filter(r => r.hasAudioSignature).length,
      });
      
      console.log('Stats updated:', {
        totalSignatures: signatures.length,
        totalRooms: rooms.length,
        activeSignatures: signatures.filter(s => s.isActive).length,
        roomsWithSignatures: rooms.filter(r => r.hasAudioSignature).length,
      });
    }
  }, [rooms, signatures]);

  // Force rooms to load when creating new signature
  useEffect(() => {
    if (activeTab === 'create') {
      console.log('Automatically fetching rooms for audio signature creation');
      
      // Fetch from both Realtime Database and Firestore
      const fetchAllRooms = async () => {
        setSearchedSources([]);
        setRoomBatchLoading(true);
        
        try {
          // 1. Try Realtime Database first (most rooms are here)
          console.log('Fetching rooms from Realtime Database...');
          const rtdbRooms = await fetchRoomsFromRTDB();
          if (rtdbRooms && rtdbRooms.length > 0) {
            console.log(`Found ${rtdbRooms.length} rooms in Realtime Database`);
            setSearchedSources(prev => [...prev, 'Firebase Realtime Database']);
          } else {
            console.log('No rooms found in Realtime Database');
          }
          
          // 2. Try Firestore collections as fallback
          const collections = ['publicChats', 'rooms', 'chatRooms'];
          for (const collection of collections) {
            try {
              console.log(`Attempting to fetch rooms from Firestore collection ${collection}...`);
              const firestoreRooms = await fetchRoomsFromCollection(collection);
              if (firestoreRooms && firestoreRooms.length > 0) {
                console.log(`Found ${firestoreRooms.length} rooms in Firestore collection ${collection}`);
                setSearchedSources(prev => [...prev, `Firestore: ${collection}`]);
              }
            } catch (err) {
              console.error(`Error fetching from Firestore collection ${collection}:`, err);
            }
          }
        } catch (err) {
          console.error('Error during room fetching:', err);
          setError(`Failed to fetch rooms: ${err.message}`);
        } finally {
          setRoomBatchLoading(false);
        }
      };
      
      fetchAllRooms();
    }
  }, [activeTab, fetchRoomsFromRTDB, fetchRoomsFromCollection]);
  
  // Add state for batch loading all collections
  const [roomBatchLoading, setRoomBatchLoading] = useState(false);
  
  // Request microphone permissions
  const requestMicrophonePermissions = async () => {
    if (!selectedRoom) {
      setError('Please select a chat room first');
      return;
    }
    
    if (!sourceDescription) {
      setError('Please enter a description of what you are recording');
      return;
    }
    
    try {
      setError(null);
      setRecordingStatus('ready');
      
      // Request microphone access
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      
      // Stop all tracks immediately - we just wanted the permission, not to start recording yet
      stream.getTracks().forEach(track => track.stop());
      
      setAudioPermissionGranted(true);
      
      // Give user feedback that permissions are granted
      console.log('Microphone permissions granted');
    } catch (err) {
      console.error('Error requesting microphone permission:', err);
      setError('Could not access microphone: ' + err.message);
      setRecordingStatus('error');
      setAudioPermissionGranted(false);
    }
  };
  
  // Start recording audio
  const startRecording = async () => {
    if (!audioPermissionGranted) {
      await requestMicrophonePermissions();
      return;
    }
    
    if (!selectedRoom || !sourceDescription) return;
    
    try {
      setError(null);
      setRecordingStatus('recording');
      setIsRecording(true);
      setRecordingTime(0);
      
      // Request microphone access
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      
      // Set up audio context and analyzer
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      audioContextRef.current = new AudioContext();
      analyserRef.current = audioContextRef.current.createAnalyser();
      analyserRef.current.fftSize = 2048;
      
      // Connect microphone to analyzer
      const microphone = audioContextRef.current.createMediaStreamSource(stream);
      microphone.connect(analyserRef.current);
      
      // Set up media recorder
      mediaRecorderRef.current = new MediaRecorder(stream);
      recordedChunksRef.current = [];
      
      mediaRecorderRef.current.ondataavailable = (e) => {
        if (e.data.size > 0) {
          recordedChunksRef.current.push(e.data);
        }
      };
      
      mediaRecorderRef.current.onstop = processRecording;
      mediaRecorderRef.current.start();
      
      // Draw the waveform
      drawWaveform();
      
      // Start a timer
      timerRef.current = setInterval(() => {
        setRecordingTime(prev => {
          if (prev >= 5) { // Auto-stop after 5 seconds
            stopRecording();
            return prev;
          }
          return prev + 1;
        });
      }, 1000);
      
      // Automatically stop after 10 seconds
      setTimeout(() => {
        if (isRecording) {
          stopRecording();
        }
      }, 10000);
    } catch (err) {
      console.error('Error starting recording:', err);
      setError('Could not access microphone: ' + err.message);
      setRecordingStatus('error');
      setIsRecording(false);
    }
  };
  
  // Stop recording
  const stopRecording = () => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state === 'recording') {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      setRecordingStatus('processing');
      
      if (timerRef.current) {
        clearInterval(timerRef.current);
      }
      
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
    }
  };
  
  // Process recorded audio
  const processRecording = async () => {
    try {
      // Create a blob from the recorded chunks
      const audioBlob = new Blob(recordedChunksRef.current, { type: 'audio/webm' });
      
      // Process audio data to create fingerprint
      const fingerprint = await processAudioData(audioBlob, audioContextRef.current);
      
      setAudioFingerprint(fingerprint);
      setRecordingStatus('success');
    } catch (err) {
      console.error('Error processing recording:', err);
      setError('Error processing audio: ' + err.message);
      setRecordingStatus('error');
    }
  };
  
  // Draw audio waveform
  const drawWaveform = () => {
    if (!analyserRef.current || !canvasRef.current) return;
    
    const canvas = canvasRef.current;
    const canvasCtx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;
    
    const bufferLength = analyserRef.current.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    
    const draw = () => {
      animationFrameRef.current = requestAnimationFrame(draw);
      
      analyserRef.current.getByteTimeDomainData(dataArray);
      
      canvasCtx.fillStyle = 'rgb(240, 240, 240)';
      canvasCtx.fillRect(0, 0, width, height);
      
      canvasCtx.lineWidth = 2;
      canvasCtx.strokeStyle = 'rgb(99, 102, 241)';
      canvasCtx.beginPath();
      
      const sliceWidth = width / bufferLength;
      let x = 0;
      
      for (let i = 0; i < bufferLength; i++) {
        const v = dataArray[i] / 128.0;
        const y = v * height / 2;
        
        if (i === 0) {
          canvasCtx.moveTo(x, y);
        } else {
          canvasCtx.lineTo(x, y);
        }
        
        x += sliceWidth;
      }
      
      canvasCtx.lineTo(width, height / 2);
      canvasCtx.stroke();
    };
    
    draw();
  };
  
  // Save audio signature to database
  const saveSignature = async () => {
    if (!audioFingerprint || !selectedRoom) return;
    
    try {
      setLoading(true);
      
      // Create new audio signature in Firestore
      const signatureRef = collection(db, 'audioSignatures');
      const newSignature = {
        roomId: selectedRoom.id,
        roomName: selectedRoom.name,
        vector: audioFingerprint,
        sourceType,
        sourceDescription,
        createdAt: Date.now(),
        expiresAt: Date.now() + (7 * 24 * 60 * 60 * 1000), // 7 days from now
        isActive: true,
        // Store room source information for later reference
        roomSource: selectedRoom.source || 'unknown',
        roomPath: selectedRoom.rtdbPath || null,
        roomCollectionName: selectedRoom.collectionName || null
      };
      
      const docRef = await addDoc(signatureRef, newSignature);
      
      // Update the room data to indicate it has an audio signature - handle both RTDB and Firestore
      if (selectedRoom.source === 'rtdb') {
        // Update in Realtime Database
        console.log('Updating RTDB room:', selectedRoom.rtdbPath);
        const rtdb = getDatabase();
        const roomRef = ref(rtdb, selectedRoom.rtdbPath);
        
        // Perform update
        await update(roomRef, {
          hasAudioSignature: true
        });
      } else {
        // Update in Firestore
        console.log('Updating Firestore room:', selectedRoom.id, 'in collection', selectedRoom.collectionName);
        const roomRef = doc(db, selectedRoom.collectionName || 'publicChats', selectedRoom.id);
        await updateDoc(roomRef, {
          hasAudioSignature: true
        });
      }
      
      // Update signatures state
      setSignatures(prev => [{ id: docRef.id, ...newSignature }, ...prev]);
      
      // Refresh rooms data
      await fetchRooms();
      
      // Reset recording state
      setAudioFingerprint(null);
      setRecordingStatus('idle');
      setSourceDescription('');
      setSelectedRoom(null);
      
      setLoading(false);
    } catch (err) {
      console.error('Error saving signature:', err);
      setError('Failed to save audio signature: ' + err.message);
      setLoading(false);
    }
  };
  
  // Delete an audio signature
  const deleteSignature = async (signatureId, roomId, roomSource, roomPath) => {
    if (!window.confirm('Are you sure you want to delete this audio signature?')) {
      return;
    }
    
    try {
      setLoading(true);
      
      // Delete the signature from Firestore
      await deleteDoc(doc(db, 'audioSignatures', signatureId));
      
      // Check if this is the last signature for this room
      const roomSignaturesQuery = query(
        collection(db, 'audioSignatures'),
        where('roomId', '==', roomId),
        where('isActive', '==', true)
      );
      
      const roomSignaturesSnapshot = await getDocs(roomSignaturesQuery);
      
      // If this was the last signature, update the room
      if (roomSignaturesSnapshot.empty) {
        if (roomSource === 'rtdb') {
          // Update in Realtime Database
          const rtdbPath = roomPath || `chats/public/${roomId}`;
          console.log('Updating RTDB room:', rtdbPath);
          const rtdb = getDatabase();
          const roomRef = ref(rtdb, rtdbPath);
          
          // Perform update
          await update(roomRef, {
            hasAudioSignature: false
          });
        } else {
          // Update in Firestore
          const collectionName = roomSource === 'firestore' ? (roomPath || 'publicChats') : 'publicChats';
          console.log('Updating Firestore room:', roomId, 'in collection', collectionName);
          const roomRef = doc(db, collectionName, roomId);
          await updateDoc(roomRef, {
            hasAudioSignature: false
          });
        }
      }
      
      // Update signatures state
      setSignatures(prev => prev.filter(sig => sig.id !== signatureId));
      
      // Refresh rooms data
      await fetchRooms();
      
      setLoading(false);
    } catch (err) {
      console.error('Error deleting signature:', err);
      setError('Failed to delete audio signature: ' + err.message);
      setLoading(false);
    }
  };
  
  // Toggle signature active status
  const toggleSignatureStatus = async (signatureId, currentStatus) => {
    try {
      setLoading(true);
      
      const signatureRef = doc(db, 'audioSignatures', signatureId);
      await updateDoc(signatureRef, {
        isActive: !currentStatus
      });
      
      // Update state
      setSignatures(prev => prev.map(sig => 
        sig.id === signatureId 
          ? { ...sig, isActive: !currentStatus }
          : sig
      ));
      
      // Update stats
      setStats(prev => ({
        ...prev,
        activeSignatures: currentStatus 
          ? prev.activeSignatures - 1 
          : prev.activeSignatures + 1
      }));
      
      setLoading(false);
    } catch (err) {
      console.error('Error toggling signature status:', err);
      setError('Failed to update signature status: ' + err.message);
      setLoading(false);
    }
  };
  
  // Reset recording state
  const resetRecording = () => {
    setAudioFingerprint(null);
    setRecordingStatus('idle');
    setAudioPermissionGranted(false);
    setError(null);
  };
  
  // Format timestamp to human readable date
  const formatDate = (timestamp) => {
    if (!timestamp) return 'Unknown';
    
    const date = new Date(timestamp);
    return date.toLocaleString();
  };
  
  // Format expiration date with countdown
  const formatExpiration = (expiresAt) => {
    if (!expiresAt) return 'Never';
    
    const now = Date.now();
    const timeLeft = expiresAt - now;
    
    if (timeLeft <= 0) {
      return 'Expired';
    }
    
    const days = Math.floor(timeLeft / (1000 * 60 * 60 * 24));
    const hours = Math.floor((timeLeft % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
    
    return `${days}d ${hours}h (${formatDate(expiresAt)})`;
  };
  
  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold flex items-center">
          <Volume2 className="mr-2" size={24} />
          Audio Detection Manager
        </h1>
        <div className="flex space-x-4">
          <button 
            onClick={() => setActiveTab('dashboard')}
            className={`px-4 py-2 rounded-md ${activeTab === 'dashboard' ? 'bg-indigo-600 text-white' : 'bg-gray-100'}`}
          >
            Dashboard
          </button>
          <button 
            onClick={() => setActiveTab('signatures')}
            className={`px-4 py-2 rounded-md ${activeTab === 'signatures' ? 'bg-indigo-600 text-white' : 'bg-gray-100'}`}
          >
            Signatures
          </button>
          <button 
            onClick={() => setActiveTab('create')}
            className={`px-4 py-2 rounded-md ${activeTab === 'create' ? 'bg-indigo-600 text-white' : 'bg-gray-100'}`}
          >
            Create New
          </button>
        </div>
      </div>
      
      {(error || roomsError) && (
        <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded relative">
          <span className="block sm:inline">{error || roomsError}</span>
          <button 
            className="absolute top-0 bottom-0 right-0 px-4 py-3"
            onClick={() => {
              setError(null);
              if (roomsError) {
                // Retry loading rooms
                fetchRooms();
              }
            }}
          >
            <span className="text-red-500">×</span>
          </button>
        </div>
      )}
      
      {/* Dashboard Tab */}
      {activeTab === 'dashboard' && (
        <div className="bg-white rounded-lg shadow p-6">
          <h2 className="text-xl font-semibold mb-4">Audio Detection Dashboard</h2>
          
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-6">
            <div className="bg-indigo-50 p-4 rounded-lg">
              <div className="flex justify-between items-start">
                <div>
                  <p className="text-indigo-600 text-sm font-medium">Total Audio Signatures</p>
                  <p className="text-3xl font-bold">{stats.totalSignatures}</p>
                </div>
                <div className="bg-indigo-100 p-3 rounded-full">
                  <Volume2 size={20} className="text-indigo-600" />
                </div>
              </div>
            </div>
            
            <div className="bg-green-50 p-4 rounded-lg">
              <div className="flex justify-between items-start">
                <div>
                  <p className="text-green-600 text-sm font-medium">Active Signatures</p>
                  <p className="text-3xl font-bold">{stats.activeSignatures}</p>
                </div>
                <div className="bg-green-100 p-3 rounded-full">
                  <PlayCircle size={20} className="text-green-600" />
                </div>
              </div>
            </div>
            
            <div className="bg-purple-50 p-4 rounded-lg">
              <div className="flex justify-between items-start">
                <div>
                  <p className="text-purple-600 text-sm font-medium">Rooms With Signatures</p>
                  <p className="text-3xl font-bold">{stats.roomsWithSignatures} / {stats.totalRooms}</p>
                </div>
                <div className="bg-purple-100 p-3 rounded-full">
                  <Music size={20} className="text-purple-600" />
                </div>
              </div>
            </div>
          </div>
          
          <div className="bg-gray-50 p-4 rounded-lg">
            <h3 className="text-lg font-medium mb-3">Recent Activity</h3>
            
            {loading || roomsLoading ? (
              <div className="text-center p-4">
                <div className="inline-block animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-indigo-600"></div>
                <p className="mt-2 text-gray-500">Loading data...</p>
              </div>
            ) : signatures.length === 0 ? (
              <div className="text-center p-4">
                <p className="text-gray-500">No audio signatures have been created yet.</p>
              </div>
            ) : (
              <div className="space-y-3">
                {signatures.slice(0, 5).map(signature => (
                  <div key={signature.id} className="bg-white p-3 rounded border">
                    <div className="flex justify-between">
                      <div>
                        <p className="font-medium">{signature.sourceDescription}</p>
                        <p className="text-sm text-gray-500">Room: {signature.roomName}</p>
                      </div>
                      <div className="text-right">
                        <p className="text-sm">Created: {formatDate(signature.createdAt)}</p>
                        <p className="text-sm text-gray-500">
                          {signature.isActive ? (
                            <span className="text-green-600">Active</span>
                          ) : (
                            <span className="text-red-600">Inactive</span>
                          )}
                        </p>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      )}
      
      {/* Signatures List Tab */}
      {activeTab === 'signatures' && (
        <div className="bg-white rounded-lg shadow overflow-hidden">
          <div className="p-4 border-b flex justify-between items-center">
            <h2 className="text-xl font-semibold">Audio Signatures</h2>
            <div className="flex space-x-2">
              <div className="relative">
                <input
                  type="text"
                  placeholder="Search signatures..."
                  className="pl-10 pr-4 py-2 border rounded-md"
                />
                <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
              </div>
              <button
                onClick={() => window.location.reload()}
                className="bg-gray-100 p-2 rounded-md"
                title="Refresh"
              >
                <RefreshCw size={18} />
              </button>
            </div>
          </div>
          
          {loading || roomsLoading ? (
            <div className="text-center p-6">
              <div className="inline-block animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-indigo-600"></div>
              <p className="mt-2 text-gray-500">Loading data...</p>
            </div>
          ) : signatures.length === 0 ? (
            <div className="text-center p-6">
              <Music size={48} className="mx-auto text-gray-300 mb-3" />
              <p className="text-gray-500">No audio signatures have been created yet.</p>
              <button
                onClick={() => setActiveTab('create')}
                className="mt-4 bg-indigo-600 text-white px-4 py-2 rounded-md flex items-center mx-auto"
              >
                <Plus size={18} className="mr-1" />
                Create Your First Signature
              </button>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="min-w-full">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Description
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Room
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Type
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Created
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Expires
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Status
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Actions
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {signatures.map(signature => (
                    <tr key={signature.id} className="hover:bg-gray-50">
                      <td className="px-6 py-4 whitespace-nowrap">
                        <div className="text-sm font-medium text-gray-900">
                          {signature.sourceDescription}
                        </div>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <div className="text-sm text-gray-500">
                          {signature.roomName}
                          <span className="text-xs ml-1 text-gray-400">
                            {signature.roomSource === 'rtdb' ? '[RTDB]' : signature.roomCollectionName ? `[${signature.roomCollectionName}]` : ''}
                          </span>
                        </div>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-blue-100 text-blue-800">
                          {signature.sourceType}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                        {formatDate(signature.createdAt)}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                        {formatExpiration(signature.expiresAt)}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${
                          signature.isActive 
                            ? 'bg-green-100 text-green-800' 
                            : 'bg-red-100 text-red-800'
                        }`}>
                          {signature.isActive ? 'Active' : 'Inactive'}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                        <div className="flex space-x-2">
                        <button
                        onClick={() => toggleSignatureStatus(signature.id, signature.isActive)}
                        className={`p-1 rounded ${
                        signature.isActive 
                        ? 'text-red-600 hover:bg-red-100' 
                        : 'text-green-600 hover:bg-green-100'
                        }`}
                        title={signature.isActive ? 'Deactivate' : 'Activate'}
                        >
                        {signature.isActive ? <PauseCircle size={18} /> : <PlayCircle size={18} />}
                        </button>
                        <button
                        onClick={() => deleteSignature(signature.id, signature.roomId, signature.roomSource, signature.roomPath)}
                        className="p-1 rounded text-red-600 hover:bg-red-100"
                        title="Delete"
                        >
                        <Trash2 size={18} />
                        </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}
      
      {/* Create New Tab */}
      {activeTab === 'create' && (
        <div className="bg-white rounded-lg shadow p-6">
          <h2 className="text-xl font-semibold mb-4">Create New Audio Signature</h2>
          
          {recordingStatus === 'success' && audioFingerprint ? (
            <div className="space-y-6">
              <div className="bg-green-50 p-4 rounded-lg border border-green-200">
                <div className="flex items-center mb-3">
                  <div className="bg-green-100 p-2 rounded-full mr-3">
                    <Mic className="text-green-600" size={20} />
                  </div>
                  <div>
                    <p className="font-medium text-green-800">Recording Successful!</p>
                    <p className="text-sm text-green-600">Audio fingerprint has been generated.</p>
                  </div>
                </div>
                
                <div className="border border-green-200 bg-white p-3 rounded-md">
                  <div className="flex justify-between items-center mb-2">
                    <p className="font-medium">Audio Information:</p>
                  </div>
                  <p className="text-sm"><span className="font-medium">Description:</span> {sourceDescription}</p>
                  <p className="text-sm"><span className="font-medium">Type:</span> {sourceType}</p>
                  <p className="text-sm"><span className="font-medium">Room:</span> {selectedRoom?.name}</p>
                  <p className="text-sm"><span className="font-medium">Fingerprint Size:</span> {audioFingerprint.length} bytes</p>
                </div>
                
                <div className="flex justify-end space-x-3 mt-4">
                  <button
                    onClick={resetRecording}
                    className="px-4 py-2 border border-gray-300 rounded-md text-gray-700"
                  >
                    Discard and Record Again
                  </button>
                  <button
                    onClick={saveSignature}
                    disabled={loading}
                    className="px-4 py-2 bg-green-600 text-white rounded-md flex items-center"
                  >
                    {loading ? (
                      <>
                        <div className="animate-spin rounded-full h-4 w-4 border-t-2 border-b-2 border-white mr-2"></div>
                        Saving...
                      </>
                    ) : (
                      <>
                        <Save className="mr-2" size={18} />
                        Save Audio Signature
                      </>
                    )}
                  </button>
                </div>
              </div>
            </div>
          ) : (
            <div className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-4">
                  <div>
                    <div className="flex justify-between items-center mb-1">
                      <label className="block text-sm font-medium text-gray-700">
                        Select Chat Room
                      </label>
                      {roomsLoading ? (
                        <span className="text-xs text-gray-500 flex items-center">
                          <div className="inline-block animate-spin rounded-full h-3 w-3 border-t-2 border-b-2 border-indigo-600 mr-1"></div>
                          Loading...
                        </span>
                      ) : (
                        <button 
                          onClick={() => fetchRooms()} 
                          title="Refresh room list"
                          className="text-xs text-indigo-600 hover:text-indigo-800 flex items-center"
                          type="button"
                        >
                          <RefreshCw size={12} className="mr-1" /> Refresh
                        </button>
                      )}
                    </div>
                    <div className="relative">
                      <select
                        id="chatRoomSelect"
                        value={selectedRoom?.id || ''}
                        onChange={(e) => {
                          const roomId = e.target.value;
                          const selected = rooms?.find(room => room.id === roomId);
                          console.log('Selected room:', selected, 'from roomId:', roomId);
                          setSelectedRoom(selected || null);
                        }}
                        className={`w-full px-3 py-2 border ${rooms && rooms.length > 0 ? 'border-gray-300' : 'border-red-300'} rounded-md`}
                        disabled={loading || roomsLoading || roomBatchLoading}
                      >
                        <option value="">
                          {roomsLoading || roomBatchLoading
                            ? '-- Loading rooms... --'
                            : rooms && rooms.length > 0
                              ? '-- Select a chat room --'
                              : '-- No rooms available --'}
                        </option>
                        {rooms && rooms.length > 0 ? (
                          rooms.map(room => {
                            return (
                              <option key={room.id} value={room.id}>
                                {room.name || `Room ${room.id}`} 
                                {room.hasAudioSignature ? '(Has Signature)' : ''}
                                {room.source ? ` [${room.source === 'rtdb' ? 'RTDB' : room.collectionName}]` : ''}
                              </option>
                            );
                          })
                        ) : null}
                      </select>
                      {(roomsLoading || roomBatchLoading) && (
                        <div className="absolute inset-y-0 right-0 flex items-center pr-3 pointer-events-none">
                          <div className="animate-spin rounded-full h-4 w-4 border-t-2 border-b-2 border-indigo-600"></div>
                        </div>
                      )}
                    </div>
                    
                    {(!rooms || rooms.length === 0) && !roomsLoading && !roomBatchLoading && (
                      <div className="mt-2">
                        <p className="text-xs text-yellow-500">
                          No chat rooms found. We searched: {searchedSources.join(', ') || 'no valid sources found'}.
                        </p>
                        <button 
                          onClick={() => {
                            console.log('Manual room fetch initiated');
                            // Try both data sources
                            setRoomBatchLoading(true);
                            setSearchedSources([]);
                            
                            Promise.all([
                              // First fetch from Realtime Database
                              fetchRoomsFromRTDB().then(rooms => {
                                if (rooms.length > 0) {
                                  setSearchedSources(prev => [...prev, 'Firebase Realtime Database']);
                                }
                                return rooms;
                              }),
                              
                              // Then try Firestore collections
                              fetchRoomsFromCollection('publicChats').then(rooms => {
                                if (rooms.length > 0) {
                                  setSearchedSources(prev => [...prev, 'Firestore: publicChats']);
                                }
                                return rooms;
                              }),
                              fetchRoomsFromCollection('rooms').then(rooms => {
                                if (rooms.length > 0) {
                                  setSearchedSources(prev => [...prev, 'Firestore: rooms']);
                                }
                                return rooms;
                              }),
                              fetchRoomsFromCollection('chatRooms').then(rooms => {
                                if (rooms.length > 0) {
                                  setSearchedSources(prev => [...prev, 'Firestore: chatRooms']);
                                }
                                return rooms;
                              })
                            ])
                            .then(() => {
                              console.log('Manual room fetch completed');
                              setRoomBatchLoading(false);
                            })
                            .catch(err => {
                              console.error('Error fetching rooms:', err);
                              setError(`Failed to fetch rooms: ${err.message}`);
                              setRoomBatchLoading(false);
                            });
                          }}
                          className="mt-1 text-xs text-indigo-600 hover:text-indigo-800 underline"
                          type="button"
                        >
                          Retry fetching rooms from all sources
                        </button>
                      </div>
                    )}
                    
                    {selectedRoom && (
                      <div className="mt-2 text-sm text-gray-600">
                        <p>{selectedRoom.description}</p>
                      </div>
                    )}
                  </div>
                  
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Source Type
                    </label>
                    <select
                      value={sourceType}
                      onChange={(e) => setSourceType(e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-md"
                    >
                      <option value="broadcast">TV/Radio Broadcast</option>
                      <option value="livestream">Live Stream</option>
                      <option value="podcast">Podcast</option>
                      <option value="music">Music</option>
                      <option value="event">Live Event</option>
                      <option value="other">Other</option>
                    </select>
                  </div>
                  
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Description
                    </label>
                    <textarea
                      value={sourceDescription}
                      onChange={(e) => setSourceDescription(e.target.value)}
                      placeholder="e.g., 'CNN News Broadcast' or 'Taylor Swift Concert'"
                      className="w-full px-3 py-2 border border-gray-300 rounded-md"
                      rows={3}
                    ></textarea>
                    <p className="mt-1 text-sm text-gray-500">
                      Describe what users will be listening to when they match with this room.
                    </p>
                  </div>
                  
                  <div className="border-t border-gray-200 pt-3 mt-4">
                    <p className="text-sm font-medium text-gray-700 mb-1">
                      Microphone Permission
                    </p>
                    <div className="flex items-center justify-between">
                      <span className="text-sm">
                        {audioPermissionGranted ? (
                          <span className="text-green-600 flex items-center">
                            <span className="w-2 h-2 bg-green-600 rounded-full mr-1"></span>
                            Permission granted
                          </span>
                        ) : (
                          <span className="text-gray-500">
                            No permission granted yet
                          </span>
                        )}
                      </span>
                      {audioPermissionGranted && (
                        <button
                          onClick={() => {
                            setAudioPermissionGranted(false);
                            setRecordingStatus('idle');
                          }}
                          className="text-xs text-red-600 hover:text-red-800"
                          type="button"
                        >
                          Reset Permission
                        </button>
                      )}
                    </div>
                  </div>
                </div>
                
                <div className="space-y-4">
                  <div className="bg-gray-50 p-4 rounded-lg border">
                    <div className="flex items-center mb-3">
                      <Info className="text-gray-500 mr-2" size={18} />
                      <p className="text-sm text-gray-700">
                        Record audio from the source to create a signature. Users can then find this chat
                        room by listening to the same audio.
                      </p>
                    </div>
                    
                    <div className="border-t border-gray-200 pt-3">
                      <p className="text-sm font-medium text-gray-700 mb-1">
                        Instructions:
                      </p>
                      <ol className="text-sm text-gray-600 space-y-1 pl-5 list-decimal">
                        <li>Position your device near the audio source</li>
                        <li>Click the "Grant Microphone Access" button</li>
                        <li>Allow microphone access when prompted by your browser</li>
                        <li>Once access is granted, click "Start Recording"</li>
                        <li>Record for 5-10 seconds</li>
                        <li>The recording will automatically stop after 5 seconds</li>
                      </ol>
                    </div>
                  </div>
                  
                  <div className="border rounded-lg p-4">
                    <div className="flex justify-between items-center mb-3">
                      <p className="font-medium">
                        {recordingStatus === 'recording' ? 'Recording...' : 'Audio Recorder'}
                      </p>
                      {recordingStatus === 'recording' && (
                        <div className="bg-red-100 text-red-600 px-2 py-1 rounded-full text-xs font-medium flex items-center">
                          <span className="w-2 h-2 bg-red-600 rounded-full mr-1"></span>
                          {recordingTime}s
                        </div>
                      )}
                    </div>
                    
                    <div className="border rounded bg-gray-50 p-2 mb-3">
                      <canvas
                        ref={canvasRef}
                        width={400}
                        height={100}
                        className="w-full"
                      ></canvas>
                    </div>
                    
                    {recordingStatus === 'recording' ? (
                      <button
                        onClick={stopRecording}
                        className="w-full py-2 bg-red-600 text-white rounded-md flex items-center justify-center"
                      >
                        <PauseCircle className="mr-2" size={18} />
                        Stop Recording
                      </button>
                    ) : recordingStatus === 'processing' ? (
                      <div className="w-full py-2 bg-gray-400 text-white rounded-md flex items-center justify-center">
                        <div className="animate-spin rounded-full h-4 w-4 border-t-2 border-b-2 border-white mr-2"></div>
                        Processing Audio...
                      </div>
                    ) : recordingStatus === 'ready' ? (
                      <div className="space-y-3">
                        <div className="flex items-center bg-green-50 p-2 rounded border border-green-200 mb-2 text-sm">
                          <div className="bg-green-100 p-1 rounded-full mr-2">
                            <Mic className="text-green-600" size={14} />
                          </div>
                          <span className="text-green-800">Microphone access granted! Ready to record.</span>
                        </div>
                        <button
                          onClick={startRecording}
                          className="w-full py-2 bg-indigo-600 text-white rounded-md flex items-center justify-center"
                        >
                          <Mic className="mr-2" size={18} />
                          Start Recording
                        </button>
                      </div>
                    ) : (
                      <div className="space-y-3">
                        {audioPermissionGranted === false && recordingStatus === 'error' && (
                          <div className="flex items-center bg-red-50 p-2 rounded border border-red-200 mb-2 text-sm">
                            <div className="bg-red-100 p-1 rounded-full mr-2">
                              <Mic className="text-red-600" size={14} />
                            </div>
                            <span className="text-red-800">Microphone access was denied. Please try again.</span>
                          </div>
                        )}
                        <button
                          onClick={requestMicrophonePermissions}
                          disabled={!selectedRoom || !sourceDescription}
                          className={`w-full py-2 rounded-md flex items-center justify-center ${
                            !selectedRoom || !sourceDescription
                              ? 'bg-gray-300 text-gray-500 cursor-not-allowed'
                              : 'bg-indigo-600 text-white'
                          }`}
                        >
                          <Mic className="mr-2" size={18} />
                          Grant Microphone Access
                        </button>
                        <p className="text-xs text-gray-500 text-center">
                          You'll be asked to give microphone permission before recording.
                        </p>
                      </div>
                    )}
                    
                    {(!selectedRoom || !sourceDescription) && (
                      <p className="mt-2 text-xs text-red-500">
                        Please select a room and enter a description first.
                      </p>
                    )}
                  </div>
                </div>
              </div>
              
              <div className="bg-blue-50 p-4 rounded-lg border border-blue-200">
                <div className="flex items-start">
                  <Info className="text-blue-600 mr-3 mt-0.5" size={18} />
                  <div>
                    <p className="font-medium text-blue-800">How Audio Detection Works</p>
                    <p className="text-sm text-blue-600 mt-1">
                      When you create an audio signature, we analyze the frequency patterns of the audio to create a digital fingerprint.
                      Users can then match with this chat room by having their app listen to the same audio source. The matching is done
                      by comparing audio fingerprints, not by storing or transmitting actual audio recordings.
                    </p>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default AudioDetectionManager;