// src/components/AuditManager/FirebaseTraceManager.js
// Integration module that connects the UI to Firebase tracing functionality

import { useEffect } from 'react';
import { 
  enableFirebaseTracing, 
  disableFirebaseTracing,
  isFirebaseTracingEnabled
} from '../../utils/firebaseTracingToggle';
import { clearAccessedPaths, getAllAccessedPaths } from '../../utils/firebaseTracer';

/**
 * Hook to manage Firebase tracing state
 * @returns {Object} Tracing controls and data
 */
export const useFirebaseTraceManager = () => {
  // Start tracing Firebase paths
  const startTracing = () => {
    clearAccessedPaths();
    enableFirebaseTracing();
    
    // Add a warning to the console for developers
    console.warn(
      '%c⚠️ Firebase Path Tracing Active ⚠️\n' +
      'All Firebase path access is being monitored for security rules generation.\n' +
      'This may affect performance. Disable when not actively auditing.',
      'color: #ff9800; font-weight: bold;'
    );
    
    return true;
  };
  
  // Stop tracing and collect paths
  const stopTracing = () => {
    const paths = getAllAccessedPaths();
    disableFirebaseTracing();
    
    console.log(`📊 Firebase Path Tracing Complete - ${paths.length} paths recorded`);
    
    return paths;
  };
  
  // Check if tracing is currently active
  const isTracing = () => {
    return isFirebaseTracingEnabled();
  };
  
  // Clean up on component unmount
  useEffect(() => {
    return () => {
      // Ensure tracing is disabled when component unmounts
      if (isFirebaseTracingEnabled()) {
        disableFirebaseTracing();
      }
    };
  }, []);

  // Function to get the latest traced paths and generate rules
  const generateRulesFromTracedPaths = (ruleTemplates = {}) => {
    const paths = getAllAccessedPaths();
    return {
      paths,
      rules: generateFirebaseRules(paths, ruleTemplates)
    };
  };
  
  // Return tracing controls
  return {
    startTracing,
    stopTracing,
    isTracing,
    getTracedPaths: getAllAccessedPaths,
    generateRulesFromTracedPaths
  };
};

/**
 * Utility function to generate Firebase rules from traced paths
 * @param {Array} paths Array of traced Firebase paths
 * @param {Object} ruleTemplates Templates for read/write rules
 * @returns {Object} Generated rules for Database and Firestore
 */
export const generateFirebaseRules = (paths, ruleTemplates = {}) => {
  // Default rule templates if not provided
  const templates = {
    database: {
      read: ruleTemplates?.database?.read || "auth != null",
      write: ruleTemplates?.database?.write || "auth != null"
    },
    firestore: {
      read: ruleTemplates?.firestore?.read || "request.auth != null",
      write: ruleTemplates?.firestore?.write || "request.auth != null"
    }
  };
  
  // Helper function to build path tree from flat paths
  const buildPathTree = (paths, dbType) => {
    const filtered = paths.filter(path => path.startsWith(`${dbType}/`))
                        .map(path => path.replace(`${dbType}/`, ''));
    
    const pathTree = {};
    
    filtered.forEach(path => {
      let parts = path.split('/');
      let current = pathTree;
      
      parts.forEach(part => {
        if (!current[part]) {
          current[part] = {};
        }
        current = current[part];
      });
    });
    
    return pathTree;
  };

  // Generate database rules recursively
  const generateDatabaseRules = (pathObj, indent = 2) => {
    let rules = '';
    const indentStr = ' '.repeat(indent);
    
    Object.keys(pathObj).forEach((key, index, arr) => {
      rules += `${indentStr}"${key}": {\n`;
      
      // If this node has children
      if (Object.keys(pathObj[key]).length > 0) {
        rules += generateDatabaseRules(pathObj[key], indent + 2);
      }
      
      // Add read/write rules
      rules += `${indentStr}  ".read": "${templates.database.read}",\n`;
      rules += `${indentStr}  ".write": "${templates.database.write}"\n`;
      
      // Close the path object
      rules += `${indentStr}}${index < arr.length - 1 ? ',' : ''}\n`;
    });
    
    return rules;
  };

  // Generate Firestore rules
  const generateFirestoreRules = (pathObj, parentPath = '') => {
    let rules = '';
    
    Object.keys(pathObj).forEach(key => {
      const currentPath = parentPath ? `${parentPath}/${key}` : key;
      
      // Format path for Firestore rules
      const formattedPath = currentPath.split('/').map(segment => {
        return segment.includes(':') ? `{${segment.replace(':', '')}}` : segment;
      }).join('/');
      
      rules += `    match /${formattedPath} {\n`;
      rules += `      allow read: if ${templates.firestore.read};\n`;
      rules += `      allow write: if ${templates.firestore.write};\n`;
      rules += `    }\n\n`;
      
      // Process children
      if (Object.keys(pathObj[key]).length > 0) {
        rules += generateFirestoreRules(pathObj[key], currentPath);
      }
    });
    
    return rules;
  };
  
  // Build path trees
  const databasePathTree = buildPathTree(paths, 'database');
  const firestorePathTree = buildPathTree(paths, 'firestore');
  
  // Generate Realtime Database rules
  let databaseRulesContent = '{\n  "rules": {\n';
  
  if (Object.keys(databasePathTree).length > 0) {
    databaseRulesContent += generateDatabaseRules(databasePathTree);
  } else {
    databaseRulesContent += '    ".read": "auth != null",\n';
    databaseRulesContent += '    ".write": "auth != null"\n';
  }
  
  databaseRulesContent += '  }\n}';

  // Generate Firestore rules
  let firestoreRulesContent = 'rules_version = \'2\';\nservice cloud.firestore {\n  match /databases/{database}/documents {\n\n';
  
  if (Object.keys(firestorePathTree).length > 0) {
    firestoreRulesContent += generateFirestoreRules(firestorePathTree);
  } else {
    firestoreRulesContent += '    match /{document=**} {\n';
    firestoreRulesContent += '      allow read: if request.auth != null;\n';
    firestoreRulesContent += '      allow write: if request.auth != null;\n';
    firestoreRulesContent += '    }\n';
  }
  
  firestoreRulesContent += '  }\n}';
  
  return {
    database: databaseRulesContent,
    firestore: firestoreRulesContent
  };
};
