// src/admin/UserList.jsx
import React from 'react';
import { Link } from 'react-router-dom';
import { Search, Download, Filter, ChevronLeft, ChevronRight, RefreshCw, Clock, 
         UserCheck, Mail, Medal, Calendar, ExternalLink, Shield } from 'lucide-react';
import { useUserList } from './hooks/useUserList';
import { exportUsersToCSV, formatDate, getRelativeTime } from './userUtils';
import styles from './UserList.module.css';

const UserList = () => {
  const { 
    users, 
    loading, 
    error, 
    isLastPage, 
    currentPage, 
    totalUsers, 
    filterParams,
    fetchUsers, 
    handleNextPage, 
    handlePrevPage, 
    handleSortChange, 
    updateFilters 
  } = useUserList();

  const { searchQuery, filterRole, sortBy } = filterParams;
  const pageSize = 25;

  // Export users as CSV
  const handleExportCSV = () => {
    exportUsersToCSV(users);
  };

  return (
    <div className={styles.userListContainer}>
      <div className="border-b p-4">
        <div className="flex justify-between items-center">
          <div>
            <h2 className="text-xl font-semibold">User List</h2>
            <p className="text-gray-600">View all registered users and their detailed information</p>
          </div>
          <Link 
            to="/admin/users/roles" 
            className="flex items-center px-4 py-2 border border-indigo-600 text-indigo-600 rounded-md hover:bg-indigo-600 hover:text-white transition-colors"
          >
            <Shield className="h-4 w-4 mr-2" />
            <span>Manage Admin Roles</span>
          </Link>
        </div>
      </div>
      
      {/* Filter and search section */}
      <div className="p-4 border-b bg-gray-50">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          {/* Search */}
          <div className="relative">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <Search className="h-5 w-5 text-gray-400" />
            </div>
            <input
              type="text"
              className="block w-full pl-10 pr-3 py-2 border border-gray-300 rounded-md leading-5 bg-white placeholder-gray-500 focus:outline-none focus:placeholder-gray-400 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500"
              placeholder="Search users by name, email or ID..."
              value={searchQuery}
              onChange={(e) => updateFilters({ searchQuery: e.target.value })}
            />
          </div>
          
          {/* Filters */}
          <div className="flex gap-3">
            <div className="relative inline-block w-full">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <Filter className="h-4 w-4 text-gray-400" />
              </div>
              <select
                className="block w-full pl-10 pr-10 py-2 border border-gray-300 rounded-md leading-5 bg-white focus:outline-none focus:ring-indigo-500 focus:border-indigo-500"
                value={filterRole}
                onChange={(e) => updateFilters({ filterRole: e.target.value })}
              >
                <option value="all">All Users</option>
                <option value="admin">Admins Only</option>
                <option value="premium">Premium Users</option>
              </select>
            </div>
            
            <div className="relative inline-block w-full">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <Clock className="h-4 w-4 text-gray-400" />
              </div>
              <select
                className="block w-full pl-10 pr-10 py-2 border border-gray-300 rounded-md leading-5 bg-white focus:outline-none focus:ring-indigo-500 focus:border-indigo-500"
                value={sortBy}
                onChange={(e) => handleSortChange(e.target.value)}
              >
                <option value="createdAt">Sort by Join Date</option>
                <option value="lastLogin">Sort by Last Login</option>
                <option value="displayName">Sort by Name</option>
                <option value="postCount">Sort by Post Count</option>
              </select>
            </div>
          </div>
          
          {/* Actions */}
          <div className="flex justify-end gap-2">
            <button
              onClick={handleExportCSV}
              className={`${styles.actionButton} ${styles.primaryButton}`}
            >
              <Download className="h-4 w-4 inline-block mr-2" />
              Export CSV
            </button>
            
            <button
              onClick={() => fetchUsers(true)}
              className={`${styles.actionButton} ${styles.secondaryButton}`}
            >
              <RefreshCw className="h-4 w-4 inline-block mr-2" />
              Refresh
            </button>
          </div>
        </div>
      </div>
      
      {/* Error message */}
      {error && (
        <div className="p-4 bg-red-50 border-b border-red-200">
          <p className="text-red-600">{error}</p>
        </div>
      )}
      
      {/* Users table */}
      <div className="overflow-x-auto">
        {loading ? (
          <div className="flex justify-center items-center p-12">
            <div className={styles.loadingSpinner}></div>
          </div>
        ) : users.length === 0 ? (
          <div className="text-center p-12 text-gray-500">
            {searchQuery ? 'No users match your search' : 'No users found'}
          </div>
        ) : (
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th scope="col" className={styles.tableHeader}>
                  User
                </th>
                <th scope="col" className={styles.tableHeader}>
                  Contact
                </th>
                <th scope="col" className={styles.tableHeader}>
                  Status
                </th>
                <th scope="col" className={styles.tableHeader}>
                  Joined
                </th>
                <th scope="col" className={styles.tableHeader}>
                  Last Active
                </th>
                <th scope="col" className={styles.tableHeader}>
                  Activity
                </th>
                <th scope="col" className={`${styles.tableHeader} text-right`}>
                  Actions
                </th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {users.map((user) => (
                <tr key={user.id} className="hover:bg-gray-50">
                  {/* User Info */}
                  <td className={styles.tableCell}>
                    <div className="flex items-center">
                      <div className="flex-shrink-0 h-10 w-10 relative">
                        {user.photoURL ? (
                          <img className={styles.userAvatarImage} src={user.photoURL} alt="" />
                        ) : (
                          <div className={`${styles.userAvatar} bg-indigo-100 text-indigo-600`}>
                            <span>
                              {user.displayName ? user.displayName[0].toUpperCase() : (user.email ? user.email[0].toUpperCase() : '?')}
                            </span>
                          </div>
                        )}
                        {user.isAdmin && (
                          <div className={styles.adminBadge} title="Admin user"></div>
                        )}
                        {user.isPremium && !user.isAdmin && (
                          <div className={styles.premiumBadge} title="Premium user"></div>
                        )}
                      </div>
                      <div className="ml-4">
                        <div className="text-sm font-medium text-gray-900">
                          {user.displayName || 'Unnamed User'}
                        </div>
                        <div className="text-xs text-gray-400 mt-1">
                          ID: {user.id.substring(0, 10)}...
                        </div>
                      </div>
                    </div>
                  </td>
                  
                  {/* Contact */}
                  <td className={styles.tableCell}>
                    <div className="text-sm text-gray-900 flex items-center">
                      <Mail className="h-4 w-4 mr-1 text-gray-400" />
                      {user.email || 'No email'}
                    </div>
                    {user.phone && (
                      <div className="text-sm text-gray-500 mt-1">
                        {user.phone}
                      </div>
                    )}
                  </td>
                  
                  {/* Status */}
                  <td className={styles.tableCell}>
                    <div className="flex flex-col gap-1">
                      <span className={`${styles.statusBadge} ${
                          user.isAdmin 
                            ? 'bg-indigo-100 text-indigo-800' 
                            : user.isPremium
                            ? 'bg-yellow-100 text-yellow-800'
                            : 'bg-gray-100 text-gray-800'
                        }`}>
                        {user.isAdmin ? 'Admin' : user.isPremium ? 'Premium' : 'User'}
                      </span>
                      
                      {user.emailVerified && (
                        <span className={`${styles.statusBadge} bg-green-100 text-green-800`}>
                          <UserCheck className="h-3 w-3 mr-1" /> Verified
                        </span>
                      )}
                      
                      {user.provider && (
                        <span className={`${styles.statusBadge} bg-blue-100 text-blue-800`}>
                          {user.provider}
                        </span>
                      )}
                    </div>
                  </td>
                  
                  {/* Join Date */}
                  <td className={styles.tableCell}>
                    <div className="text-sm text-gray-900 flex items-center">
                      <Calendar className="h-4 w-4 mr-1 text-gray-400" />
                      {formatDate(user.createdAt)}
                    </div>
                    <div className="text-xs text-gray-500 mt-1">
                      {user.createdAt ? getRelativeTime(user.createdAt) : ''}
                    </div>
                  </td>
                  
                  {/* Last Login */}
                  <td className={styles.tableCell}>
                    <div className="text-sm text-gray-900">
                      {formatDate(user.lastLogin)}
                    </div>
                    <div className="text-xs text-gray-500 mt-1">
                      {user.lastLogin ? getRelativeTime(user.lastLogin) : ''}
                    </div>
                  </td>
                  
                  {/* Activity Stats */}
                  <td className={styles.tableCell}>
                    <div className="flex flex-col gap-1">
                      <div className="text-sm text-gray-900">
                        Posts: {user.postCount || 0}
                      </div>
                      <div className="text-sm text-gray-900">
                        Comments: {user.commentCount || 0}
                      </div>
                      {user.premiumSince && (
                        <div className="flex items-center text-sm text-gray-900">
                          <Medal className="h-4 w-4 mr-1 text-yellow-400" />
                          Premium since: {new Date(user.premiumSince).toLocaleDateString()}
                        </div>
                      )}
                    </div>
                  </td>
                  
                  {/* Actions */}
                  <td className={`${styles.tableCell} text-right`}>
                    <div className="flex justify-end gap-2">
                      <a 
                        href={`/profile/${user.id}`}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="text-gray-600 hover:text-gray-900 flex items-center"
                      >
                        <ExternalLink className="h-4 w-4" />
                      </a>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
      
      {/* Pagination */}
      <div className="bg-white px-4 py-3 flex items-center justify-between border-t border-gray-200 sm:px-6">
        <div className="hidden sm:flex-1 sm:flex sm:items-center sm:justify-between">
          <div>
            <p className={styles.paginationInfo}>
              Showing <span className="font-medium">{users.length > 0 ? (currentPage - 1) * pageSize + 1 : 0}</span> to{" "}
              <span className="font-medium">{Math.min(currentPage * pageSize, totalUsers)}</span> of{" "}
              <span className="font-medium">{totalUsers}</span> results
            </p>
          </div>
          <div>
            <nav className="relative z-0 inline-flex rounded-md shadow-sm -space-x-px" aria-label="Pagination">
              <button
                onClick={handlePrevPage}
                disabled={currentPage === 1}
                className={`${styles.paginationButton} rounded-l-md ${
                  currentPage === 1 ? 'opacity-50 cursor-not-allowed' : ''
                }`}
              >
                <span className="sr-only">Previous</span>
                <ChevronLeft className="h-5 w-5" aria-hidden="true" />
              </button>
              <span className={`${styles.paginationButton} bg-white border-gray-300`}>
                Page {currentPage}
              </span>
              <button
                onClick={handleNextPage}
                disabled={isLastPage}
                className={`${styles.paginationButton} rounded-r-md ${
                  isLastPage ? 'opacity-50 cursor-not-allowed' : ''
                }`}
              >
                <span className="sr-only">Next</span>
                <ChevronRight className="h-5 w-5" aria-hidden="true" />
              </button>
            </nav>
          </div>
        </div>
      </div>
    </div>
  );
};

export default UserList;
