import LiveKitConfig from './LiveKitConfig.js';

class LiveKitIngressService {
  constructor() {
    this.apiBaseUrl = 'https://talkstudio-2c55dh9q.livekit.cloud';
    this.ingressCache = new Map();
  }

  // Create RTMP ingress for an event/room - calls real backend API
  async createRTMPIngress(roomName, options = {}) {
    try {
      const config = LiveKitConfig.getCurrentConfig();

      if (!LiveKitConfig.isConfigValid()) {
        throw new Error('LiveKit configuration is incomplete');
      }

      console.log('🎬 Creating RTMP ingress via backend API for room:', roomName);

      // Determine backend URL based on environment
      const backendUrl = this.getBackendUrl();
      const eventId = options.eventId || roomName.replace('event_', '');

      console.log('📡 Backend URL:', backendUrl);
      console.log('🎯 Event ID:', eventId);

      // Call the real backend API endpoint
      const response = await fetch(`${backendUrl}/api/livekit-ingress/create-ingress`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          roomName,
          eventId,
          options: {
            participantName: options.participantName || 'External Camera',
            videoBitrate: options.videoBitrate,
            audioBitrate: options.audioBitrate,
            width: options.width,
            height: options.height,
            framerate: options.framerate
          }
        })
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || `HTTP error ${response.status}`);
      }

      const data = await response.json();

      if (!data.success) {
        throw new Error(data.error || 'Failed to create ingress');
      }

      // Cache the ingress data
      this.ingressCache.set(roomName, data.ingress);
      this.ingressCache.set(eventId, data.ingress);

      // FIXED: Ensure rtmpUrl is valid, construct if undefined
      let rtmpUrl = data.ingress.rtmpUrl;
      if (!rtmpUrl || rtmpUrl === 'undefined') {
        rtmpUrl = 'rtmp://talkstudio-2c55dh9q.livekit.cloud/x/';
        console.log('⚠️ RTMP URL was undefined, using default LiveKit Cloud URL');
      }

      console.log('✅ Real RTMP ingress created via backend:', {
        roomName,
        ingressId: data.ingress.ingressId,
        rtmpUrl: rtmpUrl,
        streamKey: data.ingress.streamKey,
        streamUrl: data.ingress.streamUrl
      });

      return {
        success: true,
        ingress: { ...data.ingress, rtmpUrl },
        rtmpUrl: rtmpUrl,
        streamUrl: data.ingress.streamUrl,
        streamKey: data.ingress.streamKey
      };

    } catch (error) {
      console.error('❌ Failed to create RTMP ingress via backend:', error);

      // Return error without fallback (we want to know when it fails)
      return {
        success: false,
        error: error.message,
        fallback: false
      };
    }
  }

  // Determine backend URL based on environment
  getBackendUrl() {
    const hostname = window.location.hostname;
    // Check if we're in production
    if (hostname === 'talkstudio.space' || hostname === 'www.talkstudio.space' || hostname === 'talkstud.io') {
      // Production - use the Digital Ocean deployed recording-api service
      return 'https://talkstudio.space';
    }
    // Local development
    return 'http://localhost:3001';
  }

  // Generate a secure stream key
  generateStreamKey(roomName) {
    const timestamp = Date.now();
    const random = Math.random().toString(36).substring(2, 15);
    return `${roomName}_${timestamp}_${random}`;
  }

  // Get existing ingress for a room
  getIngressForRoom(roomName) {
    return this.ingressCache.get(roomName);
  }

  // Delete/cleanup ingress
  async deleteIngress(roomName) {
    try {
      console.log('🗑️ Cleaning up ingress for room:', roomName);
      
      const ingress = this.ingressCache.get(roomName);
      if (ingress) {
        this.ingressCache.delete(roomName);
        console.log('✅ Ingress cleaned up for room:', roomName);
      }

      return { success: true };
    } catch (error) {
      console.error('❌ Failed to cleanup ingress:', error);
      return { success: false, error: error.message };
    }
  }

  // List all active ingresses
  listIngresses() {
    return Array.from(this.ingressCache.values());
  }

  // Get RTMP connection instructions
  getRTMPInstructions(ingressData) {
    // FIXED: Use proper LiveKit Cloud RTMP URL format
    const rtmpServer = ingressData.rtmpUrl || 'rtmp://talkstudio-2c55dh9q.livekit.cloud/x/';
    return {
      server: rtmpServer,
      streamKey: ingressData.streamKey,
      fullRtmpUrl: `${rtmpServer}${ingressData.streamKey}`,
      instructions: [
        '1. Open OBS Studio or your preferred streaming software',
        '2. Go to Settings > Stream',
        '3. Select "Custom" as your service',
        `4. Server: ${rtmpServer}`,
        `5. Stream Key: ${ingressData.streamKey}`,
        '6. Click "Start Streaming" in OBS',
        '7. Your stream will be available to viewers instantly!'
      ],
      obsSettings: {
        service: 'Custom',
        server: rtmpServer,
        streamKey: ingressData.streamKey
      }
    };
  }

  // Validate RTMP URL format - accepts both /live/ and /x/ paths
  validateRTMPUrl(url) {
    const rtmpPattern = /^rtmp:\/\/talkstudio-2c55dh9q\.livekit\.cloud\/(live|x)\/[\w-]*$/;
    return rtmpPattern.test(url);
  }

  // Get stream status (placeholder for real implementation)
  async getStreamStatus(roomName) {
    try {
      const ingress = this.getIngressForRoom(roomName);
      if (!ingress) {
        return { active: false, error: 'No ingress found for room' };
      }

      // In a real implementation, you would check the actual stream status
      return {
        active: true,
        ingressId: ingress.ingressId,
        roomName: ingress.roomName,
        viewerCount: 0, // Would get from LiveKit API
        startedAt: ingress.createdAt,
        streamKey: ingress.streamKey
      };
    } catch (error) {
      console.error('❌ Failed to get stream status:', error);
      return { active: false, error: error.message };
    }
  }

  // Create server-side ingress (calls real backend API)
  async createServerSideIngress(roomName, options = {}) {
    // Now just calls the real implementation
    return await this.createRTMPIngress(roomName, options);
  }
}

// Export singleton instance
export const liveKitIngressService = new LiveKitIngressService();
export default liveKitIngressService;
