import React from 'react';
import { useNavigate } from 'react-router-dom';
import { Crown, Lock, Star, CheckCircle, XCircle } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { usePayment } from '../../contexts/PaymentContext';

/**
 * VIP Access Prompt Component
 * 
 * Shows a modal explaining VIP benefits and prompting users to upgrade
 * when they try to access VIP-only features.
 */
const VipAccessPrompt = ({ onClose, targetRoomId = null, targetRoomName = '' }) => {
  const navigate = useNavigate();
  const { currentUser } = useAuth();
  const { isPremium } = usePayment();
  
  // Navigate to payment page
  const handleUpgrade = () => {
    navigate('/premium-membership');
    if (onClose) onClose();
  };
  
  // Benefits list for VIP members
  const vipBenefits = [
    'Access to exclusive VIP chat rooms',
    'Ad-free experience across the platform',
    'Priority support from our team',
    'Early access to new features',
    'VIP badge next to your name'
  ];
  
  // Format price
  const formatPrice = (amount, currency = 'USD', interval = 'month') => {
    const formatter = new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: currency,
      minimumFractionDigits: 0
    });
    
    return `${formatter.format(amount)}/${interval}`;
  };
  
  return (
    <div className="vip-access-prompt">
      <div className="vip-prompt-container">
        <div className="vip-prompt-header">
          <Crown size={28} className="vip-crown-icon" />
          <h2>VIP Access Required</h2>
          <button className="close-button" onClick={onClose}>
            <XCircle size={24} />
          </button>
        </div>
        
        {targetRoomName && (
          <div className="target-room-info">
            <Lock size={16} />
            <p>
              <strong>{targetRoomName}</strong> is a VIP-only chat room
            </p>
          </div>
        )}
        
        <div className="vip-prompt-content">
          <p className="vip-prompt-message">
            {isPremium
              ? "You're already a VIP member. Something went wrong with your access."
              : "Upgrade to VIP to unlock exclusive chat rooms and premium features!"}
          </p>
          
          <div className="vip-benefits">
            <h3>VIP Membership Benefits</h3>
            <ul className="benefits-list">
              {vipBenefits.map((benefit, index) => (
                <li key={index} className="benefit-item">
                  <CheckCircle size={18} className="benefit-icon" />
                  <span>{benefit}</span>
                </li>
              ))}
            </ul>
          </div>
          
          {!isPremium && (
            <div className="vip-pricing">
              <div className="price-tag">
                <span className="price">{formatPrice(9.99)}</span>
                <span className="price-description">Unlimited VIP access</span>
              </div>
            </div>
          )}
        </div>
        
        <div className="vip-prompt-actions">
          {isPremium ? (
            <button 
              className="try-again-button"
              onClick={onClose}
            >
              Try Again
            </button>
          ) : (
            <React.Fragment>
              <button 
                className="upgrade-button"
                onClick={handleUpgrade}
              >
                <Star size={16} />
                Upgrade to VIP
              </button>
              
              <button 
                className="cancel-button"
                onClick={onClose}
              >
                Not Now
              </button>
            </React.Fragment>
          )}
        </div>
      </div>
      
      {/* Styles */}
      <style>{`
        .vip-access-prompt {
          position: fixed;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          display: flex;
          align-items: center;
          justify-content: center;
          background-color: rgba(0, 0, 0, 0.75);
          z-index: 1000;
          backdrop-filter: blur(4px);
        }
        
        .vip-prompt-container {
          background-color: white;
          border-radius: 12px;
          width: 90%;
          max-width: 480px;
          box-shadow: 0 10px 25px rgba(0, 0, 0, 0.2);
          overflow: hidden;
          display: flex;
          flex-direction: column;
          animation: vipModalIn 0.3s ease-out;
        }
        
        .vip-prompt-header {
          background: linear-gradient(135deg, #6366f1, #4f46e5);
          color: white;
          padding: 1.25rem;
          display: flex;
          align-items: center;
          position: relative;
        }
        
        .vip-crown-icon {
          color: #facc15;
          margin-right: 0.75rem;
        }
        
        .vip-prompt-header h2 {
          margin: 0;
          font-size: 1.5rem;
          font-weight: 600;
          flex-grow: 1;
        }
        
        .close-button {
          background: transparent;
          border: none;
          color: white;
          cursor: pointer;
          padding: 0;
          display: flex;
          align-items: center;
          justify-content: center;
          transition: transform 0.2s;
        }
        
        .close-button:hover {
          transform: scale(1.1);
        }
        
        .target-room-info {
          background-color: #f3f4f6;
          padding: 0.75rem 1.25rem;
          display: flex;
          align-items: center;
          gap: 0.5rem;
          border-bottom: 1px solid #e5e7eb;
        }
        
        .target-room-info p {
          margin: 0;
          font-size: 0.875rem;
        }
        
        .vip-prompt-content {
          padding: 1.5rem;
        }
        
        .vip-prompt-message {
          font-size: 1rem;
          margin-bottom: 1.25rem;
          text-align: center;
          color: #4b5563;
        }
        
        .vip-benefits {
          margin-bottom: 1.5rem;
        }
        
        .vip-benefits h3 {
          font-size: 1.1rem;
          font-weight: 600;
          margin-bottom: 0.75rem;
          color: #111827;
        }
        
        .benefits-list {
          list-style: none;
          padding: 0;
          margin: 0;
        }
        
        .benefit-item {
          display: flex;
          align-items: center;
          margin-bottom: 0.5rem;
          padding: 0.5rem;
          border-radius: 6px;
          background-color: #f9fafb;
        }
        
        .benefit-icon {
          color: #10b981;
          margin-right: 0.75rem;
          flex-shrink: 0;
        }
        
        .vip-pricing {
          margin-top: 1.5rem;
          display: flex;
          justify-content: center;
        }
        
        .price-tag {
          background: linear-gradient(135deg, #6366f1, #4f46e5);
          padding: 1rem 2rem;
          border-radius: 8px;
          display: flex;
          flex-direction: column;
          align-items: center;
          color: white;
        }
        
        .price {
          font-size: 2rem;
          font-weight: 700;
        }
        
        .price-description {
          font-size: 0.875rem;
          opacity: 0.9;
        }
        
        .vip-prompt-actions {
          padding: 1.25rem;
          display: flex;
          justify-content: center;
          gap: 1rem;
          border-top: 1px solid #e5e7eb;
        }
        
        .upgrade-button {
          background-color: #4f46e5;
          color: white;
          border: none;
          border-radius: 6px;
          padding: 0.75rem 1.5rem;
          font-weight: 600;
          cursor: pointer;
          display: flex;
          align-items: center;
          gap: 0.5rem;
          transition: background-color 0.2s;
        }
        
        .upgrade-button:hover {
          background-color: #4338ca;
        }
        
        .cancel-button {
          background-color: transparent;
          color: #6b7280;
          border: 1px solid #d1d5db;
          border-radius: 6px;
          padding: 0.75rem 1.5rem;
          font-weight: 600;
          cursor: pointer;
          transition: background-color 0.2s;
        }
        
        .cancel-button:hover {
          background-color: #f3f4f6;
        }
        
        .try-again-button {
          background-color: #4f46e5;
          color: white;
          border: none;
          border-radius: 6px;
          padding: 0.75rem 1.5rem;
          font-weight: 600;
          cursor: pointer;
          transition: background-color 0.2s;
        }
        
        .try-again-button:hover {
          background-color: #4338ca;
        }
        
        @keyframes vipModalIn {
          from {
            opacity: 0;
            transform: scale(0.95) translateY(10px);
          }
          to {
            opacity: 1;
            transform: scale(1) translateY(0);
          }
        }
      `}</style>
    </div>
  );
};

export default VipAccessPrompt;