// src/components/widgets/PostDetailPanel.jsx
import React, { useState, useEffect, useRef } from 'react';
import { getFirestore, doc, getDoc, collection, query, orderBy, onSnapshot, updateDoc, increment, addDoc, serverTimestamp, deleteDoc } from 'firebase/firestore';
import { getAuth } from 'firebase/auth';
import { formatDistanceToNow, format } from 'date-fns';
import { ThumbsUp, MessageSquare, Calendar, MapPin, Link as LinkIcon, ChevronLeft, Share2, Flag, User, Eye, MoreVertical, Trash2, Edit, Send, Heart, AlertCircle, X } from 'lucide-react';
import '../Dashboard/DetailViews/PostDetailView.css';

const PostDetailPanel = ({ post, highlightedCommentId, onClose }) => {
  const [postData, setPostData] = useState(post || null);
  const [comments, setComments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [newComment, setNewComment] = useState('');
  const [replyTo, setReplyTo] = useState(null);
  const [submitting, setSubmitting] = useState(false);
  const [showLikeAnimation, setShowLikeAnimation] = useState(false);
  const [liked, setLiked] = useState(false);
  const [showCommentMenu, setShowCommentMenu] = useState(null);
  const commentInputRef = useRef(null);
  const highlightedCommentRef = useRef(null);
  const auth = getAuth();

  // Fetch post and comments data
  useEffect(() => {
    const fetchPostAndComments = async () => {
      if (!post?.id) {
        setLoading(false);
        return;
      }

      try {
        setLoading(true);
        
        const db = getFirestore();
        
        // Only fetch post if not provided
        if (!postData) {
          const postRef = doc(db, 'posts', post.id);
          try {
            const postSnap = await getDoc(postRef);

            if (postSnap.exists()) {
              const fetchedPostData = {
                id: postSnap.id,
                ...postSnap.data(),
                createdAt: postSnap.data().createdAt?.toDate() || new Date()
              };
              setPostData(fetchedPostData);

              // Update view count
              try {
                await updateDoc(postRef, {
                  views: increment(1)
                });
              } catch (viewErr) {
                console.warn('Could not update view count:', viewErr);
                // Non-critical error, continue
              }
            } else {
              // Use the post data we already have
              setPostData(post);
            }
          } catch (postErr) {
            console.error('Error fetching post:', postErr);
            // Use the post data we already have as fallback
            setPostData(post);
          }
        }

        // Try to listen for comments
        try {
          const commentsCollection = collection(db, 'posts', post.id, 'comments');
          const commentsQuery = query(commentsCollection, orderBy('createdAt', 'asc'));

          const unsubscribe = onSnapshot(
            commentsQuery,
            (snapshot) => {
              const commentsData = snapshot.docs.map((doc) => ({
                id: doc.id,
                ...doc.data(),
                createdAt: doc.data().createdAt?.toDate() || new Date()
              }));
              setComments(commentsData);
              setLoading(false);
            },
            (err) => {
              console.error('Error fetching comments:', err);
              // Just show an empty comments list instead of error
              setComments([]);
              setLoading(false);
            }
          );

          return unsubscribe;
        } catch (commentErr) {
          console.error('Error setting up comments listener:', commentErr);
          setComments([]);
          setLoading(false);
        }
      } catch (err) {
        console.error('Error in post/comments loading:', err);
        // If we have a post already, use it
        if (post) {
          setPostData(post);
        } else {
          setError('Failed to load post. Please try again later.');
        }
        setLoading(false);
      }
    };

    fetchPostAndComments();
  }, [post, postData]);

  // Scroll to highlighted comment
  useEffect(() => {
    if (highlightedCommentId && highlightedCommentRef.current) {
      setTimeout(() => {
        highlightedCommentRef.current.scrollIntoView({ behavior: 'smooth' });
        highlightedCommentRef.current.classList.add('pulse-highlight');
        
        setTimeout(() => {
          if (highlightedCommentRef.current) {
            highlightedCommentRef.current.classList.remove('pulse-highlight');
          }
        }, 2000);
      }, 500);
    }
  }, [highlightedCommentId, comments]);

  // Handle document clicks to close menus
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (showCommentMenu && !e.target.closest('.comment-menu-container')) {
        setShowCommentMenu(null);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showCommentMenu]);

  // Like animation effect
  useEffect(() => {
    if (showLikeAnimation) {
      const timer = setTimeout(() => {
        setShowLikeAnimation(false);
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [showLikeAnimation]);

  // Handle liking the post
  const handleLike = async () => {
    try {
      if (!auth.currentUser) {
        alert('Please log in to like this post');
        return;
      }

      const db = getFirestore();
      const postRef = doc(db, 'posts', post.id);
      
      // Update the like count
      await updateDoc(postRef, {
        likes: increment(1)
      });
      
      // Update local state
      setPostData(prev => ({
        ...prev,
        likes: (prev.likes || 0) + 1
      }));
      
      // Show like animation
      setShowLikeAnimation(true);
      setLiked(true);
    } catch (error) {
      console.error('Error liking post:', error);
      alert('Failed to like post. Please try again.');
    }
  };

  // Handle reply to comment
  const handleReplyTo = (comment) => {
    setReplyTo(comment);
    setNewComment(`@${comment.authorName} `);
    commentInputRef.current?.focus();
    
    // Scroll to the comment form
    commentInputRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  // Cancel reply
  const handleCancelReply = () => {
    setReplyTo(null);
    setNewComment('');
  };

  // Submit a new comment
  const handleSubmitComment = async (e) => {
    e.preventDefault();
    
    if (!newComment.trim()) return;
    
    try {
      if (!auth.currentUser) {
        alert('Please log in to comment');
        return;
      }
      
      setSubmitting(true);
      
      const db = getFirestore();
      const commentsCollection = collection(db, 'posts', post.id, 'comments');
      
      // Prepare comment data
      const commentData = {
        content: newComment.trim(),
        authorId: auth.currentUser.uid,
        authorName: auth.currentUser.displayName || 'Anonymous',
        authorPhotoURL: auth.currentUser.photoURL || null,
        createdAt: serverTimestamp(),
        likes: 0
      };
      
      // Add reply-to reference if replying to a comment
      if (replyTo) {
        commentData.replyTo = {
          commentId: replyTo.id,
          authorId: replyTo.authorId,
          authorName: replyTo.authorName
        };
      }
      
      // Add the new comment
      await addDoc(commentsCollection, commentData);
      
      // Update the comment count on the post
      const postRef = doc(db, 'posts', post.id);
      await updateDoc(postRef, {
        commentCount: increment(1)
      });
      
      // Update local state
      setPostData(prev => ({
        ...prev,
        commentCount: (prev.commentCount || 0) + 1
      }));
      
      // Reset comment form
      setNewComment('');
      setReplyTo(null);
    } catch (error) {
      console.error('Error adding comment:', error);
      alert('Failed to add comment. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  // Toggle comment menu
  const toggleCommentMenu = (commentId) => {
    if (showCommentMenu === commentId) {
      setShowCommentMenu(null);
    } else {
      setShowCommentMenu(commentId);
    }
  };

  // Delete a comment
  const handleDeleteComment = async (commentId) => {
    if (!auth.currentUser) return;
    
    try {
      const db = getFirestore();
      const commentRef = doc(db, 'posts', post.id, 'comments', commentId);
      
      // Get the comment to check ownership
      const commentSnap = await getDoc(commentRef);
      if (!commentSnap.exists()) return;
      
      const commentData = commentSnap.data();
      
      // Verify user owns the comment
      if (commentData.authorId !== auth.currentUser.uid) {
        alert('You can only delete your own comments');
        return;
      }
      
      // Delete the comment
      await deleteDoc(commentRef);
      
      // Update comment count
      const postRef = doc(db, 'posts', post.id);
      await updateDoc(postRef, {
        commentCount: increment(-1)
      });
      
      // Update local state
      setPostData(prev => ({
        ...prev,
        commentCount: Math.max(0, (prev.commentCount || 0) - 1)
      }));
      
      // Close menu
      setShowCommentMenu(null);
    } catch (error) {
      console.error('Error deleting comment:', error);
      alert('Failed to delete comment. Please try again.');
    }
  };

  // Like a comment
  const handleLikeComment = async (commentId) => {
    if (!auth.currentUser) {
      alert('Please log in to like comments');
      return;
    }
    
    try {
      const db = getFirestore();
      const commentRef = doc(db, 'posts', post.id, 'comments', commentId);
      
      // Update like count
      await updateDoc(commentRef, {
        likes: increment(1)
      });
      
      // Update local state
      setComments(prevComments => 
        prevComments.map(comment => 
          comment.id === commentId 
            ? { ...comment, likes: (comment.likes || 0) + 1 } 
            : comment
        )
      );
    } catch (error) {
      console.error('Error liking comment:', error);
      alert('Failed to like comment. Please try again.');
    }
  };

  // Format date for display
  const formatDate = (date) => {
    if (!date) return '';
    return format(date, 'PPP');
  };

  if (loading) {
    return (
      <div className="detail-view-loading">
        <div className="spinner"></div>
        <p>Loading post...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="detail-view-error">
        <AlertCircle size={24} />
        <p>{error}</p>
      </div>
    );
  }

  if (!postData) {
    return (
      <div className="empty-detail-state">
        <p>No post selected</p>
      </div>
    );
  }

  return (
    <div className="post-detail-view">
      {/* Close button at the top */}
      <button className="detail-close-button" onClick={onClose}>
        <X size={20} />
      </button>
      
      {/* Like animation */}
      {showLikeAnimation && (
        <div className="like-animation">
          <Heart size={64} color="#ff4d4d" fill="#ff4d4d" />
        </div>
      )}
      
      <div className="post-detail-header">
        <h2 className="detail-view-title">{postData.title}</h2>
        <div className="post-detail-meta">
          <div className="post-detail-author">
            {postData.authorPhotoURL ? (
              <img src={postData.authorPhotoURL} alt={postData.authorName} className="detail-author-avatar" />
            ) : (
              <div className="detail-author-avatar-placeholder">
                <User size={16} />
              </div>
            )}
            <span className="detail-author-name">{postData.authorName || postData.username || 'Anonymous'}</span>
          </div>
          
          <div className="post-detail-info">
            <span className="detail-time">
              <Calendar size={16} />
              {formatDate(postData.createdAt)} ({formatDistanceToNow(postData.createdAt, { addSuffix: true })})
            </span>
            
            {postData.location && (
              <span className="detail-location">
                <MapPin size={16} />
                {postData.location}
              </span>
            )}
          </div>
        </div>
        
        {postData.topic && (
          <div className="detail-topic">
            <span className="topic-badge">#{postData.topic}</span>
          </div>
        )}
      </div>
      
      <div className="post-detail-content">
        <p className="detail-text">{postData.content}</p>
        
        {/* Display images - support both old and new formats */}
        {((postData.hasPhoto && postData.photoURL) || (postData.imageUrls && postData.imageUrls.length > 0)) && (
          <div className="detail-photo-container">
            {postData.imageUrls && postData.imageUrls.length > 0 ? (
              postData.imageUrls.map((imageUrl, index) => (
                <img 
                  key={index}
                  src={imageUrl} 
                  alt={`${postData.title} - Image ${index + 1}`} 
                  className="detail-photo" 
                />
              ))
            ) : (
              <img src={postData.photoURL} alt={postData.title} className="detail-photo" />
            )}
          </div>
        )}
        
        {postData.url && (
          <div className="detail-url">
            <a href={postData.url} target="_blank" rel="noopener noreferrer">
              <LinkIcon size={16} />
              <span>Related URL: {postData.url}</span>
            </a>
          </div>
        )}
      </div>
      
      <div className="post-detail-stats">
        <div className="detail-stat">
          <ThumbsUp size={16} />
          <span>{postData.likes || 0} likes</span>
        </div>
        <div className="detail-stat">
          <MessageSquare size={16} />
          <span>{postData.commentCount || 0} comments</span>
        </div>
        <div className="detail-stat">
          <Eye size={16} />
          <span>{postData.views || 0} views</span>
        </div>
      </div>
      
      <div className="post-detail-actions">
        <button 
          className={`detail-action-button ${liked ? 'liked' : ''}`} 
          onClick={handleLike}
        >
          <ThumbsUp size={16} />
          <span>Like</span>
        </button>
        <button 
          className="detail-action-button"
          onClick={() => commentInputRef.current?.focus()}
        >
          <MessageSquare size={16} />
          <span>Comment</span>
        </button>
        <button className="detail-action-button">
          <Share2 size={16} />
          <span>Share</span>
        </button>
      </div>
      
      <div className="detail-comments-section">
        <h3 className="detail-comments-title">
          Comments <span className="comments-count">({postData.commentCount || 0})</span>
        </h3>
        
        <form className="detail-comment-form" onSubmit={handleSubmitComment}>
          {replyTo && (
            <div className="reply-indicator">
              <span>Replying to <strong>{replyTo.authorName}</strong></span>
              <button type="button" onClick={handleCancelReply} className="cancel-reply-button">
                <X size={14} />
              </button>
            </div>
          )}
          
          <div className="comment-input-container">
            {auth.currentUser?.photoURL ? (
              <img src={auth.currentUser.photoURL} alt="You" className="comment-user-avatar" />
            ) : (
              <div className="comment-user-avatar-placeholder">
                <User size={16} />
              </div>
            )}
            
            <div className="comment-input-wrapper">
              <textarea
                ref={commentInputRef}
                className="detail-comment-input"
                placeholder={auth.currentUser ? "Write a comment..." : "Log in to comment"}
                value={newComment}
                onChange={(e) => setNewComment(e.target.value)}
                rows={2}
                disabled={submitting || !auth.currentUser}
              />
              
              <button 
                type="submit" 
                className="detail-comment-submit"
                disabled={!newComment.trim() || submitting || !auth.currentUser}
              >
                {submitting ? (
                  <div className="spinner-small"></div>
                ) : (
                  <Send size={16} />
                )}
              </button>
            </div>
          </div>
          
          {!auth.currentUser && (
            <p className="login-to-comment">Please log in to post a comment</p>
          )}
        </form>
        
        <div className="detail-comments-list">
          {comments.length > 0 ? (
            comments.map((comment) => (
              <div 
                key={comment.id} 
                className={`detail-comment-item ${comment.id === highlightedCommentId ? 'highlighted' : ''}`}
                ref={comment.id === highlightedCommentId ? highlightedCommentRef : null}
              >
                <div className="detail-comment-author">
                  {comment.authorPhotoURL ? (
                    <img src={comment.authorPhotoURL} alt={comment.authorName} className="detail-comment-avatar" />
                  ) : (
                    <div className="detail-comment-avatar-placeholder">
                      <User size={14} />
                    </div>
                  )}
                  <div className="detail-comment-meta">
                    <span className="detail-comment-author-name">{comment.authorName || 'Anonymous'}</span>
                    <span className="detail-comment-time">
                      {formatDistanceToNow(comment.createdAt, { addSuffix: true })}
                    </span>
                  </div>
                  
                  <button 
                    className="comment-menu-button"
                    onClick={() => toggleCommentMenu(comment.id)}
                  >
                    <MoreVertical size={16} />
                  </button>
                  
                  {/* Comment Menu */}
                  {showCommentMenu === comment.id && (
                    <div className="comment-menu-container">
                      <div className="comment-menu">
                        <button 
                          className="comment-menu-item"
                          onClick={() => handleReplyTo(comment)}
                        >
                          <MessageSquare size={14} />
                          <span>Reply</span>
                        </button>
                        
                        {auth.currentUser?.uid === comment.authorId && (
                          <button 
                            className="comment-menu-item delete-item"
                            onClick={() => handleDeleteComment(comment.id)}
                          >
                            <Trash2 size={14} />
                            <span>Delete</span>
                          </button>
                        )}
                      </div>
                    </div>
                  )}
                </div>
                
                <div className="detail-comment-content">
                  {/* Show reply to indicator */}
                  {comment.replyTo && (
                    <div className="comment-reply-indicator">
                      Replying to <span className="reply-name">@{comment.replyTo.authorName}</span>
                    </div>
                  )}
                  
                  {comment.content}
                </div>
                
                <div className="detail-comment-actions">
                  <button 
                    className="comment-action-button"
                    onClick={() => handleLikeComment(comment.id)}
                  >
                    <ThumbsUp size={14} />
                    <span>{comment.likes > 0 ? comment.likes : 'Like'}</span>
                  </button>
                  
                  <button 
                    className="comment-action-button"
                    onClick={() => handleReplyTo(comment)}
                  >
                    <MessageSquare size={14} />
                    <span>Reply</span>
                  </button>
                </div>
              </div>
            ))
          ) : (
            <p className="detail-comments-empty">No comments yet. Be the first to comment!</p>
          )}
        </div>
      </div>
    </div>
  );
};

export default PostDetailPanel;