// src/pages/SchedulePage.jsx
//
// The full schedule behind Discover's "Full schedule →": everything public in
// the next week, the shows you host (with edit links), and — on /following —
// only the hosts you follow.

import React, { useCallback, useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { collection, getDocs, query, where } from 'firebase/firestore';
import { db } from '../firebase';
import TalkStudioNav from '../components/layout/TalkStudioNav';
import { useAuth } from '../contexts/AuthContext';
import {
  listUpcomingOccurrences,
  listRoomsByHost,
  listRsvpsForUser,
  toggleRsvp,
  downloadIcs,
  deleteScheduledRoom,
  formatClock,
  formatDayTime,
  formatDuration,
  cadenceLabel,
} from '../services/scheduledRoomsService';
import './DiscoverPage.css';
import './SchedulePage.css';

const SchedulePage = ({ mode = 'all' }) => {
  const { currentUser } = useAuth();
  const navigate = useNavigate();

  const [rows, setRows] = useState(null);
  const [myShows, setMyShows] = useState([]);
  const [rsvped, setRsvped] = useState(() => new Set());
  const [followedHosts, setFollowedHosts] = useState(null);

  // /following needs the set of hosts before it can filter the schedule.
  useEffect(() => {
    if (mode !== 'following') { setFollowedHosts(null); return; }
    if (!currentUser) { setFollowedHosts(new Set()); return; }
    getDocs(query(collection(db, 'follows'), where('followerId', '==', currentUser.uid)))
      .then(snap => setFollowedHosts(new Set(snap.docs.map(d => d.data().followingId))))
      .catch(() => setFollowedHosts(new Set()));
  }, [mode, currentUser]);

  useEffect(() => {
    if (mode === 'following' && followedHosts === null) return;
    let cancelled = false;
    listUpcomingOccurrences({ window: 'week', max: 100 })
      .then(all => {
        if (cancelled) return;
        setRows(mode === 'following' ? all.filter(o => followedHosts.has(o.hostId)) : all);
      })
      .catch(err => {
        console.warn('[Schedule] load failed:', err.message);
        if (!cancelled) setRows([]);
      });
    return () => { cancelled = true; };
  }, [mode, followedHosts]);

  useEffect(() => {
    if (!currentUser) return;
    listRoomsByHost(currentUser.uid).then(setMyShows).catch(() => setMyShows([]));
    listRsvpsForUser(currentUser.uid)
      .then(list => setRsvped(new Set(list.map(r => r.occurrenceId))))
      .catch(() => {});
  }, [currentUser]);

  const handleRsvp = useCallback(async (occurrence) => {
    if (!currentUser) {
      navigate(`/login?next=${encodeURIComponent('/schedule/all')}`);
      return;
    }
    const going = rsvped.has(occurrence.id);
    setRsvped(prev => {
      const next = new Set(prev);
      if (going) next.delete(occurrence.id); else next.add(occurrence.id);
      return next;
    });
    try {
      await toggleRsvp({ user: currentUser, occurrence });
    } catch (err) {
      console.warn('[Schedule] RSVP failed:', err.message);
    }
  }, [currentUser, navigate, rsvped]);

  const removeShow = async (show) => {
    if (!window.confirm(`Delete "${show.title}"? Its upcoming airings go too.`)) return;
    await deleteScheduledRoom(show.id);
    setMyShows(prev => prev.filter(s => s.id !== show.id));
    setRows(prev => (prev || []).filter(o => o.roomId !== show.id));
  };

  return (
    <div className="ts-app schedule-list-page">
      <TalkStudioNav active={mode === 'following' ? 'following' : 'schedule'} />

      <div className="ts-page">
        <div className="schedule-list-head">
          <h1 className="schedule-list-title">
            {mode === 'following' ? 'From hosts you follow' : 'Full schedule'}
          </h1>
          <Link to="/schedule" className="ts-btn ts-btn--primary ts-btn--pill">
            Schedule a room
          </Link>
        </div>

        {currentUser && myShows.length > 0 && mode !== 'following' && (
          <section className="schedule-my-shows">
            <h2 className="discover-band-title">Your shows</h2>
            <div className="ts-card ts-card--quiet schedule-my-list">
              {myShows.map(show => (
                <div key={show.id} className="schedule-my-row">
                  <div>
                    <Link to={`/r/${show.slug}`} className="discover-cell-title">{show.title}</Link>
                    <div className="discover-cell-sub">
                      {cadenceLabel(show.repeat)} · {formatDuration(show.durationMin)} ·{' '}
                      <span className="ts-mono">/r/{show.slug}</span>
                      {show.status === 'draft' && <span className="schedule-draft-tag">draft</span>}
                    </div>
                  </div>
                  <div className="discover-cell-actions">
                    <Link to={`/schedule/${show.id}`} className="ts-btn ts-btn--sm ts-btn--neutral">Edit</Link>
                    <button
                      type="button"
                      className="ts-btn ts-btn--sm ts-btn--neutral"
                      onClick={() => removeShow(show)}
                    >
                      Delete
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </section>
        )}

        <div className="ts-card ts-card--quiet discover-table">
          <div className="discover-table-head ts-mono">
            <div>Starts</div><div>Show</div><div>Genre</div><div>Going</div><div />
          </div>

          {rows === null && (
            <div className="discover-table-row">
              <div className="ts-skeleton discover-cell-skeleton" />
              <div className="ts-skeleton discover-cell-skeleton" />
              <div className="ts-skeleton discover-cell-skeleton" />
              <div className="ts-skeleton discover-cell-skeleton" />
              <div />
            </div>
          )}

          {rows && rows.length === 0 && (
            <div className="ts-empty">
              {mode === 'following'
                ? 'Nothing from the hosts you follow this week.'
                : 'Nothing scheduled in the next seven days.'}
            </div>
          )}

          {(rows || []).map(occurrence => {
            const going = rsvped.has(occurrence.id);
            return (
              <div key={occurrence.id} className={`discover-table-row ${going ? 'going' : ''}`}>
                <div className="ts-mono discover-cell-time">
                  {formatClock(occurrence.startAt)}
                  <div className="schedule-row-day">{formatDayTime(occurrence.startAt).split(',')[0]}</div>
                </div>
                <div>
                  <Link to={`/r/${occurrence.slug}`} className="discover-cell-title">{occurrence.title}</Link>
                  <div className="discover-cell-sub">
                    {occurrence.hostName} · {cadenceLabel(occurrence.repeat)} ·{' '}
                    {formatDuration(occurrence.durationMin)}
                  </div>
                </div>
                <div className="discover-cell-genre">{(occurrence.genres || []).join(' · ')}</div>
                <div className="discover-cell-going">{occurrence.rsvpCount || 0} going</div>
                <div className="discover-cell-actions">
                  <button
                    type="button"
                    className={`ts-btn ts-btn--sm ${going ? 'ts-btn--going' : 'ts-btn--indigo-soft'}`}
                    onClick={() => handleRsvp(occurrence)}
                  >
                    {going ? 'Going ✓' : 'Notify me'}
                  </button>
                  <button
                    type="button"
                    className="ts-btn ts-btn--sm ts-btn--neutral"
                    onClick={() => downloadIcs(occurrence)}
                  >
                    Calendar
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default SchedulePage;
