// src/pages/DiscoverPage.jsx
//
// Screen A of the scheduled-rooms design: a listener lands here and is either
// in a room in one click, or committed to something later tonight.
//
// Three bands — Live now (hero + secondary list), Coming up (time/genre
// filters over the schedule table), and Replays.

import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Play } from 'lucide-react';
import TalkStudioNav from '../components/layout/TalkStudioNav';
import { useAuth } from '../contexts/AuthContext';
import {
  subscribeToLiveOccurrences,
  subscribeToLiveEvents,
  liveEventAsCard,
  listUpcomingOccurrences,
  listReplays,
  listRsvpsForUser,
  toggleRsvp,
  downloadIcs,
  formatClock,
  formatDuration,
  formatElapsed,
  cadenceLabel,
  occurrenceDate,
  GENRES,
} from '../services/scheduledRoomsService';
import './DiscoverPage.css';

const TIME_WINDOWS = [
  { id: 'tonight', label: 'Tonight' },
  { id: 'tomorrow', label: 'Tomorrow' },
  { id: 'week', label: 'This week' },
];

const artStyle = (url) => (url ? { backgroundImage: `url(${url})` } : undefined);

// A scheduled airing lives at its permanent room link; an ad-hoc broadcast
// lives at its event page.
const roomLink = (room) => (room.isEvent ? `/events/${room.eventId}` : `/r/${room.slug}`);

const endsAt = (occurrence) => {
  const end = occurrenceDate(occurrence.endAt);
  return end ? end.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }) : '';
};

const DiscoverPage = () => {
  const { currentUser } = useAuth();
  const navigate = useNavigate();

  const [liveRooms, setLiveRooms] = useState(null);
  const [liveEvents, setLiveEvents] = useState(null);
  const [upcoming, setUpcoming] = useState(null);
  const [replays, setReplays] = useState(null);
  const [timeWindow, setTimeWindow] = useState('tonight');
  const [genre, setGenre] = useState(null);
  const [rsvped, setRsvped] = useState(() => new Set());
  const [rsvpBusy, setRsvpBusy] = useState(null);

  // Live rooms stream in — the count and the hero swap without a reload.
  useEffect(() => subscribeToLiveOccurrences(setLiveRooms), []);
  // …as do ad-hoc broadcasts that aren't attached to a scheduled room.
  useEffect(() => subscribeToLiveEvents(setLiveEvents), []);

  // One list: scheduled airings first, then any event not already showing as
  // one (a bound broadcast appears in both places, and is the same room).
  const live = useMemo(() => {
    if (liveRooms === null && liveEvents === null) return null;
    const rooms = liveRooms || [];
    const bound = new Set(rooms.map(r => r.liveEventId).filter(Boolean));
    const events = (liveEvents || [])
      .filter(e => !bound.has(e.id))
      .map(liveEventAsCard);
    return [...rooms, ...events];
  }, [liveRooms, liveEvents]);

  useEffect(() => {
    let cancelled = false;
    setUpcoming(null);
    listUpcomingOccurrences({ window: timeWindow, genre })
      .then(rows => { if (!cancelled) setUpcoming(rows); })
      .catch(err => {
        console.warn('[Discover] upcoming failed:', err.message);
        if (!cancelled) setUpcoming([]);
      });
    return () => { cancelled = true; };
  }, [timeWindow, genre]);

  useEffect(() => {
    listReplays({ max: 4 })
      .then(setReplays)
      .catch(err => {
        console.warn('[Discover] replays failed:', err.message);
        setReplays([]);
      });
  }, []);

  useEffect(() => {
    if (!currentUser) { setRsvped(new Set()); return; }
    listRsvpsForUser(currentUser.uid)
      .then(rows => setRsvped(new Set(rows.map(r => r.occurrenceId))))
      .catch(() => setRsvped(new Set()));
  }, [currentUser]);

  const handleRsvp = useCallback(async (occurrence) => {
    if (!currentUser) {
      navigate(`/login?next=${encodeURIComponent('/')}`);
      return;
    }
    // Optimistic: the label flips before the write lands.
    const going = rsvped.has(occurrence.id);
    setRsvped(prev => {
      const next = new Set(prev);
      if (going) next.delete(occurrence.id); else next.add(occurrence.id);
      return next;
    });
    setUpcoming(prev => (prev || []).map(o => (
      o.id === occurrence.id
        ? { ...o, rsvpCount: Math.max(0, (o.rsvpCount || 0) + (going ? -1 : 1)) }
        : o
    )));
    setRsvpBusy(occurrence.id);
    try {
      await toggleRsvp({ user: currentUser, occurrence });
    } catch (err) {
      console.warn('[Discover] RSVP failed:', err.message);
      setRsvped(prev => {
        const next = new Set(prev);
        if (going) next.add(occurrence.id); else next.delete(occurrence.id);
        return next;
      });
    } finally {
      setRsvpBusy(null);
    }
  }, [currentUser, navigate, rsvped]);

  const [hero, ...rest] = live || [];
  const listeningTotal = useMemo(
    () => (live || []).reduce((sum, o) => sum + (o.listenerCount || 0), 0),
    [live],
  );

  return (
    <div className="ts-app ts-app--glow discover-page">
      <TalkStudioNav active="discover" />

      <div className="ts-page">
        {/* ---------------- Live now ---------------- */}
        <div className="discover-band-head">
          <span className="ts-live-dot" />
          <h2 className="discover-band-title">Live now</h2>
          <span className="ts-mono discover-band-meta">
            {live === null
              ? 'checking…'
              : `${live.length} room${live.length === 1 ? '' : 's'} · ${listeningTotal} listening`}
          </span>
        </div>

        {live === null && (
          <div className="discover-live-grid discover-live-grid--loading">
            <div className="ts-skeleton discover-hero-skeleton" />
            <div className="discover-live-list">
              <div className="ts-skeleton discover-row-skeleton" />
              <div className="ts-skeleton discover-row-skeleton" />
              <div className="ts-skeleton discover-row-skeleton" />
            </div>
          </div>
        )}

        {live && live.length === 0 && (
          <div className="ts-card discover-nothing-live">
            <div className="discover-nothing-title">Nothing live right now</div>
            <div className="discover-nothing-sub">Here's what's coming up.</div>
          </div>
        )}

        {live && live.length > 0 && (
          <div className="discover-live-grid">
            <article className="ts-card discover-hero">
              <div className="ts-art discover-hero-art" style={artStyle(hero.artworkUrl)}>
                {!hero.artworkUrl && <span className="ts-mono discover-art-caption">show art 1:1</span>}
              </div>
              <div className="discover-hero-body">
                <div className="discover-hero-badges">
                  <span className="ts-badge-live">LIVE</span>
                  <span className="ts-mono discover-hero-time">
                    {formatElapsed(hero.wentLiveAt || hero.startAt)}
                    {endsAt(hero) ? ` · ends ${endsAt(hero)}` : ''}
                  </span>
                </div>
                <h3 className="discover-hero-title">{hero.title}</h3>
                <div className="discover-hero-host">
                  <Link to={`/artist/${hero.hostId}`}>{hero.hostName}</Link>
                  {hero.isEvent
                    ? ' · live now'
                    : ` · ${cadenceLabel(hero.repeat)}, ${formatClock(hero.startAt)}`}
                </div>
                <div className="discover-hero-chips">
                  {(hero.genres || []).map(g => <span key={g} className="ts-chip">{g}</span>)}
                  {hero.publishReplay && <span className="ts-chip ts-chip--neutral">recorded</span>}
                </div>
                <div className="discover-hero-foot">
                  <Link to={roomLink(hero)} className="ts-btn ts-btn--primary ts-btn--md">
                    <Play size={14} fill="currentColor" /> Listen
                  </Link>
                  <span className="discover-hero-stats">
                    {hero.listenerCount || 0} listening
                  </span>
                  <span className="ts-mono discover-hero-url">
                    talkstudio.space{roomLink(hero)}
                  </span>
                </div>
              </div>
            </article>

            <div className="discover-live-list">
              {rest.map(room => (
                <div key={room.id} className="ts-card ts-card--sm discover-live-row">
                  <div className="ts-art--sm discover-row-art" style={artStyle(room.artworkUrl)} />
                  <div className="discover-row-body">
                    <div className="discover-row-title">{room.title}</div>
                    <div className="discover-row-sub">
                      {(room.genres || [])[0] || 'live'} · {room.listenerCount || 0} listening
                    </div>
                  </div>
                  <Link to={roomLink(room)} className="ts-btn ts-btn--indigo-soft discover-row-btn">
                    Listen
                  </Link>
                </div>
              ))}
              <div className="discover-live-note">
                Anyone can listen without an account. Chat needs a name.
              </div>
            </div>
          </div>
        )}

        {/* ---------------- Coming up ---------------- */}
        <div className="discover-controls">
          <h2 className="discover-band-title">Coming up</h2>
          <div className="ts-segmented">
            {TIME_WINDOWS.map(w => (
              <button
                key={w.id}
                type="button"
                className={timeWindow === w.id ? 'selected' : ''}
                onClick={() => setTimeWindow(w.id)}
              >
                {w.label}
              </button>
            ))}
          </div>
          <div className="discover-genre-filters">
            <button
              type="button"
              className={`ts-filter-pill ${genre === null ? 'selected' : ''}`}
              onClick={() => setGenre(null)}
            >
              All genres
            </button>
            {GENRES.map(g => (
              <button
                key={g}
                type="button"
                className={`ts-filter-pill ${genre === g ? 'selected' : ''}`}
                onClick={() => setGenre(g)}
              >
                {g}
              </button>
            ))}
          </div>
          <Link to="/schedule/all" className="discover-band-link">Full schedule →</Link>
        </div>

        <div className="ts-card ts-card--quiet discover-table">
          <div className="discover-table-head ts-mono">
            <div>Starts</div><div>Show</div><div>Genre</div><div>Going</div><div />
          </div>

          {upcoming === null && (
            <div className="discover-table-row">
              <div className="ts-skeleton discover-cell-skeleton" />
              <div className="ts-skeleton discover-cell-skeleton" />
              <div className="ts-skeleton discover-cell-skeleton" />
              <div className="ts-skeleton discover-cell-skeleton" />
              <div />
            </div>
          )}

          {upcoming && upcoming.length === 0 && (
            <div className="ts-empty">
              Nothing scheduled {timeWindow === 'week' ? 'this week' : timeWindow}
              {genre ? ` in ${genre}` : ''}.
            </div>
          )}

          {(upcoming || []).map(occurrence => {
            const going = rsvped.has(occurrence.id);
            return (
              <div
                key={occurrence.id}
                className={`discover-table-row ${going ? 'going' : ''}`}
              >
                <div className="ts-mono discover-cell-time">{formatClock(occurrence.startAt)}</div>
                <div>
                  <Link to={`/r/${occurrence.slug}`} className="discover-cell-title">
                    {occurrence.title}
                  </Link>
                  <div className="discover-cell-sub">
                    {occurrence.hostName} · {cadenceLabel(occurrence.repeat)} ·{' '}
                    {formatDuration(occurrence.durationMin)}
                  </div>
                </div>
                <div className="discover-cell-genre">{(occurrence.genres || []).join(' · ')}</div>
                <div className="discover-cell-going">{occurrence.rsvpCount || 0} going</div>
                <div className="discover-cell-actions">
                  <button
                    type="button"
                    className={`ts-btn ts-btn--sm ${going ? 'ts-btn--going' : 'ts-btn--indigo-soft'}`}
                    onClick={() => handleRsvp(occurrence)}
                    disabled={rsvpBusy === occurrence.id}
                  >
                    {going ? 'Going ✓' : 'Notify me'}
                  </button>
                  <button
                    type="button"
                    className="ts-btn ts-btn--sm ts-btn--neutral"
                    onClick={() => downloadIcs(occurrence)}
                  >
                    Calendar
                  </button>
                </div>
              </div>
            );
          })}
        </div>

        {/* ---------------- Replays ---------------- */}
        <div className="discover-controls">
          <h2 className="discover-band-title">Missed it? Replays</h2>
          <span className="discover-band-meta">Every recorded room stays up for 30 days</span>
          <Link to="/replays" className="discover-band-link">All replays →</Link>
        </div>

        {replays && replays.length === 0 ? (
          <div className="ts-empty">No replays yet.</div>
        ) : (
          <div className="discover-replays">
            {(replays || [null, null, null, null]).map((replay, i) => (
              replay ? (
                <Link
                  key={replay.id}
                  to={`/r/${replay.slug}/replay/${replay.id}`}
                  className="ts-card ts-card--sm discover-replay"
                >
                  <div className="ts-art discover-replay-art" style={artStyle(replay.artworkUrl)}>
                    <span className="ts-mono discover-replay-len">
                      {formatDuration(replay.durationMin)}
                    </span>
                    <span className="discover-replay-plays">▶ {replay.playCount || 0}</span>
                  </div>
                  <div className="discover-replay-caption">
                    <div className="discover-replay-title">{replay.title}</div>
                    <div className="discover-replay-sub">
                      {replay.hostName} · {occurrenceDate(replay.startAt)?.toLocaleDateString([], { month: 'short', day: 'numeric' })}
                    </div>
                  </div>
                </Link>
              ) : (
                // eslint-disable-next-line react/no-array-index-key
                <div key={`skeleton-${i}`} className="ts-skeleton discover-replay-skeleton" />
              )
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default DiscoverPage;
