// Custom Multi-Participant Video Layout
const MultiParticipantVideoLayout = ({ creatorIdentity }) => {
  const participants = useParticipants();
  // Microphone is in here because a DJ set is audio-only: asking for camera
  // and screen-share alone meant an audio broadcast produced zero tracks and
  // the stage sat on "Waiting for stream..." for the whole set. Every consumer
  // below filters by source, so the extra tracks change nothing else.
  const tracks = useTracks([
    Track.Source.Camera,
    Track.Source.ScreenShare,
    Track.Source.Microphone,
  ]);
  const [currentRemoteIndex, setCurrentRemoteIndex] = useState(0);
  const [communityStreamIndex, setCommunityStreamIndex] = useState(0);

  // Separate local participant and all remote participants
  const localParticipant = participants.find(p => p.isLocal);
  const remoteParticipants = participants.filter(p => !p.isLocal);

  // Get video tracks
  const localVideoTrack = tracks.find(t => t.participant.isLocal && t.source === Track.Source.Camera);
  const remoteTracks = tracks.filter(t => !t.participant.isLocal && t.source === Track.Source.Camera);

  // Someone broadcasting sound but no picture — a DJ set, a talk room.
  const remoteAudioTracks = tracks.filter(
    t => !t.participant.isLocal && t.source === Track.Source.Microphone,
  );
  const audioOnlyBroadcaster = remoteAudioTracks[0]?.participant || null;

  // Priority: Show creator if available, otherwise first remote participant, or local if alone
  let mainVideoTrack;
  let otherRemoteTracks;

  // Debug logging for creator priority
  if (import.meta.env.DEV && creatorIdentity) {
    console.log('👑 Creator Priority Debug:', {
      creatorIdentity,
      remoteTracks: remoteTracks.map(t => ({
        identity: t.participant.identity,
        name: t.participant.name,
        isCreator: t.participant.identity === creatorIdentity
      }))
    });
  }

  if (creatorIdentity) {
    // Find the creator's track - try multiple matching strategies
    let creatorTrack = remoteTracks.find(t => t.participant.identity === creatorIdentity);

    // If not found by exact identity match, try by name or partial match
    if (!creatorTrack) {
      creatorTrack = remoteTracks.find(t =>
        t.participant.name === creatorIdentity ||
        t.participant.identity.includes(creatorIdentity) ||
        creatorIdentity.includes(t.participant.identity)
      );
    }

    if (creatorTrack) {
      // Creator found - show them in main view
      console.log('✅ Creator found and prioritized:', creatorTrack.participant.identity);
      mainVideoTrack = creatorTrack;
      otherRemoteTracks = remoteTracks.filter(t => t !== creatorTrack);
    } else {
      // Creator not found - use fallback logic
      console.log('⚠️ Creator not found, using fallback');
      mainVideoTrack = remoteTracks.length > 0 ? remoteTracks[0] : localVideoTrack;
      otherRemoteTracks = remoteTracks.slice(1);
    }
  } else {
    // No creator specified - show first remote or local
    mainVideoTrack = remoteTracks.length > 0 ? remoteTracks[0] : localVideoTrack;
    otherRemoteTracks = remoteTracks.slice(1);
  }

  // Navigate through remote participants
  const handlePrevRemote = () => {
    setCurrentRemoteIndex((prev) =>
      prev === 0 ? Math.max(0, otherRemoteTracks.length - 1) : prev - 1
    );
  };

  const handleNextRemote = () => {
    setCurrentRemoteIndex((prev) =>
      prev === otherRemoteTracks.length - 1 ? 0 : prev + 1
    );
  };

  const currentRemoteTrack = otherRemoteTracks[currentRemoteIndex];

  // Get community streams (registered users who are broadcasting, excluding creator and local)
  const communityStreams = remoteTracks.filter(t => {
    const isCreatorTrack = creatorIdentity && (
      t.participant.identity === creatorIdentity ||
      t.participant.name === creatorIdentity ||
      t.participant.identity.includes(creatorIdentity) ||
      creatorIdentity.includes(t.participant.identity)
    );
    // Registered users are those who are not the creator and have video tracks
    return !isCreatorTrack;
  });

  // Auto-cycle through community streams every 5 seconds
  useEffect(() => {
    if (communityStreams.length === 0) return;

    const interval = setInterval(() => {
      setCommunityStreamIndex((prevIndex) =>
        (prevIndex + 1) % communityStreams.length
      );
    }, 5000); // Change every 5 seconds

    return () => clearInterval(interval);
  }, [communityStreams.length]);

  const currentCommunityStream = communityStreams[communityStreamIndex];

  return (
    <div style={{
      width: '100%',
      height: '100%',
      display: 'flex',
      flexDirection: 'column',
      position: 'relative',
    }}>
      {/* Main Video Area - Shows first remote participant, or local if alone */}
      <div style={{
        flex: 1,
        position: 'relative',
        backgroundColor: '#1a1a1a',
      }}>
        {mainVideoTrack ? (
          <VideoTrack
            trackRef={mainVideoTrack}
            style={{ width: '100%', height: '100%' }}
          />
        ) : audioOnlyBroadcaster ? (
          <div style={{
            width: '100%',
            height: '100%',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            flexDirection: 'column',
            gap: '0.75rem',
            color: '#f5f5f5',
            background: 'radial-gradient(circle at 50% 30%, rgba(99,102,241,0.18), transparent 60%), #0d1220',
            padding: '1.5rem',
            textAlign: 'center',
          }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
              <span style={{
                width: 8, height: 8, borderRadius: '50%',
                background: '#dc2626', boxShadow: '0 0 0 3px rgba(220,38,38,0.25)',
              }} />
              <span style={{ fontSize: 12, fontWeight: 700, letterSpacing: '0.08em' }}>LIVE</span>
            </div>
            <div style={{ fontSize: 18, fontWeight: 600 }}>
              {audioOnlyBroadcaster.name || audioOnlyBroadcaster.identity || 'On air'}
            </div>
            <div style={{ fontSize: 13, color: 'rgba(255,255,255,0.6)' }}>
              Audio only — no camera on this one.
            </div>
            {/* Only appears while the browser is blocking playback, which is
                what silences a phone that never got a tap. */}
            <SafeStartAudio />
          </div>
        ) : (
          <div style={{
            width: '100%',
            height: '100%',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            color: 'rgba(255, 255, 255, 0.5)',
            flexDirection: 'column',
            gap: '1rem',
          }}>
            <User size={64} />
            <div>Waiting for stream...</div>
          </div>
        )}

        {/* Self-view overlay in bottom left corner for registered users */}
        {localVideoTrack && localParticipant && (
          <div style={{
            position: 'absolute',
            bottom: '80px',
            left: '16px',
            width: '240px',
            height: '180px',
            borderRadius: '8px',
            overflow: 'hidden',
            border: '2px solid rgba(59, 130, 246, 0.8)',
            boxShadow: '0 4px 12px rgba(0, 0, 0, 0.5)',
            backgroundColor: '#000',
            zIndex: 10,
          }}>
            <VideoTrack
              trackRef={localVideoTrack}
              style={{ width: '100%', height: '100%', objectFit: 'cover' }}
            />
            <div style={{
              position: 'absolute',
              bottom: '4px',
              left: '4px',
              backgroundColor: 'rgba(59, 130, 246, 0.9)',
              color: 'white',
              padding: '2px 8px',
              borderRadius: '4px',
              fontSize: '0.7rem',
              fontWeight: 'bold',
            }}>
              You
            </div>
          </div>
        )}

        {/* Community Streaming Window - Bottom right corner, auto-cycles through registered users */}
        {currentCommunityStream && (
          <div style={{
            position: 'absolute',
            bottom: '80px',
            right: '16px',
            width: '240px',
            height: '180px',
            borderRadius: '8px',
            overflow: 'hidden',
            border: '2px solid rgba(16, 185, 129, 0.8)',
            boxShadow: '0 4px 12px rgba(0, 0, 0, 0.5)',
            backgroundColor: '#000',
            zIndex: 10,
          }}>
            <VideoTrack
              trackRef={currentCommunityStream}
              style={{ width: '100%', height: '100%', objectFit: 'cover' }}
            />
            <div style={{
              position: 'absolute',
              top: '4px',
              left: '4px',
              backgroundColor: 'rgba(16, 185, 129, 0.9)',
              color: 'white',
              padding: '2px 8px',
              borderRadius: '4px',
              fontSize: '0.7rem',
              fontWeight: 'bold',
              display: 'flex',
              alignItems: 'center',
              gap: '4px',
            }}>
              <Users size={12} />
              Community
            </div>
            <div style={{
              position: 'absolute',
              bottom: '4px',
              left: '4px',
              backgroundColor: 'rgba(0, 0, 0, 0.7)',
              color: 'white',
              padding: '2px 8px',
              borderRadius: '4px',
              fontSize: '0.7rem',
            }}>
              {currentCommunityStream.participant.name || currentCommunityStream.participant.identity}
            </div>
            <div style={{
              position: 'absolute',
              bottom: '4px',
              right: '4px',
              backgroundColor: 'rgba(0, 0, 0, 0.7)',
              color: 'white',
              padding: '2px 8px',
              borderRadius: '4px',
              fontSize: '0.65rem',
            }}>
              {communityStreamIndex + 1}/{communityStreams.length}
            </div>
          </div>
        )}
      </div>

      {/* Bottom Bar - Removed to give 100% space to main video */}
      {/* Community window in corner now handles showing other registered users */}
    </div>
  );
};

/**
 * Mobile browsers refuse to start audio without a user gesture, so LiveKit's
 * audio elements stay silent until room.startAudio() runs. StartAudio renders
 * only while playback is blocked and hides itself the moment sound starts —
 * without it, a phone joining an audio-only room hears nothing and has no way
 * to fix it.
 */
const SafeStartAudio = () => {
  try {
    return (
      <StartAudio
        label="Tap to listen"
        style={{
          padding: '10px 18px',
          borderRadius: 999,
          border: 'none',
          background: '#4f46e5',
          color: '#fff',
          fontSize: 14,
          fontWeight: 600,
          cursor: 'pointer',
        }}
      />
    );
  } catch (error) {
    console.error('❌ StartAudio error:', error);
    return null;
  }
};

// Safe Room Audio Renderer
const SafeRoomAudioRenderer = () => {
  try {
    return <RoomAudioRenderer />;
  } catch (error) {
    console.error('❌ RoomAudioRenderer error:', error);
    return null;
  }
};

// Simple Room Statistics (without hooks)
const SimpleRoomStats = ({ connectionState, roomName }) => {
  const [expanded, setExpanded] = useState(false);

  const getConnectionColor = () => {
    switch (connectionState) {
      case ConnectionState.Connected: return '#10b981';
      case ConnectionState.Connecting: return '#f59e0b';
      case ConnectionState.Reconnecting: return '#f59e0b';
      case ConnectionState.Disconnected: return '#ef4444';
      default: return '#6b7280';
    }
  };

  return (
    <div style={{
      position: 'absolute',
      top: '1rem',
      right: '1rem',
      backgroundColor: 'rgba(0, 0, 0, 0.8)',
      borderRadius: '8px',
      padding: '0.75rem',
      color: 'white',
      fontSize: '0.8rem',
      zIndex: 50,
      minWidth: '200px',
    }}>
      <div 
        onClick={() => setExpanded(!expanded)}
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: '0.5rem',
          cursor: 'pointer',
          marginBottom: expanded ? '0.5rem' : 0,
        }}
      >
        <div 
          style={{
            width: '8px',
            height: '8px',
            borderRadius: '50%',
            backgroundColor: getConnectionColor(),
          }}
        />
        <Wifi size={14} />
        <span style={{ fontWeight: 'bold' }}>
          {connectionState}
        </span>
        <Activity size={12} style={{ marginLeft: 'auto' }} />
      </div>

      {expanded && (
        <div style={{
          paddingTop: '0.5rem',
          borderTop: '1px solid rgba(255, 255, 255, 0.2)',
          display: 'grid',
          gap: '0.25rem',
        }}>
          <div>Room: {roomName}</div>
          <div>Status: {connectionState}</div>
        </div>
      )}
    </div>
  );
};

// Control Bar with Camera/Audio controls
const ControlBar = ({
  onLeave,
  canStream = false,
  isCreator = false,
  isBroadcasting = false,
  onStartBroadcast = null,
  onStopBroadcast = null,
  allowRegisteredToStream = true,
  onToggleRegisteredStreaming = null
}) => {
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [audioDevices, setAudioDevices] = useState([]);
  const [videoDevices, setVideoDevices] = useState([]);
  const [selectedAudioDevice, setSelectedAudioDevice] = useState('');
  const [selectedVideoDevice, setSelectedVideoDevice] = useState('');
  const { localParticipant } = useLocalParticipant();
  const room = useRoomContext(); // Get room context for device switching
  const [isCameraEnabled, setIsCameraEnabled] = useState(true);
  const [isMicEnabled, setIsMicEnabled] = useState(true);

  // Debug: Log when localParticipant changes
  useEffect(() => {
    console.log('🔧 ControlBar localParticipant updated:', {
      hasLocalParticipant: !!localParticipant,
      identity: localParticipant?.identity,
      canPublish: localParticipant?.permissions?.canPublish,
      canStream
    });
  }, [localParticipant, canStream]);

  // Load available devices
  useEffect(() => {
    const loadDevices = async () => {
      try {
        const devices = await navigator.mediaDevices.enumerateDevices();
        const audio = devices.filter(d => d.kind === 'audioinput');
        const video = devices.filter(d => d.kind === 'videoinput');
        setAudioDevices(audio);
        setVideoDevices(video);

        if (audio.length > 0 && !selectedAudioDevice) {
          setSelectedAudioDevice(audio[0].deviceId);
        }
        if (video.length > 0 && !selectedVideoDevice) {
          setSelectedVideoDevice(video[0].deviceId);
        }
      } catch (error) {
        console.error('Failed to enumerate devices:', error);
      }
    };

    if (canStream) {
      loadDevices();
    }
  }, [canStream, selectedAudioDevice, selectedVideoDevice]);

  const toggleFullscreen = useCallback(() => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen?.();
      setIsFullscreen(true);
    } else {
      document.exitFullscreen?.();
      setIsFullscreen(false);
    }
  }, []);

  const toggleCamera = useCallback(async () => {
    if (localParticipant) {
      const enabled = !isCameraEnabled;
      await localParticipant.setCameraEnabled(enabled);
      setIsCameraEnabled(enabled);
    }
  }, [localParticipant, isCameraEnabled]);

  const toggleMicrophone = useCallback(async () => {
    if (localParticipant) {
      const enabled = !isMicEnabled;
      await localParticipant.setMicrophoneEnabled(enabled);
      setIsMicEnabled(enabled);
    }
  }, [localParticipant, isMicEnabled]);

  const changeAudioDevice = useCallback(async (deviceId) => {
    console.log('🎤 Attempting to change audio device:', { deviceId, hasRoom: !!room });
    if (!room) {
      console.error('❌ No room available for audio device change');
      return;
    }
    if (!deviceId) {
      console.error('❌ No device ID provided');
      return;
    }
    try {
      console.log('🎤 Calling room.switchActiveDevice (audioinput)...');
      await room.switchActiveDevice('audioinput', deviceId);
      setSelectedAudioDevice(deviceId);
      console.log('✅ Audio device changed successfully to:', deviceId);
    } catch (error) {
      console.error('❌ Failed to change audio device:', error);
    }
  }, [room]);

  const changeVideoDevice = useCallback(async (deviceId) => {
    console.log('📹 Attempting to change video device:', { deviceId, hasRoom: !!room });
    if (!room) {
      console.error('❌ No room available for video device change');
      return;
    }
    if (!deviceId) {
      console.error('❌ No device ID provided');
      return;
    }
    try {
      console.log('📹 Calling room.switchActiveDevice (videoinput)...');
      await room.switchActiveDevice('videoinput', deviceId);
      setSelectedVideoDevice(deviceId);
      console.log('✅ Video device changed successfully to:', deviceId);
    } catch (error) {
      console.error('❌ Failed to change video device:', error);
    }
  }, [room]);

  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };

    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
  }, []);

  return (
    <div style={{
      position: 'absolute',
      bottom: '1rem',
      left: '50%',
      transform: 'translateX(-50%)',
      display: 'flex',
      flexDirection: 'column',
      gap: '0.5rem',
      zIndex: 50,
    }}>
      {/* Settings Panel */}
      {showSettings && canStream && (
        <div style={{
          backgroundColor: 'rgba(0, 0, 0, 0.9)',
          borderRadius: '12px',
          padding: '1rem',
          minWidth: '300px',
          marginBottom: '0.5rem',
        }}>
          <h4 style={{ margin: '0 0 1rem 0', color: 'white', fontSize: '0.9rem' }}>Device Settings</h4>

          {/* Camera Selection */}
          <div style={{ marginBottom: '1rem' }}>
            <label style={{ color: 'white', fontSize: '0.8rem', display: 'block', marginBottom: '0.5rem' }}>
              Camera
            </label>
            <select
              value={selectedVideoDevice}
              onChange={(e) => changeVideoDevice(e.target.value)}
              style={{
                width: '100%',
                padding: '0.5rem',
                borderRadius: '6px',
                backgroundColor: 'rgba(255, 255, 255, 0.1)',
                color: 'white',
                border: '1px solid rgba(255, 255, 255, 0.2)',
              }}
            >
              {videoDevices.map(device => (
                <option key={device.deviceId} value={device.deviceId}>
                  {device.label || `Camera ${device.deviceId.substring(0, 5)}`}
                </option>
              ))}
            </select>
          </div>

          {/* Microphone Selection */}
          <div style={{ marginBottom: isCreator ? '1rem' : '0' }}>
            <label style={{ color: 'white', fontSize: '0.8rem', display: 'block', marginBottom: '0.5rem' }}>
              Microphone
            </label>
            <select
              value={selectedAudioDevice}
              onChange={(e) => changeAudioDevice(e.target.value)}
              style={{
                width: '100%',
                padding: '0.5rem',
                borderRadius: '6px',
                backgroundColor: 'rgba(255, 255, 255, 0.1)',
                color: 'white',
                border: '1px solid rgba(255, 255, 255, 0.2)',
              }}
            >
              {audioDevices.map(device => (
                <option key={device.deviceId} value={device.deviceId}>
                  {device.label || `Microphone ${device.deviceId.substring(0, 5)}`}
                </option>
              ))}
            </select>
          </div>

          {/* Creator Only: Allow Registered Users to Stream Toggle */}
          {isCreator && onToggleRegisteredStreaming && (
            <div style={{
              padding: '0.75rem',
              borderRadius: '8px',
              backgroundColor: 'rgba(145, 70, 255, 0.2)',
              border: '1px solid rgba(145, 70, 255, 0.4)',
            }}>
              <div style={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                marginBottom: '0.5rem',
              }}>
                <label style={{ color: 'white', fontSize: '0.85rem', fontWeight: 'bold', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                  <Users size={16} />
                  Allow Registered Users to Stream
                </label>
                <button
                  onClick={onToggleRegisteredStreaming}
                  style={{
                    backgroundColor: 'transparent',
                    border: 'none',
                    cursor: 'pointer',
                    padding: 0,
                    color: allowRegisteredToStream ? '#10b981' : '#6b7280',
                  }}
                  title={allowRegisteredToStream ? 'Disable registered user streaming' : 'Enable registered user streaming'}
                >
                  {allowRegisteredToStream ? <ToggleRight size={32} /> : <ToggleLeft size={32} />}
                </button>
              </div>
              <p style={{
                margin: 0,
                fontSize: '0.7rem',
                color: 'rgba(255, 255, 255, 0.7)',
                lineHeight: '1.3',
              }}>
                {allowRegisteredToStream
                  ? 'Registered users can see and click "Start Broadcasting"'
                  : 'Only you can broadcast. Registered users will see a disabled button.'}
              </p>
            </div>
          )}
        </div>
      )}

      {/* Control Buttons */}
      <div style={{
        display: 'flex',
        gap: '0.5rem',
        backgroundColor: 'rgba(0, 0, 0, 0.8)',
        borderRadius: '12px',
        padding: '0.75rem',
      }}>
        {/* Camera Toggle - only for users who can stream */}
        {canStream && (
          <button
            onClick={toggleCamera}
            style={{
              backgroundColor: isCameraEnabled ? 'rgba(59, 130, 246, 0.8)' : 'rgba(239, 68, 68, 0.8)',
              border: 'none',
              borderRadius: '8px',
              padding: '0.75rem',
              color: 'white',
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
            }}
            title={isCameraEnabled ? 'Turn off camera' : 'Turn on camera'}
          >
            {isCameraEnabled ? <Video size={20} /> : <VideoOff size={20} />}
          </button>
        )}

        {/* Microphone Toggle - only for users who can stream */}
        {canStream && (
          <button
            onClick={toggleMicrophone}
            style={{
              backgroundColor: isMicEnabled ? 'rgba(59, 130, 246, 0.8)' : 'rgba(239, 68, 68, 0.8)',
              border: 'none',
              borderRadius: '8px',
              padding: '0.75rem',
              color: 'white',
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
            }}
            title={isMicEnabled ? 'Mute microphone' : 'Unmute microphone'}
          >
            {isMicEnabled ? <Mic size={20} /> : <MicOff size={20} />}
          </button>
        )}

        {/* Settings Toggle - only for users who can stream */}
        {canStream && (
          <button
            onClick={() => setShowSettings(!showSettings)}
            style={{
              backgroundColor: showSettings ? 'rgba(168, 85, 247, 0.8)' : 'rgba(107, 114, 128, 0.8)',
              border: 'none',
              borderRadius: '8px',
              padding: '0.75rem',
              color: 'white',
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
            }}
            title="Device settings"
          >
            <Settings size={20} />
          </button>
        )}

        {/* Creator Only: Start/Stop Stream Button */}
        {isCreator && onStartBroadcast && onStopBroadcast && (
          <button
            onClick={isBroadcasting ? onStopBroadcast : onStartBroadcast}
            style={{
              backgroundColor: isBroadcasting ? 'rgba(239, 68, 68, 0.9)' : 'rgba(145, 70, 255, 0.9)',
              border: 'none',
              borderRadius: '8px',
              padding: '0.75rem 1.5rem',
              color: 'white',
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontWeight: 'bold',
              gap: '0.5rem',
              fontSize: '0.9rem',
            }}
            title={isBroadcasting ? 'Stop broadcasting' : 'Start broadcasting'}
          >
            {isBroadcasting ? (
              <>
                <Radio size={18} />
                Stop Stream
              </>
            ) : (
              <>
                <Upload size={18} />
                Start Stream
              </>
            )}
          </button>
        )}

        {/* Fullscreen Toggle */}
        <button
          onClick={toggleFullscreen}
          style={{
            backgroundColor: 'rgba(107, 114, 128, 0.8)',
            border: 'none',
            borderRadius: '8px',
            padding: '0.75rem',
            color: 'white',
            cursor: 'pointer',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
          }}
          title={isFullscreen ? 'Exit fullscreen' : 'Enter fullscreen'}
        >
          {isFullscreen ? <Minimize2 size={20} /> : <Maximize2 size={20} />}
        </button>

        {/* Leave Room */}
        <button
          onClick={onLeave}
          style={{
            backgroundColor: 'rgba(239, 68, 68, 0.8)',
            border: 'none',
            borderRadius: '8px',
            padding: '0.75rem 1.5rem',
            color: 'white',
            cursor: 'pointer',
            fontWeight: 'bold',
          }}
          title="Leave room"
        >
          Leave
        </button>
      </div>
    </div>
  );
};

// Main LiveKit Room Component - Simplified and Safe
const LiveKitRoom = ({
  roomName,
  participantName,
  token = null,
  onConnected,
  onDisconnected,
  onError,
  className = '',
  options = {},
  creatorIdentity = null, // Identity of the event creator for always-visible display
  canStream = false, // Whether this user can stream (controls device settings visibility)
  isCreator = false, // Whether this user is the event creator
  isBroadcasting = false, // Whether the creator is currently broadcasting
  onStartBroadcast = null, // Callback for starting broadcast
  onStopBroadcast = null, // Callback for stopping broadcast
  allowRegisteredToStream = true, // Whether registered users are allowed to stream
  onToggleRegisteredStreaming = null, // Callback for toggling registered user streaming permission
  eventInfo = null, // { creatorName, eventTime } for overlay display
  eventId = null, // Event ID for creator token metadata (for egress recording)
}) => {
  const [connectionState, setConnectionState] = useState(ConnectionState.Disconnected);
  const [error, setError] = useState(null);
  const [isConnecting, setIsConnecting] = useState(false);
  const [generatedToken, setGeneratedToken] = useState(null);
  const [showEventOverlay, setShowEventOverlay] = useState(true);
  const roomRef = useRef(null);

  const config = LiveKitConfig.getCurrentConfig();

  // Hide event info overlay after 10 seconds
  useEffect(() => {
    if (eventInfo && showEventOverlay) {
      const timer = setTimeout(() => {
        setShowEventOverlay(false);
      }, 10000); // 10 seconds

      return () => clearTimeout(timer);
    }
  }, [eventInfo, showEventOverlay]);

  // Debug logging for creator controls
  useEffect(() => {
    console.log('🎛️ LiveKitRoom - Creator Control Props:', {
      isCreator,
      isBroadcasting,
      canStream,
      allowRegisteredToStream,
      hasStartBroadcast: !!onStartBroadcast,
      hasStopBroadcast: !!onStopBroadcast,
      hasToggleRegistered: !!onToggleRegisteredStreaming
    });
  }, [isCreator, isBroadcasting, canStream, allowRegisteredToStream, onStartBroadcast, onStopBroadcast, onToggleRegisteredStreaming]);
  const serverUrl = config.serverUrl;

  // Generate token if not provided
  useEffect(() => {
    const generateToken = async () => {
      if (!token && roomName && participantName) {
        try {
          setIsConnecting(true);
          if (import.meta.env.DEV) {
            console.log('🔑 Generating LiveKit token for:', { roomName, participantName, isCreator, eventId });
          }

          let tokenData;
          // Use creator token for event creators to include isArtistFeed metadata for recording
          if (isCreator && eventId) {
            console.log('👑 Generating CREATOR token with isArtistFeed metadata');
            tokenData = await liveKitTokenService.generateCreatorToken(
              roomName,
              participantName,
              eventId,
              options.tokenOptions || {}
            );
          } else {
            tokenData = await liveKitTokenService.generatePublisherToken(
              roomName,
              participantName,
              options.tokenOptions || {}
            );
          }

          setGeneratedToken(tokenData.token);
          if (import.meta.env.DEV) {
            console.log('✅ Token generated successfully', isCreator ? '(Creator token)' : '(Publisher token)');
          }
        } catch (error) {
          console.error('❌ Failed to generate token:', error);
          setError(`Token generation failed: ${error.message}`);
          setIsConnecting(false);
        }
      }
    };

    generateToken();
  }, [roomName, participantName, token, options.tokenOptions, isCreator, eventId]);

  // Use provided token or generated token
  const finalToken = token || generatedToken;

  // Handle connection state changes
  const handleConnectionStateChange = useCallback((state) => {
    setConnectionState(state);
    
    if (state === ConnectionState.Connected) {
      setIsConnecting(false);
      setError(null);
      onConnected?.(roomRef.current);
    } else if (state === ConnectionState.Disconnected) {
      setIsConnecting(false);
      onDisconnected?.();
    } else if (state === ConnectionState.Connecting) {
      setIsConnecting(true);
    }
  }, [onConnected, onDisconnected]);

  // Handle errors
  const handleError = useCallback((error) => {
    console.error('LiveKit room error:', error);
    setError(error.message);
    setIsConnecting(false);
    onError?.(error);
  }, [onError]);

  // Leave room
  const handleLeave = useCallback(async () => {
    console.log('🚪 Leave button clicked, roomRef:', !!roomRef.current);
    try {
      if (roomRef.current) {
        await roomRef.current.disconnect();
        console.log('✅ Room disconnected successfully');
      } else {
        // If no room ref, still notify parent that we're leaving
        console.log('⚠️ No room ref, calling onDisconnected directly');
        onDisconnected?.();
      }
    } catch (error) {
      console.error('❌ Error disconnecting:', error);
      // Still try to notify parent on error
      onDisconnected?.();
    }
  }, [onDisconnected]);

  if (!serverUrl) {
    return (
      <div style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        height: '400px',
        backgroundColor: 'rgba(0, 0, 0, 0.8)',
        borderRadius: '12px',
        color: 'white',
        flexDirection: 'column',
        gap: '1rem',
      }}>
        <AlertCircle size={48} color="#ef4444" />
        <div>
          <h3 style={{ margin: 0, marginBottom: '0.5rem' }}>Configuration Error</h3>
          <p style={{ margin: 0, opacity: 0.8 }}>
            LiveKit server URL not configured. Check environment variables.
          </p>
        </div>
      </div>
    );
  }

  if (!finalToken) {
    return (
      <div style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        height: '400px',
        backgroundColor: 'rgba(0, 0, 0, 0.8)',
        borderRadius: '12px',
        color: 'white',
        flexDirection: 'column',
        gap: '1rem',
      }}>
        <Clock size={48} color="#f59e0b" />
        <div>
          <h3 style={{ margin: 0, marginBottom: '0.5rem' }}>Generating Token</h3>
          <p style={{ margin: 0, opacity: 0.8 }}>
            Preparing secure connection...
          </p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        height: '400px',
        backgroundColor: 'rgba(0, 0, 0, 0.8)',
        borderRadius: '12px',
        color: 'white',
        flexDirection: 'column',
        gap: '1rem',
      }}>
        <AlertCircle size={48} color="#ef4444" />
        <div style={{ textAlign: 'center' }}>
          <h3 style={{ margin: 0, marginBottom: '0.5rem' }}>Connection Error</h3>
          <p style={{ margin: 0, opacity: 0.8 }}>{error}</p>
        </div>
      </div>
    );
  }

  return (
    <div className={`livekit-room ${className}`} style={{
      position: 'relative',
      width: '100%',
      height: '100%',
      backgroundColor: '#000',
      borderRadius: '12px',
      overflow: 'hidden',
    }}>
      <LiveKitRoomBase
        video={!!options.video}
        audio={!!options.audio}
        token={finalToken}
        serverUrl={serverUrl}
        data-lk-theme="default"
        style={{ height: '100%' }}
        onConnected={(room) => {
          try {
            roomRef.current = room;
            if (import.meta.env.DEV) {
              console.log('✅ LiveKitRoom connected successfully');
            }
            handleConnectionStateChange(ConnectionState.Connected);
          } catch (error) {
            console.error('❌ Error in onConnected callback:', error);
          }
        }}
        onDisconnected={(reason) => {
          if (import.meta.env.DEV) {
            console.log('❌ LiveKitRoom disconnected:', reason);
          }
          handleConnectionStateChange(ConnectionState.Disconnected);
        }}
        onError={handleError}
        options={LiveKitConfig.getRoomOptions(options)}
      >
        {/* Custom Multi-Participant Video Layout */}
        <MultiParticipantVideoLayout creatorIdentity={creatorIdentity} />

        {/* Event Info Overlay - Shows for 10 seconds */}
        {eventInfo && showEventOverlay && (
          <div style={{
            position: 'absolute',
            top: '2rem',
            left: '2rem',
            right: '2rem',
            backgroundColor: 'rgba(0, 0, 0, 0.85)',
            backdropFilter: 'blur(10px)',
            borderRadius: '12px',
            padding: '1.5rem 2rem',
            zIndex: 50,
            boxShadow: '0 4px 20px rgba(0, 0, 0, 0.5)',
            animation: 'fadeIn 0.5s ease-in',
          }}>
            <div style={{
              display: 'flex',
              flexDirection: 'column',
              gap: '0.75rem',
              color: 'white',
            }}>
              {eventInfo.creatorName && (
                <div style={{
                  fontSize: '1.5rem',
                  fontWeight: 'bold',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '0.5rem',
                }}>
                  <span style={{
                    width: '8px',
                    height: '8px',
                    backgroundColor: '#ef4444',
                    borderRadius: '50%',
                    animation: 'pulse 2s ease-in-out infinite',
                  }}></span>
                  {eventInfo.creatorName}
                </div>
              )}
              {eventInfo.eventTime && (
                <div style={{
                  fontSize: '1rem',
                  opacity: 0.9,
                  display: 'flex',
                  alignItems: 'center',
                  gap: '0.5rem',
                }}>
                  <span>📅</span>
                  {new Date(eventInfo.eventTime).toLocaleString()}
                </div>
              )}
            </div>
          </div>
        )}

        {/* Safe Audio Renderer */}
        <SafeRoomAudioRenderer />

        {/* Unblock audio playback on browsers that refuse to autoplay. */}
        <div style={{
          position: 'absolute', top: 16, left: '50%', transform: 'translateX(-50%)',
          zIndex: 30,
        }}>
          <SafeStartAudio />
        </div>

        {/* Control Bar with Camera/Audio controls */}
        <ControlBar
          onLeave={handleLeave}
          canStream={canStream}
          isCreator={isCreator}
          isBroadcasting={isBroadcasting}
          onStartBroadcast={onStartBroadcast}
          onStopBroadcast={onStopBroadcast}
          allowRegisteredToStream={allowRegisteredToStream}
          onToggleRegisteredStreaming={onToggleRegisteredStreaming}
        />

        {/* Connection Status Overlay */}
        {isConnecting && (
          <div style={{
            position: 'absolute',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: 'rgba(0, 0, 0, 0.8)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            color: 'white',
            zIndex: 100,
          }}>
            <div style={{ textAlign: 'center' }}>
              <div style={{
                width: '40px',
                height: '40px',
                border: '4px solid rgba(255, 255, 255, 0.2)',
                borderTop: '4px solid white',
                borderRadius: '50%',
                animation: 'spin 1s linear infinite',
                margin: '0 auto 1rem',
              }} />
              <h3 style={{ margin: 0, marginBottom: '0.5rem' }}>Connecting...</h3>
              <p style={{ margin: 0, opacity: 0.8 }}>
                Joining {roomName} as {participantName}
              </p>
            </div>
          </div>
        )}
      </LiveKitRoomBase>
    </div>
  );
};

export default LiveKitRoom;
