// src/components/activity/ActivityComposer.jsx
//
// What a creator posts to their own feed: a plain update, a plan for an
// upcoming stream, a release announcement, or clips/pictures from their
// media library. Anything uploaded here lands in the library, so the same
// clip can be reused later as set visuals.

import React, { useState } from 'react';
import { Radio, Disc3, MessageSquare, ImagePlus, Send, X } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { postActivity, ACTIVITY_TYPES } from '../../services/activityService';
import MediaLibrary from '../media/MediaLibrary';
import './ActivityComposer.css';

const TABS = [
  { id: ACTIVITY_TYPES.UPDATE, label: 'Update', icon: MessageSquare,
    placeholder: "What's happening in the studio?" },
  { id: ACTIVITY_TYPES.PLAN, label: 'Streaming plan', icon: Radio,
    placeholder: 'Tell people what you\'re planning to stream…' },
  { id: ACTIVITY_TYPES.RELEASE, label: 'Release', icon: Disc3,
    placeholder: 'Say something about the release…' },
  { id: ACTIVITY_TYPES.MEDIA, label: 'Clips & pictures', icon: ImagePlus,
    placeholder: 'Add a caption…' },
];

const ActivityComposer = ({ onPosted }) => {
  const { currentUser } = useAuth();
  const [type, setType] = useState(ACTIVITY_TYPES.UPDATE);
  const [text, setText] = useState('');
  const [scheduledFor, setScheduledFor] = useState('');
  const [release, setRelease] = useState({ title: '', url: '', releaseDate: '' });
  const [media, setMedia] = useState([]);
  const [showPicker, setShowPicker] = useState(false);
  const [posting, setPosting] = useState(false);
  const [error, setError] = useState(null);

  const active = TABS.find((t) => t.id === type) || TABS[0];

  const reset = () => {
    setText('');
    setScheduledFor('');
    setRelease({ title: '', url: '', releaseDate: '' });
    setMedia([]);
    setShowPicker(false);
  };

  const addMedia = (ref) => setMedia((prev) => (prev.some((m) => m.id === ref.id) ? prev : [...prev, ref]));
  const removeMedia = (id) => setMedia((prev) => prev.filter((m) => m.id !== id));

  const handlePost = async () => {
    setError(null);
    if (type === ACTIVITY_TYPES.RELEASE && !release.title.trim()) {
      setError('Give the release a title');
      return;
    }
    if (type === ACTIVITY_TYPES.MEDIA && !media.length) {
      setError('Pick or upload at least one clip or picture');
      return;
    }

    setPosting(true);
    try {
      // A release's first image doubles as its artwork.
      const artwork = media.find((m) => m.type === 'image');
      await postActivity({
        user: currentUser,
        type,
        text,
        media,
        scheduledFor: type === ACTIVITY_TYPES.PLAN && scheduledFor ? scheduledFor : null,
        release:
          type === ACTIVITY_TYPES.RELEASE
            ? { ...release, artworkUrl: artwork ? artwork.url : null }
            : null,
      });
      reset();
      if (onPosted) onPosted();
    } catch (err) {
      setError(err.message || 'Could not post that');
    } finally {
      setPosting(false);
    }
  };

  if (!currentUser) return null;

  return (
    <div className="activity-composer">
      <div className="composer-tabs">
        {TABS.map((tab) => {
          const Icon = tab.icon;
          return (
            <button
              key={tab.id}
              type="button"
              className={`composer-tab ${type === tab.id ? 'active' : ''}`}
              onClick={() => { setType(tab.id); setError(null); }}
            >
              <Icon size={15} />
              <span>{tab.label}</span>
            </button>
          );
        })}
      </div>

      <div className="composer-body">
        {type === ACTIVITY_TYPES.RELEASE && (
          <div className="composer-fields">
            <input
              type="text"
              value={release.title}
              onChange={(e) => setRelease({ ...release, title: e.target.value })}
              placeholder="Release title"
              className="composer-input"
            />
            <div className="composer-field-row">
              <input
                type="url"
                value={release.url}
                onChange={(e) => setRelease({ ...release, url: e.target.value })}
                placeholder="Link (Spotify, Bandcamp, …)"
                className="composer-input"
              />
              <input
                type="date"
                value={release.releaseDate}
                onChange={(e) => setRelease({ ...release, releaseDate: e.target.value })}
                className="composer-input"
                title="Release date"
              />
            </div>
          </div>
        )}

        {type === ACTIVITY_TYPES.PLAN && (
          <div className="composer-fields">
            <label className="composer-label" htmlFor="activity-scheduled-for">
              Going live at
            </label>
            <input
              id="activity-scheduled-for"
              type="datetime-local"
              value={scheduledFor}
              onChange={(e) => setScheduledFor(e.target.value)}
              className="composer-input"
            />
          </div>
        )}

        <textarea
          className="composer-textarea"
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder={active.placeholder}
          rows={3}
        />

        {media.length > 0 && (
          <div className="composer-media-strip">
            {media.map((m) => (
              <div key={m.id} className="composer-media-chip">
                <img src={m.thumbUrl || m.url} alt={m.title} />
                <button type="button" onClick={() => removeMedia(m.id)} title="Remove">
                  <X size={12} />
                </button>
              </div>
            ))}
          </div>
        )}

        {error && <div className="composer-error">{error}</div>}

        <div className="composer-actions">
          <button
            type="button"
            className="composer-attach"
            onClick={() => setShowPicker((v) => !v)}
          >
            <ImagePlus size={15} />
            <span>{showPicker ? 'Hide library' : 'Add clips & pictures'}</span>
          </button>
          <button
            type="button"
            className="composer-post"
            onClick={handlePost}
            disabled={posting}
          >
            <Send size={15} />
            <span>{posting ? 'Posting…' : 'Post'}</span>
          </button>
        </div>

        {showPicker && (
          <div className="composer-picker">
            <MediaLibrary
              mode="select"
              selected={media}
              onSelect={addMedia}
              onDeselect={removeMedia}
              emptyHint="Upload a picture or a short clip — it stays in your library for future posts and set visuals."
            />
          </div>
        )}
      </div>
    </div>
  );
};

export default ActivityComposer;
