// src/components/streaming/StreamControlPanel.jsx
import React, { useState, useEffect, useRef } from 'react';
import './StreamControlPanel.css';
import { 
  Mic, MicOff, Video, VideoOff, Settings, 
  Monitor, Smartphone, X, Check, RefreshCw, 
  Cloud, Server, Wifi, WifiOff 
} from 'lucide-react';
import { useStreamingLiveKit as useStreaming } from '../../contexts/StreamingContextLiveKit';
import { useAuth } from '../../contexts/AuthContext';

// Cloud streaming service configuration
const CLOUD_STREAMING_SERVICE = import.meta.env.REACT_APP_FFMPEG_SERVICE_URL || 'https://talkstudio-2c55dh9q.livekit.cloud';

const StreamControlPanel = ({ roomId, onStartStream, onStopStream }) => {
  const { currentUser } = useAuth();
  const { 
    userStreamPermission, 
    isStreaming, 
    streamSettings,
    availableDevices,
    updateStreamSettings,
    startStreamingInRoom,
    stopStreamingInRoom,
    getDevicesWithPermissions,
    error: contextError 
  } = useStreaming();
  
  const [localStream, setLocalStream] = useState(null);
  const [showSettings, setShowSettings] = useState(false);
  const [audioEnabled, setAudioEnabled] = useState(streamSettings.audio);
  const [videoEnabled, setVideoEnabled] = useState(streamSettings.video);
  const [selectedAudioDevice, setSelectedAudioDevice] = useState(streamSettings.audioDeviceId || '');
  const [selectedVideoDevice, setSelectedVideoDevice] = useState(streamSettings.videoDeviceId || '');
  const [quality, setQuality] = useState(streamSettings.quality || 'standard');
  const [localError, setLocalError] = useState('');
  
  // Cloud streaming states
  const [cloudStreamId, setCloudStreamId] = useState(null);
  const [streamingMode, setStreamingMode] = useState('local'); // 'local' or 'cloud'
  const [cloudStreamStatus, setCloudStreamStatus] = useState('disconnected');
  const [cloudServiceHealth, setCloudServiceHealth] = useState(null);
  
  const videoPreviewRef = useRef(null);
  
  // Check cloud service health on component mount
  useEffect(() => {
    checkCloudServiceHealth();
    const healthInterval = setInterval(checkCloudServiceHealth, 30000); // Check every 30 seconds
    
    return () => clearInterval(healthInterval);
  }, []);
  
  // Check cloud service health
  const checkCloudServiceHealth = async () => {
    try {
      const response = await fetch(`${CLOUD_STREAMING_SERVICE}/health`);
      const health = await response.json();
      setCloudServiceHealth(health);
    } catch (error) {
      console.warn('Cloud streaming service not available:', error);
      setCloudServiceHealth(null);
    }
  };
  
  // Create a reference to the initialization function
  const initializeMediaStreamRef = useRef(null);
  
  // Define the initialization function
  useEffect(() => {
    initializeMediaStreamRef.current = async () => {
      if (!userStreamPermission) return null;
      
      try {
        // Stop any existing stream
        if (localStream) {
          localStream.getTracks().forEach(track => track.stop());
        }
        
        // Get user media with appropriate constraints
        const constraints = {
          audio: audioEnabled ? 
            (selectedAudioDevice ? { deviceId: selectedAudioDevice } : true) 
            : false,
          video: videoEnabled ? {
            deviceId: selectedVideoDevice || undefined,
            width: getQualityConstraints(quality).width,
            height: getQualityConstraints(quality).height
          } : false
        };
        
        const stream = await navigator.mediaDevices.getUserMedia(constraints);
        setLocalStream(stream);
        
        // Connect stream to video preview
        if (videoPreviewRef.current) {
          videoPreviewRef.current.srcObject = stream;
        }
        
        return stream;
      } catch (err) {
        console.error('Error accessing media devices:', err);
        setLocalError(`Could not access camera/microphone: ${err.message}`);
        return null;
      }
    };
    
    // Cleanup function
    return () => {
      if (localStream) {
        localStream.getTracks().forEach(track => track.stop());
      }
    };
  }, [userStreamPermission, audioEnabled, videoEnabled, selectedAudioDevice, selectedVideoDevice, quality, localStream]);
  
  // Start cloud streaming
  const startCloudStream = async () => {
    try {
      const streamId = `${roomId}_${currentUser.uid}_${Date.now()}`;
      
      const response = await fetch(`${CLOUD_STREAMING_SERVICE}/api/streams/start`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          streamId,
          options: {
            qualities: getCloudQualitySettings(quality),
            uploadToGcs: false
          }
        })
      });
      
      if (!response.ok) {
        throw new Error(`Failed to start cloud stream: ${response.statusText}`);
      }
      
      const result = await response.json();
      setCloudStreamId(result.streamId);
      setCloudStreamStatus('live');
      
      return result;
    } catch (error) {
      console.error('Error starting cloud stream:', error);
      setLocalError(`Failed to start cloud stream: ${error.message}`);
      throw error;
    }
  };
  
  // Stop cloud streaming
  const stopCloudStream = async () => {
    if (!cloudStreamId) return;
    
    try {
      const response = await fetch(`${CLOUD_STREAMING_SERVICE}/api/streams/${cloudStreamId}/stop`, {
        method: 'POST'
      });
      
      if (!response.ok) {
        throw new Error(`Failed to stop cloud stream: ${response.statusText}`);
      }
      
      const result = await response.json();
      setCloudStreamId(null);
      setCloudStreamStatus('disconnected');
      
      return result;
    } catch (error) {
      console.error('Error stopping cloud stream:', error);
      setLocalError(`Failed to stop cloud stream: ${error.message}`);
      throw error;
    }
  };
  
  // Handle starting stream
  const handleStartStream = async () => {
    try {
      setLocalError(''); // Clear any previous errors
      
      // First get device permissions and update device list with labels
      await getDevicesWithPermissions();
      
      // Initialize the media stream
      const stream = await initializeMediaStreamRef.current();
      
      if (!stream) {
        setLocalError('Could not initialize media stream.');
        return;
      }
      
      // Choose streaming mode based on availability and user preference
      if (streamingMode === 'cloud' && cloudServiceHealth) {
        // Start cloud streaming
        const cloudResult = await startCloudStream();
        console.log('Cloud stream started:', cloudResult);
        
        // You would typically send the media stream to the cloud service here
        // This might involve WebRTC, RTMP, or another protocol
        
        // For now, we'll still start local streaming as well
        await startStreamingInRoom(roomId, stream);
      } else {
        // Start local streaming only
        await startStreamingInRoom(roomId, stream);
      }
      
      // Call parent handler
      if (onStartStream) {
        onStartStream(stream);
      }
    } catch (err) {
      console.error('Error starting stream:', err);
      setLocalError(`Failed to start streaming: ${err.message}`);
    }
  };
  
  // Handle stopping stream
  const handleStopStream = async () => {
    try {
      // Stop cloud stream if active
      if (cloudStreamId) {
        await stopCloudStream();
      }
      
      // Stop local streaming
      await stopStreamingInRoom(roomId);
      
      // Call parent handler
      if (onStopStream) {
        onStopStream();
      }
    } catch (err) {
      console.error('Error stopping stream:', err);
      setLocalError(`Failed to stop streaming: ${err.message}`);
    }
  };
  
  // Toggle audio
  const toggleAudio = () => {
    setAudioEnabled(!audioEnabled);
    updateStreamSettings({ audio: !audioEnabled });
    
    // If we have a local stream, toggle audio tracks
    if (localStream) {
      localStream.getAudioTracks().forEach(track => {
        track.enabled = !audioEnabled;
      });
    }
  };
  
  // Toggle video
  const toggleVideo = () => {
    setVideoEnabled(!videoEnabled);
    updateStreamSettings({ video: !videoEnabled });
    
    // If we have a local stream, toggle video tracks
    if (localStream) {
      localStream.getVideoTracks().forEach(track => {
        track.enabled = !videoEnabled;
      });
    }
  };
  
  // Handle audio device change
  const handleAudioDeviceChange = (e) => {
    setSelectedAudioDevice(e.target.value);
    updateStreamSettings({ audioDeviceId: e.target.value });
  };
  
  // Handle video device change
  const handleVideoDeviceChange = (e) => {
    setSelectedVideoDevice(e.target.value);
    updateStreamSettings({ videoDeviceId: e.target.value });
  };
  
  // Handle quality change
  const handleQualityChange = (e) => {
    setQuality(e.target.value);
    updateStreamSettings({ quality: e.target.value });
  };
  
  // Handle streaming mode change
  const handleStreamingModeChange = (e) => {
    setStreamingMode(e.target.value);
  };
  
  // Refresh available devices
  const refreshDevices = async () => {
    try {
      await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
      // The useStreaming hook will handle updating availableDevices
    } catch (err) {
      console.error('Error refreshing devices:', err);
      setLocalError(`Could not refresh devices: ${err.message}`);
    }
  };
  
  // Helper function to get quality constraints
  const getQualityConstraints = (qualityLevel) => {
    switch (qualityLevel) {
      case 'low':
        return { width: 640, height: 360 };
      case 'high':
        return { width: 1280, height: 720 };
      case 'ultra':
        return { width: 1920, height: 1080 };
      case 'standard':
      default:
        return { width: 854, height: 480 };
    }
  };
  
  // Helper function to get cloud quality settings
  const getCloudQualitySettings = (qualityLevel) => {
    const baseQualities = [
      { name: "480p", width: 854, height: 480, bitrate: "1200k", audioBitrate: "96k" }
    ];
    
    switch (qualityLevel) {
      case 'low':
        return [
          { name: "360p", width: 640, height: 360, bitrate: "800k", audioBitrate: "64k" }
        ];
      case 'high':
        return [
          { name: "720p", width: 1280, height: 720, bitrate: "2500k", audioBitrate: "128k" },
          ...baseQualities
        ];
      case 'ultra':
        return [
          { name: "1080p", width: 1920, height: 1080, bitrate: "5000k", audioBitrate: "128k" },
          { name: "720p", width: 1280, height: 720, bitrate: "2500k", audioBitrate: "128k" },
          ...baseQualities
        ];
      case 'standard':
      default:
        return baseQualities;
    }
  };
  
  if (!userStreamPermission) {
    return (
      <div className="stream-control-panel permission-required">
        <div className="no-permission-message">
          <p>You don't have permission to stream in this room.</p>
        </div>
      </div>
    );
  }
  
  return (
    <div className="stream-control-panel">
      {/* Error Display */}
      {(contextError || localError) && (
        <div className="error-message">
          <p>{contextError || localError}</p>
          <button onClick={() => setLocalError('')} className="clear-error">
            <X size={16} />
          </button>
        </div>
      )}
      
      {/* Cloud Service Status */}
      <div className="cloud-status">
        <div className={`status-indicator ${cloudServiceHealth ? 'online' : 'offline'}`}>
          {cloudServiceHealth ? (
            <>
              <Cloud size={16} />
              <span>Cloud Streaming Available</span>
            </>
          ) : (
            <>
              <WifiOff size={16} />
              <span>Cloud Service Offline</span>
            </>
          )}
        </div>
        {cloudStreamStatus === 'live' && (
          <div className="stream-status live">
            <span className="live-indicator"></span>
            Live on Cloud
          </div>
        )}
      </div>
      
      {/* Video Preview */}
      <div className="video-preview-container">
        {videoEnabled ? (
          <video
            ref={videoPreviewRef}
            autoPlay
            playsInline
            muted
            className="video-preview"
          />
        ) : (
          <div className="video-disabled-placeholder">
            <VideoOff size={48} />
            <p>Camera is disabled</p>
          </div>
        )}
      </div>
      
      {/* Basic Controls */}
      <div className="basic-controls">
        <button 
          className={`control-button ${!audioEnabled ? 'disabled' : ''}`}
          onClick={toggleAudio}
          title={audioEnabled ? 'Mute microphone' : 'Unmute microphone'}
        >
          {audioEnabled ? <Mic size={20} /> : <MicOff size={20} />}
        </button>
        
        <button 
          className={`control-button ${!videoEnabled ? 'disabled' : ''}`}
          onClick={toggleVideo}
          title={videoEnabled ? 'Turn off camera' : 'Turn on camera'}
        >
          {videoEnabled ? <Video size={20} /> : <VideoOff size={20} />}
        </button>
        
        <button 
          className="control-button"
          onClick={() => setShowSettings(!showSettings)}
          title="Stream settings"
        >
          <Settings size={20} />
        </button>
        
        <button 
          onClick={isStreaming ? handleStopStream : handleStartStream}
          className={`stream-button ${isStreaming ? 'stop' : 'start'} ${streamingMode === 'cloud' ? 'cloud-mode' : ''}`}
          disabled={!audioEnabled && !videoEnabled}
        >
          {streamingMode === 'cloud' && <Cloud size={16} />}
          {isStreaming ? 'Stop Streaming' : 'Start Streaming'}
        </button>
      </div>
      
      {/* Advanced Settings Panel */}
      {showSettings && (
        <div className="settings-panel">
          <h3>Stream Settings</h3>
          
          <div className="settings-form">
            <div className="form-group">
              <label htmlFor="streaming-mode">Streaming Mode</label>
              <select 
                id="streaming-mode" 
                value={streamingMode}
                onChange={handleStreamingModeChange}
              >
                <option value="local">Local Only</option>
                <option value="cloud" disabled={!cloudServiceHealth}>
                  Cloud Enhanced {!cloudServiceHealth && '(Unavailable)'}
                </option>
              </select>
              {streamingMode === 'cloud' && (
                <p className="mode-description">
                  Cloud mode provides HLS streaming, multiple quality options, and better scalability.
                </p>
              )}
            </div>
            
            <div className="form-group">
              <label htmlFor="audio-device">Microphone</label>
              <div className="select-with-refresh">
                <select 
                  id="audio-device" 
                  value={selectedAudioDevice}
                  onChange={handleAudioDeviceChange}
                  disabled={!audioEnabled}
                >
                  <option value="">Default Microphone</option>
                  {availableDevices.audioInputs.map(device => (
                    <option key={device.deviceId} value={device.deviceId}>
                      {device.label || `Microphone ${device.deviceId.slice(0, 5)}...`}
                    </option>
                  ))}
                </select>
                <button 
                  className="refresh-button"
                  onClick={refreshDevices}
                  title="Refresh devices"
                >
                  <RefreshCw size={16} />
                </button>
              </div>
            </div>
            
            <div className="form-group">
              <label htmlFor="video-device">Camera</label>
              <div className="select-with-refresh">
                <select 
                  id="video-device" 
                  value={selectedVideoDevice}
                  onChange={handleVideoDeviceChange}
                  disabled={!videoEnabled}
                >
                  <option value="">Default Camera</option>
                  {availableDevices.videoInputs.map(device => (
                    <option key={device.deviceId} value={device.deviceId}>
                      {device.label || `Camera ${device.deviceId.slice(0, 5)}...`}
                    </option>
                  ))}
                </select>
                <button 
                  className="refresh-button"
                  onClick={refreshDevices}
                  title="Refresh devices"
                >
                  <RefreshCw size={16} />
                </button>
              </div>
            </div>
            
            <div className="form-group">
              <label htmlFor="stream-quality">Stream Quality</label>
              <select 
                id="stream-quality" 
                value={quality}
                onChange={handleQualityChange}
              >
                <option value="low">Low (360p)</option>
                <option value="standard">Standard (480p)</option>
                <option value="high">High (720p)</option>
                {streamingMode === 'cloud' && (
                  <option value="ultra">Ultra (1080p) - Cloud Only</option>
                )}
              </select>
              {streamingMode === 'cloud' && (
                <p className="quality-note">
                  Cloud mode supports adaptive bitrate streaming with multiple quality levels.
                </p>
              )}
            </div>
            
            {/* Cloud Service Information */}
            {cloudServiceHealth && (
              <div className="cloud-info">
                <h4>Cloud Service Status</h4>
                <div className="cloud-stats">
                  <div className="stat">
                    <span>Active Streams:</span>
                    <span>{cloudServiceHealth.activeStreams}</span>
                  </div>
                  <div className="stat">
                    <span>Max Concurrent:</span>
                    <span>{cloudServiceHealth.limits?.maxConcurrentStreams}</span>
                  </div>
                  <div className="stat">
                    <span>Service:</span>
                    <span>{cloudServiceHealth.service}</span>
                  </div>
                </div>
                <div className="features">
                  <span>Features:</span>
                  {cloudServiceHealth.features?.map(feature => (
                    <span key={feature} className="feature-tag">{feature}</span>
                  ))}
                </div>
              </div>
            )}
            
            <div className="settings-info">
              <p>
                <strong>Note:</strong> Changing devices or quality will restart your video preview.
                {streamingMode === 'cloud' ? ' Cloud mode provides better quality and scalability.' : ' Higher quality requires better internet connection.'}
              </p>
            </div>
          </div>
        </div>
      )}
      
      {/* Cloud Stream Information */}
      {cloudStreamId && (
        <div className="cloud-stream-info">
          <h4>Cloud Stream Active</h4>
          <div className="stream-details">
            <div className="detail">
              <span>Stream ID:</span>
              <code>{cloudStreamId}</code>
            </div>
            <div className="detail">
              <span>Status:</span>
              <span className={`status ${cloudStreamStatus}`}>{cloudStreamStatus}</span>
            </div>
            <div className="detail">
              <span>HLS Playlist:</span>
              <a 
                href={`${CLOUD_STREAMING_SERVICE}/api/streams/${cloudStreamId}/master.m3u8`}
                target="_blank"
                rel="noopener noreferrer"
              >
                View Playlist
              </a>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default StreamControlPanel;
