// src/services/activityService.js
//
// A creator's activity feed: what they're planning, what they just released,
// the clips and pictures they want on their profile — plus the entries the
// platform writes for them automatically when they go live and when the
// stream ends, so a profile fills up by streaming, not only by posting.
//
// Feed is public (anyone can read a creator's page); only the author writes.
//
// Activity document shape:
// {
//   type: 'update'|'plan'|'release'|'media'|'stream',
//   author: { uid, name, photoURL },
//   text,
//   scheduledFor: Timestamp|null,                        // plan
//   release: { title, url, artworkUrl, releaseDate }|null,
//   media: [{ id, type, url, thumbUrl, title }],
//   stream: { streamId, eventId, title, streamType,
//             status: 'live'|'ended', startedAt, endedAt,
//             durationMs, viewerCount }|null,
//   system: boolean,                                     // written by the app
//   createdAt, updatedAt
// }

import {
  getFirestore,
  collection,
  doc,
  addDoc,
  getDocs,
  updateDoc,
  deleteDoc,
  query,
  where,
  orderBy,
  limit as fsLimit,
  serverTimestamp,
  Timestamp,
} from 'firebase/firestore';
import { app } from '../firebase';

const COLLECTION = 'creatorActivity';
const db = () => getFirestore(app);

export const ACTIVITY_TYPES = {
  UPDATE: 'update',
  PLAN: 'plan',
  RELEASE: 'release',
  MEDIA: 'media',
  STREAM: 'stream',
};

const authorOf = (user) => ({
  uid: user.uid,
  name: user.displayName || user.email || 'artist',
  photoURL: user.photoURL || null,
});

const toTimestamp = (value) => {
  if (!value) return null;
  if (value instanceof Timestamp) return value;
  const date = value instanceof Date ? value : new Date(value);
  return Number.isNaN(date.getTime()) ? null : Timestamp.fromDate(date);
};

/**
 * Post to your own feed. `type` decides which of the optional blocks matter:
 * a plan carries `scheduledFor`, a release carries `release`, and any type may
 * carry `media` picked from the creator's library.
 */
export async function postActivity({
  user,
  type = ACTIVITY_TYPES.UPDATE,
  text = '',
  scheduledFor = null,
  release = null,
  media = [],
  system = false,
  stream = null,
}) {
  if (!user || !user.uid) throw new Error('Must be signed in to post');

  const trimmed = (text || '').trim();
  if (!trimmed && !media.length && !release && !stream && !scheduledFor) {
    throw new Error('Add something to post — a note, a plan, a release, or a clip');
  }

  const ref = await addDoc(collection(db(), COLLECTION), {
    type,
    author: authorOf(user),
    text: trimmed,
    scheduledFor: toTimestamp(scheduledFor),
    release: release
      ? {
          title: (release.title || '').trim(),
          url: (release.url || '').trim(),
          artworkUrl: release.artworkUrl || null,
          releaseDate: toTimestamp(release.releaseDate),
        }
      : null,
    media: media || [],
    stream,
    system,
    createdAt: serverTimestamp(),
    updatedAt: serverTimestamp(),
  });
  return ref.id;
}

/**
 * One creator's feed, newest first. The ordered query wants a composite index;
 * until that's deployed we read unordered and sort in memory rather than
 * leaving the tab empty — same fallback the profile page uses for streams.
 */
export async function listActivityByUser(uid, { max = 50 } = {}) {
  if (!uid) return [];
  const base = collection(db(), COLLECTION);
  const sortNewestFirst = (items) =>
    items.sort((a, b) => (b.createdAt?.seconds || 0) - (a.createdAt?.seconds || 0));

  try {
    const snap = await getDocs(
      query(base, where('author.uid', '==', uid), orderBy('createdAt', 'desc'), fsLimit(max)),
    );
    return snap.docs.map((d) => ({ id: d.id, ...d.data() }));
  } catch (err) {
    console.warn('[activity] ordered query unavailable, sorting client-side:', err.message);
    const snap = await getDocs(query(base, where('author.uid', '==', uid), fsLimit(max)));
    return sortNewestFirst(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
  }
}

export async function deleteActivity(id) {
  if (!id) return;
  await deleteDoc(doc(db(), COLLECTION, id));
}

/* ------------------------------------------------------------------ *
 * Automatic stream entries
 *
 * Going live writes one entry; ending the stream updates that same entry
 * with the duration and peak viewers instead of posting a second time. The
 * id is remembered in sessionStorage so a page reload between "go live" and
 * "end stream" still closes the right entry, and a Firestore lookup covers
 * the case where even that is gone (different tab, crashed session).
 * ------------------------------------------------------------------ */

const liveKey = (streamId) => `creatorActivity:live:${streamId}`;

const rememberLiveEntry = (streamId, activityId) => {
  try {
    sessionStorage.setItem(liveKey(streamId), activityId);
  } catch (_) { /* private mode — the Firestore lookup covers us */ }
};

const recallLiveEntry = (streamId) => {
  try {
    return sessionStorage.getItem(liveKey(streamId));
  } catch (_) {
    return null;
  }
};

const forgetLiveEntry = (streamId) => {
  try {
    sessionStorage.removeItem(liveKey(streamId));
  } catch (_) { /* noop */ }
};

/** Find an open 'live' entry for this stream (equality-only: no index needed). */
async function findLiveActivity(uid, streamId) {
  const snap = await getDocs(
    query(
      collection(db(), COLLECTION),
      where('author.uid', '==', uid),
      where('stream.streamId', '==', streamId),
      where('stream.status', '==', 'live'),
      fsLimit(1),
    ),
  );
  return snap.empty ? null : snap.docs[0].id;
}

/**
 * Post "X is live" to the creator's feed. Safe to call more than once for the
 * same stream — a second call returns the existing entry.
 * Never throws: a feed entry must not be able to break going live.
 */
export async function recordStreamStarted({
  user,
  streamId,
  eventId = null,
  title = '',
  streamType = 'stream',
  text = '',
}) {
  if (!user || !user.uid || !streamId) return null;
  try {
    const existing = recallLiveEntry(streamId) || (await findLiveActivity(user.uid, streamId));
    if (existing) {
      rememberLiveEntry(streamId, existing);
      return existing;
    }

    const id = await postActivity({
      user,
      type: ACTIVITY_TYPES.STREAM,
      text,
      system: true,
      stream: {
        streamId,
        eventId,
        title: title || 'Live stream',
        streamType,
        status: 'live',
        startedAt: Timestamp.now(),
        endedAt: null,
        durationMs: null,
        viewerCount: 0,
      },
    });
    rememberLiveEntry(streamId, id);
    return id;
  } catch (err) {
    console.warn('[activity] could not record stream start:', err.message);
    return null;
  }
}

/**
 * Close out the live entry with how it went. Falls back to posting a fresh
 * "streamed" entry if the opening one can't be found, so the session still
 * shows up on the profile. Never throws.
 */
export async function recordStreamEnded({
  user,
  streamId,
  viewerCount = 0,
  title = '',
  eventId = null,
  streamType = 'stream',
  startedAt = null,
}) {
  if (!user || !user.uid || !streamId) return null;
  try {
    const id = recallLiveEntry(streamId) || (await findLiveActivity(user.uid, streamId));
    const endedAt = Timestamp.now();
    const startTs = toTimestamp(startedAt);
    const durationMs = startTs ? endedAt.toMillis() - startTs.toMillis() : null;

    if (id) {
      await updateDoc(doc(db(), COLLECTION, id), {
        'stream.status': 'ended',
        'stream.endedAt': endedAt,
        'stream.viewerCount': viewerCount || 0,
        ...(durationMs ? { 'stream.durationMs': durationMs } : {}),
        updatedAt: serverTimestamp(),
      });
      forgetLiveEntry(streamId);
      return id;
    }

    const newId = await postActivity({
      user,
      type: ACTIVITY_TYPES.STREAM,
      system: true,
      stream: {
        streamId,
        eventId,
        title: title || 'Live stream',
        streamType,
        status: 'ended',
        startedAt: startTs,
        endedAt,
        durationMs,
        viewerCount: viewerCount || 0,
      },
    });
    return newId;
  } catch (err) {
    console.warn('[activity] could not record stream end:', err.message);
    return null;
  }
}

export default {
  ACTIVITY_TYPES,
  postActivity,
  listActivityByUser,
  deleteActivity,
  recordStreamStarted,
  recordStreamEnded,
};
