import React, { useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import VenueEarnings from '../components/venue/VenueEarnings';
import VenueArtistLineup from '../components/venue/VenueArtistLineup';
import { DollarSign, Users, Calendar, TrendingUp, Settings } from 'lucide-react';
import './VenuePortalPage.css';

const VenuePortalPage = () => {
  const { currentUser, venueId } = useAuth();
  const [activeTab, setActiveTab] = useState('overview');

  const tabs = [
    { id: 'overview', label: 'Overview', icon: TrendingUp },
    { id: 'earnings', label: 'Earnings', icon: DollarSign },
    { id: 'lineup', label: 'Artist Lineup', icon: Users },
    { id: 'events', label: 'Events', icon: Calendar },
    { id: 'settings', label: 'Settings', icon: Settings }
  ];

  return (
    <div className="venue-portal">
      <div className="venue-portal-header">
        <h1>Venue Portal</h1>
        <p>Manage your venue, track earnings, and coordinate with artists</p>
      </div>

      <div className="venue-portal-tabs">
        {tabs.map(tab => {
          const Icon = tab.icon;
          return (
            <button
              key={tab.id}
              className={`tab-button ${activeTab === tab.id ? 'active' : ''}`}
              onClick={() => setActiveTab(tab.id)}
            >
              <Icon size={20} />
              <span>{tab.label}</span>
            </button>
          );
        })}
      </div>

      <div className="venue-portal-content">
        {activeTab === 'overview' && (
          <div className="overview-section">
            <div className="stats-grid">
              <div className="stat-card">
                <h3>Total Earnings</h3>
                <p className="stat-value">$0.00</p>
                <p className="stat-change">+0% from last month</p>
              </div>
              <div className="stat-card">
                <h3>Active Artists</h3>
                <p className="stat-value">0</p>
                <p className="stat-change">No change</p>
              </div>
              <div className="stat-card">
                <h3>Upcoming Events</h3>
                <p className="stat-value">0</p>
                <p className="stat-change">View calendar</p>
              </div>
              <div className="stat-card">
                <h3>Tips This Month</h3>
                <p className="stat-value">$0.00</p>
                <p className="stat-change">0 tips received</p>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'earnings' && <VenueEarnings venueId={venueId} />}
        
        {activeTab === 'lineup' && <VenueArtistLineup venueId={venueId} />}
        
        {activeTab === 'events' && (
          <div className="events-section">
            <h2>Upcoming Events</h2>
            <p>Events scheduled at your venue will appear here.</p>
          </div>
        )}
        
        {activeTab === 'settings' && (
          <div className="settings-section">
            <h2>Venue Settings</h2>
            <p>Configure your venue preferences and payment settings.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default VenuePortalPage;