// src/pages/ArtistSignUpPage.jsx
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { getFirestore, doc, getDoc, setDoc, serverTimestamp } from 'firebase/firestore';
import { ref, uploadBytes, getDownloadURL } from 'firebase/storage';
import { storage } from '../firebase';
import { useAuth } from '../contexts/AuthContext';
import {
  Radio, Upload, Check, MapPin, Calendar, Camera,
  Music, Gamepad2, Palette, Mic, GraduationCap,
  Dumbbell, ChefHat, Cpu, MessageCircle, Sparkles
} from 'lucide-react';
import '../styles/ArtistSignUp.css';

// Content categories the creator can pick from. `id` is stored on the profile;
// the icon/label are presentation only.
const CATEGORIES = [
  { id: 'music', label: 'Music', icon: Music },
  { id: 'gaming', label: 'Gaming', icon: Gamepad2 },
  { id: 'art', label: 'Art & Design', icon: Palette },
  { id: 'talk', label: 'Talk & Podcast', icon: Mic },
  { id: 'education', label: 'Education', icon: GraduationCap },
  { id: 'fitness', label: 'Fitness', icon: Dumbbell },
  { id: 'cooking', label: 'Cooking', icon: ChefHat },
  { id: 'tech', label: 'Tech', icon: Cpu },
  { id: 'irl', label: 'IRL / Just Chatting', icon: MessageCircle },
  { id: 'other', label: 'Other', icon: Sparkles },
];

const SOCIALS = [
  { key: 'instagram', label: 'Instagram', placeholder: 'Instagram username' },
  { key: 'tiktok', label: 'TikTok', placeholder: 'TikTok username' },
  { key: 'youtube', label: 'YouTube', placeholder: 'YouTube channel' },
  { key: 'twitch', label: 'Twitch', placeholder: 'Twitch channel' },
  { key: 'x', label: 'X', placeholder: 'X / Twitter handle' },
];

const ArtistSignUpPage = () => {
  const { currentUser } = useAuth();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(false);
  const [formData, setFormData] = useState({
    creatorName: '',
    category: '',
    categoryDetail: '',
    bio: '',
    websiteUrl: '',
    socialLinks: {
      instagram: '',
      tiktok: '',
      youtube: '',
      twitch: '',
      x: ''
    },
    nextEvent: {
      venue: '',
      dateTime: ''
    },
    agreesToTerms: false
  });
  const [profileImage, setProfileImage] = useState(null);
  const [profileImagePreview, setProfileImagePreview] = useState(null);
  const [coverImage, setCoverImage] = useState(null);
  const [coverImagePreview, setCoverImagePreview] = useState(null);

  // Check if user is already a creator
  useEffect(() => {
    const checkCreatorStatus = async () => {
      if (!currentUser) {
        navigate('/login', { state: { from: '/artist-signup' } });
        return;
      }

      try {
        const db = getFirestore();
        const userRef = doc(db, 'users', currentUser.uid);
        const userDoc = await getDoc(userRef);

        if (userDoc.exists() && userDoc.data().isArtist) {
          // Already a creator — send them to their profile
          navigate('/artist-profile');
        } else if (userDoc.exists()) {
          // Pre-fill with existing display name
          setFormData(prev => ({
            ...prev,
            creatorName: currentUser.displayName || ''
          }));
        }
      } catch (err) {
        console.error('Error checking creator status:', err);
        setError('Failed to check your account status. Please try again.');
      }
    };

    checkCreatorStatus();
  }, [currentUser, navigate]);

  // Handle input changes
  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;

    if (type === 'checkbox') {
      setFormData(prev => ({ ...prev, [name]: checked }));
    } else if (name.includes('.')) {
      // Nested objects (social links, next event)
      const [parent, child] = name.split('.');
      setFormData(prev => ({
        ...prev,
        [parent]: { ...prev[parent], [child]: value }
      }));
    } else {
      setFormData(prev => ({ ...prev, [name]: value }));
    }
  };

  const selectCategory = (id) => {
    setFormData(prev => ({ ...prev, category: id }));
    setError(null);
  };

  // Handle image upload
  const handleImageChange = (e, imageType) => {
    const file = e.target.files[0];
    if (!file) return;

    const validTypes = ['image/jpeg', 'image/png', 'image/webp'];
    if (!validTypes.includes(file.type)) {
      setError('Please upload a valid image file (JPEG, PNG, or WebP)');
      return;
    }

    if (file.size > 5 * 1024 * 1024) {
      setError('Image must be less than 5MB');
      return;
    }

    if (imageType === 'profile') {
      setProfileImage(file);
      setProfileImagePreview(URL.createObjectURL(file));
    } else if (imageType === 'cover') {
      setCoverImage(file);
      setCoverImagePreview(URL.createObjectURL(file));
    }

    setError(null);
  };

  // Handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!formData.category) {
      setError('Please choose a content category');
      return;
    }

    if (!formData.agreesToTerms) {
      setError('You must agree to the terms and conditions');
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const db = getFirestore();
      // Images are optional, so an upload failure must NOT block a creator from
      // going live. Upload each in its own try/catch; on failure we keep the
      // profile imageless and warn, rather than aborting the whole signup.
      // Uses the shared `storage` singleton (bound to the correct bucket).
      let imageWarning = false;
      const uploadImage = async (file, path) => {
        try {
          const imageRef = ref(storage, `artist-profiles/${currentUser.uid}/${path}`);
          await uploadBytes(imageRef, file);
          return await getDownloadURL(imageRef);
        } catch (uploadErr) {
          console.error(`Image upload failed (${path}):`, uploadErr?.code || uploadErr);
          imageWarning = true;
          return null;
        }
      };

      const profileImageUrl = profileImage ? await uploadImage(profileImage, 'profile-image') : null;
      const coverImageUrl = coverImage ? await uploadImage(coverImage, 'cover-image') : null;

      const timestamps = { createdAt: serverTimestamp(), updatedAt: serverTimestamp() };

      // Primary profile document read by the streaming studios (artistProfiles).
      // We keep the legacy `artistName`/`genre` keys populated for back-compat
      // with older components while introducing the generalized fields.
      const artistProfileRef = doc(db, 'artistProfiles', currentUser.uid);
      await setDoc(artistProfileRef, {
        uid: currentUser.uid,
        creatorName: formData.creatorName,
        artistName: formData.creatorName, // legacy alias
        stageName: formData.creatorName,  // legacy alias
        category: formData.category,
        categoryDetail: formData.categoryDetail,
        genre: formData.categoryDetail || formData.category, // legacy alias
        bio: formData.bio,
        websiteUrl: formData.websiteUrl,
        socialLinks: formData.socialLinks,
        nextEvent: formData.nextEvent,
        profileImageUrl,
        coverImageUrl,
        ...timestamps,
        isVerified: false,
        streamCount: 0,
        followerCount: 0
      });

      // Mirror to the `artists` collection used by the portal + public showcase,
      // in the shape those components expect (displayName / profileImage / genres).
      const artistRef = doc(db, 'artists', currentUser.uid);
      await setDoc(artistRef, {
        uid: currentUser.uid,
        displayName: formData.creatorName,
        bio: formData.bio,
        category: formData.category,
        genres: formData.category ? [formData.category] : [],
        profileImage: profileImageUrl || '',
        coverImage: coverImageUrl || '',
        websiteUrl: formData.websiteUrl,
        socialLinks: formData.socialLinks,
        ...timestamps
      }, { merge: true });

      // Mark the user as a creator
      const userRef = doc(db, 'users', currentUser.uid);
      await setDoc(userRef, {
        isArtist: true,
        artistProfileId: currentUser.uid,
        updatedAt: serverTimestamp()
      }, { merge: true });

      if (imageWarning) {
        // Profile was created, but one or more images didn't upload. Let them
        // know they can add art later from their profile — don't fail the flow.
        console.warn('Creator profile created without one or more images.');
      }

      setSuccess(true);
      setTimeout(() => {
        navigate('/artist-profile');
      }, 2000);
    } catch (err) {
      console.error('Error creating creator profile:', err);
      const code = err?.code ? ` (${err.code})` : '';
      setError(`Couldn't create your creator profile${code}. Please try again.`);
    } finally {
      setLoading(false);
    }
  };

  if (success) {
    return (
      <div className="creator-signup">
        <div className="creator-card success-card">
          <div className="success-icon">
            <Check size={40} />
          </div>
          <h2>You&rsquo;re all set!</h2>
          <p>Your creator profile is ready. Taking you to your studio&hellip;</p>
        </div>
      </div>
    );
  }

  return (
    <div className="creator-signup">
      <div className="creator-card">
        <div className="creator-hero">
          <div className="creator-hero-badge">
            <Radio size={26} />
          </div>
          <h1>Become a Creator</h1>
          <p>Set up your profile and go live &mdash; music, gaming, talk shows, art, or anything you stream.</p>
        </div>

        {error && <div className="error-message">{error}</div>}

        <form onSubmit={handleSubmit} className="creator-form">
          {/* Basics */}
          <section className="form-section">
            <div className="section-head">
              <span className="section-num">1</span>
              <h2>The basics</h2>
            </div>

            <div className="form-group">
              <label htmlFor="creatorName">Creator / channel name *</label>
              <input
                type="text"
                id="creatorName"
                name="creatorName"
                value={formData.creatorName}
                onChange={handleChange}
                required
                placeholder="The name your audience will know you by"
              />
            </div>

            <div className="form-group">
              <label htmlFor="bio">Bio *</label>
              <textarea
                id="bio"
                name="bio"
                value={formData.bio}
                onChange={handleChange}
                required
                placeholder="Tell viewers what your streams are about"
                rows="4"
              />
            </div>
          </section>

          {/* Category */}
          <section className="form-section">
            <div className="section-head">
              <span className="section-num">2</span>
              <h2>What do you create?</h2>
            </div>

            <div className="category-grid">
              {CATEGORIES.map(({ id, label, icon: Icon }) => (
                <button
                  type="button"
                  key={id}
                  className={`category-card ${formData.category === id ? 'selected' : ''}`}
                  onClick={() => selectCategory(id)}
                  aria-pressed={formData.category === id}
                >
                  <Icon size={22} />
                  <span>{label}</span>
                </button>
              ))}
            </div>

            <div className="form-group category-detail">
              <label htmlFor="categoryDetail">
                Add a detail <span className="optional">(optional)</span>
              </label>
              <input
                type="text"
                id="categoryDetail"
                name="categoryDetail"
                value={formData.categoryDetail}
                onChange={handleChange}
                placeholder="e.g. Lo-fi hip hop, speedruns, watercolor, true crime…"
              />
            </div>
          </section>

          {/* Images */}
          <section className="form-section">
            <div className="section-head">
              <span className="section-num">3</span>
              <h2>Profile look</h2>
            </div>

            <div className="image-row">
              <div className="form-group">
                <label>Profile image</label>
                <div className="upload-block">
                  <div className="avatar-preview">
                    {profileImagePreview ? (
                      <img src={profileImagePreview} alt="Profile preview" />
                    ) : (
                      <Camera size={26} />
                    )}
                  </div>
                  <div className="upload-controls">
                    <input
                      type="file"
                      id="profileImage"
                      accept="image/jpeg,image/png,image/webp"
                      onChange={(e) => handleImageChange(e, 'profile')}
                      className="file-input"
                    />
                    <label htmlFor="profileImage" className="file-label">
                      <Upload size={16} /> Choose image
                    </label>
                    <p className="upload-help">Square, 500&times;500px. Max 5MB.</p>
                  </div>
                </div>
              </div>

              <div className="form-group">
                <label>Cover image</label>
                <label htmlFor="coverImage" className="cover-dropzone">
                  {coverImagePreview ? (
                    <img src={coverImagePreview} alt="Cover preview" />
                  ) : (
                    <div className="cover-empty">
                      <Upload size={20} />
                      <span>Upload a cover banner</span>
                      <p className="upload-help">1600&times;400px. Max 5MB.</p>
                    </div>
                  )}
                </label>
                <input
                  type="file"
                  id="coverImage"
                  accept="image/jpeg,image/png,image/webp"
                  onChange={(e) => handleImageChange(e, 'cover')}
                  className="file-input"
                />
              </div>
            </div>
          </section>

          {/* Web presence */}
          <section className="form-section">
            <div className="section-head">
              <span className="section-num">4</span>
              <h2>Where else can people find you?</h2>
              <span className="section-optional">Optional</span>
            </div>

            <div className="form-group">
              <label htmlFor="websiteUrl">Website</label>
              <input
                type="url"
                id="websiteUrl"
                name="websiteUrl"
                value={formData.websiteUrl}
                onChange={handleChange}
                placeholder="https://yourwebsite.com"
              />
            </div>

            <div className="social-grid">
              {SOCIALS.map(({ key, label, placeholder }) => (
                <div className="form-group" key={key}>
                  <label htmlFor={`social-${key}`}>{label}</label>
                  <input
                    type="text"
                    id={`social-${key}`}
                    name={`socialLinks.${key}`}
                    value={formData.socialLinks[key]}
                    onChange={handleChange}
                    placeholder={placeholder}
                  />
                </div>
              ))}
            </div>
          </section>

          {/* Next event */}
          <section className="form-section">
            <div className="section-head">
              <span className="section-num">5</span>
              <h2>Upcoming stream or event</h2>
              <span className="section-optional">Optional</span>
            </div>

            <div className="event-row">
              <div className="form-group">
                <label htmlFor="venue"><MapPin size={15} className="icon-inline" /> Where</label>
                <input
                  type="text"
                  id="venue"
                  name="nextEvent.venue"
                  value={formData.nextEvent.venue}
                  onChange={handleChange}
                  placeholder="Venue, platform, or “Online”"
                />
              </div>

              <div className="form-group">
                <label htmlFor="dateTime"><Calendar size={15} className="icon-inline" /> Date &amp; time</label>
                <input
                  type="datetime-local"
                  id="dateTime"
                  name="nextEvent.dateTime"
                  value={formData.nextEvent.dateTime}
                  onChange={handleChange}
                />
              </div>
            </div>
          </section>

          {/* Terms */}
          <div className="form-group checkbox-group">
            <input
              type="checkbox"
              id="agreesToTerms"
              name="agreesToTerms"
              checked={formData.agreesToTerms}
              onChange={handleChange}
              required
            />
            <label htmlFor="agreesToTerms">
              I agree to the <a href="/terms-of-service" target="_blank" rel="noreferrer">Terms &amp; Conditions</a> for
              creators, including content guidelines and monetization policies.
            </label>
          </div>

          <div className="form-actions">
            <button
              type="button"
              className="cancel-button"
              onClick={() => navigate('/')}
              disabled={loading}
            >
              Cancel
            </button>
            <button type="submit" className="submit-button" disabled={loading}>
              {loading ? 'Creating…' : 'Create creator profile'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default ArtistSignUpPage;
